-- Content Seed — HİSSƏ 6/13: DB kontentinin ru/tr tərcümələri
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Hissələri istənilən ardıcıllıqla, istənilən qədər təkrar işlətmək təhlükəsizdir.
-- Cəmi: 12258 UPDATE, 13 hissə
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Сердце вашего малыша начало биться ещё на 4-й неделе, когда всего несколько клеток чудесным образом стали сокращаться и расслабляться. Всего за 40 дней этот крошечный двигатель развился и превратился в полностью сформированный четырёхкамерный орган. Сейчас, на четвёртом месяце, сердце малыша перекачивает по его маленькому телу примерно 20-25 литров крови в сутки. К моменту рождения этот показатель поразительным образом увеличится до 250-300 литров в сутки. Сердце малыша бьётся примерно в два раза быстрее вашего — 140-160 ударов в минуту. За всю беременность это маленькое сердце совершит более 1.5 миллиона ударов, обеспечивая каждую клеточку малыша кровью и жизнью.'), baby_message_ru = COALESCE(baby_message_ru, 'Я слушаю твоё сердце! ❤️ Мой слух с каждым днём становится всё лучше. Стук твоего сердца, шум крови, текущей по сосудам, и урчание в животе — моя постоянная музыка. Эти звуки меня успокаивают. После рождения, когда ты возьмёшь меня на руки, я тоже услышу биение твоего сердца и успокоюсь, потому что этот звук будет напоминать мне о "доме".'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кубинское яблоко'), body_changes_ru = COALESCE(body_changes_ru, 'Обычно человеку необходимо выпивать около 2 литров воды в день. Однако во время беременности это количество может увеличиться до 3-3.5 литров. Поскольку к физиологическим изменениям в организме женщины добавляется рост малыша, потребность в воде значительно возрастает. С начала и до конца беременности объём крови увеличивается примерно на 1-1.5 литра, а в матке вокруг малыша образуется амниотическая жидкость. В течение дня она должна обновляться. Амниотическая жидкость через определённые промежутки времени обменивается с жидкостью в организме матери и таким образом очищается. Достаточный объём амниотической жидкости, окружающей малыша, имеет огромное значение для его движений и развития лёгких. Кроме того, поскольку клетки организма малыша примерно на 80% состоят из воды, количество воды, которое пьёт мама, напрямую влияет на него. В этот период вода также очень важна для регулирования температуры тела, здоровья суставов, красоты кожи и работы пищеварительной системы.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Носите хлопковое нижнее бельё и избегайте узких брюк. Если вы пользуетесь ежедневными прокладками, меняйте их каждые 3-4 часа, чтобы влажная среда не способствовала размножению бактерий. Важно поддерживать интимную область сухой.') WHERE id = '170cfd85-3741-42d0-81e6-fb29eb61eb4e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе ваш малыш весит около 50 граммов, а его рост составляет 11-12 см. Теперь он выглядит как миниатюрный человечек: от кожи головы до бровей его покрывает густой пушок лануго, у него маленькие ушки и закрытые веки. Хотя глаза малыша уже полностью сформированы структурно, с функциональной точки зрения они будут развиваться в последнюю очередь. Для этого есть любопытная причина: нервных клеток — нейронов — уже много, но окружающая их миелиновая оболочка ещё не сформировалась. Миелиновая оболочка — это особый жировой слой, покрывающий нервы. Его можно сравнить с изоляцией вокруг электрических проводов. Без этого слоя электрические сигналы не могут быстро передаваться между нейронами. По мере формирования миелиновой оболочки малыш сможет быстрее воспринимать и распознавать поступающие извне изображения и сигналы.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, моя кожа пока очень тонкая, но пушок под названием "лануго" согревает меня. Мои ноги становятся длиннее рук. Теперь я выгляжу более пропорционально. Расти очень утомительно, но я справляюсь!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кубинское яблоко'), body_changes_ru = COALESCE(body_changes_ru, 'На протяжении беременности вам необходимо пить достаточно воды ради здоровья малыша и вашего собственного здоровья. В этот период количество потребляемой воды одинаково сильно влияет как на малыша, так и на вас. Достаточное употребление воды во время беременности не только помогает справиться со многими проблемами, но в некоторых случаях и полностью предотвращает их. Оно помогает предотвратить сокращения матки и снижает риск преждевременных родов. Вода делает кожу более сияющей и здоровой, а также уменьшает появление растяжек. Она помогает предотвратить инфекции мочевыводящих путей, запоры и геморрой. Кроме того, достаточное употребление воды снижает риск уменьшения объёма и недостаточного обновления амниотической жидкости, окружающей малыша. Особенно в жаркие летние месяцы вода восполняет жидкость, потерянную с потом. Она также уменьшает такие жалобы, как тошнота, изжога и отёки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Миндаль или стакан тёплого молока помогают естественным образом облегчить изжогу.') WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя с момента рождения ваш малыш способен слышать, плакать и демонстрировать некоторые рефлексы, для развития таких навыков, как зрение, речь и ходьба, ему потребуется время. Главная причина в том, что нервная система ещё не получила достаточного количества внешних стимулов. Развитие мозга завершается по мере своеобразного «накопления опыта». Особенно поздно развивается зрительная система. При рождении и сетчатка глаза, и зрительный центр в головном мозге ещё не полностью созрели. В утробе матери малыш способен различать свет, однако это ещё нельзя считать полноценным зрением. В первые 3 месяца изображение остаётся размытым. Ваш малыш может различать только предметы, находящиеся на расстоянии 50-70 см (примерно на таком расстоянии он видит ваше лицо, когда вы держите его на руках). Способность фокусировать взгляд пока развита слабо. В 5-6 месяцев, по мере повышения двигательной активности, зрение также становится острее. Малыш уже следит глазами за движущимися предметами и благодаря зрительно-моторной координации тянется рукой к игрушке, которую видит. Развитие глаз и зрительных нервов полностью завершается к 7 годам.'), baby_message_ru = COALESCE(baby_message_ru, 'Я различаю вкусы! 🍬 Anacan, когда вы едите что-нибудь сладкое, амниотическая жидкость становится слаще, и я глотаю её активнее. А когда она кислая или горькая, я морщусь. Моё чувство вкуса почти такое же развитое, как у взрослого человека. Какие овощи я буду любить в будущем, уже сейчас зависит от вашего питания. Питайтесь правильно, чтобы и я был здоровым!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Губинское яблоко'), body_changes_ru = COALESCE(body_changes_ru, 'На следующей неделе врач может назначить вам тройной скрининговый тест. Тройной скрининговый тест — это анализ крови, который рекомендуется всем беременным женщинам в период между 16-й и 18-й неделями беременности. В образце крови будущей мамы измеряют уровни 3 различных гормонов. Результаты этих измерений вместе с такими данными, как возраст и вес матери, наличие или отсутствие курения, а также срок беременности вводят в специальную компьютерную программу для обработки. Этот тест предназначен для выявления у малыша хромосомных нарушений, в частности Трисомии 21, известной как синдром Дауна, и Трисомии 18, известной как синдром Эдвардса, а также аномалий, называемых дефектами нервной трубки. Особенно важно пройти этот тест женщинам, в семейном анамнезе которых есть врождённые пороки, женщинам в возрасте 35 лет и старше, тем, кто принимал во время беременности потенциально вредные лекарства или таблетки, страдает инсулинозависимым сахарным диабетом или диабетом, перенёс во время беременности вирусную инфекцию либо ранее родил ребёнка с врождённым пороком.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте завершение 15-й недели и немного побалуйте себя! Чтобы предотвратить боль в пояснице, носите удобную обувь и не поднимайте тяжести. Для здоровья дёсен не забывайте регулярно получать достаточное количество кальция. На следующей неделе движения малыша станут ещё сильнее, поэтому возьмите за привычку каждый день спокойно разговаривать с ним в течение нескольких минут.') WHERE id = '7f759cae-0b0a-4f2e-8095-e125d4622671';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Начиная с этой недели для наблюдения за ростом малыша уже недостаточно измерять только его длину. Врачи уделяют внимание более подробным показателям — окружности головы и живота, а также длине бедренной кости. Эти данные позволяют точно определить, соответствует ли развитие малыша сроку беременности. Ваш малыш уже может держать голову и шею более прямо. Это возможно благодаря сильным мышцам, расположенным по обеим сторонам шеи. Они поддерживают череп и позволяют малышу свободно двигать головой. В подвижных суставах есть суставная жидкость, которая предотвращает трение и изнашивание костей. Благодаря этой жидкости кости двигаются легко и безболезненно, словно смазанные.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои ножки становятся длиннее! 🦵 До сих пор мои ручки и ножки были одинаковой длины, но теперь ножки растут быстрее по отношению к телу. Я уже выгляжу как настоящая модель! Я сгибаю ножки и подтягиваю колени к себе. Готовлюсь как следует пнуть вас этими длинными ножками. Шучу, я не причиню вам боль, а просто скажу «привет».'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Губинское яблоко'), body_changes_ru = COALESCE(body_changes_ru, 'Начиная с этого периода беременности из-за быстрого роста малыша и давления на сосуды в паховой области кровообращение в венах ног ухудшается. Если к этому добавляется жаркая летняя погода, отёки могут появиться в разных частях тела, чаще всего в области стоп, лодыжек и голеней. Старайтесь отдыхать при любой возможности, лежать на удобной кровати или диване, приподняв ноги и подложив под них подушку, при необходимости делать лёгкий массаж кистей и лодыжек, а также носить удобную обувь — это поможет уменьшить неприятные ощущения.;;;
Ещё одной причиной появления отёков может быть чрезмерная прибавка веса в сочетании с малоподвижным образом жизни. Сбалансированное питание и выполнение упражнений, разрешённых во время беременности, помогают контролировать вес, а также уменьшить боли в пояснице и паховой области, которые могут возникнуть в последующие месяцы.;;;
Ходьба и плавание считаются наиболее подходящими видами физической активности для беременных. Оба вида нагрузки будущая мама может выполнять без риска для сердца, равновесия, суставов и мышц. Во время занятий необходимо делать короткие перерывы и не допускать чрезмерного утомления. Для плавания по возможности лучше выбирать море, а не бассейн. Избегайте бассейнов, в надлежащем санитарном контроле которых вы не уверены.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку объём крови увеличивается, уделяйте особое внимание поступлению железа. Чтобы уменьшить боль в связках, старайтесь избегать резких движений. Если вы ощущаете зуд в области живота, каждый вечер делайте массаж с увлажняющими маслами. Чтобы приятно провести день, можете почитать малышу вслух любимую книгу.') WHERE id = 'abd207ad-c924-457f-b115-c38d8e842b83';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя на этой неделе структуры внутреннего уха малыша начинают формироваться, до того момента, когда он действительно начнёт слышать, должно пройти ещё несколько недель. Внутреннее ухо — это очень сложная система, отвечающая как за восприятие звуков, так и за поддержание равновесия тела.;;;
После полного развития малыш сможет с помощью этой системы слышать все звуки в диапазоне от 20 до 20.000 герц. Сейчас этот удивительный «аппарат» только формируется, а полностью заработает на более позднем сроке беременности (примерно к 30-й неделе).'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую вас! 🤗 Anacan, когда вы гладите живот, я чувствую это давление и тепло. Иногда я подплываю к тому месту, где находится ваша рука. Между нами лишь кожа и вода, но наши души едины. Когда вы испытываете стресс, я тоже беспокоюсь, а когда вы смеётесь, я успокаиваюсь. Пожалуйста, всегда улыбайтесь!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Апельсин'), body_changes_ru = COALESCE(body_changes_ru, 'Время от времени вы можете ощущать эмоциональное напряжение, стресс и противоречивые чувства. Во время беременности в вашем организме происходят различные изменения. Эти физические и гормональные перемены могут влиять и на ваше психологическое состояние. Повышенная эмоциональность, обидчивость и чувствительность — наиболее распространённые проявления в этот период. Важно помнить, что трудности, возникающие во время беременности, носят временный характер, а поддержка партнёра поможет вам обоим легче пройти этот этап.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы чувствуете одышку, выпрямитесь и отведите плечи назад. Так у лёгких появится больше пространства. Медленное и глубокое дыхание обеспечивает кислородом и вас, и малыша.') WHERE id = '2da10eb1-918c-43c6-ad16-6306b072b4cb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Начиная с этой недели темп роста головы вашего малыша немного замедляется, чтобы тело могло догнать её по размеру. В то же время в лёгких уже сформировались важнейшие структуры, которые в будущем обеспечат дыхание, — альвеолы. Альвеолы — это маленькие мешочки, расположенные на самых концевых участках лёгких, которые будут наполняться воздухом. Их главная задача — осуществлять газообмен: удалять углекислый газ из крови и передавать в неё необходимый организму кислород. Сейчас ваш малыш «тренирует» эту систему не воздухом, а амниотической жидкостью. Такие тренировки очень важны, чтобы после рождения он смог сделать свой первый вдох.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои ушки уже на месте! 👂 Теперь они расположены по бокам головы, то есть заняли своё окончательное положение. Сейчас я слышу тебя ещё лучше. Звуки твоего кишечника и дыхания для меня словно симфония. Но больше всего я люблю слушать твой голос и смех. Почаще пой мне колыбельные — я их запоминаю.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Апельсин'), body_changes_ru = COALESCE(body_changes_ru, 'В ближайшие дни у вас могут возникать носовые кровотечения. С такой жалобой на определённом этапе беременности сталкиваются многие женщины, поэтому беспокоиться не стоит. По мере роста малыша в матке объём циркулирующей в вашем организме крови увеличивается, а сосуды испытывают дополнительную нагрузку. Особенно чувствительны к этому тонкие поверхностные сосуды слизистой оболочки носа: они могут повреждаться и кровоточить. При носовом кровотечении не рекомендуется ложиться или запрокидывать голову назад. В этом случае кровь может стекать в горло, попадать в желудок и вызывать тошноту. Вместо этого сядьте или встаньте, слегка наклоните голову вперёд и зажмите нос ближе к переносице, пока кровотечение не остановится. Кроме того, по рекомендации врача вы можете принимать витамин C для укрепления сосудистых стенок.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить кровоточивость дёсен, пользуйтесь мягкой зубной щёткой. Старайтесь утолять усилившийся аппетит полезными продуктами. Чтобы избежать боли в пояснице, не оставайтесь подолгу в одном положении. Для хорошего настроения составьте плейлист с любимой музыкой и слушайте его вместе с малышом.') WHERE id = '785f2466-b995-4db8-a286-7f765b7f2877';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже размером с авокадо!  Самое интересное событие этой недели — развитие у малыша чувства вкуса.;;;
На поверхности его языка уже сформировались вкусовые сосочки. Механизм восприятия вкуса довольно сложен и интересен: пищевые вещества растворяются в слюне, после чего рецепторы на поверхности языка распознают вкус и передают сигнал в сенсорный центр головного мозга.;;;
Как и любое живое существо, ваш малыш учится реагировать на окружающие раздражители — в данном случае на вкус амниотической жидкости, которую он глотает. Интересно, что разные участки языка воспринимают вкусы с разной интенсивностью:;;;
Поскольку вкус съеденных вами продуктов проникает в амниотическую жидкость, малыш уже знакомится с разными вкусами. Это может повлиять даже на его предпочтения в еде в будущем.'), baby_message_ru = COALESCE(baby_message_ru, 'Моё сердце сильное! 💪 Моё маленькое сердечко перекачивает примерно 25 литров крови в сутки! Для такого крошечного тела это огромная работа. Кровь циркулирует по всему моему организму, доставляя кислород и питательные вещества. Благодаря тебе у меня сильное сердце. Оно будет биться всю мою жизнь, чтобы любить тебя.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Авокадо'), body_changes_ru = COALESCE(body_changes_ru, 'Время от времени вы можете чувствовать сильную усталость, а в некоторые дни — быть энергичнее обычного. В первые три месяца быстрое повышение уровня прогестерона может вызывать сонливость. Обмен веществ также ускоряется, организм расходует больше энергии, что усиливает усталость на ранних сроках беременности. Кроме того, пониженное артериальное давление и увеличение объёма крови тоже отнимают силы. Второй триместр, в который вы вступили, часто называют «медовым месяцем» беременности. Ваш организм уже приспособился к потоку гормонов беременности, поэтому вы можете чувствовать себя менее уставшей, чем в первом триместре, и начать полноценно готовиться к появлению малыша. В периоды усталости не забывайте о сбалансированном питании, достаточном употреблении воды, регулярном режиме сна и физической активности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Старайтесь сидеть прямо и отводить плечи назад во время ходьбы — это поможет уменьшить боль в пояснице. Продолжайте пользоваться увлажняющими средствами, чтобы поддерживать эластичность кожи. Отдавайте предпочтение продуктам, богатым кальцием и магнием (миндалю, зелёным овощам), чтобы кости малыша укреплялись, а у вас не возникали судороги в ногах.') WHERE id = '6a2c14a8-03ef-4ac3-8457-485f9afcbef3';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Скелет вашего малыша уже настолько развит, что его можно отчётливо увидеть во время ультразвукового исследования. Скелетная система состоит из костей и соединяющих их суставов. Вместе с мышцами они обеспечивают ловкие движения малыша в вашей утробе.;;;
В теле новорождённого насчитывается 270 костей, тогда как у взрослого человека их 206. Это связано с тем, что кости малыша ещё имеют хрящевую структуру и отделены друг от друга. Такая гибкость помогает защитить малыша от травм во время прохождения через родовые пути. После рождения эти маленькие кости, например части черепа, постепенно срастаются, образуя более крупные и прочные кости.'), baby_message_ru = COALESCE(baby_message_ru, 'Я держу голову прямо! 🦒 Anacan, мышцы моей шеи настолько окрепли, что теперь я могу держать голову прямо. Раньше она была наклонена к груди, а сейчас мне удобнее смотреть по сторонам (хотя вокруг темно). Моё тело вытягивается, я становлюсь более стройным и держусь ровнее. Делать гимнастику в твоём животике так приятно!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Авокадо'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за изменения гормонального баланса во время беременности в вашем организме происходят необычные процессы. Тошнота, рвота, потемнение в глазах, головокружение и обмороки особенно часто наблюдаются в первые три месяца, но могут время от времени возникать на любом сроке беременности. Поскольку матка во время беременности значительно увеличивается, к ней, где находится ваш малыш, направляется большая часть крови. Поэтому другие органы, включая головной мозг, иногда могут временно получать меньше крови, чем им необходимо. Если организм не успевает быстро компенсировать эту потребность, могут возникнуть головокружение и обморок. Чтобы снизить риск подобных состояний, не вставайте слишком быстро и резко, избегайте сна на спине, не допускайте голода и обезвоживания, а при наличии анемии обязательно пройдите назначенное лечение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не забывайте массировать кожу живота с натуральными маслами, чтобы уменьшить зуд. Старайтесь не сидеть подолгу в одном положении, чтобы предотвратить боль в пояснице. Достаточное употребление жидкости очень важно для обмена веществ как у вас, так и у малыша. На следующей неделе нас ждут ещё более значительные сюрпризы!') WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Долгожданная неделя наступила! Начиная с этой недели будьте готовы узнать пол малыша на приёме у врача. На 16-й неделе беременности при наличии качественного аппарата УЗИ и опытного врача пол малыша можно определить с точностью до 90%, если он находится в подходящем положении. К этому сроку половые органы девочек и мальчиков уже достаточно развиты, чтобы их можно было различить на УЗИ. Главное изменение у мальчиков в этот период заключается в том, что яички, ранее находившиеся в брюшной полости, начинают опускаться в мошонку.;;;
Иногда при определении пола возможны ошибки. Например: у девочек пуповина под некоторыми углами может выглядеть как мужской половой орган. У мальчиков, если яички ещё не полностью опустились в мошонку, малыша могут ошибочно принять за девочку. Именно поэтому врачи стараются рассмотреть малыша в нескольких разных положениях. Если врач не даёт однозначного ответа, а лишь высказывает предположение, лучше дождаться подробного УЗИ (обычно на 18-22-й неделях), прежде чем приступать к крупным покупкам.'), baby_message_ru = COALESCE(baby_message_ru, '16 НЕДЕЛЬ ПОЗАДИ! 🥑 Я размером с авокадо! Самая важная новость обо мне: моё кровообращение работает превосходно. Моё маленькое сердечко ежедневно перекачивает литры крови. Я расту, становлюсь сильнее и жду дня нашей встречи. Вы — весь мой мир!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Авокадо'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности из-за давления растущей матки на мочевой пузырь и гормональных изменений вы можете испытывать частые позывы к мочеиспусканию. Однако если при этом возникают жжение или резь во время мочеиспускания, чувство давления и боль в паху, а моча становится тёмной, можно заподозрить инфекцию мочевыводящих путей. Чаще всего её вызывают бактерии из кишечника. Недостаточная или неправильная интимная гигиена, незащищённые половые контакты, заболевания, ослабляющие иммунную систему, сахарный диабет у будущей мамы, структурные заболевания почек, камни в почках и перенесённые ранее операции на мочеполовой системе также могут повышать риск подобных жалоб во время беременности. При инфекции мочевыводящих путей важна ранняя диагностика, поскольку инфекция может распространиться и вызвать осложнения со стороны почек. Высокая температура может спровоцировать преждевременные сокращения матки и, как следствие, выкидыш или даже преждевременные роды. Во время беременности рекомендуется выпивать не менее 2 литров воды в день. Увеличение потребления жидкости усиливает ток мочи и помогает очищению мочевыводящих путей. Кроме того, употребление богатых пробиотиками продуктов, таких как йогурт и кефир, помогает поддерживать здоровую микрофлору и активизировать иммунную систему, снижая восприимчивость к инфекциям.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Вы находитесь в одном из самых прекрасных периодов беременности, поэтому наслаждайтесь каждым мгновением. Продолжайте спать на боку и включайте в рацион продукты, богатые железом, чтобы предотвратить анемию. Не забывайте регулярно увлажнять кожу, чтобы поддержать её при растяжении. На следующей неделе слух малыша станет ещё совершеннее!') WHERE id = '4db5e35d-0bef-4624-aa7c-2dbb50189eef';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже достиг размера авокадо. В ближайшие несколько недель его ждёт период стремительного развития: и вес, и рост увеличатся примерно вдвое. ;;;
На этой неделе во время УЗИ велика вероятность увидеть малыша лежащим на спине. Его позвоночник и мышцы спины уже значительно окрепли, благодаря чему он может держать голову и шею более прямо. Ноги стали ещё длиннее по сравнению с предыдущими неделями и теперь выглядят пропорционально телу.;;;
Мимика малыша тоже становится разнообразнее: он уже может хмурить брови и двигать глазами, хотя веки пока остаются закрытыми.;;;
Одна из самых волнующих новостей — малыш начинает слышать. Благодаря развитию структур внутреннего уха он уже воспринимает звуки. Первыми он слышит звуки вашего тела: биение сердца, дыхание и работу кишечника. Вскоре его мозг начнёт глубже анализировать эти звуки, и малыш научится отличать ваш голос от других звуков извне. Поэтому уже сейчас вы можете разговаривать с ним и петь ему песни.'), baby_message_ru = COALESCE(baby_message_ru, 'Я накапливаю жир! 🧈 До сих пор я был очень худеньким, и моя кожа свободно облегала косточки. Но теперь я начинаю накапливать особый слой жира, который называется «бурым жиром». Он будет согревать меня и снабжать энергией. Постепенно я становлюсь тем самым милым пухленьким малышом. Я хочу быть мягким, когда окажусь в ваших объятиях.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Авокадо'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности важно обеспечивать суточную потребность в витамине C — для вашего здоровья, развития малыша и уменьшения несовершенств кожи. Благодаря антиоксидантным свойствам витамин C помогает бороться с инфекциями и защищает организм от токсинов в период беременности, когда иммунная система становится более уязвимой. Он жизненно важен для восстановления тканей, заживления ран, повышения эластичности кожи и профилактики растяжек, роста и восстановления костей, а также для выработки коллагена — структурного белка, необходимого для здоровья кожи и содержащегося в хрящах, костях, сухожилиях и коже. Витамин C также улучшает усвоение железа, необходимого вашему организму. Благодаря этому он помогает поддерживать нормальный уровень гемоглобина и защищает от анемии. Кроме того, витамин C способствует формированию тканей малыша и укрепляет кровеносные сосуды плаценты, обеспечивая поступление большего количества кислорода к плоду и снижая риск преждевременной отслойки плаценты. Витамин C также помогает при запорах и способствует комфортной работе кишечника.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При уходе за кожей избегайте кремов, содержащих «ретиноиды» (производные витамина A) или «салициловую кислоту». Эти вещества могут навредить малышу. Выбирайте натуральные масла или косметику, предназначенную для беременных.') WHERE id = '15cf9597-2ec2-4fe2-8400-f9a4938a8ee5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На 16-й неделе беременности глаза малыша уже способны различать темноту и яркий свет. Однако, чтобы он заметил разницу, свет должен быть очень ярким, поскольку стенка матки служит надёжным барьером. Сейчас до малыша доходит лишь 1% света извне. Есть и другие интересные особенности. Веки: пока веки малыша остаются сомкнутыми. Они начнут открываться и закрываться только с середины 20-х недель. Различие дня и ночи: в последующие недели по мере растяжения и истончения кожи живота внутрь будет проникать больше света. Это поможет малышу различать день и ночь и даже поворачиваться к источнику света. Зрачковый рефлекс: с 30-й недели у малыша появляется зрачковый рефлекс. Мышцы радужки — цветной части глаза — реагируют на свет: при ярком освещении зрачок сужается, а при слабом расширяется. Это удивительный механизм, который защищает глаз и регулирует зрительное восприятие.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя пуповина становится толще! 🔌 Это моя линия жизни. Питательные вещества и кислород поступают от вас ко мне по этому «кабелю». Теперь он стал толще и прочнее, и по нему проходит много крови. Иногда я хватаю его рукой и играю с ним, но не волнуйтесь: я не могу сжать его и остановить кровоток, потому что он очень эластичный и скользкий.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Груша'), body_changes_ru = COALESCE(body_changes_ru, 'Для правильного развития растущего в матке малыша вам уже желательно не спать на спине. Чтобы обеспечить более свободный приток крови к малышу, рекомендуется спать на левом боку. Когда вы лежите на спине, вес тела приходится на позвоночник и мышцы спины. Это создаёт дополнительное давление на кровеносные сосуды и уменьшает приток крови к малышу. Во время беременности лучшим положением для сна считается положение на левом боку с согнутыми коленями и подушкой между ног. Такая поза облегчает работу почек и уменьшает отёки, которые могут возникать в теле, особенно в руках и коленях. Для более комфортного сна в этот период также может быть полезна подушка для беременных. Чтобы сон был здоровым и продолжительным, исключите из рациона напитки с кофеином, такие как кофе, чай и кола. Пейте достаточно жидкости в течение дня, но прекратите её употребление за 2-3 часа до сна и избегайте тяжёлой пищи. Кроме того, регулярные упражнения, тёплый душ перед сном и молоко могут значительно улучшить качество сна.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы ощущаете сухость глаз, чаще делайте перерывы в течение дня и проводите меньше времени перед экраном. Поскольку потребность в кальции возрастает, обязательно включайте в рацион кунжут, сыр и зелёные листовые овощи. Если вы чувствуете лёгкое напряжение в спине, сидя осторожно отведите плечи назад и выполните несколько лёгких движений. Каждый день мы становимся немного больше!') WHERE id = 'c27b671d-4d70-44eb-80ea-7aedfd97f434';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Плацента, которую называют верной спутницей малыша, продолжает расти вместе с ним. В первые недели беременности, когда группы клеток начинают делиться, формируя вашего малыша, часть этих клеток дифференцируется и образует плаценту. Пока малыш растёт внутри амниотического мешка, продолжает развиваться и плацента, с которой он соединён формирующейся пуповиной. К 4-й неделе беременности уровень гормонов беременности в организме начинает повышаться. Они поддерживают развитие не только малыша, но и плаценты, поэтому малыш и плацента внутри плодного пузыря продолжают расти одновременно. Плацента — это временный орган, который на протяжении всей беременности обеспечивает обмен питательными веществами между вами и малышом, растёт вместе с ним в матке, а после его рождения выходит из организма, завершая свою работу. На протяжении значительной части беременности этот орган по размеру сопоставим с малышом, а к последним неделям достигает в среднем 20-25 см в диаметре, 2-3 см в толщину и весит около 500 граммов.'), baby_message_ru = COALESCE(baby_message_ru, 'Полёт бабочки! 🦋 Anacan, ты меня чувствуешь? Я тут кувыркаюсь! Некоторые мамы описывают это ощущение словами «будто в животе порхает бабочка» или «плавает рыбка». Если ты пока ничего не чувствуешь, не расстраивайся: я ещё маленький, и мои толчки слабые. Но совсем скоро я так тебя пну, что ты сразу всё поймёшь!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Груша'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности особенно важно здоровье сердечно-сосудистой системы, то есть сердца и кровеносных сосудов. Поэтому, если врач не выявил у вас противопоказаний, специалисты настоятельно рекомендуют сохранять физическую активность во время беременности. Упражнения помогают уменьшить такие распространённые жалобы, как боль в пояснице, судороги в ногах и усталость, а также повышают уровень энергии. Кроме того, физическая активность снижает риск гестационного сахарного диабета и повышенного артериального давления. Она также может значительно снизить вероятность послеродовой депрессии. Повышая выносливость и укрепляя мышцы, упражнения помогают подготовиться к родам. Укрепление мышц живота и спины уменьшает вероятность появления болей во время беременности. Регулярная растяжка поможет определить участки, в которых накапливается напряжение, и расслабить болезненные мышцы.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Вечером прилягте в тихой комнате, положите руку на живот и сосредоточьтесь на своих ощущениях. Иногда, чтобы почувствовать движения, нужны лишь тишина и внимание. Что-нибудь сладкое может побудить малыша начать двигаться.') WHERE id = '6f4082a3-2c0c-4302-bc06-2af671b9e9b3';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя кожа вашего малыша продолжает утолщаться, на этом этапе она всё ещё остаётся прозрачной. Благодаря этому, если бы вы могли сейчас увидеть малыша, то заметили бы под тонкой кожей кровеносные сосуды, скелет и внутренние органы. Мигательный рефлекс малыша продолжает развиваться. В среднем веки моргают 15-20 раз в минуту, и за день это число достигает примерно 30 тысяч. Моргание не только защищает глазное яблоко, но и постоянно поддерживает необходимый уровень увлажнения поверхности глаза и роговицы. Веки также способствуют питанию наружного слоя глаза, который во время сна получает меньше кислорода. Моргание происходит непроизвольно и защищает глаза от яркого света и инородных частиц. При смыкании век слёзная жидкость распределяется по всей поверхности глазного яблока, увлажняя его и предотвращая сухость, а также повреждение глаз раздражающими веществами. Кроме того, моргание помогает сохранять фокусировку взгляда на одной точке во время движения.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня формируются потовые железы! 💦 Моя кожа всё ещё развивается, и теперь начинают формироваться потовые железы. Конечно, в воде я не потею, но после рождения они очень понадобятся мне для регулирования температуры тела. Всё это — подготовка к моей будущей жизни. Какое же твоё тело удивительное и совершенное место для обучения!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Груша'), body_changes_ru = COALESCE(body_changes_ru, 'По мере роста живота вы можете начать ощущать зуд в этой области и замечать растяжки, похожие на тонкие линии. На определённом этапе беременности на груди, ягодицах и животе могут появиться слегка запавшие и зудящие полосы розового, фиолетового или красного цвета. Эти линии представляют собой мелкие разрывы, возникающие из-за чрезмерного растяжения поддерживающих слоёв ткани под кожей. Важнейшим фактором, влияющим на появление растяжек, является генетическая предрасположенность. Помимо генетики, ещё одним фактором риска является резкое и чрезмерное увеличение веса. Быстро растущий живот вызывает натяжение кожи и снижение её эластичности, что может привести к появлению растяжек. Поэтому для их профилактики очень важно набирать вес постепенно и в рекомендуемых пределах. Чтобы предотвратить появление растяжек или уменьшить их выраженность, поддерживайте увлажнённость кожи, набирайте вес постепенно, пейте достаточно воды, придерживайтесь здорового питания и регулярно выполняйте физические упражнения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы избежать головокружения, медленно вставайте из положения сидя или лёжа. Достаточное употребление жидкости поможет сохранить вашу энергию и поддержит обновление околоплодных вод. Поскольку потребность в кальции увеличилась, отдавайте предпочтение таким продуктам, как творог и йогурт. Завершить день спокойной прогулкой будет полезно и для вашего самочувствия, и для комфорта малыша.') WHERE id = '011238e0-e01a-4bb0-b882-82b96d90dc82';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Чувствуете ли вы время от времени лёгкие шевеления в животе? Скорее всего, это ваш малыш! 😊 Его кости и мышцы уже достаточно развились и окрепли, поэтому теперь вы можете начать ощущать его движения. Начиная с этого этапа малыш будет двигаться активнее и сильнее, и вы сможете чувствовать его толчки. Благодаря увеличению матки и объёма околоплодных вод у него также достаточно пространства для движений. На этом сроке беременности вы можете почувствовать движения малыша, при которых он соприкасается со стенкой матки дольше одной секунды. Благодаря хорошо развитым костям и мышцам малыш активен как никогда. Он задействует все свои мышцы, помогая им развиваться ещё больше. Если вы пока не чувствуете малыша, не волнуйтесь — совсем скоро вы начнёте ощущать его движения. Причинами более позднего появления первых ощущений могут быть плотные мышцы живота при первой беременности, жировая прослойка в области живота, выполняющая роль амортизатора, или больший, чем обычно, объём околоплодных вод. 90% беременных начинают чувствовать движения малыша между 16-й и 22-й неделями.'), baby_message_ru = COALESCE(baby_message_ru, 'Я покрываюсь «сыром»! 🧀 Звучит забавно, но на моей коже начинает появляться белое кремообразное вещество. Его называют «верниксом» (Vernix Caseosa), или первородной смазкой. Оно защищает мою тонкую кожу от размокания в воде. Если бы не верникс, из-за долгого пребывания в воде моя кожа стала бы сморщенной. Это мой естественный увлажнитель.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Груша'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности плацента и матка вырабатывают большое количество прогестерона. Повышенный уровень этого гормона в крови замедляет перистальтику и сокращения желудка, а также способствует расслаблению нижнего пищеводного сфинктера. В результате желудочная кислота попадает в пищевод и возникает изжога. Чтобы уменьшить её проявления, избегайте жирной и острой пищи, напитков с кофеином, полуфабрикатов и переработанных продуктов, таких как кетчуп и соленья, а вместо газированных напитков выбирайте воду. Старайтесь заканчивать приём пищи не позднее чем за три часа до сна. В положении лёжа желудочной кислоте легче попасть через расслабленный сфинктер в пищевод. Если вы поздно поужинали, постарайтесь не ложиться хотя бы в течение часа после еды. Также могут помочь небольшие частые приёмы пищи и тщательное пережёвывание. Прежде чем использовать молоко, йогурт или травяные чаи, включая ромашковый, мятный и имбирный, для облегчения изжоги, посоветуйтесь с врачом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Выполняйте специальные упражнения на растяжку при боли по ходу седалищного нерва. Не сидите долго в одном положении. Тёплый душ или тёплый компресс на болезненную область помогут расслабить мышцы.') WHERE id = '3902a1df-6463-4c00-82b6-0534aaec9c0a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Матка, которая служит домом для вашего малыша на протяжении 9 месяцев, начиная с этой недели располагается прямо под пупком. В начале беременности она весила в среднем 60 грамм, а на данном этапе её вес уже достиг 250 грамм. На этой неделе внутри матки, в плодном пузыре, где находится ваш малыш, содержится в среднем 100 мл амниотической жидкости. Это примерно равно 10 столовым ложкам воды. Эта жидкость поддерживает постоянную температуру для малыша и служит защитной подушкой, оберегая его от механических травм и внешних воздействий. Кроме того, благодаря своим антибактериальным свойствам она создаёт вокруг малыша стерильную среду и защищает его от инфекций.'), baby_message_ru = COALESCE(baby_message_ru, 'Я слышу тебя, мама! 🗣️ Теперь мои ушки начинают полноценно работать. Я слышу твою речь, смех и даже песни, которые ты поёшь. Хотя звуки кажутся приглушёнными (как под водой), я различаю интонацию. Почаще говори мне: "Я тебя люблю" — я хочу запомнить эти слова.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Груша'), body_changes_ru = COALESCE(body_changes_ru, 'Боль в паху, которая в первые недели беременности может возникать из-за роста матки и усиления кровообращения, в последующие недели может быть связана с увеличением веса и растяжением связок, поддерживающих матку. Кроме того, во время беременности организм вырабатывает гормон релаксин. Релаксин размягчает плотные ткани, соединяющие связки. Это означает, что во время беременности суставы таза и паховой области могут стать более подвижными. Во втором триместре по мере роста малыша начинают растягиваться круглые связки, поддерживающие матку, что также может вызывать боль в паху. Чтобы предотвратить или уменьшить такую боль, старайтесь оставаться активной, не переутомляясь, и избегайте резких движений при выполнении повседневных дел.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Разговаривайте с малышом! Читайте ему книги, рассказывайте, как прошёл ваш день. Это укрепляет эмоциональную связь между вами. Исследования показывают, что после рождения малыши узнают звуки и песни, которые слышали в утробе матери.') WHERE id = '16510ace-04bb-4c83-9c44-82e27d7b140c';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе ваш малыш продолжает готовиться к дню своего рождения. Сейчас важнейшие навыки, над которыми он работает, — рефлексы сосания и глотания! Он готовится к первым глоткам молока, которым вы будете его кормить.Глотание — один из первых рефлекторных механизмов, развивающихся у малыша. Этот процесс начинается после завершения формирования верхней губы, когда она начинает функционировать и позволяет закрывать рот.;;;
В результате развития глотания инстинктивно формируется сосательный рефлекс. То есть в функциональном отношении эти два рефлекса развиваются один за другим. Эта напряжённая тренировка, которую ваш малыш начинает уже сейчас, полностью завершится лишь к 32-й неделе.;;;
В этот же период малыш учится глотать амниотическую жидкость и таким образом, как и в случае с дыхательной функцией, готовится к рождению. Благодаря этому к моменту рождения его глотательный рефлекс будет достаточно развит, чтобы сосать молоко из вашей груди. В зависимости от количества слюны глотательный рефлекс срабатывает примерно два раза в минуту во время бодрствования и примерно один раз в минуту во время сна.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои ручки не остаются без дела! ✊ У меня очень сильный хватательный рефлекс. Я сжимаю кулачки и шевелю пальчиками. Иногда хватаюсь за пуповину, а иногда — за другую ручку. Эти движения укрепляют мои пальчики. Когда я родюсь, то так крепко схвачу тебя за палец, что ты удивишься!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Груша'), body_changes_ru = COALESCE(body_changes_ru, 'Ваша матка почти достигла уровня пупка, и вы уже можете почувствовать её рукой. Начиная с этой недели малыш будет набирать вес и развиваться быстрее, чем прежде, поэтому, скорее всего, вы тоже начнёте прибавлять в весе немного быстрее. К этому моменту вы должны были набрать в среднем 2.5-5 кг. У некоторых будущих мам живот может выглядеть больше или меньше, чем ожидается на данном сроке беременности. Наиболее вероятные причины этого — скопление газов в кишечнике или плотность кожи.;;;
До конца этой недели вам следует пройти тройной тест. Хотя некоторые лаборатории благодаря используемым компьютерным программам могут оценивать результаты тройного теста вплоть до 20-й недели и даже позже, лучше определить возможный риск как можно раньше. Некоторые врачи считают тройной тест необязательным, если результаты двойного теста, проведённого между 11-14-й неделями, показали низкий риск, тогда как другие могут рекомендовать пройти и двойной, и тройной тест.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Вы находитесь в одном из самых комфортных периодов беременности, поэтому уделяйте время себе. Привыкайте спать на левом боку, чтобы кровообращение было оптимальным и для вас, и для малыша. Продолжайте пить достаточно жидкости и употреблять продукты, богатые кальцием. На следующей неделе вероятность того, что вы будете отчётливее ощущать движения малыша, возрастёт!') WHERE id = '0f424a2a-4630-431c-9be8-af0ad1977c5a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Лёгкие вашего малыша продолжают всесторонне развиваться и становиться функциональными. Хотя они пока ещё не способны обеспечивать обмен углекислого газа и кислорода, уже формируется функция, которая позволит малышу дышать после рождения. Пока эти дыхательные движения происходят с участием окружающей его амниотической жидкости.;;;
Первый вдох малыша после рождения станет самым трудным вдохом в его жизни. Это связано с тем, что заполненная жидкостью дыхательная система должна наполниться воздухом.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои кости становятся крепче! 🦴 Раньше мой скелет состоял из мягкой, словно резина, хрящевой ткани, но теперь она превращается в настоящую кость (оссификация). Я становлюсь крепче. Мои рёбра, позвоночник и кости ног твердеют. Я уже не маленький комочек желе, а крепкий мальчик (или девочка)!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Груша'), body_changes_ru = COALESCE(body_changes_ru, 'Если у вас был сахарный диабет ещё до беременности, во время беременности вам следует быть особенно внимательной. Контролировать уровень сахара в крови в этот период может быть сложнее, чем до беременности. Также может потребоваться изменение дозы инсулина. В таком случае вам нужно будет чаще посещать врача.;;;
Сахарный диабет — это заболевание, вызывающее повышение уровня сахара в крови. Даже если обычно у вас нет сахарного диабета, во время беременности может развиться так называемый гестационный диабет. Между 24-28-й неделями беременности проводится скрининг с помощью глюкозотолерантного теста, известного как тест с нагрузкой глюкозой. Результаты уточняют с помощью перорального теста с 50-75-100 граммами глюкозы, после чего устанавливают окончательный диагноз. Связанный с беременностью сахарный диабет может развиться примерно в одном случае из 150 беременностей. Если у вас наблюдаются такие симптомы, как жажда, потеря веса, чрезмерный аппетит, употребление большего количества воды и более частое мочеиспускание, чем обычно, а также постоянная усталость, проконсультируйтесь с врачом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить внезапное головокружение, при подъёме из положения лёжа сначала сядьте, а затем медленно встаньте. При боли в пояснице очень полезны лёгкая пренатальная йога или прогулки. Уделяйте особое внимание поступлению железа и кальция. Как насчёт того, чтобы сегодня прочитать малышу сказку или рассказать ему о ваших планах на будущее?') WHERE id = 'ae23805e-1ec4-470c-a370-e36eb29268eb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Жировая ткань (жировая прослойка) накапливается под кожей и вокруг внутренних органов. Она служит запасом энергии. Сердцебиение малыша регулируется мозгом и становится более ритмичным (140–150 ударов в минуту). Система кровообращения работает в полную силу.'), baby_message_ru = COALESCE(baby_message_ru, 'Я «набираю вес», Anacan! 🧸 В моём теле продолжает накапливаться жировая ткань. Раньше я был очень худеньким, но теперь мои ручки и ножки становятся пухлее. Эта жировая прослойка очень нужна мне, потому что после рождения она поможет регулировать температуру моего тела. Не волнуйся за меня: здесь мне тепло, и я сыт. Ты просто питайся правильно, а об остальном я позабочусь!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая луковица'), body_changes_ru = COALESCE(body_changes_ru, 'На этом этапе беременности вы можете заметить множество физических и эмоциональных изменений. Из-за усиления кровообращения увеличивается количество вагинальных выделений, пота, слизи и других жидкостей. Необычные сны также могут быть связаны с гормональными изменениями, вашим эмоциональным состоянием и ожиданиями. Во время беременности вы можете избегать физических упражнений, опасаясь навредить себе или малышу. Однако правильно подобранные упражнения не только облегчают роды, но и положительно влияют на здоровье малыша. В этот период можно регулярно выполнять упражнения для спины, укрепляющие позвоночник. Йога и пилатес для беременных также рекомендуются с первых недель беременности. Энергичные 30-минутные прогулки 3–5 дней в неделю будут очень полезны на протяжении всей беременности. Однако важно заниматься так, чтобы не переутомляться. Если вы не любите тренировки, можно танцевать. Танцы во время беременности укрепляют тело, повышают гибкость, снижают уровень стресса и улучшают настроение. Кроме того, это прекрасный способ уже сейчас начать веселиться вместе с малышом!'), daily_tip_ru = COALESCE(daily_tip_ru, 'Обязательно включайте в меню продукты, богатые кальцием. Употребляйте молочные продукты, брокколи, миндаль и кунжут. Если вы не будете получать достаточно кальция, малыш восполнит свою потребность за счёт ваших костей и зубов.') WHERE id = 'c7911f10-1eb8-49da-80ba-c909457132da';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На пальчиках рук и ног малыша, которые с каждым днём становятся длиннее, продолжают формироваться отпечатки. Каждая клетка, из которой состоит и формируется тело малыша, содержит молекулу ДНК. Хотя ДНК всех людей совпадает примерно на 99%, оставшийся 1% определяет уникальные особенности вашего малыша.;;;
Узоры, образованные видимыми линиями и изгибами на коже кончиков пальцев, формируются благодаря кожным выступам, которые называются папиллярными линиями. Благодаря этой структуре у каждого человека есть уникальные отпечатки пальцев. Ни у кого, даже у однояйцевых близнецов, отпечатки пальцев не совпадают. Иными словами, отпечаток пальца — это уникальный знак, который мы оставляем на всём, к чему прикасаемся. Рисунок папиллярных линий остаётся неизменным на протяжении всей жизни, если нет серьёзных травм или глубоких порезов.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне уже снятся сны! 💤 Anacan, учёные говорят, что я уже могу входить в фазу «REM-сна», то есть фазу быстрого движения глаз. Это означает, что я могу видеть сны! Интересно, что мне снится? Наверное, я слышу твой голос или представляю твоё лицо. Большую часть дня я сплю, но, когда просыпаюсь, становлюсь очень активным.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая луковица'), body_changes_ru = COALESCE(body_changes_ru, 'В последние годы пилатес стал одним из самых популярных видов физической активности среди будущих мам. Он расслабляет тело и помогает обрести душевное равновесие, предотвращает боли в спине и пояснице, а также позволяет будущей маме лучше почувствовать своё тело. Важно заниматься под руководством специалиста и выполнять упражнения, адаптированные для периода беременности.;;;
Что касается йоги, некоторые позы во время беременности категорически противопоказаны. Поэтому заниматься следует только с опытными инструкторами, которые проводят специализированные занятия для беременных. Изучите доступные варианты йоги для беременных и выберите наиболее подходящий для себя. ;;;
Опустите одно колено на пол, а другую ногу выставьте вперёд и присядьте. Вы почувствуете, как растягиваются мышцы ног и бёдер. Затем поменяйте ноги местами. Это упражнение укрепляет ноги, благодаря чему им будет легче выдерживать растущую нагрузку живота.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не пугайтесь необычных снов — это нормальная часть беременности. Перед сном послушайте успокаивающую музыку или почитайте книгу, чтобы расслабиться. Следите за тем, чтобы в спальне было прохладно.') WHERE id = '109a3421-ce4d-45f2-89cf-6db2482011b0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'У малыша начала формироваться зубная эмаль. Зуб состоит из эмали, дентина, цемента и внутренней мягкой ткани, известной как пульпа. Эмаль — самое твёрдое вещество в организме. Она покрывает зуб снаружи, образуя защитный слой.;;;
На этом этапе соли кальция, входящие в состав зубной эмали малыша, постепенно откладываются на органической основе зуба и кристаллизуются. Этот процесс продолжается до прорезывания зубов. Некоторые лекарства, принимаемые во время беременности, могут замедлить формирование зубной эмали. В результате на зубах может появиться жёлтая, серая или коричневая пигментация. Иногда может возникнуть гипоплазия — недоразвитие или недостаточное формирование тканей зуба.'), baby_message_ru = COALESCE(baby_message_ru, 'Я вздрагиваю от звуков! 🔊 Если ты внезапно чихнёшь, громко хлопнет дверь или заиграет громкая музыка, я подпрыгиваю на месте. Это называется «рефлексом Моро». Я внезапно развожу ручки и ножки, а затем снова прижимаю их к телу. Мой слух стал очень чувствительным. Пожалуйста, старайся находиться в спокойной обстановке — громкие звуки беспокоят меня.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая луковица'), body_changes_ru = COALESCE(body_changes_ru, 'Дыхательные упражнения помогают исправить нарушения осанки во время беременности и уменьшить боли в пояснице. Они позволяют освоить техники дыхания и расслабления, которые пригодятся во время родов, а также повышают эластичность и силу мышц живота и паховой области. Такие упражнения психологически подготавливают вас к родам, помогают контролировать дыхание во время схваток, правильно тужиться и рационально расходовать силы в процессе родов.;;;
Правильное дыхание повышает уровень кислорода в крови и способствует выведению токсинов из организма. Оно также помогает регулировать работу нервной и гормональной систем, укреплять иммунитет, улучшать работу клеток и состояние кожи. К его преимуществам относятся улучшение концентрации и памяти, ускорение процессов понимания и восприятия, развитие творческого и быстрого мышления, нормализация и повышение качества сна, а также обретение душевного спокойствия.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы ещё не чувствовали движений малыша, в эти дни можно спокойно прилечь, сосредоточиться на ощущениях в животе и попытаться уловить его первые лёгкие шевеления. Чтобы уменьшить боль в пояснице, носите обувь на низком каблуке. Поскольку потребность в кальции возрастает, добавьте в рацион больше молочных продуктов и зелёных овощей. Сегодня порадуйте себя небольшим подарком!') WHERE id = '5dba3d5c-bb87-4502-8385-7f27405dc9b2';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе плацента — важнейшее связующее звено между мамой и малышом — уже полностью функционирует. Она получает питательные вещества и кислород, необходимые для развития вашего малыша, непосредственно из вашей крови и передаёт их ему. Ещё одна очень важная и удивительная задача плаценты — защитная функция. В норме ваш организм мог бы воспринять малыша как «чужеродное тело» и атаковать его, однако плацента служит барьером и не позволяет клеткам вашей иммунной системы причинить ему вред.;;;
На осмотре у врача плацента уже хорошо видна, и на 18-й неделе она почти такого же размера, как ваш малыш. После этого и плацента, и малыш продолжат расти, но малыш будет увеличиваться быстрее.'), baby_message_ru = COALESCE(baby_message_ru, 'Я зеваю и икаю! 🥱 Моя диафрагма работает очень активно. Я часто икаю. Тебе это может показаться странным, но для меня это очень полезно. Так я очищаю лёгкие и дыхательные пути. А когда устаю, сладко зеваю. Отдохни вместе со мной, хорошо?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Сладкий перец'), body_changes_ru = COALESCE(body_changes_ru, 'Для многих мам эта неделя становится переломным моментом, когда они начинают ощущать движения малыша. Если вы их ещё не почувствовали, будьте внимательны: в животе может появиться лёгкое ощущение, похожее на «пузырьки газа» или «трепетание крыльев». Артериальное давление всё ещё может быть пониженным, из-за чего вы можете чувствовать слабость. Аппетит может достигнуть пика. Обмен веществ ускорился, и организму требуется дополнительная энергия для малыша. Однако после еды вас может беспокоить изжога. Из-за давления матки на желудок становится сложнее есть большими порциями.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Контролируйте артериальное давление. Если у вас часто кружится голова, пейте достаточно жидкости в течение дня и можете в небольшом количестве употреблять солёные продукты, например айран или солёные крекеры, если врач не рекомендовал иное.') WHERE id = '1343d008-0806-4770-8e2d-0452ed215751';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В организме вашего малыша началось формирование жировой ткани — одного из важнейших факторов, ускоряющих его рост. Жиры делятся на три основных класса: простые, сложные и производные.;;;
Наиболее известный вид жиров — холестерин — поступает с пищей или синтезируется внутри клеток. Наиболее активную роль в этом процессе играет печень. Жиры выполняют в организме очень важные функции: служат главным источником энергии, защищают внутренние органы и помогают сохранять тепло, предохраняя организм от холода.;;;
Жиры также необходимы для усвоения организмом витаминов A, D, E и K. Когда формирование жировой ткани малыша завершится, 90% этих жиров будет находиться под кожей. Остальная часть расположится в брюшной полости, между мышечными волокнами, а также вокруг жизненно важных органов, таких как почки, сердце и печень, защищая их.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои пальчики и отпечатки! 🧬 Anacan, мои отпечатки пальцев уже полностью сформировались. Эти узоры не изменятся на протяжении всей моей жизни. Я уникален! Я уже свободно двигаю ручками и ножками. Иногда сижу, скрестив ножки, а иногда «плаваю». Для меня это самое уютное место.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Сладкий перец'), body_changes_ru = COALESCE(body_changes_ru, 'Не беспокойтесь, если в один день живот кажется вам больше, а в другой — меньше. В те дни, когда он выглядит больше обычного, причиной может быть скопление газов или вздутие из-за некоторого замедления работы кишечника. Если показатели ультразвукового исследования (УЗИ) соответствуют сроку беременности, размер живота не имеет значения. Он полностью зависит от строения мышц живота, анатомических особенностей тела и реакции организма на изменения, вызванные беременностью.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Старайтесь не стоять подолгу, поскольку это может усилить боль в пояснице. Если у вас сидячая работа, каждый час вставайте и ходите в течение 5 минут. При лёгкой сухости глаз можно использовать препараты искусственной слезы, предварительно посоветовавшись с врачом. Малыш уже гораздо лучше чувствует ваши движения, поэтому продолжайте укреплять вашу связь.') WHERE id = 'e537dc02-2a8f-44e4-8520-858b44bd2d69';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Органы чувств вашего малыша уже стали довольно чувствительными. Исследования показывают, что ещё в утробе малыш способен отличать ваш голос от всех остальных звуков. Малыши сильнее реагируют на женские и высокие голоса, чем на мужские. Это связано с тем, что стенки матки по-разному пропускают звуковые волны: на этом этапе малыш лучше слышит высокие звуки. Первые звуки, которые слышит малыш, исходят из вашего тела: это биение сердца, ток крови и работа внутренних органов. По мере развития органов чувств малыш начинает воспринимать внешние звуки и запоминать их. Интересно, что после рождения его могут успокаивать звуки пылесоса, фена или посудомоечной машины, поскольку они напоминают ему об обстановке в утробе. Такие звуки называют «белым шумом» (white noise); это один из наиболее эффективных способов успокоить малыша, особенно при коликах.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой пол уже точно определён! 🩷💙 Если я девочка, мои матка и фаллопиевы трубы уже сформировались и находятся на своих местах. Если я мальчик, мои половые органы уже хорошо видны. Ты уже знаешь, кто я? Или хочешь сохранить это в тайне до моего рождения? В любом случае я твой малыш и очень тебя люблю!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Сладкий перец'), body_changes_ru = COALESCE(body_changes_ru, 'Сейчас, когда вы почти достигли середины беременности, важно быть внимательной к своему здоровью и здоровью малыша, если вы набрали больше веса, чем рекомендуется, или вам кажется, что вес увеличивается слишком быстро. Во время беременности суточная потребность в калориях у женщин с нормальным исходным весом возрастает всего примерно на 300 ккал. В среднем она составляет от 1900 до 2500 ккал. Эта норма индивидуальна для каждой женщины, а превышение необходимой калорийности может привести к нездоровому набору веса. Чтобы контролировать вес во время беременности, лучше есть часто и небольшими порциями. Перекусы между основными приёмами пищи помогут избежать переедания. Продукты, богатые железом, помогают уменьшить слабость, часто возникающую во время беременности. Употребление фасоли, рыбы и нежирного мяса не только помогает предотвратить чрезмерный набор веса, но и снижает риск гипертонии и преэклампсии.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При боли в пояснице выполняйте упражнение «тазовые часы». Лягте на спину и плавно двигайте тазом вперёд и назад. Это помогает расслабить мышцы поясницы. Кроме того, поддерживающий бандаж для беременных может уменьшить нагрузку на поясницу.') WHERE id = '10652607-2e60-42fd-8695-4db1781a35b4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Тело вашего малыша становится всё более пропорциональным. Поэтому объём крови, перекачиваемой сердцем по организму, поддерживается на определённом стабильном уровне. Развитие сердца, которое приобретает свою особую форму по мере дифференцировки и развития клеток, завершается в течение двух месяцев после оплодотворения. За 60 дней оно превращается в орган с 4 клапанами и 4 камерами и продолжает работать на протяжении всей жизни вашего малыша.;;;
На этом этапе сердце малыша бьётся с частотой 140-160 ударов в минуту. К 3 месяцам частота сердечных сокращений составит 135-140 ударов в минуту, к 6 месяцам — 130, к 9 месяцам — 120-125, к 12 месяцам — 115-120, к 24 месяцам — 115, к 4 годам — 100, а к 15 годам стабилизируется примерно на уровне 75-80 ударов в минуту.;;;
Кроме того, в этот период при ультразвуковом исследовании в сердце малыша могут быть обнаружены отверстия. Если родители не состоят в близком родстве и среди близких родственников нет людей с аномалиями сердца, во время беременности вы не принимали лекарства без назначения врача, не переносили тяжёлые инфекции, такие как краснуха, у малыша не диагностированы синдромы Дауна и Тёрнера и вы не употребляете алкоголь, такие отверстия с вероятностью 80% закроются до рождения малыша.'), baby_message_ru = COALESCE(baby_message_ru, 'Я играю с пуповиной! ➰ Моя любимая игрушка — пуповина. Я хватаю её, сжимаю и скручиваю. Но не бойтесь: она очень скользкая и прочная, поэтому я не могу её повредить. Эта игра развивает мой хватательный рефлекс и зрительно-моторную координацию. А чем занимаетесь вы? Мне здесь совсем не скучно!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая луковица'), body_changes_ru = COALESCE(body_changes_ru, 'Беременность способствует появлению варикозного расширения вен. Это связано с тем, что объём крови значительно увеличивается, чтобы обеспечить потребности малыша. В результате в сосудах циркулирует больше крови, и она чаще застаивается, особенно в ногах. Варикозное расширение вен во время беременности обычно возникает из-за давления растущего в матке малыша на вены в паховой области.;;;
Варикоз проявляется фиолетовыми или синими утолщёнными венами на коже, напоминающими паутину. По мере его прогрессирования могут возникать сильная боль, судороги, усталость в ногах, ощущение жара и распирания. Несколько простых, но важных привычек помогут предотвратить появление варикозного расширения вен.;;;
Старайтесь не сидеть долго, закинув ногу на ногу. Во время сидения двигайте стопами, чтобы активизировать кровообращение. Во время отдыха держите ноги выше уровня тела. Не поднимайте тяжести. Пейте больше воды и избегайте очень солёной пищи. Не проводите много времени за рулём. Не носите обувь на высоком каблуке. Используйте специальные компрессионные чулки. Спите на левом боку, а не на спине. Не принимайте слишком горячую ванну или душ и не носите чрезмерно тесную одежду.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить нагрузку на поясницу, старайтесь сидеть прямо и не стойте подолгу. Вечером отдохните 15 минут, приподняв ноги немного выше уровня сердца: это поможет уменьшить отёчность и улучшить самочувствие. Поскольку ваша потребность в кальции возросла, включите в рацион творог, сыр или миндаль. Завершите день любимым хобби.') WHERE id = '1282e899-e7f6-47fc-b213-e93601a67a84';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя во время обследования у врача скелет малыша может выглядеть как единая структура, на самом деле костная система устроена очень сложно. Она состоит из живых костных клеток — остеоцитов — и межклеточного вещества, которое заполняет пространство между ними и выделяется этими клетками. В состав межклеточного вещества входят фосфат кальция, карбонат кальция и фосфат магния, придающие костям твёрдость, а также небольшое количество таких минералов, как железо и натрий.;;;
Жёлтый костный мозг, компактное и губчатое костное вещество, надкостница, хрящи и кровеносные сосуды — всё это структуры, образующие кость. Хрящи расположены в местах соединения костей. Благодаря своей мягкой структуре они предотвращают трение и изнашивание костей, а также обеспечивают их рост в длину. Кровеносные сосуды доставляют кровь к костным клеткам.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои кости становятся крепче! 🦴 Мой скелет с каждым днём всё больше укрепляется. Кальций накапливается в костях и делает их твёрже. Я уже не похож на маленького резинового человечка. Мои рёбра, позвоночник, кости ног... Всё это превращается в настоящие кости. Молоко, которое вы пьёте, и сыр, который вы едите, становятся для меня строительным материалом. Спасибо, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая луковица'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности некоторые болезненные ощущения считаются нормальными. К ним относится и боль в ногах. Наиболее заметный сопутствующий признак — отёчность ног: могут отекать как голени, так и стопы. Отёк стоп вызывает боль и дискомфорт. Чтобы проверить наличие отёка, слегка надавите пальцем на область лодыжки. Дефицит кальция и магния, чрезмерная прибавка веса, недостаточная физическая активность, затруднённый отток крови к сердцу, а также низкий уровень калия, магния и кальция могут усиливать боль. Если у вас болят ноги, старайтесь давать им как можно больше отдыха. Ночью лучше спать на боку. Контролируйте прибавку веса. Во время сна держите ноги в приподнятом положении — это поможет облегчить дискомфорт. Холодная вода способствует уменьшению отёка мышц и сужению кровеносных сосудов. Поэтому прохладный душ и холодный компресс могут оказать благоприятное действие. Кроме того, боль помогают уменьшить массаж и физические упражнения. Чтобы снизить отёчность, не забывайте пить достаточно жидкости.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить судороги в ногах, употребляйте продукты, богатые магнием. Перед сном могут помочь растяжка мышц ног и тёплый душ.') WHERE id = '79568d36-35e8-4a60-8ad2-b99e6d2f45e1';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Пока малыш находится в утробе, его мозг производит больше нейронов, чем необходимо. После рождения неиспользуемые и не получающие стимуляции нейроны исчезают в ходе процесса, называемого «синаптическим прунингом».;;;
Каждый из 100 миллиардов нейронов мозга образует особые точки контакта с тысячами других нейронов. К двум-трём годам количество таких связей достигает примерно 15.000. Помимо управления жизненно важными процессами, такими как дыхание и сердцебиение, мозг регулирует и высшие функции — мышление, память и речь.;;;
Каждая новая поверхность, к которой прикасается ваш малыш, каждый запах, который он ощущает, и каждый звук, который он слышит, способствуют формированию этих нервных связей. Их укрепление и сохранение зависят от регулярного повторения соответствующих стимулов.'), baby_message_ru = COALESCE(baby_message_ru, 'Здравствуйте, Anacan! Сейчас я размером со сладкий перец. Моя нервная система развивается. Особое вещество под названием «миелин» покрывает мои нервные волокна. Благодаря ему сигналы от мозга к телу будут передаваться быстрее. С каждым днём я становлюсь умнее!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Сладкий перец'), body_changes_ru = COALESCE(body_changes_ru, 'Теперь ваша беременность уже заметна окружающим. На протяжении беременности матка увеличивается, чтобы вместить малыша, плаценту и околоплодные воды, а ближе к её окончанию вес матки достигает примерно 1100 граммов. Это почти в 20 раз больше её обычного веса. Перед родами её вместимость достигает примерно 5 литров, а объём увеличивается в 500-1000 раз по сравнению с обычным. Это происходит не за счёт увеличения количества гладкомышечных клеток матки, а благодаря увеличению их размера.;;;
В первые месяцы беременности матка сохраняет грушевидную форму, но примерно к 12-й неделе становится шарообразной и поднимается над костями таза. После этой недели матка увеличивается настолько, что её можно прощупать над лобковой костью. В последующие недели она растёт вверх, приобретая овальную форму и занимая всё больше места в брюшной полости. По мере роста матка прилегает к передней брюшной стенке, оттесняя кишечник в стороны и вверх, к печени.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте эти 18 недель небольшим путешествием — отправьтесь на прогулку! Чтобы уменьшить боль в пояснице, старайтесь сидеть прямо и носить удобную обувь. Во время сна обязательно ложитесь на левый бок: это благоприятно влияет и на приток крови к малышу, и на работу ваших почек. Не забывайте пить достаточно жидкости и употреблять продукты, богатые кальцием (молоко, йогурт, миндаль).') WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Если ваш малыш — девочка, на этом этапе в её яичниках уже началось образование яйцеклеток. На ранних этапах развития эмбрионы обоих полов имеют по две пары половых протоков. У мальчиков мезонефральные протоки формируют мужскую репродуктивную систему, а у девочек парамезонефральные протоки обеспечивают развитие женской репродуктивной системы. По мере дифференцировки половых органов у девочек эти протоки превращаются в матку и влагалище. Интересно, что до рождения в яичниках девочки образуется более 2 миллионов яйцеклеток. Это максимальное количество яйцеклеток, которое будет у неё за всю жизнь.;;;
К подростковому возрасту их число сокращается примерно до 400,000–500,000. После начала репродуктивного периода ежемесячно теряется около 1000 яйцеклеток. С возрастом уменьшается не только их количество, но и меняется качество: например, у женщины в 30 лет хромосомно нормальной является примерно каждая 2-3-я яйцеклетка, а к 40 годам — лишь каждая 5-6-я.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои нервные импульсы ускоряются! ⚡ Сигналы от мозга к телу теперь передаются по «сверхскоростному» пути. Благодаря миелиновой оболочке я всё лучше управляю своими движениями. Теперь я двигаюсь не случайно, а целенаправленно прикасаюсь и поворачиваюсь. Мой мозг программируется, словно гигантский компьютер. Вы можете мной гордиться!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Сладкий перец'), body_changes_ru = COALESCE(body_changes_ru, 'Пройти всю беременность совсем без прибавки веса или набрав всего несколько килограммов — нереалистичная и неправильная цель. Если есть беременность, естественно, будет и прибавка веса. Во втором триместре, в который вы вступили, малыш начинает быстро расти и развиваться. Поэтому именно в этот период прибавка веса становится заметной. По мере роста малыша увеличивается количество питательных веществ и энергии, которые он получает от вас, поэтому вам требуется больше пищи. Таким образом, на этом сроке беременности прибавка примерно на 500 граммов в неделю считается нормальной.;;;
Такие добавки, как нитриты и нитраты, которые используются при производстве переработанных мясных продуктов, например сосисок, салями и суджука, могут навредить здоровью малыша. ;;;
Продукты, богатые углеводами, уменьшают тошноту. Однако крахмалистые продукты, такие как белый рис и макароны, повышают уровень сахара в крови. Чтобы получать достаточно витаминов во время беременности, крайне важно увеличить потребление фруктов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если у вас возникло выраженное затуманивание зрения или перед глазами появились «вспышки света», немедленно обратитесь к врачу. Это может быть признаком высокого артериального давления. Небольшое затуманивание зрения обычно считается нормальным.') WHERE id = '29db8583-08d7-4065-8fa7-18665ece5422';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В течение следующего месяца тело вашего малыша начнёт покрываться особым слоем, который называется первородной смазкой — vernix caseosa. Это белое кремообразное вещество служит первой защитой малыша в утробе матери и оберегает его вплоть до первого купания.;;;
Исследования показывают, что первородная смазка содержит около 40 различных белков, поддерживающих иммунитет. Интересно, что половина этих белков не встречается больше нигде в природе, кроме первородной смазки. Эти уникальные вещества обладают антимикробными свойствами и надёжно защищают малыша от инфекций.;;;
Слой первородной смазки также выполняет для малыша роль естественного увлажняющего средства и регулятора температуры. Он препятствует потере жидкости организмом малыша, способствует образованию новых клеток кожи и благодаря своей скользкой текстуре облегчает процесс родов.'), baby_message_ru = COALESCE(baby_message_ru, 'В моём мозге зажигаются огоньки! 🧠 Anacan, мой мозг теперь работает как гигантский компьютер. Формируются специальные центры зрения, слуха, вкуса, обоняния и осязания. Я не просто расту — я готовлюсь познавать мир. Когда я слышу ваш голос, в моём мозге активируется «центр слуха». Наша связь уже подтверждена наукой!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Помидор'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности кожа становится более чувствительной и сильнее реагирует на солнечные лучи. Повышение уровня меланоцитстимулирующего гормона, который вырабатывается гипофизом и воздействует на клетки, производящие отвечающий за цвет кожи меланин, делает кожу особенно склонной к потемнению.;;;
Под воздействием солнечных лучей пигментные пятна беременных могут появиться или стать более выраженными — это очень распространённое явление. Кроме того, длительное пребывание на солнце может привести как к чрезмерному повышению температуры тела, так и к обезвоживанию. Оба состояния способны негативно повлиять на течение беременности. По всем этим причинам во время беременности не рекомендуется долго находиться на солнце.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в пояснице, полностью откажитесь от обуви на высоком каблуке. Когда сидите, подкладывайте под поясницу небольшую подушку. Не перенапрягайте мышцы в средней части живота, а вставая с кровати, сначала повернитесь на бок.') WHERE id = 'bc3702e9-c9f0-4b15-a3b9-8dd5c0a6dd34';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже может видеть сны! Благодаря продолжающему развиваться мозгу малыш уже способен переходить в фазу быстрого сна — REM-фазу. Именно в этой фазе сна в мозге формируются сновидения. Она наблюдается на 4-й стадии сна и занимает в среднем 15-20% его общей продолжительности. Эта фаза наступает примерно через 30-90 минут после засыпания.;;;
Существует 4 различные стадии сна. На 1-й стадии может возникнуть ощущение, что не удаётся полностью уснуть или будто вы падаете с высоты. На 2-й стадии организм готовится к полноценному сну. Частота сердцебиения и температура тела начинают снижаться. 3-я и 4-я стадии — это фазы глубокого сна, во время которых могут наблюдаться эпизоды хождения во сне. На этих стадиях, называемых глубоким сном, организм восстанавливается, ткани заживают, ненужные клетки удаляются, а иммунная система избавляется от ненужных веществ. Именно на этих стадиях сна малыши растут и развиваются.;;;
Во время REM-сна дыхание учащается, а глаза начинают совершать быстрые хаотичные движения. Благодаря этому сновидения кажутся очень реалистичными. Но самое важное заключается в том, что в этой фазе мозг активен почти так же, как во время бодрствования. Начиная ещё с внутриутробного периода и после рождения малыши проводят большую часть времени в REM-сне. Это помогает им лучше объединять полученный опыт в самый важный период развития. REM-сон составляет около 50% цикла сна малыша. По мере взросления эта фаза постепенно сокращается, а с возрастом её доля быстро уменьшается.'), baby_message_ru = COALESCE(baby_message_ru, 'Я оберегаю вас! 🥚 Если я девочка, в моих крошечных яичниках уже есть 6 миллионов яйцеклеток! Это значит, что ваши будущие внуки уже сейчас находятся во мне. Если я мальчик, мои половые органы продолжают развиваться. Род продолжается, Anacan. Вы создаёте историю.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Помидор'), body_changes_ru = COALESCE(body_changes_ru, 'Для сохранения физического и эмоционального здоровья во время беременности очень важно правильно принимать витамины в подходящих дозах. Недостаточное поступление витаминов, влияющих на все органы и системы организма, может привести к различным проблемам. Витамины — это содержащиеся в натуральных продуктах вещества, которые регулируют процессы в организме, укрепляют его защитные силы, способствуют обновлению клеток и выработке энергии. Они ежедневно необходимы организму в определённом количестве, а при их дефиците должны дополнительно поступать извне.;;;
Недостаточное потребление витаминов во время беременности может привести к нарушениям зрения, постоянной усталости, трещинам на языке и коже, анемии, умственному переутомлению и симптомам депрессии, появлению синяков и пятен на коже, болям в костях и потере мышечной массы.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Во время сна старайтесь обязательно лежать на левом боку: это обеспечивает максимальный приток крови к малышу и матке. Для уменьшения боли в пояснице выполняйте лёгкие упражнения на растяжку. Уравновешивайте возросший аппетит фруктами и овощами. Малыш уже слышит вас гораздо лучше, поэтому сегодня включите ему любимую спокойную музыку.') WHERE id = '695bdf70-cf7b-4ed0-9ff8-c4418720fc60';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе ваш малыш проводит во сне 90% времени. Плавая в амниотической жидкости, он в течение дня убаюкивается вашими движениями и спокойно засыпает. А ночью, когда вы перестаёте двигаться и жидкость становится менее подвижной, малыш начинает просыпаться. Считается, что эта привычка — одна из причин, по которой новорождённые часто просыпаются по ночам.;;;
Поскольку стенка матки сглаживает различия между днём и ночью во внешнем мире, малышу может потребоваться 1-2 месяца после рождения, чтобы привыкнуть к этому ритму. А важнейшая причина, по которой он проводит во сне почти весь день, — гормон роста.;;;
Этот гормон белковой природы вырабатывается клетками передней доли гипофиза и обеспечивает рост тела и развитие тканей. Самое важное, что он синтезируется преимущественно во время сна малыша. То есть чем больше ваш малыш спит, тем здоровее и быстрее он растёт.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня уже есть режим сна! 🌙 Anacan, я не бодрствую целыми днями. У меня тоже есть время для сна и бодрствования. Обычно, когда ты ходишь или двигаешься, меня укачивает, и я засыпаю. А когда ты ложишься отдохнуть, я просыпаюсь и устраиваю дискотеку. Наши режимы немного отличаются, прости!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Манго'), body_changes_ru = COALESCE(body_changes_ru, 'До беременности каждая молочная железа в среднем весит 230-250 граммов. Во время беременности из-за расширения молочных протоков грудь увеличивается в объёме и становится чувствительной. Может появиться ощущение тяжести в груди. Размер правой и левой молочных желёз может различаться. Под кожей груди могут стать заметны сосуды. В результате вес груди может увеличиться вдвое по сравнению с обычным. Матка, которая обычно весит около 60 граммов, на этом этапе достигает примерно 300 граммов. К моменту родов её вес увеличится до 1000 граммов. Сейчас количество околоплодных вод, окружающих малыша, составляет около 350-400 граммов, а к концу беременности увеличится до 800 граммов. Начиная с этой недели плацента по размеру и весу почти не отличается от малыша, а к концу беременности будет весить примерно 600-650 граммов. Кроме того, объём межтканевой жидкости увеличится на 1500-2000 граммов по сравнению с периодом до беременности. Запасы жира, которые организм накапливает для будущего грудного вскармливания, на этом этапе достигают 400-500 граммов, а к концу беременности составят 3500-4000 граммов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить покраснение и ощущение жара в руках, мойте их прохладной водой. Не прикасайтесь к химическим чистящим средствам. Чтобы защитить лицо от солнца, обязательно носите головной убор и используйте крем с SPF.') WHERE id = 'd0d5f1e7-e726-4e8b-9248-bacff687b744';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На коже головы вашего малыша начинают развиваться настоящие волосяные фолликулы, отличающиеся от фолликулов других волосков на теле. Волосы состоят из прочного белка под названием кератин. Особые связи в его внутренней структуре обеспечивают прочность волос. Если защитный наружный слой повреждается, волосы начинают ломаться.;;;
Корень волоса формируется внутри фолликула в нижнем слое кожи, затем волос растёт, проходит через верхний слой кожи и выходит наружу. Цвет волос малыша определяется пигментом меланином, информация о котором заложена в ДНК вашей и вашего партнёра. В зависимости от количества этого пигмента волосы будут светлыми или тёмными.;;;
Тип волос определяется плотностью дисульфидных связей: в кудрявых волосах таких связей больше. Хотя волос кажется очень тонким, на самом деле он состоит из нескольких слоёв и множества волокон. Секущиеся кончики появляются именно из-за расслоения этих волокнистых структур.'), baby_message_ru = COALESCE(baby_message_ru, 'Я покрыт первородной смазкой! 🧼 Белое кремообразное вещество на моём теле теперь стало ещё плотнее. Оно защищает мою кожу от длительного пребывания в воде. А во время рождения поможет мне легче пройти через родовые пути. Природа всё предусмотрела, правда? У меня есть все средства защиты, чтобы родиться здоровым.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Манго'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за гормональных изменений во время беременности слизистая оболочка носа может отекать, вызывая заложенность. При этом количество выделений из носа увеличивается. Как и при синусите, из-за перекрытия околоносовых пазух может возникнуть заложенность носа. Это одна из причин появления храпа. Кроме того, по мере роста малыша вес начинает быстро увеличиваться. Дополнительный набор веса также возможен из-за изменения рациона. Избыток жировой ткани распределяется по разным участкам тела, приводя к увеличению объёма тканей. Женщины, набравшие во время беременности лишний вес, более склонны к храпу. Поэтому важно не допускать набора веса сверх нормы для здорового течения беременности. Следует придерживаться сбалансированного рациона и контролировать прибавку веса.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить изжогу, не ложитесь сразу после еды и старайтесь питаться часто, но небольшими порциями. При боли в пояснице подкладывайте под спину небольшую подушку, когда сидите, и держите спину прямо. Не забывайте принимать железо, чтобы полностью удовлетворить потребность в нём как вашего организма, так и организма малыша. Сегодня вечером уделите немного времени себе и послушайте спокойную музыку.') WHERE id = '481d4a59-0854-49d1-ad3d-0f418a6738b5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе вес вашего малыша приближается примерно к 300 граммам. Совершенно нормально, если во время обследования врач обнаружит, что развитие малыша немного опережает расчётный срок или отстаёт от него. Разница до 2 недель считается нормой.;;;
В первые месяцы развития у 60% малышей срок может опережать срок, рассчитанный от даты последней менструации. Ближе к концу второго триместра эта разница обычно уменьшается, и размеры начинают соответствовать сроку беременности. Если разница превышает 2 недели, врач может направить вас на консультацию к перинатологу или на дополнительные обследования для более тщательного наблюдения.;;;
Если малыш немного «отстаёт» от расчётного срока, это не обязательно означает задержку развития. Ультразвуковые измерения очень чувствительны: на результат влияют положение малыша, методика измерения врача и технические характеристики аппарата. Даже измерения, выполненные с разницей в несколько минут, могут незначительно различаться, поэтому при расхождении до 2 недель причин для беспокойства нет.'), baby_message_ru = COALESCE(baby_message_ru, 'Готовы к большому обследованию? 🩺 В ближайшие дни нам предстоит «анатомическое сканирование» (доплерография). Врач по очереди проверит каждый мой орган — сердце, мозг, пальчики. Я помашу тебе ручкой! Если нам повезёт, ты также сможешь точно узнать мой пол. (Если я не буду прятаться).'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Манго'), body_changes_ru = COALESCE(body_changes_ru, 'Начиная с этой недели пигментированная область вокруг сосков будет постепенно увеличиваться. Эта область, называемая ареолой, может занимать почти половину молочной железы. По мере увеличения груди положение соска и ареолы меняется. Это нормально и может продолжаться до 12-го месяца после родов. Ареола — это тёмное кольцо, окружающее сосок. Её форма, цвет и размер индивидуальны и зависят в том числе от оттенка кожи. После первой беременности ареола обычно становится темнее и сохраняет этот цвет. Внутри ареолы расположены небольшие сальные железы, которые называются железами Монтгомери.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить нагрузку на поясницу, старайтесь сидеть прямо и не стойте подолгу. Вечером отдохните 15 минут, подняв ноги немного выше уровня сердца: это поможет уменьшить отёчность и снять нагрузку с сосудов. Уделите особое внимание приёму железа и кальция. Завершите день, прочитав малышу вслух несколько страниц любимой книги.') WHERE id = '6ad08d05-7381-4d47-abac-7c50836b90a0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Первым движением малыша, которое вы почувствуете, может оказаться икота! Икота — это внезапный вдох, возникающий в результате резкого сокращения диафрагмы — мышцы, разделяющей брюшную и грудную полости, — и смыкания голосовой щели. Хотя икота часто встречается у новорождённых, на самом деле этот процесс начинается ещё в утробе матери.;;;
Ваш малыш икает, потому что заглатывает амниотическую жидкость в полости матки. Некоторых мам это беспокоит, но на самом деле икота очень полезна для развития малыша. Благодаря ей укрепляется сосательный рефлекс, который поможет малышу начать питаться сразу после рождения.;;;
Когда малыш заглатывает амниотическую жидкость, сокращение и расслабление диафрагмы тренирует его лёгкие. Жидкость, попадающая в лёгкие во время сосательных и глотательных движений и икоты, способствует их развитию и подготовке к дыханию. По мере приближения родов малыш заглатывает больше жидкости, поэтому приступы икоты могут становиться чаще.'), baby_message_ru = COALESCE(baby_message_ru, 'Привет, Anacan! Я уже размером с манго. Мои ручки и ножки теперь пропорциональны телу. Я маленький человечек! Теперь я могу толкаться сильнее. Будьте готовы!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Манго'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности необходимо уделять особое внимание питанию. Цинк — один из важнейших питательных элементов, который обязательно должен присутствовать в вашем рационе. Это один из основных минералов, входящих в структуру белков и клеточных мембран. Кроме того, он участвует в процессе производства белков, информация о которых заложена в генах. Достаточное количество цинка в организме также обеспечивает нормальную и слаженную работу более 100 ферментов.;;;
Во время беременности потребность организма в цинке возрастает. Достаточное поступление цинка в этот период играет важную роль в формировании ДНК и белковых структур. Поэтому во время беременности, когда образование клеток происходит чрезвычайно быстро, получать достаточно цинка особенно важно. Если суточная потребность небеременной женщины составляет 8 mq, то у беременной женщины она возрастает до 11 mq. Кормящей маме необходимо получать 12 mq цинка в день. Больше всего цинка содержится в мясе и морепродуктах.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте маленьким приятным событием то, что вы прошли уже половину пути! Чтобы уменьшить боль в спине, старайтесь сидеть прямо и не поднимайте тяжёлые предметы. Если у вас отекают ноги, в конце дня немного приподнимите их и отдохните. Продолжайте пить достаточно воды и включать в рацион продукты, богатые клетчаткой. Завтра нас ждёт важный день — «экватор»!') WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поздравляем! Вы уже прошли половину беременности.;;;
Если ваш малыш — девочка, в её яичниках активно продолжают формироваться яйцеклетки. У мальчиков яички уже сформировались и продолжают опускаться к своему постоянному месту. Яички — важнейшая часть мужской репродуктивной системы. Для нормального развития сперматозоидов им необходима среда примерно на 2 градуса прохладнее температуры тела. Именно поэтому мошонка расположена снаружи тела: более низкая температура предотвращает разрушение сперматозоидов.;;;
Яички выполняют несколько важных функций: вырабатывают гормон тестостерон, способствуют развитию мужских физических признаков и обеспечивают производство сперматозоидов. После полного созревания эта система сможет производить до 200 миллионов сперматозоидов в сутки.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня растут волосы! 💇‍♂️ На коже моей головы начинают появляться настоящие волосики. Пока они очень тонкие и бесцветные, но, возможно, я рожусь с волосами. Знаете, как бабушки говорят при изжоге: «Это у малыша волосы растут»? Может быть, они и правы?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Манго'), body_changes_ru = COALESCE(body_changes_ru, 'На этом этапе матка расположена в три раза выше, чем до беременности. Начиная с этой недели и до родов она будет подниматься примерно на 1 sm каждую неделю. По мере роста матки положение внутренних органов будет меняться. Из-за расслабления сфинктера желудка кислое содержимое может попадать в пищевод, вызывая изжогу.;;;
Изжога и кислотный рефлюкс часто встречаются во время беременности. Чтобы избежать изжоги, рекомендуется ограничить такие продукты, как помидоры, лук, чеснок, газированные и кислые напитки, мороженое, пропитанные сиропом сладости, шоколад, жареные блюда, томатная паста, острая пища, соленья, апельсины и острый перец, а также отказаться от курения. Если вы почувствовали изжогу, можно сначала попробовать выпить тёплого молока. Оно может уменьшить неприятные ощущения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Порадуйте себя приятным днём в честь того, что половина пути уже пройдена! Чтобы предотвратить боль в спине, старайтесь сидеть прямо и обязательно отдыхайте лёжа на левом боку. Обратите особое внимание на поступление железа, поскольку оно всё больше необходимо малышу для кроветворения. Ежедневные лёгкие прогулки продолжительностью 20-30 минут помогут вам чувствовать себя бодрее.') WHERE id = 'ac85f07b-25b5-4dda-969a-4a8dfc9a2528';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя в эти недели тело малыша полностью покрыто волосками лануго, в области бровей и головы они становятся гуще и уже хорошо заметны. Брови нужны не только для красоты: они выполняют важную функцию, защищая глаза от капель пота, воды и других веществ, которые могут попасть сверху. Интересно, что длина бровей у девочек и мальчиков одинакова — примерно 10 mm, — но их густота различается. В области бровей вашего малыша формируется в среднем 200-300 волосков. Если ваш малыш — мальчик, структура его бровей будет схожа со структурой будущих усов и бороды. Волоски бровей и ресниц считаются самыми стойкими на теле: они седеют позже остальных и при отсутствии особых проблем со здоровьем выпадают реже всего.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои почки работают великолепно! 💧 Я заглатываю амниотическую жидкость, мои почки фильтруют её, и она возвращается в виде чистой мочи. Эта жидкость защищает меня, поддерживает мою температуру и помогает двигаться. Я сам очищаю свой бассейн. А вы пейте достаточно воды, чтобы моей воды было много и она оставалась чистой.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Манго'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности обычно неподвижные сочленения таза становятся более подвижными и немного расширяются, чтобы малышу было легче пройти во время родов. Поэтому в этот период у вас могут возникать некоторые нарушения равновесия. Выход из таза имеет овальную форму: он длиннее в переднезаднем направлении и короче в поперечном. Самая узкая часть этого пути находится посередине, где расположены некоторые костные выступы. Между головкой малыша и овальной частью таза имеется пространство всего до 20 sm. Пока малыш находится в утробе, его головка наклонена вперёд, а подбородок прижат к груди. Благодаря этому головка входит в таз своим наименьшим диаметром. И головка малыша, и тазовые кости не являются абсолютно жёсткими и неподвижными. На протяжении беременности они изменяются, приспосабливаясь друг к другу. Кости черепа малыша могут немного смещаться относительно друг друга и остаются более мягкими, чем кости взрослого человека. Благодаря этому малыш может пройти через родовые пути.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить усталость и отёчность ног, чаще меняйте положение тела в течение дня и не оставайтесь неподвижными надолго. Чтобы получать больше железа, добавьте в рацион красное мясо, чечевицу и тёмно-зелёные овощи. Ваш малыш уже всё слышит, поэтому сегодня вы можете вслух прочитать ему свою любимую книгу.') WHERE id = '34d9ab3e-6f7e-4354-93cc-e6f91180c7df';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Пищеварительная система вашего малыша уже достигла важного этапа развития. Его желудок полностью готов вырабатывать особое вещество — фермент химозин, предназначенный для переваривания молока.;;;
Процесс переваривания молока начинается со створаживания содержащегося в нём белка казеина. После рождения, когда малыш будет пить молоко, химозин в его желудке сразу же начнёт створаживать его. Затем в работу включится фермент пепсин, который расщепит белок на аминокислоты, чтобы клетки малыша могли их усвоить. Под действием химозина молоко приобретает неоднородную консистенцию, напоминающую йогурт или творог. Пепсин расщепляет эти белки, после чего питательные вещества поступают в кровь и разносятся по всему организму.;;;
После рождения малыши иногда срыгивают лишнее молоко. Если молоко, выходящее изо рта малыша, уже не жидкое, а более густое и створоженное, это означает, что ферменты в его желудке активно и нормально переваривают молоко.'), baby_message_ru = COALESCE(baby_message_ru, 'Готовлю свой голос! 🎤 Моя гортань и голосовые связки полностью готовы. Сейчас мне не хватает только воздуха. Как только я появлюсь на свет, с первым вдохом скажу вам: "Привет, мама!" (то есть "Уа-а!"). Представляете этот момент? Я тренируюсь ради него каждый день.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Банан'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности необходимо внимательно относиться к выбору травяных чаёв. Чай с мелиссой и имбирный чай можно пить после одобрения вашего врача. Известно, что употребление обладающего успокаивающим действием чая с мелиссой во время беременности не оказывает вредного воздействия. Женщины, которым трудно заснуть или которые страдают бессонницей, могут выпить перед сном чашку чая с мелиссой. Богатый антиоксидантами имбирь полезен и в виде чая. В первом триместре, когда часто возникают тошнота и рвота, имбирный чай может помочь уменьшить эти симптомы. Чай из листьев малины может по-разному воздействовать на мышцы. Малиновый чай способен влиять на родовые схватки, поэтому его употребление в последние недели беременности может быть рискованным. Зелёный чай очень полезен благодаря высокому содержанию антиоксидантов. Он также способствует выведению токсинов из организма. Однако зелёный чай может ухудшать усвоение фолиевой кислоты и тем самым негативно влиять на малыша. Поэтому во время беременности его обычно не рекомендуют. Употребление чая с шалфеем во время беременности может повлиять на схватки или повысить риск кровотечения. Поэтому не следует пить травяные чаи, способствующие разжижению крови.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы избежать запоров, ешьте больше продуктов, богатых клетчаткой, и пейте достаточно воды. Не стойте и не сидите подолгу. Упражнения Кегеля улучшают кровообращение в области тазового дна и также могут помочь при геморрое.') WHERE id = '0c65c176-54fc-4e82-af61-c7b6cff2d77a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Примерно 70% беременных женщин начиная с этой недели ощущают первые движения малыша. Это первый физический контакт с вашим малышом и один из самых волнующих моментов беременности.;;;
Малыш пока ещё недостаточно большой, чтобы вы могли регулярно ощущать его движения каждый день. Совершенно нормально почувствовать активность в один день, а затем ничего не ощущать в течение нескольких дней. Обычно движения становятся регулярными после середины 20-х недель. Если вы пока не почувствовали ни одного шевеления, не беспокойтесь: до 24-й недели это считается нормой. Причиной могут быть натяжение связок живота, положение малыша или жировая ткань в области живота.;;;
По мере роста матка смещает кишечник в стороны. Вызванная этим давлением перистальтика кишечника, газы или пищеварительные процессы иногда могут напоминать движения малыша. Со временем вы научитесь различать эти ощущения.'), baby_message_ru = COALESCE(baby_message_ru, 'ПОЛОВИНА ПУТИ! 🏁 Поздравляю, Anacan! Мы преодолели ровно половину (50%) нашего 40-недельного марафона. Я уже размером с банан! Невероятно, правда? Только посмотрите, как я вырос! Ваш живот уже поднялся до уровня пупка. Мы движемся к финишу!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Банан'), body_changes_ru = COALESCE(body_changes_ru, 'Минералы имеют огромное значение для защиты клеток и здоровья зубов, костей и кожи. Кроме того, они играют важную роль в регулировании артериального давления, сердечного ритма, работы мышц, поддержании водного баланса в организме, репродуктивной функции и многих других процессов. Среди этих минералов одним из самых важных на протяжении всей беременности является кальций. Количество кальция в организме важно не только для костей: этот минерал участвует во всех процессах организма. Он также необходим для здоровья и прочности зубов и играет большую роль в работе мышц. Кальций особенно важен для использования железа организмом и переноса питательных веществ через клеточные мембраны.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отпразднуйте половину пройденного пути чем-нибудь приятным! Чтобы уменьшить боль в пояснице, старайтесь не сидеть, закинув ногу на ногу. Ночью обязательно ложитесь на левый бок и кладите подушку между коленями. Продолжайте получать достаточно железа (чечевица, красное мясо, шпинат), чтобы полностью обеспечить потребности в крови как вашего организма, так и организма малыша.') WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Вес вашего малыша составляет 250–280 граммов. Как же быстро он растёт, правда? Сердце вашего стремительно растущего малыша продолжает работать без остановки, чтобы перекачивать больше крови по всему его организму. Благодаря этому сердечная мышца продолжает развиваться и укрепляться.;;;
Благодаря сокращениям сердца кислород и питательные вещества поступают к каждой клетке организма малыша. Эти сокращения необходимы для поддержания жизненно важных функций.'), baby_message_ru = COALESCE(baby_message_ru, 'Я "ем"! 🍽️ Anacan, моя пищеварительная система уже работает. Я глотаю амниотическую жидкость, а мой кишечник усваивает из неё сахар и воду. Вкус этой жидкости меняется каждый день — вчера я почувствовал вкус блюда с чесноком, которое вы ели! В моём кишечнике накапливается первый кал, который называется "меконий". Не волнуйтесь, я приберегу его для подгузника и не буду ничего пачкать!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Морковь'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности уделяйте особое внимание поступлению железа, необходимого для вашего здоровья. В этот период потребность в железе увеличивается почти вдвое. Во время беременности объём крови в организме становится на 50% больше, чем до неё. А железо необходимо для образования клеток крови.;;;
Железо также играет важную роль в работе структур, обеспечивающих мышцы и соединительную ткань кислородом, и в поддержке иммунной системы. На уровень железа в крови влияют другие вещества, поступающие в организм. Кальций, а также содержащие кофеин напитки, например чай и кофе, могут препятствовать усвоению железа.;;;
Витамин C, напротив, способствует усвоению железа. Поэтому после употребления продуктов с высоким содержанием железа полезно выпить стакан фруктового сока или съесть фрукт.;;;
Особенно во втором и третьем триместрах железо жизненно важно для развития малыша и плаценты. Необходимое для крови железо можно получать благодаря сбалансированному питанию. Чтобы снизить риск анемии, не забывайте регулярно проходить обследования.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы замечаете отёки ног, чаще меняйте положение тела в течение дня, а по вечерам отдыхайте, положив ноги на подушку. Чтобы сохранить эластичность кожи, пейте достаточно воды и используйте увлажняющие масла. Следите за достаточным поступлением кальция и магния, чтобы предотвратить судороги в ногах.') WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже слышит вас!;;;
К 20-й неделе беременности формирование ушей малыша в основном завершается. Однако их развитие продолжается до 24-й недели. Ваш малыш уже может воспринимать внешние звуки с помощью внутреннего уха и слышать ваш голос, когда вы разговариваете.;;;
В течение нескольких недель слух малыша станет настолько чувствительным к вашему голосу, эмоциональному состоянию и поведению, что под их влиянием будут меняться его сердцебиение и движения. Когда вы говорите спокойно, малыш тоже успокаивается, а его сердцебиение замедляется. Особенно после 24 недель при громком шуме малыш может вздрогнуть, а иногда после этого начать икать.;;;
В этот период спокойная музыка с низким звучанием помогает малышу расслабиться. Вы можете включать её обычным способом или использовать специальные наушники, предназначенные для размещения на животе.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня есть брови и ресницы! 👁️ Anacan, теперь моё лицо совсем как у человека. Над глазами у меня появились тонкие брови, а на веках — длинные ресницы. Теперь я ещё красивее. Я готовлюсь моргать, но смогу открыть глаза только через несколько недель. Вы представляете меня? А я представляю вас.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Морковь'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности у вас могут возникнуть некоторые проблемы с кожей. Например, повышенная жирность кожи может привести к появлению акне. Если вы столкнулись с этим, очищайте кожу натуральным средством два раза в день. Следите за тем, чтобы используемые кремы не содержали масел. Не принимайте препараты от акне внутрь. Они могут вызывать тяжёлые пороки развития у малыша. После консультации с врачом вы можете начать принимать добавки с омега-жирными кислотами, необходимыми для развития малыша. Омега-жирные кислоты относятся к незаменимым жирам, которые должны поступать в организм. Они особенно важны для развития мозга и зрения малыша. Исследования показывают, что омега-жирные кислоты снижают риск преждевременных родов и способствуют рождению малышей с большей массой тела.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Наполните холодильник полезными продуктами. Если под рукой будут вымытые фрукты, овощи, йогурт или творог, вам будет легче отказаться от вредных "перекусов".') WHERE id = '11b2d6de-75e4-4639-b4fc-0a1a64a49ebf';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'У вашего малыша уже начинает формироваться собственный режим сна, хотя пока он ещё не совсем регулярный. Поэтому вполне естественно, что во время осмотров у врача вы часто видите его спящим. Когда вы двигаетесь в течение дня, околоплодные воды мягко покачивают малыша, словно убаюкивая его, помогают успокоиться и заснуть.;;;
Наиболее активен малыш обычно ночью, когда вы отдыхаете, ваше артериальное давление снижается, а вокруг становится тихо. Выспавшись за день, малыш наслаждается возможностью "поиграть" в ночной тишине. Формирование режима сна в этот период создаёт основу как для развития в утробе, так и для здоровых привычек сна после рождения.;;;
Исследования показывают, что вредные привычки во время беременности (алкоголь, наркотические вещества и т. д.) резко ухудшают качество сна малыша. В таких случаях у малышей возникает проблема "неэффективного сна": они просыпаются в 5 раз чаще, чем здоровые малыши, а общая продолжительность их сна значительно сокращается.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя кровь становится красной! 🩸 Костный мозг внутри моих костей теперь производит клетки крови. Это очень важно для моего будущего иммунитета и переноса кислорода. Моя группа крови уже определена. Она такая же, как у вас, или как у папы? Вы узнаете это после моего рождения. С каждым днём я становлюсь всё самостоятельнее.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Морковь'), body_changes_ru = COALESCE(body_changes_ru, 'Если вы ощущаете постоянное онемение в запястьях и пальцах, эта жалоба может быть связана с синдромом запястного канала. Синдром запястного канала возникает из-за сдавления срединного нерва в канале, проходящем через запястье. На ранней стадии он проявляется онемением. Отёки кистей и стоп, часто возникающие во время беременности, могут оказывать давление на нервы в области запястий. Это вызывает онемение, покалывание и боль в запястьях и пальцах. Если сдавление нерва связано только с беременностью, то вскоре после родов оно обычно проходит самостоятельно, без лечения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить зуд живота, после душа нанесите натуральное масло массажными движениями на ещё влажную кожу. Чтобы снизить нагрузку на ноги, во время отдыха сидя слегка приподнимайте их. Отдавайте предпочтение продуктам, богатым магнием: это поможет предотвратить судороги в ногах.') WHERE id = '374d8324-b6d6-473c-83ac-7fb12f83f44c';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе тело малыша по-прежнему покрыто волосками лануго, а его соски начинают формироваться независимо от пола. Основная функция сосков — обеспечивать грудное вскармливание. Интересно, что в соске находится не одно отверстие, а до 20 небольших протоков (отверстий), через которые выделяется молоко. Вы сможете заметить это яснее после родов, когда у вас начнёт вырабатываться молоко.;;;
Ещё на эмбриональном этапе, до начала формирования половых органов, клетки, из которых образуются соски, уже объединяются. Характерные особенности половых органов начинают формироваться не ранее 8-й недели. Когда у мальчиков активируется ген SRY, отвечающий за формирование мужской репродуктивной системы, соски уже существуют, поэтому этот ген не может полностью остановить их развитие. Именно поэтому соски есть у представителей обоих полов.'), baby_message_ru = COALESCE(baby_message_ru, '🥕 Я размером с крупную морковь! Теперь я больше сплю и сильнее пинаюсь. Мой режим сна может не совпадать с вашим. Когда вы засыпаете, я просыпаюсь, потому что, когда вы не двигаетесь, мне кажется, будто мои "качели" остановились, и я просыпаюсь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Морковь'), body_changes_ru = COALESCE(body_changes_ru, 'Во втором триместре беременности, в который вы вступили, у вас время от времени могут появляться отёки. Обычно они связаны с нарушением кровообращения. Увеличивающиеся в процессе подготовки к родам матка и таз оказывают давление на кровеносные сосуды ног. Это замедляет кровообращение и приводит к появлению отёков. Ещё одной причиной отёчности могут быть особенности питания. Установлено, что значительная часть женщин с выраженными отёками получает недостаточно белка. Необходимый белок можно получать из мяса и других продуктов, а также употребляя не менее трёх порций молока или молочных продуктов в день. Ещё один важный аспект питания — достаточное потребление соли. Многие считают, что избыток соли приводит к задержке воды в организме и, следовательно, к отёкам. Хотя это действительно так, недостаточное потребление соли тоже может стать причиной отёков. Главное — употреблять достаточное количество соли и всегда придерживаться сбалансированного и здорового питания. Если у вас появились отёки, отдыхайте лёжа, приподнимайте ноги, пейте достаточно жидкости, совершайте короткие прогулки, носите свободную одежду и внимательно следите за своим рационом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить нагрузку на поясницу, старайтесь сидеть прямо и не стойте подолгу. Вечером отдохните 15 минут, расположив ноги немного выше уровня сердца: это поможет уменьшить отёчность и расслабиться. Поскольку ваша потребность в кальции увеличилась, добавьте в рацион творог, сыр или миндаль. Завершите день любимой музыкой.') WHERE id = '4291c964-97b5-4aa4-a48e-b3cb8e0fe5cb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Сердцебиение вашего малыша уже можно услышать с помощью стетоскопа! Во время осмотра врач может проверить сердцебиение малыша этим прибором. Отличить ваше сердцебиение от сердцебиения малыша довольно легко: его сердце бьётся примерно в 2 раза быстрее вашего.;;;
Один из главных участников стремительного развития вашего малыша — пуповина (umbilical cord). На протяжении всей беременности она обеспечивает поступление жизненно важных для малыша питательных веществ и кислорода. Средняя длина пуповины составляет 50-55 сантиметров, и она имеет спиралевидную форму.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую ваш стресс. 😟 Мамочка, когда вы напряжены, гормоны стресса (кортизол), вырабатывающиеся в вашем организме, поступают и ко мне, поэтому я тоже начинаю беспокоиться. Моё сердце бьётся быстрее. Но когда вы спокойны и счастливы, я тоже получаю «гормоны счастья». Пожалуйста, не расстраивайтесь. Мы вместе, и всё будет хорошо.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Морковь'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности может появиться геморрой или усилиться дискомфорт, вызванный уже имеющимся геморроем.;;;
Расположенные близко к поверхности сосуды расширяются, что способствует развитию варикоза и геморроя. Кроме того, повышенный в этот период уровень гормона прогестерона расслабляет гладкую мускулатуру вокруг сосудов, из-за чего они легче расширяются. Первым признаком геморроя обычно становятся следы крови, появляющиеся во время дефекации (опорожнения кишечника). Помимо кровотечения, могут наблюдаться чувство распирания в области ануса, припухлость, которая ощущается при гигиенических процедурах после посещения туалета, а также боль, возникающая при дефекации и сохраняющаяся длительное время. Самый важный способ профилактики геморроя — предотвращение запоров. Отдавайте предпочтение продуктам, богатым клетчаткой и пищевыми волокнами, пейте больше воды, ешьте больше овощей и фруктов, чтобы стул был мягким и не требовал натуживания. Если эти меры не помогают, можно использовать подходящее средство для размягчения стула, назначенное вашим врачом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы замечаете небольшую отёчность ног, в конце дня отдохните, немного приподняв их. Чтобы уменьшить боль в спине, носите удобную обувь на низком каблуке. Поскольку ваша потребность в кальции возросла, добавьте в рацион больше молочных продуктов и зелёных овощей. Как насчёт того, чтобы сегодня спеть малышу колыбельную?') WHERE id = '39505edc-cdd2-40ac-b9cb-aa04fd0c51af';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поджелудочная железа вашего малыша уже начала регулярно вырабатывать инсулин и глюкагон. Инсулин выделяется бета-клетками островков Лангерганса, расположенных в поджелудочной железе малыша. Когда уровень сахара в крови превышает потребность организма, инсулин способствует его накоплению в печени в виде гликогена. Таким образом он снижает уровень сахара в крови.;;;
Инсулин также помогает глюкозе из крови, а при необходимости аминокислотам и свободным жирным кислотам, проникать внутрь клеток, благодаря чему клетки получают необходимую энергию. При недостаточной выработке инсулина уровень сахара в крови повышается, и сахар выводится с мочой. Это приводит к развитию сахарного диабета, который в быту называют сахарной болезнью. Глюкагон вырабатывается альфа-клетками поджелудочной железы. Он выполняет функцию, противоположную действию инсулина. Глюкагон повышает уровень сахара в крови, способствуя высвобождению в кровь гликогена, накопленного в печени и мышцах. Этот баланс необходим, чтобы организм не остался без энергии при длительном голодании.'), baby_message_ru = COALESCE(baby_message_ru, 'Я настоящий гурман и уже различаю вкусы! 😋 Вкусовые рецепторы на моём языке работают в полную силу. Когда вы едите острый перец, я икаю, а когда едите шоколад — становлюсь активнее. Учёные говорят, что чем разнообразнее вы питаетесь сейчас, тем менее привередливым в еде я буду, когда вырасту. Давайте питаться правильно вместе!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Морковь'), body_changes_ru = COALESCE(body_changes_ru, 'Если в этот период вы замечаете выпадение волос, ломкость ногтей, слабость, снижение аппетита, головную боль, головокружение, одышку, учащённое сердцебиение, быструю утомляемость или раздражительность, необходимо сдать анализы крови. Анемия во время беременности обычно развивается во втором триместре, когда малыш получает необходимое ему железо из организма матери. Беременность повышает риск анемии, которая угрожает не только здоровью матери, но и может негативно повлиять на малыша. Чтобы увеличить поступление железа с ежедневным рационом, следует избегать напитков с высоким содержанием кофеина, таких как чай, кофе и кола, поскольку они препятствуют усвоению железа.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в спине, во время сидения обязательно подкладывайте под спину подушку и старайтесь сохранять прямую осанку. При кожном зуде используйте после душа натуральные увлажняющие средства. Не забывайте пить достаточно воды — это важно и для вас, и для обновления околоплодных вод. Завершите день любимым хобби.') WHERE id = 'f309c326-d1e8-4059-8ac7-ab4a84a92059';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Жизненно важная для вашего малыша амниотическая жидкость, в которой он находится, на этом этапе обновляется каждые три часа. Поэтому поддержание водного баланса организма имеет огромное значение для здоровья малыша. Эта жидкость на 99% состоит из воды, а также содержит неорганические соли, органические вещества и вещества, поступающие из организма малыша.;;;
Кроме того, для развития дыхательной системы малыш ежедневно тренируется, втягивая в лёгкие объём жидкости, равный четверти его веса. То же самое происходит и с пищеварительной системой. Эта жизненно важная жидкость защищает малыша от возможных травм, способствует развитию дыхательной системы, позволяет ему свободно двигаться, обеспечивая развитие скелета и мышц, поддерживает электролитный баланс, укрепляет иммунную систему и создаёт антибактериальную среду. Кроме того, когда перед родами плодный пузырь вскрывается и жидкость отходит, она очищает родовые пути, подготавливая их к появлению малыша.;;;
Если амниотической жидкости меньше нормы, это состояние называется маловодием (олигогидрамнионом), а если больше нормы — многоводием (полигидрамнионом). При недостаточном или избыточном количестве амниотической жидкости необходимо чаще наблюдаться у врача.'), baby_message_ru = COALESCE(baby_message_ru, 'Я познаю мир через прикосновения! 🖐️ Я прикасаюсь руками к лицу, ногам, пуповине и стенкам матки. Это помогает мне понимать границы своего тела. Я исследую себя. Иногда я сосу большой палец — это меня успокаивает. Когда вы прикасаетесь к животу, я тоже чувствую это тепло.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Морковь'), body_changes_ru = COALESCE(body_changes_ru, 'Если у вас наблюдаются выраженные отёки лица, области вокруг глаз, суставов и ног, внезапная и быстрая прибавка веса, сильная и не проходящая головная боль, нарушения зрения, например затуманенность, а также резкая боль в животе и рвота, это может указывать на преэклампсию. Преэклампсия, известная также как поздний токсикоз беременности, — серьёзное осложнение, которое встречается у 5% беременных. Диагноз ставится после 20-й недели беременности, если помимо высокого артериального давления присутствует как минимум ещё один признак. К таким признакам относятся наличие белка в моче, нарушения функции печени или почек. Иногда преэклампсия может развиваться без каких-либо симптомов. Артериальное давление может повышаться постепенно или внезапно. Контроль артериального давления — важная часть дородового наблюдения, поскольку первым признаком преэклампсии обычно становится его повышение. Вероятность развития преэклампсии выше при беременности в возрасте до 18 или старше 35 лет, при избыточной или слишком низкой массе тела, в кровнородственных браках, после перенесённых серьёзных хирургических операций, а также у женщин, которые до беременности страдали заболеваниями сердца, сахарным диабетом, повышенным артериальным давлением, эпилепсией, заболеваниями щитовидной железы или другими болезнями.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте завершение 21-й недели небольшой прогулкой! Чтобы уменьшить боль в спине, носите удобную обувь на низком каблуке. Во время сна обязательно ложитесь на левый бок и подкладывайте под ноги подушку — это улучшит кровообращение. Продолжайте пить достаточно воды и включать в рацион продукты, богатые клетчаткой.') WHERE id = '925057a2-a250-49b9-bcfa-f9f914c5c38f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Эта неделя означает, что вы беременны 4 месяца и 3 недели. То есть до завершения 5-го месяца осталась всего 1 неделя! ;;;
Один из вопросов, который больше всего интересует будущих мам во время наблюдения за беременностью, — развитие малыша, а также его вес и рост на текущей неделе. Оценка веса и роста на основании параметров, определяемых при ультразвуковом исследовании, имеет большое медицинское значение: эти показатели особенно важны для контроля набора веса и развития малыша, а также для выбора способа родоразрешения.;;;
У малышей, родившихся с низким или чрезмерно большим весом, могут возникнуть определённые осложнения и риски во время или после родов. По данным Всемирной организации здравоохранения (ВОЗ), малыши весом 4500 граммов и более не считаются подходящими для естественных родов. В практике Азербайджана решение может зависеть от вас и вашего врача, однако в целом при предполагаемом весе малыша 4 кг и более рекомендуется кесарево сечение.'), baby_message_ru = COALESCE(baby_message_ru, 'Я слышу папу! 👨 Теперь я лучше слышу не только твой голос, но и низкие звуки, доносящиеся извне. Если папа приблизится к твоему животу и заговорит, я узнаю его голос. Скажи ему, чтобы он рассказал мне сказку или просто сказал "привет". Я тоже его люблю!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Такие симптомы первых месяцев, как тошнота, слабость, головные боли и спазмы, постепенно проходят, и физически вы чувствуете себя бодрее. Кроме того, второй триместр — это период, когда начинается и психологическая адаптация к беременности.;;;
На этом этапе беременности из-за увеличения количества кровеносных сосудов в половых органах и усиления кровообращения сексуальное желание может возрасти. При этом оргазм женщины во время полового акта не причиняет малышу никакого вреда. Напротив, некоторые исследования показали, что сокращения матки во время оргазма могут положительно влиять на сердцебиение малыша.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы почувствуете лёгкое напряжение в нижней части живота, немного полежите, отдохните и пейте больше воды. Продолжайте принимать железо и магний, чтобы поддерживать стабильный уровень энергии.') WHERE id = 'f395dae9-427a-4c8d-8ba3-bfb8922cadf2';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя волосы вашего малыша уже появились, они пока выглядят бесцветными, поскольку ещё не содержат пигмента. Волосы в основном состоят из различных белков, а их естественный цвет определяется пигментом меланином. Меланин присутствует как в светлых, так и в тёмных волосах. Разница в оттенке волос зависит от количества меланина. Другими словами, волосы с большим содержанием меланина выглядят темнее, чем волосы с меньшим количеством этого пигмента. Кроме того, волосы на голове растут быстрее других видов волос на теле. Средняя скорость их роста составляет от 0.3 mm до 0.5 mm в день. При рождении толщина волос у мальчиков и девочек одинакова.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую ритм! 🥁 Когда ты слушаешь музыку или танцуешь, я ощущаю этот ритм. Иногда я даже могу двигаться в такт музыке. Спокойная музыка усыпляет меня, а быстрая — пробуждает. У меня формируется собственный музыкальный вкус.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Повышение аппетита чаще всего наблюдается во втором триместре беременности, то есть с начала 3-го месяца до конца 6-го месяца. В первые 3 месяца интенсивные гормональные изменения вызывают повышенную чувствительность к запахам и тошноту. Во втором триместре организм привыкает к новому гормональному балансу, тошнота уменьшается, а аппетит усиливается. Поэтому именно в этот период обычно происходит наиболее значительный набор веса во время беременности. Каким бы сильным ни был ваш аппетит, важно питаться здоровой пищей и избегать жирных, солёных продуктов и пищи с высоким содержанием сахара. Кроме того, частое питание небольшими порциями помогает поддерживать стабильный уровень сахара в крови и предотвращает употребление слишком большого количества калорий за один приём. Физические упражнения и прогулки также помогут вам контролировать аппетит в этот период.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если ночью ногу свело судорогой, сразу потяните пальцы стопы на себя, к колену, одновременно направляя пятку вперёд. Это движение растягивает икроножную мышцу и уменьшает боль. Массаж также будет полезен.') WHERE id = '68f0e92d-9dd8-4759-acc2-0054a8f6a53a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Движения малыша — важнейший фактор, способствующий развитию его мышц. При рождении масса мышц малыша составляет примерно одну пятую от массы его тела. К подростковому возрасту мышцы будут составлять треть общей массы тела, а во взрослом возрасте — две пятых. В целом рост мышц происходит параллельно с ростом организма. При рождении у малышей уже хорошо развиты глазные и дыхательные мышцы. При этом мышцы рук развиты лучше, чем мышцы ног. До подросткового возраста крупные мышцы работают лучше, чем мелкие. Поэтому детям легче выполнять широкие и размашистые движения, чем мелкие и точные.'), baby_message_ru = COALESCE(baby_message_ru, '🥥 Я размером с кокос! Сейчас я уже похож на миниатюрного малыша. У меня есть всё: брови, ресницы, ногти. Теперь моя главная цель — набрать вес и подготовить лёгкие. Я пока ещё очень худенький, но ты хорошо меня питаешь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Увеличение объёма крови необходимо как для малыша, так и для вашего здоровья. Однако по этой причине на ногах могут появиться варикозно расширенные вены. В первые годы варикоз чаще всего вызывает только эстетический дискомфорт, но позднее может привести к боли. В развитии варикоза участвует множество факторов. Его появлению могут способствовать беременность, избыточный вес, длительное пребывание на ногах, приём противозачаточных таблеток и гормональная терапия, ношение тесной одежды, запоры, пожилой возраст и генетическая предрасположенность. Для профилактики варикоза полезно регулярно заниматься физическими упражнениями, не стоять подолгу, не сидеть, закинув ногу на ногу, избегать слишком тесной и узкой одежды, выбирать удобную обувь вместо туфель на высоком каблуке, предотвращать запоры и употреблять продукты с высоким содержанием клетчатки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Ночью старайтесь чаще лежать на левом боку, а не на правом: это улучшает приток крови к матке и работу почек. Чтобы уменьшить лёгкую отёчность ног, контролируйте потребление соли и пейте больше воды. Если вы чувствуете одышку, двигайтесь медленнее, держите спину прямо и глубоко дышите.') WHERE id = '0192bd32-2239-497b-af81-dc9dc504732a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Количество эритроцитов в организме вашего малыша постепенно увеличивается. Эти клетки отвечают за перенос кислорода и углекислого газа по организму. Они составляют 99% всех клеток крови и отличаются ярко-красным цветом.;;;
Производство этих клеток регулируется гормоном эритропоэтином, который вырабатывается почками. Процесс начинается в костном мозге, и примерно через неделю созревшие клетки поступают в кровоток. У зрелых эритроцитов нет ядра, поэтому они очень эластичны. Благодаря этой гибкости они легко проходят даже через самые узкие сосуды и доставляют кислород ко всем тканям организма. Продолжительность жизни эритроцитов составляет всего 3 месяца. Со временем старые и повреждённые клетки расщепляются и удаляются из организма в селезёнке, печени и костном мозге в процессе, который называется фагоцитозом.'), baby_message_ru = COALESCE(baby_message_ru, 'Я узнаю твой голос! 🗣️ Anacan, я уже могу отличить твой голос от голосов других людей. Когда ты говоришь, я успокаиваюсь, а моё сердцебиение замедляется. Для меня это самый надёжный и родной голос в мире. Продолжай петь мне песни — я складываю их в свою "копилку воспоминаний". Когда я появлюсь на свет и услышу эту песню, то сразу успокоюсь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'У некоторых беременных женщин акне не появляется совсем, а у других высыпаний может стать больше. Обычно это связано со значительным повышением уровня гормонов в крови. Вместе с изменением гормонального фона усиливается и выработка кожного сала. Его избыток на поверхности кожи становится одной из основных причин появления акне. Во время беременности следует избегать плотного макияжа, не пользоваться недостаточно очищенными косметическими принадлежностями и кистями, отказаться от вредной пищи, особенно жареных блюд, уделять очищению кожи больше внимания и использовать подходящие для беременных увлажняющие средства на водной основе. Также важно помнить, что выдавливание прыщей и прикосновения к ним могут привести к распространению гнойного содержимого по поверхности кожи и появлению новых высыпаний. Поэтому старайтесь лишний раз не трогать лицо и помните, что это временное явление.'), daily_tip_ru = COALESCE(daily_tip_ru, 'По вечерам делайте ногам массаж с помощью "холодного душа". Направляйте струю воды снизу вверх, чтобы улучшить кровообращение. Избегайте солёных продуктов, поскольку соль задерживает воду в организме.') WHERE id = '47e98235-5632-4780-b011-1fba5afdb56a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Репродуктивная система вашего малыша продолжает созревать и развиваться. Если у вас мальчик, в эти дни в его яичках продолжают развиваться клетки-предшественники сперматозоидов. Находящиеся в канальцах яичек малыша первичные половые клетки имеют диплоидный набор хромосом — 2n. Это означает, что они ещё не являются зрелыми сперматозоидами и пока ведут себя как обычные клетки организма. Половые клетки должны иметь гаплоидный набор хромосом — n, тогда как клетки организма содержат диплоидный набор — 2n.;;;
До начала полового созревания у мальчиков клетки-предшественники сперматозоидов имеют набор хромосом 2n и размножаются путём митоза. С наступлением полового созревания эти клетки достигают определённой стадии зрелости и становятся способными к мейозу. Благодаря этому образуются половые клетки с необходимым гаплоидным набором хромосом — n.'), baby_message_ru = COALESCE(baby_message_ru, 'Я трогаю своё лицо! 🤲 Руками я изучаю своё лицо. Прикасаюсь к носу, подбородку и глазам. Моя кожа ещё очень тонкая, но чувствительность уже хорошо развита. Эти движения помогают моему мозгу создавать карту тела. Я начинаю узнавать себя. Когда ты прикасаешься к животу, я тоже это чувствую.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'К концу дня отёчность ног может усиливаться. Это связано с задержкой жидкости в организме, увеличением объёма крови и жаркой погодой. Вы также можете заметить, что кольца стали тесными. Для этого срока беременности такое физиологическое состояние считается нормальным. Кроме того, по ночам вас могут беспокоить судороги в ногах. Это может быть связано с замедлением кровообращения или дефицитом кальция, магния либо калия. Также может возникнуть "синдром беспокойных ног".'), daily_tip_ru = COALESCE(daily_tip_ru, 'Вместо того чтобы расчёсывать зудящие участки ногтями, нанесите увлажняющее масло или крем и аккуратно погладьте кожу ладонью. Холодный компресс также может уменьшить зуд.') WHERE id = 'da8c9afd-1f7d-4478-b2fc-5b192ee0259f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе по мере ускорения окостенения продолжает формироваться череп вашего малыша. В нижней и задней части череп соединяется с позвоночником, а в передней части поддерживает лицевые кости. На этом этапе череп малыша ещё недостаточно развит, но к взрослому возрасту его размеры составят примерно 18 см спереди назад, 13 см в высоту и 14 см в диаметре.'), baby_message_ru = COALESCE(baby_message_ru, 'Моё сердце поёт! ❤️ Врач уже может услышать моё сердцебиение без специальных приборов — с помощью обычного стетоскопа. Моё сердце бьётся 140-150 раз в минуту. Для тебя этот звук — ритм жизни, правда? Благодаря тебе моё сердце бьётся так сильно.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Поскольку ваш быстро растущий малыш уже находится примерно на уровне пупка, кожа в этой области может начать растягиваться, и на ней могут появиться растяжки. Обычно они возникают в нижней части живота, но также могут появиться на бёдрах, ягодицах, груди и руках. Растяжки имеют розовато-белый цвет и внешне могут напоминать повреждения кожи. Они выглядят как небольшие неглубокие бороздки на её поверхности. Если ваша кожа достаточно эластична, причин для беспокойства нет, поскольку такая кожа менее склонна к появлению растяжек. В этом случае нет необходимости использовать какие-либо специальные средства для их профилактики. Уменьшить выраженность растяжек можно с помощью специальных увлажняющих кремов или натуральных средств для наружного применения, например миндального масла или масла абрикосовых косточек.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня нежно помассируйте живот и поговорите с малышом — он уже очень хорошо чувствует давление и тепло вашей руки.') WHERE id = 'aa1f1ed4-15e9-4574-a163-232172e516be';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По мере полного формирования слуха вашего малыша ускоряется процесс установления связей между нейронами головного мозга. Теперь мозг вашего малыша, как и у взрослого человека, состоит из пяти основных отделов, каждый из которых выполняет свою функцию:;;;
Лобная доля: Отвечает за осознанное мышление и управление эмоциями.;;;
Теменная доля: Объединяет информацию, поступающую от органов чувств, и обеспечивает пространственное восприятие.;;;
Затылочная доля: Центр обработки зрительной информации.;;;
Височная доля: Обеспечивает восприятие звуков и запахов, распознавание лиц и мест.;;;
Мозжечок: Поддерживает равновесие и координирует движения с сенсорными ощущениями.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с грейпфрут! Мой вес составляет примерно 370 грамм, а рост — 27.1 см. Моя кожа пока ещё морщинистая, потому что я расту очень быстро, а жировой слой ещё не успел её заполнить. Но не волнуйся, к рождению я стану тем самым милым пухленьким малышом. Сейчас моя главная задача — набирать вес!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за повышения концентрации гормона прогестерона в крови опорожнение желудка замедляется, а перистальтика кишечника снижается. В результате могут появиться жалобы на запор.;;;
Пищеварительная система также относится к числу систем, наиболее подверженных изменениям в этот период. Повышение секреции желудочной кислоты из-за гормональных изменений, снижение волнообразных сокращений пищевода, возникновение рефлюкса вследствие расслабления желудочных сфинктеров и замедление пищеварения из-за того, что растущая матка, особенно в последние 3 месяца беременности, смещает желудок вверх, — вот лишь некоторые из этих изменений.;;;
Поскольку в этот период объём тела увеличивается, почки также могут немного увеличиться. В увеличившихся в объёме и массе почках замедляется отток мочи, а каналы, по которым моча поступает из почек в мочевой пузырь, расширяются. Поэтому во время беременности инфекции мочевыводящих путей встречаются довольно часто.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку сегодня выходной, уделите себе больше времени. Чтобы уменьшить ощущение нехватки воздуха, старайтесь сидеть прямо, а во время сна подкладывайте под спину дополнительную подушку. Контролируйте повышенный аппетит с помощью полезных орехов и сухофруктов. Завтра начинается новая неделя, поэтому сегодня вечером составьте для малыша плейлист с успокаивающей музыкой.') WHERE id = 'dcc1b63f-cc53-4d60-9050-ad76c211d2c4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Эта неделя — первая неделя последнего месяца второго триместра. Проще говоря, до окончания второго триместра остался всего 1 месяц.;;;
Начиная с этой недели формирование жирового слоя ускоряется, хотя и не так интенсивно, как в последнем триместре. Поэтому кожа малыша выглядит менее морщинистой, чем раньше. По мере быстрого увеличения объёма жировой ткани вашего малыша морщинистость его кожи будет соответственно уменьшаться. Количество жировых клеток, способных увеличиваться в 6 раз по сравнению с собственным размером, к подростковому возрасту вашего малыша будет составлять от 40 миллиардов до 100 миллиардов. Эти клетки, которые уже начинают формироваться, необходимы для жизни и поддерживают энергетическую систему организма. Кроме того, благодаря жирам организм усваивает жирорастворимые витамины A, D, E и K. Жиры также помогают удерживать кальций в организме.'), baby_message_ru = COALESCE(baby_message_ru, 'Я тренируюсь! 🏋️‍♂️ Anacan, мои движения теперь стали сильнее. Иногда ты можешь заметить, как одна сторона живота выпирает или двигается. Это я толкаю тебя локтем или коленом. Так я говорю тебе: "Я здесь!" А когда ты кладёшь руку на живот, я успокаиваюсь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Особенно по вечерам вы можете замечать, что ваши стопы кажутся больше обычного. Увеличение размера стоп во время беременности, как правило, носит временный характер. Одна из основных причин — отёки, возникающие из-за накопления жидкости в организме. Особенно в последние месяцы беременности задержка жидкости приводит к отёчности рук и ног. Из-за этого обувь, которую раньше вы носили без проблем, может стать тесной. Ещё одна причина — чрезмерно быстрый или избыточный набор веса во время беременности. В этом случае из-за накопления жировой ткани стопы могут казаться более отёчными. Также увеличение размера стоп связано с гормоном релаксином. Этот гормон способствует размягчению и расслаблению связок таза и других соединительных тканей организма, чтобы во время родов малыш мог пройти через родовые пути.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сейчас прекрасное время, чтобы сфотографировать свой животик! Эти недели отлично подходят для коллажей "Before/After" (До/После), поскольку ваш животик уже приобрёл аккуратную округлую форму.') WHERE id = 'a3ddbe51-ede9-4765-9b27-d3fb41ca5df3';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В лёгких вашего малыша началась выработка вещества, называемого сурфактантом. Проще говоря, сурфактант — это вещество, которое снижает поверхностное натяжение жидкости. Он крайне важен для того, чтобы лёгкие могли выполнять дыхательную функцию.;;;
Благодаря началу выработки сурфактанта в лёгких ваш малыш значительно приблизился к порогу жизнеспособности. Количество сурфактанта в лёгких будет постепенно увеличиваться, и к 37-й неделе развитие лёгких вашего малыша завершится.;;;
В лёгких малышей, родившихся раньше срока, вырабатывается недостаточно сурфактанта. Из-за его дефицита лёгкие не могут полноценно выполнять дыхательную функцию, поэтому может потребоваться аппарат искусственной вентиляции лёгких.'), baby_message_ru = COALESCE(baby_message_ru, 'Я слушаю мир! 🌍 Теперь я слышу не только твой голос, но и громкие звуки снаружи. Если лает собака, сигналит машина или работает пылесос, я всё это слышу. Иногда эти звуки пугают меня, и я вздрагиваю. Когда ты спокойна, я тоже спокоен. Теперь у нас общий мир.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Ближе к середине 20-х недель могут появиться ложные схватки, называемые схватками Брекстона — Хикса. Они возникают из-за напряжения мышц матки и могут начаться в любое время второго триместра беременности. В отличие от настоящих родовых схваток, их интенсивность и частота могут меняться. Особенно часто они возникают вечером и при переутомлении. Отличить ложные схватки от настоящих можно по следующим признакам: они нерегулярны, со временем не учащаются, постепенно ослабевают, проходят при изменении положения тела и чаще ощущаются в передней части живота. Чтобы облегчить такие сокращения, вам следует отдохнуть, прогуляться, пить достаточно жидкости и сделать массаж поясницы. Тёплый душ также может уменьшить дискомфорт. Если вы замечаете, что схватки возникают через определённые интервалы, а их частота и интенсивность постепенно увеличиваются, вам следует обратиться в ближайшее медицинское учреждение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если ложные схватки вызывают у вас беспокойство, выпейте стакан воды, прилягте на левый бок и отдохните. Часто обезвоживание или усталость усиливают такие схватки.') WHERE id = '97aa8d6c-1084-4919-a563-80230748cb6e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Организм вашего малыша начал вырабатывать антитела, пусть пока и в очень небольшом количестве. Это означает, что, хотя иммунная система ещё не сформирована полностью, её основы уже заложены. Антитела — это полезные вещества, которые вырабатываются организмом в ответ на появление вредных бактерий, микробов и чужеродных веществ. Являясь естественным механизмом защиты организма, антитела составляют основу иммунной системы.;;;
Сразу после рождения очень важно кормить малыша вашим первым молоком — молозивом. Оно содержит антитела, которые организм малыша пока не способен вырабатывать самостоятельно. Во время кормления эти антитела всасываются в тонком кишечнике, попадают в кровь малыша, способствуют развитию его иммунной системы и защищают от вредных микроорганизмов извне.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне снятся сны? 💤 Волны моего мозга показывают, что я нахожусь в фазе «быстрого сна». В это время мои глаза закрыты, но глазные яблоки быстро двигаются. Учёные говорят, что это означает, что я вижу сны. Что же мне снится? Может быть, ваш голос, а может, вкус околоплодных вод.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Подробное ультразвуковое исследование проводится между 19-й и 23-й неделями беременности. К этому времени органы малыша уже сформированы, а благодаря увеличению объёма околоплодных вод можно получить более детальные изображения. Цель подробного УЗИ — оценить развитие малыша и определить наличие возможных аномалий. Во время этого исследования с помощью современных ультразвуковых аппаратов могут быть выявлены аномалии развития или признаки хромосомных нарушений. В ходе обследования по отдельности и подробно оцениваются череп и головной мозг малыша, позвоночник, органы грудной клетки и брюшной полости, желудок и кишечник, сердце, руки и ноги, а также плацента.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Лягте на 15 минут, подняв ноги и оперев их на стену. Это помогает оттоку крови и уменьшает отёчность. Ешьте меньше солёной пищи, но не сокращайте количество воды!') WHERE id = 'aebe9763-3910-4530-99d7-d5c87283c426';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Благодаря развитию внутреннего уха вашего малыша и формированию слуха участок мозга, отвечающий за восприятие звуков, сейчас развит сильнее других участков.;;;
Скелет и мышцы малыша окрепли настолько, что его движения ощущаются через брюшную стенку и даже могут быть заметны. Позвоночник малыша укрепляется. Кровеносные сосуды продолжают развиваться, особенно в лёгких.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои толчки становятся сильнее! 🥋 Anacan, чувствуете? Теперь я не просто «плаваю», а наношу настоящие удары. Иногда вам может казаться, что я занимаюсь карате. Эти движения показывают, что я здоров. Вы уже можете начинать считать мои движения.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Глюкозотолерантный тест, который проводится между 24-й и 28-й неделями беременности, помогает оценить риск диабета по уровню глюкозы в крови. Даже у женщины, которая до беременности не болела сахарным диабетом и не имела его симптомов, во время беременности может развиться диабет из-за изменений чувствительности к инсулину. Это состояние, называемое гестационным сахарным диабетом, встречается примерно у 10% беременных.;;;
Кроме того, женщинам, у которых сахарный диабет был ещё до беременности, во время беременности может стать сложнее контролировать уровень глюкозы в крови. Поэтому беременным с диабетом необходимо регулярно проходить обследования, соблюдать рекомендованный рацион и получать подходящее лечение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Полезный перекус: грецкие орехи, изюм, курага или миска йогурта. Эти продукты надолго насыщают и обеспечивают малыша необходимыми витаминами. Откажитесь от фастфуда: он лишь способствует набору лишнего веса, не принося пользы.') WHERE id = '846475dc-14c4-4c7d-ac51-e75ce4438f24';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Жировая ткань, которая начинает формироваться в организме вашего малыша, отличается от жировой ткани взрослого человека. Хотя об этом известно не всем, существует два вида жировых клеток: белые и бурые. Главное различие между ними заключается в цвете. Внутри белой жировой клетки находится одна крупная липидная, то есть жировая, капля и практически нет других структур. Именно эта жировая капля придаёт клетке характерный цвет. Белый жир служит для накопления энергии и создаёт мягкую защитную прослойку для внутренних органов. Кроме того, эти клетки вырабатывают многие гормоны, в том числе эстроген и лептин, а также участвуют в регуляции действия других гормонов, например инсулина. На этом этапе в организме вашего малыша преимущественно образуются бурые жировые клетки. Вместо одной крупной жировой капли они содержат небольшое количество мелких жировых капель и множество митохондрий. Ещё одна причина их более тёмного цвета — наличие железа в клеточных структурах. В отличие от белых жировых клеток, бурые активно вырабатывают тепло, помогая поддерживать температуру тела. Это особенно важно для малышей, которые ещё не могут согреваться за счёт активных движений.'), baby_message_ru = COALESCE(baby_message_ru, 'Я удерживаю равновесие! ⚖️ «Вестибулярный аппарат» в моём ухе уже полностью работает. Теперь я чувствую, нахожусь ли я головой вниз или вверх. Когда вы двигаетесь, я тоже стараюсь сохранять равновесие. Мы можем танцевать вместе!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'С начала и до конца беременности баланс гормонов в вашем организме полностью меняется, чтобы поддерживать вас и малыша. К этим гормонам относятся ХГЧ, эстроген, прогестерон, релаксин, окситоцин и ЛГ.;;;
Эстроген играет важную роль в подготовке организма к вынашиванию малыша и грудному вскармливанию. Он также способствует надёжному прикреплению эмбриона к слизистой оболочке матки. Во время беременности уровень этого гормона может повышаться до 50 раз. Эстроген способствует росту мышц матки и молочных протоков, а также обеспечивает достаточное кровоснабжение матки. Кроме того, он увеличивает активность меланоцитов — клеток, вырабатывающих пигмент, который придаёт коже цвет. Поэтому во время беременности могут потемнеть соски и область влагалища, появиться веснушки на лице и так называемая «маска беременности». Эстроген также может способствовать повышению артериального давления и усилению сексуального желания.;;;
Ещё один важнейший гормон беременности — прогестерон. Его основная задача заключается в поддержании состояния внутренней оболочки матки, где развивается ваш малыш. Эту функцию он выполняет вместе с эстрогеном. Прогестерон также расслабляет мышцы во время беременности, особенно мускулатуру матки, предотвращая ненужные сокращения, которые могут привести к преждевременному прерыванию беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы чувствуете одышку, заведите руки за голову и сделайте глубокий вдох — это временно увеличит объём грудной клетки. Чтобы ночью было удобнее спать, положите подушку между коленями: это поможет уменьшить боль в области таза. Пейте достаточно воды и добавьте в рацион больше продуктов, богатых калием, чтобы уменьшить мышечное напряжение.') WHERE id = 'b80a4824-be4e-45cc-b6d6-5d38c928227c';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Сосудистая система, которая словно сеть окутывает тело вашего малыша, уже активно развивается. Представьте: общая длина кровеносных сосудов в организме человека составляет примерно 100 000 км — этого невероятного расстояния хватило бы, чтобы более двух раз обогнуть Землю! Эта удивительная транспортная система состоит из трёх видов «дорог». Артерии — это «скоростные магистрали» организма. Они переносят от сердца по всему телу насыщенную кислородом кровь. Аорта — самая крупная и мощная артерия — выходит из сердца и распределяет кровь по более мелким ветвям. Стенки артерий одновременно мышечные и эластичные, благодаря чему они выдерживают давление, возникающее при каждом ударе сердца. Вены — это «обратные пути», по которым кровь с низким содержанием кислорода возвращается к сердцу. У вен есть интересная особенность: внутри них расположены небольшие чувствительные клапаны. Они не позволяют крови под действием силы тяжести течь назад и обеспечивают её движение только к сердцу. Капилляры — это микроскопические сосуды, которые соединяют артерии с венами и по толщине уступают даже волосу. Они настолько проницаемы и тонки, что именно через них клетки получают питательные вещества и избавляются от продуктов обмена. Капилляры присутствуют во всех тканях нашего организма и являются настоящим центром обмена веществ.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои ногти растут! 💅 Ногти на моих руках уже почти достигают кончиков пальцев. Они очень тонкие и острые. Иногда я случайно царапаю себе лицо. Но моя кожа быстро заживает. С каждым днём я всё больше становлюсь похожим на вас, Anacan.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за того, что малыш растёт с невероятной скоростью, а матка поднимается вверх, центр тяжести вашего тела смещается.;;;
Судороги в ногах — довольно распространённое болезненное явление, особенно во втором и третьем триместрах беременности. Они могут возникать при сдавливании кровеносных сосудов или нервов в ногах. Недостаток магния в ежедневном рационе также может стать причиной судорог.;;;
Боль в пояснице возникает примерно у двух третей беременных женщин. Обычно она связана с тем, что растущий живот увеличивает нагрузку на мышцы спины и меняет осанку. Чтобы уменьшить боль, принимайте тёплый душ, используйте поддерживающий пояс для беременных, сидите на стульях с опорой для поясницы, избегайте длительного пребывания на ногах и неподвижного положения. Ложась на правый или левый бок, кладите подушку между ногами и старайтесь не делать резких движений.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Одевайтесь многослойно. Если вам станет жарко, вы сможете снять верхний слой одежды. Выбирайте одежду из натуральных тканей (хлопка, льна), чтобы кожа могла дышать. Пейте достаточно воды, чтобы регулировать температуру тела.') WHERE id = '2970a789-ae12-4a5d-81be-71d79963f650';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш появится на свет с непроизвольными рефлекторными движениями, которыми управляет мозг. К ним относятся рефлекс Моро, хватательный рефлекс, рефлекс вздрагивания, подошвенный и шаговый рефлексы, а также сосательный и поисковый рефлексы.;;;
Когда малышу кажется, что он падает, он вытягивает руки вперёд, раскрывает ладони и максимально разводит пальцы. Затем сводит руки, словно пытаясь за что-то ухватиться. Если ноги свободны, он двигает ими таким же образом. Это называется рефлексом Моро, и он исчезает вскоре после рождения.;;;
Рефлекс вздрагивания возникает, когда рядом с малышом раздаётся громкий или неожиданный звук. В результате его тело напрягается, плечи сгибаются, а руки поднимаются, словно он пытается защититься от возможной угрозы. В отличие от других рефлексов, этот защитный рефлекс не исчезает, а продолжает развиваться и укрепляться на протяжении жизни.;;;
Сосательный рефлекс после рождения запускается при прикосновении чего-либо к верхней части полости рта малыша. Благодаря ему малыш может достаточно крепко захватить сосок для грудного вскармливания. В течение 3-4 месяцев этот рефлекс сменяется осознанными движениями.;;;
Некоторые из этих рефлексов через некоторое время могут исчезнуть. По мере развития мозга сохраняющиеся непроизвольные движения сменяются осознанными, произвольными движениями.'), baby_message_ru = COALESCE(baby_message_ru, 'Почему ваш живот подпрыгивает? 🐇 Anacan, вы почувствовали? Я только что икнул! Моя диафрагма тренируется, поэтому моё тело ритмично вздрагивает. Вам это может показаться странным — словно в животе тикают часы. Не волнуйтесь, мне не больно. Наоборот, это укрепляет мои лёгкие.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'В этот период вашему малышу особенно необходимо железо. Из-за этого в вашем организме может возникнуть дефицит железа. Если вас беспокоят слабость, утомляемость и бледность, врач может назначить анализы для проверки уровня железа. Дополнительное железо необходимо растущему малышу и плаценте. У большинства женщин в начале беременности запасов железа недостаточно для покрытия этой потребности. Особенно значительно она возрастает во втором и третьем триместрах, и удовлетворить её только за счёт питания обычно невозможно. Помимо приёма назначенного врачом препарата железа, отдавайте предпочтение салатам с лимонным соком к мясным блюдам и сочетайте овощные блюда с салатами, богатыми витамином C, — это улучшит усвоение железа.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отпразднуйте успешное завершение 23-й недели и побалуйте себя! Чтобы уменьшить боль в пояснице, носите обувь на низком каблуке и не оставайтесь надолго в одном положении. Следите за поступлением кальция и витамина D, чтобы кости малыша продолжали правильно развиваться. Завтра мы начинаем новую неделю — 24-ю!') WHERE id = 'c1de12f1-7759-492c-b277-e01fb2d857c9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поздравляем! Ваш малыш уже достиг порога жизнеспособности. Начиная с этой недели у малышей, родившихся преждевременно, появляется шанс выжить при условии, что больница располагает подходящим отделением реанимации и интенсивной терапии новорождённых.;;;
Главная причина, по которой с этой недели малыш достигает порога жизнеспособности, заключается в переходе лёгких на важный этап развития. Уже сформировавшиеся дыхательные ветви в лёгких теперь соединены с воздушными мешочками. Кроме того, началась выработка сурфактанта, покрывающего их внутреннюю поверхность. Сурфактант уменьшает поверхностное натяжение в лёгких при дыхании и не позволяет воздушным мешочкам спадаться. Хотя его выработка начинается на этой неделе, при нормальном течении беременности она достигает необходимого уровня к 38-й неделе. Поэтому при угрозе преждевременных родов на сроке 24-34 недели врачи различными способами стараются отсрочить роды, чтобы выиграть время, и вводят кортикостероидные препараты, которые усиливают выработку сурфактанта и тем самым ускоряют созревание лёгких.'), baby_message_ru = COALESCE(baby_message_ru, 'Я слушаю! 👂 Anacan, пылесос дома работает очень громко, правда? Я уже вздрагиваю от громких звуков. Но ваш спокойный голос меня успокаивает. Когда вы разговариваете со мной, я могу перестать двигаться, чтобы послушать вас. Начинаются наши первые диалоги.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Теперь движения малыша можно увидеть снаружи по вашему животу. Пигментация кожи может стать более выраженной. Кроме того, пупок (умбиликус) может не втягиваться внутрь, а выпячиваться наружу, становясь похожим на «пуговку». Это связано с давлением матки. Температура вашего тела может быть выше обычной. Вы можете чаще потеть и ощущать «приливы жара». Это связано с ускорением обмена веществ и увеличением объёма кровообращения. Вам может хотеться находиться в прохладных местах.'), daily_tip_ru = COALESCE(daily_tip_ru, 'На этой неделе обсудите с врачом проведение глюкозотолерантного теста (OGTT). Регулярно используйте увлажняющие кремы, чтобы уменьшить зуд и растяжение кожи живота. Сегодня не перенапрягайтесь: через каждый 1 час вытягивайте ноги и отдыхайте 10 минут.') WHERE id = '372f913d-c4b6-4616-837e-127ec92b9515';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Вы находитесь на 6-м месяце беременности. Органы малыша, вступившего в период быстрого набора веса, уже достаточно развиты, чтобы он мог адаптироваться к внешнему миру, а его крошечные ножки к моменту рождения станут почти в два раза больше.;;;
Ваш малыш продолжает развивать рефлекторные движения. Кроме того, он уже начал совершать некоторые произвольные движения. Рефлекс — это непроизвольная физическая реакция, возникающая в ответ на внешний раздражитель. При рождении у малыша будет множество рефлексов. Поначалу он будет проявлять их непроизвольно и не сможет ими управлять.'), baby_message_ru = COALESCE(baby_message_ru, 'Я набираю вес! ⚖️ Моя кожа пока немного морщинистая, словно она мне велика. Но я быстро набираю вес и заполняю эти складочки. Скоро я стану милым пухленьким малышом. Ты хорошо меня кормишь, спасибо!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности в вашей сердечно-сосудистой системе происходит множество изменений. В частности, повышение уровня гормона прогестерона в крови с первых недель беременности снижает системное сосудистое сопротивление, что приводит к снижению артериального давления. Потемнение в глазах, головокружение и обмороки, возникающие в первые недели, могут быть связаны именно с этим. Ударный объём сердца, то есть количество крови, которое сердце выбрасывает в кровоток при каждом сокращении, увеличивается примерно на 50%. Объём крови, перекачиваемой за минуту, возрастает с 4,5 литра до 6 литров. Частота сердечных сокращений, то есть пульс, может увеличиться с 70 до 90 ударов в минуту.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Витамин C укрепляет дёсны. Ешьте киви, красный перец, апельсины и другие богатые им продукты. Будьте очень осторожны при использовании зубной нити.') WHERE id = '5f95650f-570c-4da1-a06d-ada1c9adbe04';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Не позднее этой недели вы уже должны были почувствовать движения малыша. По мере развития беременности характер его движений может меняться. Лёгкие шевеления, которые вы ощущали поначалу, на этом этапе становятся более заметными.;;;
Сейчас малыш часто двигается в ответ на происходящее вокруг. Сильный шум, яркий свет или некоторые продукты, стимулирующие его активность, могут заставить малыша толкаться и двигаться. На этом сроке ещё рано ожидать от него регулярных движений. Тем не менее, если вы долго не чувствуете шевелений, попробуйте съесть продукт, повышающий уровень сахара в крови, и полежать на левом боку в спокойной обстановке — это может помочь.'), baby_message_ru = COALESCE(baby_message_ru, 'Я мастер равновесия! 🤸‍♂️ Орган равновесия в моём ухе уже полноценно работает. Когда ты двигаешься, я тоже раскачиваюсь внутри. Для меня это настоящий аттракцион!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой грейпфрут'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности довольно часто встречается железодефицитная анемия, известная как малокровие. Снижение уровня гемоглобина в некоторых случаях может протекать без каких-либо симптомов. К распространённым признакам относятся бледность кожи, слабость, утомляемость, нарушение концентрации внимания, головная боль, онемение рук и ног, раздражительность, шум в ушах, трещины на губах и ранки в уголках рта, выпадение волос, истончение и ломкость ногтей. При прогрессировании дефицита железа могут возникнуть учащённое сердцебиение, желание есть землю или лёд, замедление функции щитовидной железы и синдром «беспокойных ног».;;;
Для профилактики анемии старайтесь ежедневно употреблять не менее 2-3 порций продуктов, содержащих железо. Больше всего железа содержится в субпродуктах (печени и т. д.), мясе, зелёных овощах, изюме, пекмезе, фундуке, арахисе, яйцах и бобовых. Апельсиновый сок, томатный сок и салат, употребляемые вместе с препаратами железа или железосодержащими продуктами, улучшают усвоение железа организмом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в области таза, выполняйте упражнения Кегеля — они также помогут подготовить мышцы к родам. Если вы почувствуете напряжение в животе, примите слегка тёплый душ: это поможет расслабиться и вам, и малышу.') WHERE id = '3837da99-9708-4d97-b55a-0f688693e446';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'С этой недели у вашего малыша начинается скачок роста. Это означает, что только за эту неделю он наберёт примерно 150 грамм. К концу недели малыш станет активнее, чем когда-либо, благодаря окрепшим мышцам, увеличившейся матке и возросшему объёму амниотической жидкости. Если вы рассчитываете на долгий ночной сон, вашим планам может быть не суждено сбыться. 😊 На этом этапе малыш спит около 18 часов в сутки, но ночью становится активнее. Причина в том, что днём ваши движения создают плавные колебания амниотической жидкости, которые убаюкивают малыша и помогают ему заснуть.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои глаза двигаются! 👀 Хотя веки всё ещё закрыты, под ними мои глаза быстро двигаются из стороны в сторону. Это значит, что я вижу сны. Наверное, во сне я вижу тебя. Я в мире красочных сновидений.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кукуруза'), body_changes_ru = COALESCE(body_changes_ru, 'Начиная с этого срока у вас могут появиться одышка и ощущение нехватки воздуха. Это связано с ростом матки и изменениями в гормональной системе. По мере роста малыша матка увеличивается и начинает давить на диафрагму. Кроме того, особенно на поздних сроках беременности, диафрагма поднимается примерно на 4 см. Это приводит к сдавливанию лёгких и изменению объёма вдыхаемого воздуха, вызывая одышку.;;;
Под действием гормона прогестерона дыхательный центр в головном мозге во время беременности заставляет вас дышать чаще и глубже. Это необходимо для доставки большего количества кислорода к плаценте и более интенсивного выведения углекислого газа. Поскольку при каждом вдохе и выдохе лёгкие пропускают на %30-40 больше воздуха, чем обычно, может возникать затруднённое дыхание и одышка.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить отёки ног, не оставайтесь надолго в одном положении, а когда сидите, приподнимайте ноги. При боли в спине лягте на левый бок и положите подушку между коленями. Продолжайте пить много воды: это помогает предотвращать отёки и поддерживать чистоту околоплодных вод. Сегодня уделите немного времени себе и послушайте успокаивающую музыку.') WHERE id = 'fd7b3482-d799-4c13-953a-cf2d0bbea122';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'У вашего малыша начали формироваться капилляры. Если бы вы могли увидеть малыша, то легко различили бы сосуды, появившиеся под его тонкой кожей. Эти сосуды уже достигают каждого органа и каждой ткани — от головы до кончиков пальцев.;;;
Капилляры образуют по всему телу разветвлённую сеть, общая длина которой, если вытянуть их в одну линию, может превышать 40 километров. Поскольку капилляры имеют наибольшую суммарную площадь поверхности среди всех кровеносных сосудов, скорость кровотока в них самая низкая.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои волосы приобретают цвет! 🎨 До сих пор они были совсем белыми, но теперь начинают окрашиваться в соответствии с моим генетическим кодом. Чёрные, светлые, каштановые... Интересно, какого цвета они будут? Может быть, как у вас, а может, как у папы. Это тоже сюрприз!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кукуруза'), body_changes_ru = COALESCE(body_changes_ru, 'Около 10% беременностей завершаются преждевременными родами. Поэтому вам важно уметь отличать признаки начала настоящих родов от ложных схваток.;;;
Постоянная или возникающая через регулярные промежутки боль, которая обычно начинается в пояснице, частые ритмичные сокращения, схваткообразные боли в нижней части живота, диарея и тошнота, ощущение давления во влагалище и прямой кишке, значительное увеличение количества влагалищных выделений и кровотечение могут указывать на начало родов.;;;
Ложные схватки возникают нерегулярно. Обычно они проходят при смене положения тела или во время движения. Однако при настоящих родовых схватках смена положения и движение не облегчают боль.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить онемение в руках, чаще встряхивайте кистями. Старайтесь не сгибать запястья во время сна. Если вы работаете за компьютером, регулярно делайте перерывы. После родов эти симптомы пройдут.') WHERE id = '5496d151-ca1f-41e0-a2f7-53fb1cdf1218';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе сосательный рефлекс вашего малыша, при котором он открывает рот в ответ на прикосновение к области вокруг рта и щёкам, уже достаточно хорошо развит. Для выживания малышу необходимо уметь получать грудное молоко. Поэтому благодаря сосательному рефлексу он может питаться без какого-либо обучения. Малыш может сосать не только для насыщения, но и чтобы чувствовать себя в безопасности.;;;
Почти все малыши рождаются с хорошо выраженным сосательным рефлексом. Его отсутствие может указывать на очень серьёзные причины. Поскольку родовые травмы, кислородное голодание мозга, нарушения работы ствола мозга, заболевания нервной системы и такие серьёзные инфекции, как менингит, могут привести к исчезновению сосательного рефлекса, таким малышам необходимо тщательное медицинское наблюдение.'), baby_message_ru = COALESCE(baby_message_ru, 'Когда я пугаюсь, то вздрагиваю! 😯 Мои рефлексы очень хорошо развиты. Услышав внезапный звук, я вздрагиваю всем телом. Это называется "Startle reflex". Вы тоже можете почувствовать внезапный толчок в животе. Когда я испугаюсь, погладьте живот и спокойно поговорите со мной — и я сразу успокоюсь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кукуруза'), body_changes_ru = COALESCE(body_changes_ru, 'Если инфекцию мочевыводящих путей не лечить и она будет прогрессировать, это может привести к преждевременным родам. Наиболее характерные признаки инфекции мочевыводящих путей — жжение при мочеиспускании и частые позывы к нему. Однако в зависимости от того, какой участок поражён, инфекция может прогрессировать и без каких-либо симптомов. Обычно инфекцию мочевыводящих путей лечат антибиотиками, и вскоре после начала терапии воспаление начинает уменьшаться. Однако при рецидивирующих инфекциях мочевыводящих путей может потребоваться лечение более высокими дозами антибиотиков.;;;
Если у вас инфекция мочевыводящих путей, обильное питьё помогает выводить бактерии из организма. Поэтому, выпивая не менее 2 литров жидкости в день, вы можете замедлить размножение бактерий и предотвратить прогрессирование инфекции. Употребление подходящих травяных чаёв также может способствовать ускорению выздоровления.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить давление на ноги, чаще меняйте положение тела в течение дня и при любой возможности отдыхайте, приподняв ноги выше уровня сердца. Это также поможет предотвратить отёки. Продукты, богатые магнием, уменьшают мышечные спазмы. Сегодня вечером в спокойной обстановке расскажите малышу о вашей первой совместной прогулке в будущем.') WHERE id = '6533fb18-848f-4cc6-b4c7-bf0dc1cff401';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Формирующиеся капилляры придают телу вашего малыша розоватый оттенок, поскольку его кожа пока ещё недостаточно плотная. Кроме того, в эти дни начинают открываться ноздри малыша, которые до сих пор оставались закрытыми. Нос не только играет важнейшую роль в дыхании, но и является органом обоняния — одного из пяти чувств. Обоняние работает вместе со вкусом. Именно поэтому при наличии инфекции в организме вкус пищи может не ощущаться.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя кожа уже не прозрачная! 🎨 Мама, раньше сквозь неё были видны все мои сосуды, но теперь кожа становится плотнее и приобретает цвет. По мере увеличения слоя подкожного жира она становится непрозрачной. Я уже теряю свой "инопланетный" вид и становлюсь похожим на настоящего милого малыша. Когда вы меня увидите, то сразу влюбитесь!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кукуруза'), body_changes_ru = COALESCE(body_changes_ru, 'Примерно через 1 месяц шейка матки начнёт постепенно укорачиваться. Во время беременности её длина остаётся стабильной с 14-й по 28-ю неделю, а после 28-й недели шейка матки начинает постепенно укорачиваться и истончаться.;;;
Согласно одному исследованию, около половины женщин, у которых на 24-й неделе длина шейки матки составляла 25 mm или менее, родили до 35-й недели.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в пояснице, не сидите долго в одном положении: каждые 30 минут вставайте и немного ходите. Сон полностью на левом боку улучшит поступление кислорода и к вам, и к малышу. Если в пояснице возникнет острая боль, обязательно проконсультируйтесь с врачом и обсудите использование ортопедического пояса.') WHERE id = '525f7e7c-0bea-4071-90df-5a46dae136d6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Основные причины столь быстрого набора веса вашим малышом — развитие мышечной и костной массы, образование жировой ткани и рост органов. Движения способствуют развитию мышц рук и ног, а окрепшие мышцы позволяют малышу двигаться ещё активнее, что, в свою очередь, стимулирует их дальнейшее развитие. Благодаря увеличению объёма жировой ткани щёчки малыша становятся пухлее. Черты его лица постепенно приобретают всё более чёткие очертания. Во время подробного ультразвукового исследования, если малыш находится в подходящем положении, вы даже сможете увидеть, на кого он похож. 😊;;;
Слух вашего малыша стал настолько чувствительным, что он способен различать даже низкочастотные звуки. Среди других звуков он с лёгкостью узнаёт ваш голос. Услышав его, малыш чувствует себя в безопасности, его сердцебиение учащается, и он даже может ответить вам активным движением, показывая, что слышит вас.'), baby_message_ru = COALESCE(baby_message_ru, 'Моё личико уже готово! 👶 Anacan, если бы вы увидели меня сейчас, то точно знали бы, как я буду выглядеть после рождения. Черты лица, носик, губы — всё уже сформировалось. Просто я пока немного худенький. На кого же я похож — на вас или на папу?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кукуруза'), body_changes_ru = COALESCE(body_changes_ru, 'К этому сроку вы, вероятно, набрали от 5500 граммов до 8500 граммов. Если вам кажется, что вы набрали больше, внимательное отношение к весу поможет предотвратить возможные проблемы как у вас, так и у малыша.;;;
Чрезмерный набор веса может неблагоприятно повлиять на течение беременности и повысить риск таких состояний, как гестационная гипертензия и гестационный сахарный диабет. Кроме того, лишний вес может сохраниться после родов, и избавиться от него будет непросто.;;;
Если до беременности у вас был средний вес, без его избытка или дефицита, то в первом триместре вам не требуются дополнительные калории. Во втором триместре достаточно увеличить суточную калорийность рациона на 300 калорий. В последнем триместре дополнительная потребность возрастает примерно до 450 калорий. Это соответствует дополнительным двум-трём порциям фруктов, 2 стаканам нежирного молока, 1 большой миске йогурта, 60 граммам миндаля или 45 граммам сливочного масла в день.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Давайте глазам отдых. Если вы много работаете за компьютером, чаще делайте перерывы. Капли «искусственная слеза» с натуральным составом могут помочь устранить сухость.') WHERE id = '64f0cdbb-7db6-482f-be9f-92435bab2ca8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Вкусовые ощущения вашего малыша достигли уже достаточно высокого уровня развития. Восприятие вкуса осуществляется с помощью рецепторов на языке. Вкусовые рецепторы, также называемые вкусовыми почками, расположены в особых структурах — сосочках. Сосочки представляют собой небольшие неровные выступы на поверхности языка.'), baby_message_ru = COALESCE(baby_message_ru, '🌽 Я уже размером с кукурузу! Эта неделя очень важна, Anacan. Врачи говорят, что теперь я считаюсь «жизнеспособным». Это означает, что даже если я сейчас появлюсь на свет, благодаря современной медицине у меня будет шанс выжить (но пока ещё слишком рано, я хочу остаться здесь!). Это важнейший этап!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кукуруза'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за быстро растущего живота, частого мочеиспускания и затруднённого дыхания у вас могли начаться проблемы со сном. Несколько бессонных ночей подряд способны усиливать чувство усталости.;;;
Частая потребность ходить в туалет — одна из основных причин бессонницы в этот период. Повышение уровня прогестерона и рост матки усиливают давление на мочевой пузырь, из-за чего позывы к мочеиспусканию возникают чаще. Кроме того, бессонницу могут вызывать отёки, синдром беспокойных ног, изжога и нарушения пищеварения.;;;
Чтобы спать спокойнее, старайтесь ужинать пораньше, избегайте жирной и острой пищи, принимайте перед сном тёплый душ и пейте молоко. Чтобы реже вставать в туалет, выпивайте основную часть суточного объёма воды днём и старайтесь не пить слишком много вечером.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Из-за повышения температуры тела вам может чаще хотеться пить, поэтому выработайте привычку регулярно пить воду. Чтобы облегчить боль в рёбрах, поднимите руки вверх и сделайте глубокий вдох — это поможет расширить грудную клетку. Если вы ощущаете тяжесть в пояснице, выбирайте не слишком мягкий матрас. Сегодня не перенапрягайтесь: немного почитайте и отдохните.') WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе во время осмотра у врача вы можете увидеть, как ваш малыш улыбается. 😊 Такие мимические движения малыша, как высовывание языка, гримасы и улыбка, могут указывать на активное развитие тканей мозга в утробе матери.;;;
В дни сильного стресса, после травмирующих событий или когда вы чувствуете себя несчастной, выделяемые вашим организмом гормоны могут влиять на малыша, из-за чего он будет двигаться меньше.;;;
Точно так же, когда вы смеётесь, радуетесь или испытываете приятное волнение, гормоны, выделяемые вашим организмом, через кровь и плаценту напрямую поступают к малышу. Это может ускорить его сердцебиение, сделать его активнее и побудить реагировать на вас.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои лёгкие готовятся! 🌬️ В них начало вырабатываться особое вещество под названием «сурфактант». Когда я сделаю первый вдох, оно поможет моим лёгким раскрыться и не даст им слипнуться. Пока я ещё нахожусь в воде, но это важнейшая подготовка к будущему. Дышать — значит быть свободным!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кукуруза'), body_changes_ru = COALESCE(body_changes_ru, 'Возможно, вы заметили, что время от времени из груди выделяется жидкость. Это нормально и не должно вызывать беспокойства. Гормоны, подготавливающие грудь к выработке молока после родов, могут уже во время беременности вызывать выделение жидкости из груди. Эти выделения отличаются от зрелого грудного молока и называются молозивом. Молозиво содержит больше белка, жиров и антител, чем зрелое грудное молоко.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте завершение 24-й недели, уделив время себе! Чтобы уменьшить боль в спине, выбирайте ортопедическую обувь на низком каблуке. Если вы ещё не проходили тест на толерантность к глюкозе, обсудите его с врачом. Ночью отдыхать лёжа на левом боку лучше всего для кровообращения и у вас, и у малыша.') WHERE id = 'f9782520-1096-410b-87b6-a06b825d2aa4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Функционирующие голосовые связки малыша могут время от времени вызывать у него икоту в течение дня. Возможно, вы уже даже ощущаете её. Если малыш через равные промежутки времени совершает ритмичные движения, напоминающие сердцебиение, это означает, что он икает. Многие беременные женщины думают, что икота вредит малышу, однако она имеет большое значение для его развития. Икота может прекратиться через несколько минут, а иногда длиться до получаса. Кроме того, поскольку органы продолжают расти и развиваться, диафрагма время от времени сокращается, вызывая икоту. Можно сказать, что икота — это своеобразная тренировка диафрагмы. Так диафрагма готовится к самостоятельному дыханию малыша после рождения.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои ноздри открываются! 👃 До сих пор они были закрыты, но сегодня начинают открываться. Теперь я могу свободнее «вдыхать» амниотическую жидкость носом. Это тренирует мои дыхательные мышцы. Иногда, когда жидкость попадает мне в горло, я икаю. Вы чувствуете эти ритмичные «тук-тук»?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Боль в пояснице может усилиться. По мере того как живот растёт вперёд, вы непроизвольно отклоняете спину назад, чтобы сохранять равновесие. Это создаёт напряжение в мышцах спины. Длительное пребывание на ногах усиливает боль.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить одышку, старайтесь сидеть прямо и расправлять грудную клетку, отводя плечи назад. Для восполнения потребности в кальции в течение дня отдавайте предпочтение молочным продуктам или зелёным листовым овощам. Если кожа живота чешется, увлажняйте её натуральным миндальным маслом или маслом какао. Сегодня постарайтесь немного успокоиться и помечтайте вместе с малышом о прекрасных днях, которые ждут вас впереди.') WHERE id = '637acaae-ce43-494a-a7b1-a90cc43779c0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Благодаря кровеносным сосудам, сформировавшимся в лёгких малыша, осуществляется малый круг кровообращения. Сначала кровь с низким содержанием кислорода и высоким содержанием углекислого газа, собравшаяся в правом желудочке, поступает в лёгкие по лёгочной артерии. Достигнув правого и левого лёгкого, эта кровь в результате газообмена отдаёт углекислый газ, насыщается кислородом и очищается. Малый круг кровообращения завершается, когда очищенная кровь по лёгочной вене поступает в левое предсердие сердца, а затем через аорту перекачивается по всему организму.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой позвоночник очень крепкий! 🦴 Мои кости, суставы и связки окрепли настолько, что теперь я могу держать тело совершенно прямо. Я выпрямляю спинку и потягиваюсь. Позвоночник — это главная опора, которая в будущем поможет мне держаться прямо. Продолжайте получать достаточно кальция — он мне ещё очень нужен!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Вы можете ощущать сухость глаз или затуманивание зрения. Гормоны беременности уменьшают выработку слёзной жидкости. Кроме того, задержка жидкости в организме может незначительно изменить форму роговицы. Показатели зрения могут временно измениться, поэтому не спешите покупать новые очки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если во время сна положить подушку между коленями, боль в пояснице может значительно уменьшиться. Это помогает сохранять позвоночник в ровном положении. Кроме того, во время беременности сон на жёстком матрасе может быть более комфортным.') WHERE id = 'a0633b87-cd3d-42be-95e2-2574a37bda58';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Малыш достиг порога жизнеспособности. Его спинной мозг, управляющий всеми нервными импульсами, уже хорошо развит и продолжает формироваться.;;;
В структуре спинного мозга снаружи находится белое вещество, а внутри — серое. Окружающее спинной мозг белое вещество состоит из нервных волокон, покрытых миелиновой оболочкой, а серое — из нервных клеток без миелиновой оболочки. Одна из важнейших функций спинного мозга — управление рефлексами, сигналы для которых поступают из продолговатого мозга, а также обеспечение выполнения произвольных движений, управляемых головным мозгом. Позвоночный столб состоит в общей сложности из 33 позвонков. Для защиты позвоночника от ударов и травм между позвонками находится вещество, называемое спинномозговой жидкостью.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с цветную капусту! Сейчас я быстро набираю вес. Морщинки на моей коже разглаживаются, а щёчки становятся пухлее. Я уже похож на милого малыша. Цвет и структура моих волос уже определились.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Не забывайте регулярно сдавать анализы крови и мочи. Ежемесячные анализы крови помогают своевременно выявлять и предотвращать такие проблемы, как возможный дефицит железа, ранее не диагностированные заболевания щитовидной железы, которые могут активизироваться во время беременности, незамеченная несовместимость крови, инфекции, включая токсоплазмоз и краснуху, гепатит и бессимптомные инфекции мочевыводящих путей.;;;
Невыявленные заболевания щитовидной железы напрямую влияют на ваш обмен веществ и поэтому могут негативно сказаться на развитии малыша. В первые 12 недель беременности щитовидная железа малыша ещё не завершила своё развитие и не способна самостоятельно вырабатывать гормоны, поэтому часть вырабатываемых вашим организмом гормонов поступает к малышу. После 12-й недели, особенно в третьем триместре беременности, уровень ТТГ постепенно повышается под воздействием некоторых гормонов, выделяемых плацентой.;;;
Бессимптомные инфекции мочевыводящих путей, встречающиеся во время беременности, являются одной из наиболее распространённых причин выкидышей на ранних сроках. Поэтому необходимо регулярно сдавать общий анализ мочи.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в пояснице, не оставайтесь подолгу в одном положении и отдавайте предпочтение удобной ортопедической обуви. Если вы ощущаете зуд или стянутость кожи живота, не забывайте пользоваться увлажняющими маслами. Помимо достаточного количества воды, увеличьте содержание клетчатки в рационе, чтобы облегчить работу пищеварительной системы. Сегодня позвольте себе отдыхать больше, чем обычно.') WHERE id = '3d485358-4a99-4889-8e24-ba3824e8665d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже может открывать глаза в утробе матери! Веки, которые до этого этапа оставались закрытыми, теперь обрели способность открываться. Веки — важная защитная система: они оберегают глаза от внешних воздействий, равномерно распределяют слёзную жидкость, предотвращая пересыхание, и регулируют количество поступающего света.;;;
Несколько интересных особенностей век: верхнее веко благодаря особой мышце более подвижно, чем нижнее. Мышцы верхнего и нижнего век работают в противоположных направлениях, обеспечивая полное закрытие глаз. Веки двигаются как осознанно, так и рефлекторно. Мигательный рефлекс распределяет слёзную жидкость по поверхности глаза, помогая сохранять его функции.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя жировая прослойка увеличивается! 🧈 Складочки на моём теле постепенно разглаживаются, потому что под ними накапливается жир. Теперь я выгляжу более гладким и мягким. Эта жировая прослойка будет согревать меня. Когда вы возьмёте меня на руки, я буду не костлявым, а «пухленьким». Благодаря вашему молоку я вырасту ещё больше.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'К этой неделе вы уже должны были пройти глюкозотолерантный тест. Если показатели превышают допустимые значения, вам могли диагностировать гестационный сахарный диабет.;;;
Во время беременности организму требуется больше инсулина. Однако происходящие гормональные изменения могут снижать чувствительность клеток к нему. В норме при повышении уровня сахара в крови поджелудочная железа реагирует выделением большего количества инсулина. Но если она не может выработать достаточно инсулина для снижения уровня сахара в крови, возникает состояние, называемое нарушением толерантности к глюкозе. Если оно развивается во время беременности, его называют гестационным сахарным диабетом.;;;
У женщин с гестационным сахарным диабетом избыток глюкозы в крови проникает через плаценту к малышу, из-за чего он может набрать чрезмерный вес.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить отёки, не забывайте пить достаточно воды в течение дня. При судорогах в ногах перед сном могут помочь лёгкий массаж или тёплый душ. Сегодня проведите немного времени вместе с малышом, расскажите ему о своих планах на будущее — он сразу чувствует волнение и любовь в вашем голосе.') WHERE id = 'e581817d-cd7b-4e6d-a51b-e85acf339c0a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Формирование слоёв сетчатки глаза вашего малыша уже завершилось. Сетчатка — одна из важнейших частей глаза. Это тонкий слой, покрывающий заднюю поверхность глазного яблока. Благодаря напоминающей сеть структуре кровеносных сосудов она получила название сетчатой оболочки глаза. Этот слой выстилает всю внутреннюю стенку глаза и состоит из сосудов и нервных волокон, связанных с головным мозгом. На обращённой внутрь глазного яблока поверхности сетчатки находятся миллионы клеток, чувствительных к свету и цвету. Они принимают световые сигналы, поступающие из передней части глаза, преобразуют их в электрические импульсы, понятные мозгу, и передают зрительному нерву. Зрительный нерв, в свою очередь, передаёт эти сигналы в мозг, благодаря чему формируется зрительное восприятие. По каналообразной структуре зрительный нерв направляется к участку мозга, отвечающему за зрение. Место выхода зрительного нерва называется диском зрительного нерва, или соском зрительного нерва. Поскольку в расположенном в центральной области сетчатки диске зрительного нерва нет светочувствительных клеток, он не воспринимает свет, поэтому эту область называют «слепым пятном».'), baby_message_ru = COALESCE(baby_message_ru, 'Я готовлюсь открыть глаза! 👁️ Линия, соединяющая мои веки, уже вот-вот разделится. Совсем скоро, возможно через несколько дней, я открою глаза! Даже находясь в темноте, я хочу смотреть. Мои ресницы уже готовы защищать глаза. Я с нетерпением жду встречи с вами, Anacan.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Возможно, вы уже заметили, что ваши волосы стали более блестящими и густыми. Однако вместе с этим на теле может появиться больше волос, чем до беременности. Такое усиление роста волос, связанное с гормональными изменениями, обычно начинается во втором триместре, а вскоре после родов лишние волосы чаще всего выпадают.;;;
Если во время беременности вас беспокоят нежелательные волосы, предпочтительными способами их удаления являются бритьё, эпилятор или воск. Эти методы никак не вредят вашему малышу. Однако следует учитывать, что ставшая более чувствительной во время беременности кожа может покраснеть или раздражиться, что повышает риск инфекции. Кроме того, во время беременности не следует пользоваться кремами для депиляции. Причина в том, что содержащиеся в них агрессивные химические вещества, такие как сульфид бария и тиогликолят кальция, потенциально могут навредить малышу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Включите упражнения Кегеля — попеременное напряжение и расслабление мышц тазового дна — в свой ежедневный распорядок. Укрепление этих мышц помогает предотвратить недержание мочи и облегчить роды. Использование ежедневных прокладок поможет вам чувствовать себя комфортнее.') WHERE id = 'ca71a802-8315-4430-831a-1c24d93987c8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Брови и ресницы вашего малыша уже стали хорошо заметными. Они служат естественным защитным барьером, оберегающим глаза от инородных частиц. Ресницы отличаются по строению от остальных волос на теле: у них нет мышцы, поднимающей волос, и, в отличие от многих других волос, они не подвержены воздействию некоторых гормонов. Брови — это дугообразно расположенные волоски над надбровными дугами. Хотя волосяные фолликулы бровей имеют такое же базовое строение, как фолликулы на других участках тела, их фазы роста проходят значительно быстрее.;;;
Брови защищают глаза от пота и создают тень. Они также очень важны для мимики: вместе с ресницами, скулами, линией роста волос и носом брови обрамляют глаза и тем самым влияют на внешний облик лица.;;;
Эти структуры содержат небольшое количество воды, а также богаты углеводами, мочевиной, мочевой кислотой, свободными аминокислотами, фосфолипидами, холестерином, жирными кислотами и важнейшим строительным материалом — кератином. Иными словами, основу этих структур составляет кератин — белок из 18 аминокислот, который вырабатывается кератиноцитами, расположенными в нижних слоях кожи.'), baby_message_ru = COALESCE(baby_message_ru, 'Я разделяю ваш стресс. 😔 Anacan, когда вы напряжены, кортизол из вашей крови поступает и ко мне. Я начинаю беспокоиться, и мои движения меняются. Но когда вы смеётесь и радуетесь, я тоже успокаиваюсь. Пожалуйста, берегите себя. Мы с вами одна команда, ваши чувства — это и мои чувства.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Срок беременности, рассчитанный врачом по результатам ультразвукового исследования малыша, может не полностью совпадать со сроком, определённым по дате вашей последней менструации. В таких случаях не следует беспокоиться.;;;
Если во время контрольных ультразвуковых исследований врач обнаруживает, что развитие малыша отстаёт от ожидаемых показателей, может быть заподозрена задержка внутриутробного развития. У значительной части малышей это связано с генами, унаследованными от родителей. Если мама и папа генетически имеют миниатюрное телосложение, не стоит ожидать, что малыш в утробе будет крупным. Различия в развитии в пределах двух недель в большую или меньшую сторону считаются нормальными и при отсутствии других факторов не вызывают подозрений. Если разница превышает 2 недели, могут потребоваться подробное ультразвуковое исследование, консультация специалиста по беременности высокого риска и оценка кровотока к малышу. Известно, что в 75% случаев задержка развития у малышей имеет конституциональный характер. Кроме того, к ней могут привести снижение кровотока к малышу, старение плаценты и уменьшение количества околоплодных вод.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить изжогу, не ложитесь сразу после еды, а во время сна слегка приподнимайте голову с помощью подушки. При болях в пояснице регулярно выполняйте лёгкие упражнения на растяжку. Вы уже носите чудо весом 1 кг, поэтому ни в коем случае не поднимайте тяжести. Сегодня вечером погладьте живот и поговорите со своим малышом — он чувствует ваши прикосновения!') WHERE id = '7b482622-6ce3-4e23-a975-62440aec9dc6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Нервная система вашего малыша и все связанные с ней мышцы уже достаточно развиты, чтобы осознанно реагировать на внешние раздражители. Под поведением понимается осознанная реакция на внутренние и внешние воздействия. Основное отличие поведения от простого движения заключается в том, что поведение представляет собой осознанную реакцию на определённое воздействие.;;;
Осознанное поведение по своей сути имеет причину и обязательно направлено на достижение определённой цели. В отличие от движения, оно отражает волю и индивидуальные мотивы того, кто его проявляет.;;;
С физиологической точки зрения это поток энергии, направляемый к телу внутренними и внешними факторами. Благодаря развитой нервной системе организм воспринимает и интерпретирует этот поток, а затем использует обратную связь, чтобы адаптироваться к окружающей среде и раздражителям.;;;
В основе поведения лежит соответствие между раздражителем и ответной реакцией на него. Такое соответствие помогает организму сохранять равновесие во взаимодействии с окружающей средой.;;;
Проявлением этого равновесия можно считать то, что малыш улыбается, когда улыбаетесь вы, поджимает губы, когда ему больно, и сосёт молоко, когда голоден.'), baby_message_ru = COALESCE(baby_message_ru, 'Я ОТКРЫЛ ГЛАЗА! 👀 Anacan, сегодня для меня революционный день. Мои веки, которые до сих пор были сомкнуты, разделились, и я впервые открыл глаза. Пока всё вокруг размыто, но я уже умею моргать. Хотя здесь темно, я учусь смотреть. Я стал ещё на шаг ближе к тому, чтобы увидеть тебя!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Схватки Брэкстона — Хикса (ложные схватки) могут возникать чаще. Не пугайтесь, если живот становится твёрдым как камень. Так мышцы матки «тренируются». Если схватки проходят после смены положения тела или стакана воды, значит, они ложные. Настоящие родовые схватки постепенно усиливаются и не проходят.;;;
Также может появиться боль в рёбрах. Матка поднялась настолько высоко, что уже начинает расширять рёберную дугу. Голова или ножки малыша могут упираться в ваши рёбра. Иногда из-за этого становится трудно глубоко вдохнуть.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Запомните признаки преэклампсии: внезапные отёки лица и рук, сильная головная боль, «вспышки света» перед глазами или боль под рёбрами. При появлении любого из этих симптомов немедленно обратитесь к врачу.') WHERE id = '664b492c-1968-495f-9380-1ec985579ba8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ускоренное образование жировой ткани у малыша способствует развитию подкожной клетчатки, благодаря чему он быстро набирает вес. Кроме того, после рождения этот жировой слой будет служить защитным барьером от холода.;;;
Вес доношенных малышей при рождении обычно составляет от 2500 граммов до 4000 граммов. Этот показатель зависит от множества факторов, один из наиболее известных — пол малыша. Между девочками и мальчиками существуют генетические различия: у мальчиков жировых клеток больше, чем у девочек.;;;
Вес малыша в утробе может быть ниже или выше среднего по множеству причин. Значительная часть случаев недостаточного веса связана с генетическими факторами. Кроме того, к этой проблеме могут привести некоторые заболевания во время беременности и неправильное питание. Если вес малыша выше среднего и при этом наблюдается избыток жидкости, в первую очередь подозревают гестационный диабет. Вместе с тем генетические особенности и различия в обмене веществ также могут стать причиной того, что вес малыша превышает средние показатели.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои ресницы растут! 👁️ Теперь, когда я открыл глаза, их нужно защищать. У меня длинные, шелковистые ресницы. Когда ты посмотришь мне в глаза, то будешь ими восхищаться. А ещё мои брови уже полностью сформировались. Теперь я похож на маленькую куколку.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'В этот период из-за изменений гормонального баланса меняется микрофлора влагалища. Поэтому во время беременности организм становится более восприимчивым к вагинальному кандидозу. Особенно часто он может возникать, если у вас есть риск выкидыша и по этой причине вы используете вагинальные свечи или кремы. К симптомам вагинального кандидоза относятся жжение и зуд в области половых органов, обильные белые выделения, учащённое мочеиспускание и боль во время полового акта. Хотя проявления могут различаться, выделения при вагинальном кандидозе чаще всего имеют белый или кремовый цвет, густую кремообразную консистенцию, комковатую структуру, напоминающую творог или крошки сыра, и кислый запах.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте завершение 26-й недели, побаловав себя! Чтобы уменьшить боль в пояснице, во время сидения обязательно подкладывайте под спину поддерживающую подушку. Если вы ещё этого не сделали, уточните у врача последние детали проведения глюкозотолерантного теста. Ночью лучше всего лежать на левом боку — это оптимальное положение для кровообращения и у вас, и у малыша.') WHERE id = '3c253a83-3ac7-475e-8987-d27fab00a076';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Дыхательная, пищеварительная, нервная и иммунная системы вашего малыша продолжают развиваться. Иммунная система — это защитная система организма, противостоящая вредному воздействию микроорганизмов, вызывающих инфекции: вирусов, бактерий, грибков и паразитов.;;;
Клетки, ткани и органы, формирующие иммунную систему, работают сообща, слаженно и очень эффективно. Иммунитет подразделяется на два основных вида: врождённый и приобретённый. Врождённая иммунная система естественным образом присутствует в организме. Она первой встречает и распознаёт проникшие в организм болезнетворные микроорганизмы, а затем старается их уничтожить. Приобретённая иммунная система активируется после встречи организма с вредоносным микроорганизмом и определённого периода подготовки. Она вырабатывает защитные структуры против возбудителя и обладает иммунологической памятью. Её основными элементами являются T- и B-лимфоциты.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, 3-й триместр уже на пороге! Я перехожу в «тяжёлую весовую категорию». Места становится всё меньше, поэтому мои движения могут быть более резкими. Прости, если задеваю твои рёбра, — я просто потягиваюсь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'На этих неделях преэклампсия встречается особенно часто, поэтому вам следует быть внимательной и регулярно измерять артериальное давление. Преэклампсия проявляется после 20-й недели беременности повышением артериального давления выше 140/90 мм ртутного столба и появлением белка в моче. Эти состояния часто сопровождаются отёками.;;;
Механизм развития преэклампсии можно описать как нарушение сосудистого русла. В основе проблемы лежит чрезмерное сужение тонких и извитых артерий, питающих матку, из-за чего плацента не может обеспечивать малыша достаточным количеством питательных веществ.;;;
Преэклампсия встречается примерно в 5%–7% всех беременностей. При резком увеличении веса, появлении отёков и припухлостей, слабости, помутнении сознания, боли в животе или уменьшении активности малыша необходимо немедленно обратиться в ближайшее медицинское учреждение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если во время сна класть подушки между ног и под живот, это поможет уменьшить боль в пояснице. Сон на левом боку улучшает приток крови к малышу и облегчает работу ваших почек.') WHERE id = '1d4c4310-3e73-4b60-b4c5-883dd87bf1e3';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По мере стремительного развития мозга вашего малыша формируются сложные оболочки, которые окружают и защищают его со всех сторон, — мозговые оболочки. Эти оболочки состоят из трёх слоёв и вместе с костями черепа служат прочной «бронёй», защищающей мозг от внешних ударов. Эта защитная система продолжается до области позвоночника, оберегая все отделы центральной нервной системы. В мозге вашего малыша развиваются две основные структуры:;;;
Серое вещество: часть мозга, в которой сосредоточены нервные клетки; мозговые оболочки участвуют в его формировании.;;;
Белое вещество: длинные нервные волокна, покрытые миелиновой оболочкой и обеспечивающие связь между отделами нервной системы.;;;
Самая интересная часть — кора головного мозга. Несмотря на толщину всего 3 mm, именно в ней находится три четверти всех нервных клеток мозга. Чтобы такое количество клеток поместилось на столь небольшой площади, кора головного мозга приобретает складчатую структуру с глубокими бороздами.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои капилляры наполняются кровью! 🩸 Под моей кожей формируются и наполняются кровью тысячи крошечных кровеносных сосудов. Благодаря этому моя кожа приобретает красивый розовый оттенок. Моё кровообращение уже настолько развито, что сердце снабжает кислородом всё моё тело. Я полон жизни, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности вам следует особенно внимательно относиться к уходу за кожей. В первом и последнем триместрах усиливается выработка кожного сала — себума, поэтому склонность к акне может появиться даже у женщин, которые обычно не сталкиваются с высыпаниями. В этот период очищайте кожу органическими и безопасными средствами без агрессивных химических компонентов. Кроме того, важно защищать кожу от солнца и регулярно увлажнять её средствами с составом, подходящим для беременных.;;;
Чтобы предотвратить грибковые инфекции, после душа тщательно вытирайте внутреннюю часть и область за ушами, шею, подмышки, участки между грудями и под грудью, пупок, паховую область и промежутки между пальцами ног. Отдавайте предпочтение нижнему белью и носкам из хлопка.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня создайте для себя приятную атмосферу в честь того, что вы успешно прошли 25 недель беременности. Чтобы уменьшить отёчность ног, подкладывайте под них подушку, когда отдыхаете. Пейте достаточно воды и немного сократите употребление соли. Если вы ещё не проходили тест с глюкозной нагрузкой, обсудите его планирование с врачом. Завтра начинается новая неделя — 26-я!') WHERE id = '2ee2955f-80d8-4cff-afab-c01bdb172368';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Благодаря открывшимся ноздрям ваш малыш периодически совершает тренировочные дыхательные движения. Эти упражнения способствуют развитию дыхательной системы. Дыхательная система последовательно включает нос, глотку, гортань, трахею и лёгкие. Через нос воздух поступает в организм. Волосовидные структуры на его внутренней поверхности и слизистый эпителий поддерживают влажность в полости носа, помогая защищать организм от инфекций. Глотка проводит поступивший воздух в дыхательное горло, а дыхательное горло, называемое «трахеей», направляет его в лёгкие. Слизь, вырабатываемая мерцательным эпителием внутри трахеи, увлажняет проходящий воздух и помогает защищать лёгкие от инфекций.'), baby_message_ru = COALESCE(baby_message_ru, 'Я уже пользуюсь рукой! 🖐️ Anacan, теперь мои движения не просто случайны. Я выбираю, какой рукой буду пользоваться чаще. То есть уже определено, буду ли я левшой или правшой. Я шевелю пальчиками и хватаюсь за пуповину.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'К этой неделе общий объём крови в вашем организме увеличился примерно на 25%. Чтобы удовлетворить растущую потребность малыша в кровоснабжении, объём крови, поступающей к матке, должен увеличиваться. В последние недели беременности кровоток в матке достигает 1 литра в минуту. Ещё одна причина увеличения объёма крови связана с кровопотерей во время родов. При вагинальных родах теряется 500-750 ml крови, а при кесаревом сечении этот объём достигает 1000 ml. С учётом разрезов, выполняемых во время родов, и послеродового кровотечения организм должен быть подготовлен к такой значительной кровопотере.;;;
Однако, несмотря на увеличение объёма крови, растущая с каждой неделей матка уменьшает приток крови к сердцу, особенно когда вы лежите на спине. Поэтому теперь для здоровья как вашего, так и малыша очень важно лежать на правом или левом боку.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы заметите внезапный и выраженный отёк век или ног, обязательно сообщите врачу, чтобы проверить артериальное давление. Для уменьшения одышки старайтесь сидеть прямо и выполняйте лёгкие дыхательные упражнения. Сократите количество соли в рационе, но продолжайте пить достаточно воды. Сегодня расскажите малышу о его будущей комнате или игрушках.') WHERE id = 'd74fd8bf-8b0d-4ea8-8d39-905a3d36166e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Альвеолы в лёгких вашего малыша продолжают развиваться. Альвеолы — это похожие на виноградные гроздья воздушные мешочки, расположенные на концах бесчисленных бронхиол внутри лёгких. Именно здесь происходит газообмен: кислород поступает в кровь, а углекислый газ выводится из неё. Альвеолы покрыты очень тонкой оболочкой. Общая толщина барьера между воздухом в альвеолах и кровью в капиллярах составляет всего 4 микрометра. Это примерно равно радиусу одного эритроцита. Благодаря чрезвычайной тонкости этого барьера газообмен в обоих направлениях происходит очень быстро и эффективно. Кроме того, при вдохе и выдохе альвеолы раскрываются и сжимаются. Они покрыты веществом, называемым сурфактантом, которое помогает воздушным мешочкам раскрываться и сжиматься. Благодаря ему мешочки не спадаются полностью при выдохе, а поверхностное натяжение в лёгких регулируется.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую ваш запах! 👃 Запах амниотической жидкости меняется в зависимости от того, что вы едите, и от окружающей среды. Моё обоняние уже настолько развито, что я замечаю эти изменения. После рождения я узнаю ваш запах среди тысяч людей. Запах мамы — самый прекрасный аромат в мире.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Если во время беременности у вас повышено артериальное давление, обязательно сообщите об этом врачу.;;;
При повышенном артериальном давлении приток крови к плаценте замедляется. Это означает, что ваш малыш может получать недостаточно кислорода и питательных веществ. В результате его внутриутробное развитие может замедлиться. Среди возможных причин повышения давления — гипертония до беременности, возраст 35 лет и старше, избыточный вес, многоплодная беременность и нарушения иммунной системы.;;;
Если повышенное артериальное давление сопровождается сильной болью, быстрым набором веса, отёками рук и лица, а также затуманенным зрением, незамедлительно обратитесь к врачу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить чувство переполнения желудка, ешьте небольшими порциями 5-6 раз вместо нескольких обильных приёмов пищи. Чтобы снизить нагрузку на поясницу, во время сидения используйте поддерживающие спину подушки и держите спину прямо. Для профилактики запоров добавьте в рацион больше сырых овощей и фруктов. Сегодня вечером немного приподнимите ноги и отдохните под спокойную музыку.') WHERE id = 'ed58011e-092e-41ea-a45c-df149cb7fc4b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Эластичность мышц вашего малыша продолжает развиваться. Развитие эластичности мышц положительно влияет на силу хватания малыша и играет важную роль в формировании рефлексов.;;;
Основу двигательной системы составляют мышцы, прикреплённые к скелету. В теле человека насчитывается около 650 мышц, общая масса которых в среднем составляет 40-50% массы всего тела. Мышцы подразделяются на три типа: поперечнополосатые, гладкие и сердечная мышца. Они обладают рядом особых свойств: возбудимостью, проводимостью, сократимостью, эластичностью и вязкостью.;;;
Как и любая живая ткань, мышцы способны реагировать на воздействующий на них раздражитель. Ответ мышц на раздражение проявляется в виде сокращения. Существует пять типов сокращений: изометрические, концентрические, эксцентрические, изокинетические и тетанические.'), baby_message_ru = COALESCE(baby_message_ru, 'Здравствуй, 3-й триместр! 👋 Anacan, мы завершили большой этап. Второй триместр заканчивается, и теперь начинается 3-й триместр. Я уже большой малыш. Теперь моя главная задача — набирать вес и готовиться к появлению на свет. Я знаю, что ты устала, но осталось совсем немного. Мы скоро встретимся!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Брокколи'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за того, что ваш живот заметно увеличился, привычная одежда может стать вам мала. Особенно в последнем триместре следует избегать одежды, сдавливающей живот, поскольку это может причинять малышу дискомфорт и замедлять кровоток. Кроме того, брюки, сильно сдавливающие ноги, могут нарушать работу вен и способствовать развитию варикоза.;;;
Ещё один важный вопрос — ношение обуви на высоком каблуке во время беременности. При ходьбе босиком 50% массы тела приходится на пятку, а 50% — на переднюю часть стопы, что помогает сохранять равновесие. При ношении обуви на высоком каблуке это соотношение меняется примерно до 10% и 90%, что приводит к серьёзному нарушению равновесия. Поскольку во время беременности из-за растущей матки центр тяжести тела и без того смещается, обувь на высоком каблуке может привести к потере равновесия и серьёзным травмам.'), daily_tip_ru = COALESCE(daily_tip_ru, 'С началом третьего триместра самое время обсудить с врачом резус-конфликт (если у вас отрицательная группа крови) и результаты глюкозотолерантного теста. Для уменьшения боли в пояснице можно использовать бандаж для беременных. Начните считать движения малыша в течение дня; обычно нормой считается 10 движений за 2 часа.') WHERE id = 'efc08af4-0ca2-4af8-832f-852d08704ce8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе начинается 7-й месяц вашей беременности. Одновременно вы вступаете в последние три месяца беременности, известные как последний триместр. К этому времени малыш уже достаточно развит, чтобы выжить вне матки. На данном этапе его шансы на выживание в случае преждевременных родов превышают 80%. Лёгкие, которые полностью созреют к 37-й неделе, уже развиты настолько, что при преждевременных родах на этой неделе малыш сможет дышать при поддержке в отделении реанимации новорождённых. Главная причина этого заключается в том, что значительная часть сурфактанта уже выработана.;;;
Начиная с этой недели врач может попросить вас считать движения малыша. При подсчёте важно помнить, что у малыша есть периоды сна и бодрствования и большую часть суток он проводит во сне. Благодаря увеличению мышечной силы и массы тела вы можете ощущать каждое его движение в часы бодрствования. Для подсчёта движений выберите время, когда малыш бодрствует и активен. Лягте на левый бок в спокойной обстановке и отмечайте каждое его движение.'), baby_message_ru = COALESCE(baby_message_ru, 'Привет, Anacan! Мы отлично справились и вступили в заключительный этап беременности. Теперь для меня главное — набирать вес и готовиться к появлению на свет. Места становится всё меньше, но сил у меня всё больше. Я крепко толкаю тебя ножкой и говорю: «Поздравляю!»'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой баклажан'), body_changes_ru = COALESCE(body_changes_ru, 'Одно из веществ, особенно необходимых малышу на этих неделях, — кальций. Если вы не получаете достаточно кальция с пищей в течение дня, эта потребность будет восполняться за счёт запасов в ваших костях.;;;
Если потребность в железе, которое участвует в образовании эритроцитов у вас и малыша, не будет в достаточной мере покрываться питанием и назначенными врачом препаратами, малыш сформирует собственные клетки крови, но у вас может развиться анемия.;;;
Наряду с железом и кальцием одной из важнейших потребностей третьего триместра являются жирные кислоты Omega-3, которые в большом количестве используются для активно ускоряющегося в эти недели развития тканей мозга малыша. Omega-3 содержатся в растительных продуктах, таких как соевые бобы и грецкие орехи, но особенно много их в рыбе. Поэтому во время беременности полезно увеличить употребление рыбы.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы отметить начало этого периода, устройте небольшой ужин с партнёром или, если планируете "Baby Shower", составьте список необходимого. Порадуйте себя — вы проделываете огромную работу!') WHERE id = '96a22ed0-5e13-4094-87c4-74d0da4a58fc';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На осмотре у врача на этой неделе может выясниться, что малыш находится в головном или тазовом предлежании. В обоих случаях причин для беспокойства нет. До 34-й недели беременности у каждого малыша достаточно околоплодных вод, чтобы свободно двигаться и менять положение в матке. По мере роста малыша его голова становится тяжелее относительно тела, и под действием силы тяжести он занимает положение головой вниз. В таком положении вагинальные роды проходят легче всего. Таким образом малыш готовится продвигаться по родовым путям во время естественных родов.;;;
На 32-34-й неделях беременности около 70-80% малышей уже занимают головное предлежание. К 37-й неделе этот показатель увеличивается до 95%. В некоторых случаях малыш может располагаться иначе, например в тазовом предлежании. В такой ситуации врач усиливает наблюдение в условиях стационара, а при необходимости родоразрешение проводят с помощью кесарева сечения. Среди причин, по которым малыш после определённого срока всё ещё не занимает положение для родов, могут быть избыточное количество околоплодных вод, расположение плаценты, перекрывающее родовые пути, аномалии формы матки и узкий таз.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня есть режим сна! 🌙 Теперь я сплю не когда придётся. У меня есть определённые часы сна и бодрствования. Обычно, когда ты отдыхаешь, я просыпаюсь. А во сне у меня бывает "REM-сон" (сон с быстрыми движениями глаз). Это значит, что я вижу сны! Возможно, мне снишься именно ты...'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой баклажан'), body_changes_ru = COALESCE(body_changes_ru, 'В этот период физическая усталость может вернуться. Ваш живот значительно увеличился, поэтому двигаться и удобно спать становится сложнее. Если у вас отрицательная (-) группа крови, а у вашего партнёра положительная (+), на этой неделе следует обсудить с врачом введение "Rhogam" (антирезусного иммуноглобулина) для профилактики резус-конфликта.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не ешьте тяжёлую пищу перед сном и старайтесь не пользоваться экранами (телефоном, TV). Тёплый душ и стакан тёплого молока могут помочь вам легче заснуть.') WHERE id = '65a58c5e-3cca-4355-b7cb-eb0f566d682e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Добро пожаловать на последнюю неделю второго триместра! Как быстро летит время, правда? Теперь рост вашего малыша определяют уже не по расстоянию от макушки до копчика, а умножая длину бедренной кости на 7.;;;
Незадолго до начала третьего триместра во время осмотра врач может увидеть, что ваш малыш занял положение головой вниз. Это совершенно нормально. Пока у малыша больше пространства для движений, чем будет в последние недели, поэтому ему легко менять положение. Кроме того, благодаря большому количеству вкусовых рецепторов во рту малыша вкус продуктов, которые вы едите, передаётся ему через амниотическую жидкость, позволяя различать разные вкусы.;;;
На этом этапе на поверхности языка малыша больше вкусовых рецепторов, чем у взрослого человека. Благодаря этому малыш не только различает вкусы, но и может реагировать на них. Например, на некоторые пряные и очень острые продукты он может отреагировать икотой.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне снятся сны! 💤 Учёные исследовали мой мозг и выяснили, что я нахожусь в фазе "быстрого сна". То есть, хотя мои глаза закрыты, я вижу сны. Интересно, что мне снится? Ваш голос? Или тот вкусный шоколад, который вы съели? Я мечтатель, совсем как вы.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Начиная с 28-й недели беременности большая часть запасов вашего организма направляется малышу. Поэтому для поддержания нормальной работы организма очень важно употреблять продукты, богатые кальцием, магнием, витаминами A, D, E и K.;;;
Если во время беременности вы получаете недостаточно кальция, необходимый для развития малыша кальций будет поступать из ваших костей. Это может привести к дефициту кальция и в будущем создать предпосылки для развития остеопороза — снижения плотности костной ткани. Больше всего кальция содержится в молоке, йогурте и сыре. Значительное количество кальция также содержат курага, грецкие и лесные орехи, миндаль, форель, тёмно-зелёные листовые овощи и сушёные бобовые. В одном стакане молока содержится 250 mq кальция. В одном ломтике белого сыра, в зависимости от его вида, — 100 mq, в горсти сырых орехов — 50 mq, а в горсти изюма — 30 mq кальция.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в пояснице, носите удобную обувь на низком каблуке и обязательно поддерживайте спину, когда сидите. При сухости в носу поддерживайте достаточную влажность воздуха в помещении. Сегодня больше разговаривайте с малышом или почитайте ему сказку — в будущем он будет помнить мелодику вашего голоса. Не забывайте пить много воды и включать в рацион продукты, богатые клетчаткой.') WHERE id = '1533383b-1c83-483c-ad7a-9958fe297dd1';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш быстро набирает вес благодаря тому, что в его организме с необычайной скоростью образуются клетки бурой жировой ткани. Бурые жировые клетки не только накапливают некоторые виды холестерина, но и вырабатывают тепло благодаря большому количеству митохондрий. Поскольку теперь поддерживать температуру тела малыша будут бурые жировые клетки, волосы лануго, которые до этого согревали его, начинают постепенно выпадать. Сроки выпадения лануго у каждого малыша различаются и зависят от особенностей развития и обмена веществ. Выпавшие волоски лануго попадают в окружающую малыша амниотическую жидкость, которую он глотает. Затем они продолжают накапливаться в кишечнике малыша и входят в состав мекония, известного как "первый стул". Кроме того, благодаря быстрому увеличению количества бурых жировых клеток подкожный слой малыша активно развивается и становится более объёмным, поэтому морщинки на коже разглаживаются, а сама кожа становится более упругой. Прежде прозрачная кожа уплотняется, и расположенные под ней капилляры больше не видны.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня икота! 🤭 Чувствуете в животе ритмичное "тук-тук-тук"? Это я икаю! Когда я глотаю амниотическую жидкость, моя диафрагма раздражается, и у меня начинается икота. Вам это может показаться странным, но для меня это упражнение, укрепляющее лёгкие. Не бойтесь, я не задыхаюсь!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Цветная капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Вы приближаетесь к завершению второго триместра. Окончание этого этапа, известного как золотой период беременности или медовый месяц, означает, что некоторые неприятные симптомы первого триместра могут вернуться.;;;
Поскольку малыш поднялся довольно высоко, под давлением матки ваши органы смещаются. Сильнее всего это влияет на желудок. Он располагается выше обычного, поэтому после тяжёлой пищи давление в нём может усиливаться, вызывая рвоту и изжогу. Кроме того, из-за смещения кишечника в сторону его моторика может замедлиться, что приводит к вздутию и запорам. По мере роста малыша матка снова начинает давить на мочевой пузырь, поэтому вам вновь может потребоваться чаще ходить в туалет. Из-за давления объём мочевого пузыря уменьшается, в результате чего мочеиспускание учащается, а напор струи может ослабнуть.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня приготовьте себе чашку травяного чая (предварительно посоветовавшись с врачом) и в спокойной обстановке понаблюдайте за движениями малыша.') WHERE id = '0a949afb-87f2-4780-b137-5c4298637904';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе часть веса малыша приходится на клетки бурой жировой ткани. По сравнению с обычными клетками организма и белыми жировыми клетками они содержат очень большое количество митохондрий. Число митохондрий — структур клетки, вырабатывающих энергию, — может различаться в зависимости от энергетических потребностей клетки. Особенно много их бывает в клетках, которым требуется большое количество энергии, например в мышечных и нервных. Так, в клетках печени — одного из органов с очень высокими энергетическими потребностями — их насчитывается около 2500. Митохондрии присутствуют во всех эукариотических клетках, способных к кислородному дыханию. Поэтому в эритроцитах, которым не требуется энергия, поскольку они переносятся с током крови, митохондрий нет.'), baby_message_ru = COALESCE(baby_message_ru, 'Знаете, что такое Lightning Crotch"? ⚡ Иногда, когда я пинаюсь вниз или поворачиваю голову, вы можете почувствовать в паховой области внезапную боль, похожую на удар током. По-английски это называют "Lightning Crotch" (удар молнии). Это происходит потому, что я задеваю нерв. Простите, что причиняю вам боль, просто мне здесь тесно!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Брокколи'), body_changes_ru = COALESCE(body_changes_ru, 'Не стоит беспокоиться, если временами малыш двигается очень активно или, наоборот, его движения замедляются. Хотя у него уже формируется определённый режим, интенсивность движений не всегда ощущается одинаково. Чаще всего это зависит от положения, в котором малыш находится в данный момент. Если малыш занял положение для родов головой вниз, он может сильнее давить на желудок и лёгкие, вызывая одышку. Кроме того, толчки в область грудной клетки могут быть довольно болезненными. Если малыш находится в ягодичном предлежании, может возникать чувство давления в области прямой кишки и увеличиваться нагрузка на мочевой пузырь.;;;
Кроме того, малыши не двигаются постоянно. Помните, что на этом этапе ваш малыш проводит во сне почти 18-20 часов в сутки. Совершенно нормально, если во время вашей активности малыш двигается меньше, а когда вы отдыхаете — становится особенно активным. Однако если вы заметили необычное затишье, отсутствие движений или малыш не проявляет привычной активности, необходимо связаться с врачом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если у вас болит паховая область, не разводите ноги слишком широко. Садясь в машину, сначала опуститесь на сиденье, а затем перенесите внутрь обе ноги вместе. Категорически избегайте подъёма тяжёлых предметов.') WHERE id = 'e505d439-55d1-41af-8277-5a18a75a724e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже умеет открывать и закрывать глаза. Благодаря этому он достиг уровня развития, позволяющего различать день и ночь. Хотя стенка матки служит барьером для внешних раздражителей, таких как свет и звук, по мере роста малыша она растягивается и становится относительно тонкой. Если на этом этапе направить на живот яркий источник света, малыш может отреагировать и попытаться повернуть голову в сторону света. Такая реакция также становится возможной благодаря развивающимся роговице и зрительному нерву.;;;
Кроме того, малыш реагирует на ваш голос и уже может отличать голос папы от других звуков. Женские и детские голоса более высокие и тонкие, чем мужские, поэтому они легче проникают через стенку матки, и малыш чаще на них реагирует. От внезапных и громких звуков он может вздрагивать и сильно толкаться.'), baby_message_ru = COALESCE(baby_message_ru, '⚖️ Чем больше становится мой вес, тем тяжелее тебе меня носить. Я знаю, что у тебя болит спина. Но подумай о том, каким здоровым и сильным я становлюсь. Моя жировая прослойка будет согревать меня. А когда я появлюсь на свет, то наполню твои объятия.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Брокколи'), body_changes_ru = COALESCE(body_changes_ru, 'На поздних сроках беременности из-за гормональных изменений выделения могут стать более жидкими, и их легко спутать с отхождением околоплодных вод. При разрыве амниотического мешка обычно выделяется большое количество жидкости, которая обильно стекает по ногам. Однако в некоторых случаях по определённым причинам амниотический мешок может повредиться сбоку или сверху. Тогда околоплодные воды могут подтекать понемногу.;;;
Если вы подозреваете подтекание околоплодных вод, обратитесь в больницу. С помощью простого теста можно определить, является ли выделяющаяся жидкость околоплодными водами или влагалищными выделениями.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить одышку, старайтесь сидеть прямо, отведите плечи назад и расправьте грудную клетку. Для восполнения потребности в кальции в течение дня отдавайте предпочтение молочным продуктам или зелёным листовым овощам. Если кожа живота чешется, увлажняйте её натуральными маслами. Сегодня немного отдохните и помечтайте вместе с малышом о прекрасных днях, которые ждут вас впереди.') WHERE id = 'e2245d19-3163-447c-8f3b-d37ca7523b57';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Вы вступили в период между 27-й и 32-й неделями — время, когда малыш наиболее активен за всю беременность. Кроме того, в эти недели его движения становятся регулярными. Это означает, что в каждый час бодрствования малыша вы должны ощущать не менее 10 движений. Наиболее активен малыш ночью, когда околоплодные воды почти не колеблются. Днём ваши движения вызывают колебания околоплодных вод, которые убаюкивают малыша. Поэтому теперь он уже может мешать вам спать. 😊;;;
Главная причина, по которой на этом этапе вы ощущаете так много сильных движений, заключается в том, что малыш уже достаточно вырос, а объём околоплодных вод пока позволяет ему активно двигаться.;;;
С каждой неделей малыш выделяет в амниотический мешок с мочой меньше жидкости, чем заглатывает. В результате объём окружающих его околоплодных вод постепенно начинает уменьшаться. Это естественный и необходимый процесс, поскольку по мере роста малышу требуется всё больше места.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня уже есть свой режим! 📅 Anacan, ты заметила? Обычно я просыпаюсь и засыпаю примерно в одно и то же время. Например, когда вечером ты ложишься отдохнуть, я просыпаюсь. А по утрам веду себя спокойно. Мои биологические часы уже заработали. После рождения я ещё некоторое время буду жить по такому режиму (стану ночной совой!).'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Брокколи'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за воздействия гормона прогестерона сфинктер в месте соединения желудка и пищевода расслабляется, что может вызывать изжогу. Во время беременности следует избегать продуктов, усиливающих изжогу. Поскольку наклоны также могут усугубить эту проблему, вам не стоит заниматься тяжёлой домашней работой или другой деятельностью, требующей частых наклонов. Ешьте медленно, не торопясь, и избегайте кислых, газированных и содержащих кофеин напитков.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Стакан тёплой воды натощак или несколько штук кураги по утрам помогут запустить работу кишечника. Никогда не откладывайте посещение туалета.') WHERE id = '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Примерно с 24-й недели малыш достигает порога жизнеспособности, а если он родится преждевременно на этой неделе, вероятность его выживания превысит 90%. Главная причина заключается в том, что лёгкие уже вырабатывают значительное количество сурфактанта. Это вещество снижает поверхностное натяжение жидкости в альвеолах и предотвращает их спадение, а также препятствует развитию отёка и скоплению других веществ. Обеспечивая скольжение поверхностей и участвуя в газообмене, сурфактант представляет собой сложную смесь белков и липидов. Кроме того, органы осязания, вкуса, слуха, обоняния и зрения малыша уже полностью сформированы.'), baby_message_ru = COALESCE(baby_message_ru, 'Я реагирую на твой голос! 🎵 Когда папа приближается к животу и разговаривает со мной, моё сердцебиение меняется. Я очень хорошо слышу его голос. Скажи ему, чтобы он разговаривал со мной. Я уже начинаю узнавать членов семьи по голосам.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Брокколи'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за заметно выросшего живота и активности малыша в ночное время у вас могут возникнуть проблемы со сном. В этот период вам может помочь подушка для беременных. Она поддерживает спину и поясницу, уменьшая боль, и способствует более эффективной работе почек. Поддерживая правильное дыхание, она помогает уменьшить одышку, часто возникающую во время беременности. Такая подушка также способствует лучшему поступлению питательных веществ и кислорода к малышу и уменьшает изжогу — ещё одну распространённую жалобу во время беременности. Благодаря улучшению кровообращения она помогает уменьшить судороги и отёки, особенно в ногах. ;;;
Особенно в последнем триместре обычно рекомендуется лежать на левом боку. Это помогает избежать сдавливания нижней полой вены, расположенной справа, которое может нарушить кровообращение в нижней части тела и вызвать связанные с этим проблемы.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня отметьте успешно пройденные 27 недель, позволив себе хорошо отдохнуть. Чтобы уменьшить отёки ног, следите за количеством соли в рационе и отдыхайте, приподняв ноги. Наладьте режим сна, чтобы начать третий триместр с энергией. Начиная с завтрашнего дня до нашей встречи останется ещё меньше времени!') WHERE id = '7654580f-12f8-4fea-93bd-20d5a4e92397';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе вес вашего малыша может составлять как 850 граммов, так и более 1000 граммов. Если вес малыша ниже или выше среднего, не стоит беспокоиться. Помните, что не все дети рождаются с одинаковым весом: вес здорового новорождённого может варьироваться в широком диапазоне — от 2500 до 4000 граммов. Сейчас, когда вы вступаете в последний триместр, начинается период наиболее активного набора веса малышом.;;;
В последнем триместре малыши в среднем набирают по 250 граммов в неделю. Если нет никаких проблем со здоровьем, малыш продолжает набирать вес даже при переношенной беременности. Если же есть проблема, связанная с вашим здоровьем или состоянием малыша, набор веса может замедлиться или прекратиться. Нормальным весом доношенного малыша при рождении считается 2500–4000 граммов. Чаще всего дети рождаются с весом 3000–3500 граммов. При этом средняя разница в весе между девочками и мальчиками может составлять около 10 процентов.;;;
Кроме того, генетические факторы являются одними из важнейших факторов, определяющих вес малыша при рождении. Было бы неправильно оценивать состояние малыша только по его весу. Несмотря на ваше здоровое питание, низкий вес при рождении могут вызвать проблемы со здоровьем малыша, хронические заболевания, курение и генетические факторы.'), baby_message_ru = COALESCE(baby_message_ru, 'Я моргаю! 😉 Anacan, я уже умею открывать и закрывать глаза. Если на твой живот падает яркий свет, я отворачиваюсь или моргаю. Моё зрение ещё не полностью сформировано, но я прекрасно различаю свет и темноту. Не могу дождаться, когда увижу мир.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой баклажан'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности из-за повышения уровня прогестерона в крови связки и мышцы в области таза и брюшной полости растягиваются и становятся более эластичными. Благодаря этому растущая матка удерживается и сохраняет стабильное положение. Ближе к концу беременности верхняя часть позвоночника немного отклоняется назад, помогая уменьшить давление матки на другие органы. Суставы, образующие таз, становятся более эластичными и начинают готовиться к родам. Все эти изменения происходят под воздействием гормонов беременности, в том числе эстрогена и прогестерона, уровень которых в организме повышается и меняется.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При боли в пояснице попробуйте упражнение из йоги «Кошка-корова» (встаньте на четвереньки и поочерёдно округляйте и прогибайте спину). Оно уменьшает нагрузку на позвоночник и помогает малышу занять более удобное положение.') WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе ваш малыш может находиться в самых разных положениях. Наиболее благоприятным считается передний вид головного предлежания: малыш расположен головой вниз, а его лицо обращено к вашей спине. Такое положение считается идеальным по нескольким причинам. В нём малыш удобно располагается с учётом изгиба вашего таза. Во время родов это положение позволяет ему повернуть спину и прижать подбородок к груди. Кроме того, макушка давит на шейку матки, способствуя выработке гормонов, необходимых для начала схваток. На этапе потуг такое положение помогает малышу занять правильный угол и облегчает прохождение головки через родовые пути. Благодаря этому повышается вероятность родов без стимуляции схваток и кесарева сечения. Роды могут пройти быстрее и легче, боль будет менее выраженной, а облегчение наступит раньше. До последних недель беременности малыш может ещё не занимать положение для родов. Даже на этом этапе он способен перевернуться самостоятельно. В некоторых случаях малыш поворачивается уже после начала родов.'), baby_message_ru = COALESCE(baby_message_ru, 'Я тренируюсь дышать! 🌬️ Конечно, воздуха здесь пока нет, но я поднимаю и опускаю грудную клетку и втягиваю амниотическую жидкость в лёгкие. Эти упражнения укрепляют мою диафрагму. Иногда при этом я икаю. Ты чувствуешь эти ритмичные толчки? Это моя тренировка.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой баклажан'), body_changes_ru = COALESCE(body_changes_ru, 'Нарушения работы кишечника и запоры относятся к числу наиболее распространённых проблем на протяжении всей беременности. Повышенный уровень прогестерона — одного из гормонов беременности — расслабляет мышцы пищеварительного тракта. В результате частично переваренная пища, называемая химусом, медленнее продвигается по кишечнику.;;;
Кроме того, растущая матка может давить на разные отделы толстого кишечника в брюшной полости, затрудняя продвижение остатков пищи. В результате возникает запор.;;;
Если запор продолжается больше недели, обязательно обратитесь к врачу, чтобы не допустить затягивания проблемы. Длительный запор без лечения может привести к геморрою и другим осложнениям.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не ложитесь сразу после еды — оставайтесь в вертикальном положении не менее 1 часа. Сон с высокой подушкой под головой поможет предотвратить обратный заброс кислоты. Избегайте газированной минеральной воды: из-за содержания соли она может вызывать отёки.') WHERE id = 'b00d6682-7d24-499f-8007-e3d98626d47b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Клетки головного мозга вашего малыша продолжают каждую секунду образовывать миллионы нейронов. Поскольку клетки мозга размножаются с невероятной скоростью, а объёма черепа уже недостаточно для их размещения на гладкой поверхности, мозг начинает формировать складки. По мере обучения благодаря уже развившимся органам чувств образование этих извилистых структур ускоряется. Борозды и извилины на поверхности позволяют мозгу получить дополнительную площадь за счёт складывания внутрь и выполнять больше функций. Благодаря этим складкам площадь поверхности человеческого мозга, ограниченного внутренним пространством черепа, увеличивается примерно до размера двух развёрнутых газетных страниц, лежащих рядом.'), baby_message_ru = COALESCE(baby_message_ru, 'Я узнаю тебя! 🎤 Anacan, твой голос для меня самый родной. Исследования показывают, что, когда я слышу твой голос, моё сердцебиение успокаивается. Я уже запоминаю твою интонацию и манеру речи. Когда я появлюсь на свет, тебе будет достаточно просто заговорить, чтобы успокоить меня.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой баклажан'), body_changes_ru = COALESCE(body_changes_ru, 'В эти недели из протоков молочных желёз может выделяться небольшое количество накопившегося молозива. Стимуляция сосков усиливает его выделение, а также ускоряет выброс гормона окситоцина, который может вызвать сокращения матки. Поэтому ни в коем случае не сжимайте соски, чтобы проверить, выделяется ли молозиво. В обычных условиях его появление не связано с преждевременными родами, однако стимуляция сосков может вызвать сокращения мышц матки и тем самым спровоцировать преждевременные роды. Выработка пролактина также подавляет овуляцию, поэтому у кормящих матерей она некоторое время отсутствует. Поскольку этот гормон препятствует созреванию и развитию яйцеклеток, после родов менструация некоторое время не наступает. У некоторых женщин менструальный цикл восстанавливается в течение 6 месяцев, однако отсутствие менструации на протяжении 2 лет также может считаться нормой.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня вечером уделите немного времени себе и расскажите малышу о вашем первом совместном путешествии в будущем.') WHERE id = '4ca04882-bd78-4264-985d-0684e463329f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Мозговые волны вашего малыша уже сформировались. Согласно исследованиям последних лет, электрическая активность мозга и создаваемые им электрические волны начинают возникать ещё в утробе матери. Мозг генерирует бета-, альфа-, тета- и дельта-волны, которые измеряются в герцах (Hz). Герц обозначает количество циклов в секунду. Когда мозг находится в бета-состоянии, организм бодрствует. Это наиболее часто используемое в повседневной жизни состояние сознания, необходимое для мышления, речи, принятия решений, решения задач, планирования и действий. Когда в течение дня человек закрывает глаза и расслабляется, мозг переходит с бета-частоты на альфа-частоту. Это состояние называют лёгким гипнозом: сознательный контроль ослабевает, а творческие способности усиливаются. Дельта-состояние — это привычный нам режим сна. Оно возникает не на уровне подсознания, а за пределами сознания. Когда мозг работает в диапазоне дельта-волн, организм переходит в фазу отдыха и восстановления. Сон необходим каждому человеку, поскольку во время сна организм восстанавливается, а нервная система отдыхает.'), baby_message_ru = COALESCE(baby_message_ru, '28 НЕДЕЛЬ ПОЗАДИ! 👋 Мы официально вступаем в 7-й месяц. Мне становится всё теснее, поэтому теперь вы чувствуете не то, как я «плаваю», а отчётливые толчки моих локтей и коленей.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой баклажан'), body_changes_ru = COALESCE(body_changes_ru, 'На этом этапе под влиянием гормонов и частичного смещения внутренних органов в вашей пищеварительной системе происходят значительные изменения. Из-за расслабления сфинктера желудка желудочная кислота может попадать в пищевод, вызывая изжогу. Поэтому не следует ложиться сразу после еды. Газированные напитки, острая пища и жирные жареные блюда, особенно при переедании, могут ещё больше усилить изжогу. Пищевод не имеет защиты от воздействия кислоты, поэтому при частой изжоге в нём могут возникнуть стойкие изменения. По этой причине для вашего здоровья очень важно следить за питанием и есть часто, но небольшими порциями.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня наградите себя за то, что успешно прошли путь длиной в 28 недель, и хорошо отдохните. Чтобы уменьшить отёчность ног, контролируйте потребление соли и отдыхайте, приподняв ноги. Если вы ещё этого не сделали, начните составлять список первых необходимых вещей для малыша. Завтра начинается 29-я неделя — новый этап, который ещё на один шаг приближает нас к встрече!') WHERE id = 'bfd55361-27a4-4f83-b42f-472543bccd24';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Теперь, когда вы вступили в третий триместр, ваш малыш будет набирать примерно 150-200 граммов в неделю. Такая прибавка в весе связана с быстрым накоплением жировой ткани. По мере увеличения количества жировых клеток кожа малыша становится менее морщинистой. К этой неделе амниотический мешок также уже полностью сформирован. Начался период быстрого развития мозга и костей черепа малыша, который готовится к жизни во внешнем мире. Органы чувств уже сформировались, а отвечающие за них отделы мозга продолжают созревать, поэтому малыш начинает учиться, воспринимая внешние раздражители. Поскольку для хранения новой информации мозгу требуется дополнительное пространство, на его поверхности начинают образовываться извилины, позволяющие компактнее разместить нервную ткань. С момента рождения малыш начнёт быстро учиться и сохранять полученную информацию в памяти. Часть избыточных миллиардов клеток мозга будет устранена в ходе процесса, называемого частичным прунингом, чтобы освободить место для новых знаний.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои кости становятся крепче! 🦴 Anacan, теперь я многим обязана вам за кальций. Мои кости быстро укрепляются. Каждый день я накапливаю примерно 250 мг кальция. Если вы не будете получать достаточно кальция, я «заберу» его из ваших костей. Берегите себя и ешьте сыр!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кочан капусты'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности значительные изменения происходят не только в вашем теле, но и в биохимических процессах мозга. В связи с этими изменениями, особенно если вы очень чувствительны, у вас может повыситься склонность к депрессии. Хотя чаще депрессия усиливается после родов, иногда её первые признаки могут появиться ещё во время беременности. Постоянная раздражительность, чувство собственной никчёмности и вины, нарушения аппетита и пищевого поведения, боли, не поддающиеся лечению, утрата удовольствия от того, что раньше вас радовало, снижение интереса к любимым занятиям, серьёзные нарушения сна, трудности с вниманием и концентрацией могут быть признаками депрессии. В этот период важно заручиться поддержкой партнёра и членов семьи, сосредоточиться на хорошем и стараться не зацикливаться на том, что вас расстраивает.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Уделяйте особое внимание поступлению кальция с пищей (молоком, йогуртом, сыром), поскольку в этот период малышу требуется много кальция. Чтобы уменьшить боль в пояснице, обязательно подкладывайте под спину поддерживающую подушку, когда сидите. Если вы ещё не начали, сейчас самое время составить список вещей для сумки малыша. Сегодня отдохните вместе с малышом под звуки спокойной музыки.') WHERE id = '124477a3-06f6-44dd-a276-41487168c5e0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Мимические мышцы полностью сформированы. Малыш может улыбаться, гримасничать и высовывать язык. Надпочечники вырабатывают гормон «эстриол». Этот гормон стимулирует выработку молока в организме матери.;;;
Процесс окостенения достиг пика. Скелет малыша становится твёрже. В мозге начинает работать центр терморегуляции. Теперь малыш уже может частично регулировать температуру своего тела и меньше зависит от температуры амниотической жидкости.'), baby_message_ru = COALESCE(baby_message_ru, 'Я улыбаюсь! 😊 Во время ультразвукового исследования врачи часто видят, как мы улыбаемся. Обычно это происходит во сне. Может быть, я вижу ангелов? Или просто тренирую мышцы лица? Какой бы ни была причина, я счастлив. Улыбнитесь и вы, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кочан капусты'), body_changes_ru = COALESCE(body_changes_ru, 'До самого рождения малыша плацента выполняет функции, которые впоследствии возьмут на себя его лёгкие, почки и печень. Поскольку лёгкие малыша пока ещё не могут работать самостоятельно, их функцию выполняет плацента. Кровь малыша поступает по сосудам пуповины в плаценту, где насыщается кислородом из вашей крови, а затем по пуповине возвращается к малышу. Таким же образом все продукты обмена, образующиеся в организме малыша, выводятся не его почками и печенью, а поступают в плаценту, затем в вашу систему кровообращения и удаляются из организма. Поскольку плацента выполняет жизненно важные функции, любые нарушения её структуры или работы, включая кальцификацию, преждевременное старение и нарушение кровотока, могут привести к тому, что малыш не будет получать достаточно питательных веществ.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Регулярно используйте кремы от растяжек. Однако помните, что появление растяжек в большей степени зависит от генетики. Чтобы уменьшить зуд, принимайте прохладный душ и избегайте синтетической одежды.') WHERE id = '82410eeb-db13-46e1-be5e-f6446cc033ef';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе объём амниотической жидкости вокруг вашего малыша увеличивается в последний раз. В течение следующих нескольких недель её объём больше не будет расти и останется стабильным до родов. Амниотическая жидкость — это стерильная среда, которая защищает малыша от внешних воздействий. Малыш заглатывает эту жидкость, а также она всасывается через его лёгкие и кожу, попадая в кровь. Уменьшающийся объём жидкости вновь восполняется благодаря мочеиспусканию малыша. Помимо веществ, отражающих биохимические процессы в его организме, амниотическая жидкость содержит слущенные клетки кожи, первородную смазку и волоски лануго.;;;
Амниотическая жидкость поддерживает рост и развитие вашего малыша, способствует развитию его головного мозга. Она защищает малыша от внешних раздражителей, таких как шум, удары, свет и давление. Амниотическая жидкость участвует в регуляции и поддержании стабильной температуры тела, способствует развитию органов чувств. Она также играет важную роль в развитии многих систем органов, прежде всего мышечной и нервной систем.;;;
Основным источником амниотической жидкости являются почки малыша. Моча, выделяемая его почками, формирует амниотическую жидкость. Малыш заглатывает её, после чего жидкость вновь попадает в систему кровообращения. Затем она снова фильтруется почками и в виде мочи возвращается в амниотическую жидкость. Этот цикл непрерывно повторяется.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои зубки спрятались! 🦷 Anacan, под моими дёснами уже сформировались зачатки молочных зубов. А под ними есть даже зачатки постоянных зубов. Я появлюсь на свет без зубов, но всё уже подготовлено. Природа удивительна, правда? Мы делаем запасы на будущее.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Капуста'), body_changes_ru = COALESCE(body_changes_ru, 'Если нет показаний к кесареву сечению, способ родоразрешения пока ещё точно не определён. С началом последнего триместра вам стоит задуматься о том, как будут проходить роды. Существуют разные варианты: естественные роды, кесарево сечение, роды с эпидуральной анестезией, роды в воде и другие.;;;
Процесс вагинальных родов, которые также называют естественными, может быть довольно длительным. Для рождения малыша шейка матки должна раскрыться до 10 см. Первые 4 см относятся к латентной фазе, и для раскрытия шейки матки до 4 см иногда может потребоваться до 2 недель. Раскрытие от 4 до 10 см в среднем занимает от 4 до 12 часов, после чего шейка матки считается полностью раскрытой.;;;
Если имеются связанные с малышом обстоятельства, например тазовое предлежание, слишком крупный размер, невозможность вставления головки в родовой канал, нарушения сердечного ритма или перекрытие шейки матки плацентой, а также связанные с вашим состоянием факторы — ВПЧ-инфекция, преэклампсия, чрезмерный вес или узкий таз, — естественные роды могут быть невозможны. В таком случае проводится необходимое кесарево сечение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы полностью опорожнить мочевой пузырь, сидя на унитазе, слегка наклонитесь вперёд. Это поможет лучше опорожнить мочевой пузырь и снизить риск инфекции.') WHERE id = '98a97832-2773-43d8-bf72-e6458dfbc947';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Железы вашего малыша продолжают развиваться. В организме существуют два типа желёз: железы внутренней и внешней секреции. Железы внешней секреции выделяют секрет в специальные протоки, а железы внутренней секреции — непосредственно в кровь. Переносимые кровью гормоны через капилляры достигают всех клеток организма.;;;
Одна из таких желёз — гипофиз, расположенный в нижней части переднего мозга. В нём вырабатывается множество гормонов. Они обеспечивают рост и развитие вашего малыша, а также формирование его половой системы. Вырабатываемые гипофизом гормоны в будущем будут влиять на образование сперматозоидов у мальчика или созревание яйцеклеток у девочки, а также участвовать в регуляции водного баланса организма и артериального давления. Гормоны щитовидной железы регулируют скорость обмена веществ и ускоряют процесс окостенения во время роста малыша. Кроме того, они регулируют использование кислорода клетками. Надпочечники участвуют в выработке адреналина, помогающего организму реагировать на возможную опасность, и регулируют минеральный баланс. Поджелудочная железа является железой смешанной секреции: она вырабатывает гормоны инсулин и глюкагон, регулирующие уровень сахара в крови, а также пищеварительные ферменты.'), baby_message_ru = COALESCE(baby_message_ru, '200 ДНЕЙ! 🎉 Anacan, это невероятно! Мы вместе уже 200 дней. Я размером с большую тыкву. Теперь я очень сильный малыш. Иногда мои толчки могут причинять тебе боль, но знай: я просто проверяю свои силы. До нашей встречи осталось совсем немного!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Примерно через два месяца врач проведёт оценку размеров вашего таза, известную как пельвиометрия. Если плановое кесарево сечение не предусмотрено, цель этого обследования — определить, подходит ли строение таза для вагинальных родов. Если будут выявлены анатомические особенности, например сужение верхней части таза, в зависимости от его степени могут быть рекомендованы другие способы родоразрешения.;;;
Полость таза представляет собой канал диаметром около 10 см, окружённый мышцами и связками. Именно через этот канал ваш малыш пройдёт, появляясь на свет. Изнутри родовой канал не прямой, а имеет изгибы и неровности. Чтобы пройти через него, во время родов малышу необходимо принимать определённые положения. Сокращения матки создают продвигающую силу и помогают ему двигаться в правильном направлении.;;;
Малыш входит головкой во вход в малый таз, образованный верхними границами тазовых костей. Вначале головка располагается поперечно, а в середине канала поворачивается на 90 градусов, и лицо малыша оказывается обращено к вашей спине. Достигнув выхода из канала, малыш рождается головкой в этом положении. После рождения головки он поворачивает её в сторону внутренней поверхности одного из ваших бёдер, чтобы плечики смогли войти в родовой канал. После завершения поворота рождается остальная часть тела.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте 200-й день небольшим подарком для себя или выделите время на отдых. Чтобы уменьшить боль в пояснице, во время сидения ставьте ноги на маленькую скамеечку. Продолжайте спать на левом боку, положив подушку между коленями: это улучшит кровообращение. Если вы ещё не начали, сейчас самое время завершить подготовку комнаты малыша или составить список вещей для сумки в роддом.') WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На каждом квадратном сантиметре кожи вашего малыша находится примерно 110 потовых желёз, 15 сальных желёз и до 3000 чувствительных к температуре клеток. Потоотделение, обеспечиваемое формирующимися под кожей потовыми железами, — это полностью непроизвольный процесс и естественная функция обмена веществ. Оно помогает поддерживать стабильную температуру тела и участвует в выведении продуктов обмена. Примерно половина потовых желёз, формирующихся в организме малыша, выделяет прозрачную жидкость без запаха. Большинство желёз, выделяющих прозрачный пот, расположено на подошвах, ладонях и лице. Железы, выделяющие более густой пот с характерным запахом, находятся в определённых областях, например в подмышечных впадинах и в области половых органов. В подмышечных впадинах количество желёз, выделяющих прозрачный и густой пот, примерно одинаково, тогда как на других участках желёз, выделяющих прозрачный пот, в десять раз больше. Основная функция потоотделения — регулирование температуры тела. Жидкость, выделяемая потовыми железами, испаряется и помогает охлаждать организм. Температура тела контролируется центром терморегуляции, расположенным в гипоталамусе головного мозга. Этот процесс осуществляется за счёт выделения пота и регуляции кровотока в коже.'), baby_message_ru = COALESCE(baby_message_ru, 'Я вижу сны! 😴 Anacan, мой мозг уже настолько развит, что я вхожу в фазу "REM-сна" (быстрого движения глаз). Это значит, что теперь я действительно вижу сны! Интересно, что мне снится? Твой голос или тот вкусный торт? Большую часть дня я сплю, но во время бодрствования очень активен.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'На этом сроке беременности у вас могут возникать сильные боли в пояснице и спине. Это связано с тем, что растущая матка, в которой находится малыш, поднимается вверх и смещает центр тяжести вашего тела. Лучший способ облегчить состояние — физические упражнения, пилатес или йога для беременных. Такие занятия не только уменьшают связанные с беременностью боли и мышечные спазмы, но и помогают исправить нарушения осанки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Избегайте тяжёлой работы по дому. Направьте энергию "гнездования" на лёгкие дела, например стирку одежды или украшение комнаты. Вешать шторы и передвигать мебель категорически запрещено!') WHERE id = '2b574c8a-d0de-45f5-bd25-7b7b01e3d2fe';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В волосяных фолликулах вашего малыша уже начали формироваться постоянные волосы, помимо волосков лануго. Благодаря этим волоскам организм малыша может поддерживать водный и тепловой баланс. Волоски на определённых участках тела также отвечают за теплоизоляцию. В холодной среде маленькие мышцы, расположенные у волосяных фолликулов, сокращаются и приподнимают волоски, вырабатывая в этой области энергию и, следовательно, тепло. При рождении тело малыша, помимо ещё не выпавших волосков лануго, будет покрыто настолько тонкими постоянными волосками, что они практически незаметны. По мере роста малыша эти волоски будут становиться толще. Вся кожа человека, за исключением ладоней, подошв и губ, покрыта волосками. Однако на большинстве участков они настолько тонкие и светлые, что остаются незаметными. Чёрный, коричневый, светлый или рыжий цвет волос зависит от наличия пигментов — красящих веществ, расположенных непосредственно под наружным слоем волоса. Если ни одного из этих пигментов нет, многочисленные воздушные полости отражают весь свет, поэтому волосы и волоски кажутся белыми.'), baby_message_ru = COALESCE(baby_message_ru, 'Я вижу вас — почти! 💡 Мои глаза открыты, и если вы направите на живот яркий свет, я поверну голову в его сторону. Я уже могу следить за источником света. Хотя в моём мире темно, иногда я вижу слабые проблески света, проникающие сквозь стенку вашего живота. Для меня это настоящее чудо!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'До родов осталось совсем немного времени. Начиная с этого этапа вам может быть трудно даже двигаться, особенно из-за заметно увеличившегося живота. Если из-за этих трудностей вы решите меньше двигаться, ваше тело ослабнет, а роды могут пройти тяжелее. Поэтому вам следует совершать короткие прогулки и выполнять упражнения, которые не будут сильно вас утомлять. Упражнения помогут вам стать физически сильнее и повысить гибкость тела. Мышцы рук и ног укрепятся, а мышцы и связки станут более эластичными. Благодаря гибкости мышц бёдер и области таза вы сможете подготовиться к более комфортным родам. Упражнения Кегеля укрепят мышцы тазового дна и помогут подготовиться к последним месяцам беременности, родам и послеродовому восстановлению.;;;
Согласно исследованиям, женщины, которые занимаются физическими упражнениями на протяжении беременности, набирают к родам примерно на 7 килограммов меньше. Упражнения также могут помочь предотвратить усиливающиеся на поздних сроках отёки ног.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Компрессионные чулки улучшают кровообращение и уменьшают боль в ногах. Наиболее эффективно надевать их утром, ещё до того, как вы встанете с постели.') WHERE id = '98b2e2a6-b569-4828-8904-245e5d1bc37e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Начиная с этой недели, когда вы находитесь на 7-м месяце беременности, и до родов ваш малыш наберёт вес, примерно равный удвоенной массе его тела на данный момент. Главная причина этого — формирование белых жировых клеток наряду с бурой жировой тканью. Белая жировая ткань накапливает избыток энергии в жировых клетках в виде триглицеридов и при необходимости может быстро возвращать их в кровоток. Жировая ткань — крупнейшее хранилище энергии в организме; накопление и высвобождение энергии в жировых клетках регулируется гормональными сигналами. Она состоит из жировых клеток и содержит большое количество кровеносных сосудов и нервов. У мужчин жировая ткань составляет 15-20% массы тела, а у женщин — 20-25%. Жировые клетки специализируются на накоплении нейтральных жиров и выработке тепла. Поскольку человек принимает пищу с перерывами, а расход энергии происходит непрерывно, эти клетки выполняют важную функцию энергетического резерва. Жировая ткань защищает от травм и активно участвует в теплоизоляции организма. Кроме того, она очень чувствительна к нервным и гормональным сигналам.'), baby_message_ru = COALESCE(baby_message_ru, '29 НЕДЕЛЬ! 🎃 Я размером с большую тыкву! С каждым днём я всё больше становлюсь похожим на человека. Моя голова уже пропорциональна телу. Теперь моя главная задача — набрать вес. Когда я пинаюсь, вы уже гораздо лучше чувствуете мою силу, правда?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Кожа обладает эластичной структурой. Во время беременности растущие живот и грудь приводят к дополнительному растяжению кожи. В результате кожа теряет влагу и появляется зуд. Он может возникнуть уже на тех неделях, когда живот становится заметным. Кроме того, растяжки на груди и животе также могут время от времени вызывать зуд. Если зуд связан с растяжением и потерей влаги, можно увлажнять беспокоящие участки кремом или вазелином, рекомендованным вашим врачом. Масла, например миндальное, также могут помочь уменьшить зуд. Во время беременности не следует пользоваться парфюмерией и ароматизированными косметическими средствами, поскольку они могут усилить зуд. Чтобы поддерживать водный баланс организма, пейте достаточно воды.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Разделите приёмы пищи на 5-6 небольших порций в течение дня. Большие порции усиливают изжогу. Не ложитесь сразу после еды — оставайтесь в вертикальном положении или немного прогуляйтесь.') WHERE id = 'cad83eb0-58a7-4d1b-bb76-60f58c14c58f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Зачатки постоянных зубов вашего малыша уже завершили своё развитие в зубных почках. Молочные зубы, которые появятся через некоторое время после рождения и будут служить малышу в течение нескольких лет, играют очень важную роль в правильном и здоровом прорезывании постоянных зубов. Первые зубы обычно начинают появляться над дёснами в возрасте 5-8 месяцев. Первыми прорезываются нижние передние резцы. Обычно это происходит после того, как малышу исполнится 6 месяцев. Вскоре после них, примерно с 8-го месяца, начинают прорезываться верхние резцы. Затем появляются боковые резцы и коренные зубы. Последними прорезываются задние коренные зубы. Молочные зубы выпадают, когда растущие снизу постоянные зубы начинают оказывать на них давление. Под этим давлением корень молочного зуба постепенно рассасывается, и в итоге зуб выпадает. Постоянные зубы начинают прорезываться в возрасте 6-7 лет, в зависимости от темпов роста малыша. С появлением «зубов мудрости» завершается формирование полного набора из 32 постоянных зубов.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне нужен кальций! 🥛 Мои кости быстро укрепляются. Сейчас я каждый день получаю из вашей крови примерно 250 миллиграммов кальция. Это необходимо, чтобы мой скелет был крепким. Если вы не будете пить молоко, я «одолжу» этот кальций из ваших зубов и костей. Берегите себя, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Вы наверняка уже заметили изменения в своих волосах. Они выглядят более густыми и блестящими и растут довольно быстро. Это связано с гормонами, вырабатывающимися во время беременности, и прежде всего с высоким уровнем эстрогена в крови. После рождения малыша выработка эстрогена значительно снижается, а его уровень в крови возвращается к норме, из-за чего рост волос в значительной степени замедляется. В этот момент многие волосяные фолликулы одновременно переходят в фазу выпадения, и через 2-3 месяца волосы начинают заметно выпадать. Эта фаза обычно завершается в течение 6 месяцев, после чего на месте выпавших волос начинают расти новые.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Следите за движениями малыша в течение дня. Если вы заметите резкое снижение его активности, проконсультируйтесь с врачом. Сегодня немного отдохните и порадуйте себя любимым занятием.') WHERE id = '64fd7099-afb5-4134-9918-3acc90ed702e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Шишковидная железа, расположенная в мозге вашего малыша, с этой недели начинает функционировать. Шишковидная железа — это орган размером с чечевичное зерно, расположенный в задней части мозга. Она регулирует выработку мелатонина и поддерживает его баланс в организме малыша. Этот орган также отвечает за настройку биологических часов организма. Иными словами, он участвует во многих процессах, включая режим сна, засыпание и пробуждение. Гормон мелатонин, вырабатываемый шишковидной железой, запускает половое созревание, обеспечивает половое развитие и влияет на репродуктивную функцию. Он регулирует биологические часы и ритмы организма, способствует обновлению клеток, защищает сетчатку глаза и выполняет противоопухолевую функцию. Исследования последних лет показали, что шишковидная железа обычно активизируется в темноте. Именно поэтому через некоторое время после пребывания в тёмном помещении появляется ощущение тяжести и сонливость. Шишковидная железа особенно эффективно работает в темноте. Кроме того, эта железа активно участвует в процессе роста, а выделяемые ею гормоны, особенно в подростковом возрасте, предотвращают преждевременное развитие половых желёз.'), baby_message_ru = COALESCE(baby_message_ru, 'Я регулирую температуру своего тела! 🌡️ Раньше я полностью зависел от температуры вашего тела. Но теперь благодаря мозгу и жировой прослойке я начинаю самостоятельно регулировать температуру своего тела. Я уже словно маленькая печка. Я готовлюсь к тому, чтобы не замёрзнуть после рождения.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Самая серьёзная проблема при многоплодной беременности — преждевременные роды. Чем больше малышей, тем короче срок беременности и тем меньше масса тела каждого малыша при рождении. Если средняя продолжительность беременности двойней составляет примерно 37 недель, то при тройне — 35 недель. Каждая дополнительная неделя, проведённая малышами в матке, способствует созреванию их органов и систем, а также увеличению массы тела при рождении. При многоплодной беременности важно продлить её как можно дольше, чтобы избежать преждевременных родов. Лучший способ — соблюдение постельного режима. Возможно, на протяжении всей беременности вам не удастся сохранять привычный уровень активности. Может потребоваться соблюдать рекомендованный врачом постельный режим.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы улучшить качество ночного сна, ложитесь на левый бок и кладите подушку между ног — это уменьшит нагрузку на поясницу. Для облегчения зуда кожи живота используйте увлажняющие средства с натуральным составом. Следите за достаточным поступлением кальция и железа, поскольку сейчас кости вашего малыша проходят этап наиболее интенсивного укрепления. Сегодня постарайтесь не перенапрягаться.') WHERE id = '2a9f34ac-1247-4ead-b172-d62294531480';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По мере роста малыша пространство для движений в матке постепенно уменьшается. Поэтому он прижимает ручки и ножки к телу, принимая знакомую нам «позу эмбриона». Эта удобная поза не только экономит место, но и помогает сохранять тепло тела. На этом этапе мозг вашего малыша достигает невероятного уровня зрелости. Центры его мозга уже учатся управлять важнейшими для жизни после рождения функциями — дыханием и температурой тела. Дыхательный центр регулирует ритмичные движения, подготавливая лёгкие к дыханию, а гипоталамус берёт на себя роль «термостата», поддерживающего стабильную внутреннюю температуру малыша. Это показывает, насколько хорошо мозг вашего малыша уже подготовлен к жизни вне матки.'), baby_message_ru = COALESCE(baby_message_ru, 'Я поворачиваюсь головкой вниз? ⬇️ Возможно, я уже понемногу начинаю готовиться к положению для родов. Пока я очень подвижен и часто переворачиваюсь, но моя головка становится тяжелее, поэтому сила тяжести тянет меня вниз. Если я ещё не расположился головкой вниз, не волнуйтесь — у меня ещё много времени!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Вы можете ощущать давление или боль в паховой области. По мере того как малыш растёт и опускается ниже, давление на кости таза и мочевой пузырь усиливается. Может снова появиться потребность часто ходить в туалет. Также может развиться «симфизит» — болезненное расхождение костей таза.;;;
Вы можете ощущать приливы жара. Ваш обмен веществ работает на 20% интенсивнее ради малыша, из-за чего вырабатывается дополнительное тепло. Вам может быть постоянно жарко, даже если окружающие мёрзнут. Потоотделение усиливается.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить изжогу, ешьте небольшими порциями, но часто, и не ложитесь сразу после еды. Сон на левом боку поможет как вашему пищеварению, так и кровообращению малыша. Для облегчения боли в пояснице примите тёплый душ или выполните лёгкие упражнения на растяжку. Сегодня уделите немного времени себе и подумайте о деталях комнаты или уголка, который вы готовите для малыша.') WHERE id = '46d5df45-3974-471b-a1a7-d53afb295423';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Осязание — первое и наиболее развитое чувство, с помощью которого ваш малыш познаёт мир. Сейчас в матке он ведёт себя как настоящий исследователь: ощупывает ручками стенки матки, хватается за пуповину, сосёт пальчики и часто гладит своё лицо.;;;
Эти прикосновения — не просто движения, но и важные сигналы для сенсорного развития мозга. Интересно, что на этом этапе надпочечники вашего малыша также выполняют чрезвычайно важную задачу. Они начинают вырабатывать особый гормон — кортизол. Кортизол играет роль «волшебного ключа» в созревании лёгких малыша. Он ускоряет выработку в лёгочной ткани вещества под названием сурфактант. Сурфактант не позволяет крошечным воздушным мешочкам в лёгких слипаться. Благодаря этому процессу сразу после рождения ваш малыш сможет легко сделать первый вдох, и его лёгкие полностью наполнятся воздухом. Таким образом, и физические движения, и внутренние гормональные процессы прекрасно готовят малыша к важному «дню открытия» — первому вдоху и первому прикосновению.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую вас! 🤗 Anacan, когда вы гладите живот, а папа кладёт на него руку, я чувствую это тепло и давление. Иногда я тоже прикасаюсь изнутри к тому же месту. Так мы «здороваемся». Между нами лишь тонкая стенка, а наши души едины.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Забывчивость может достичь своего пика. Вам может быть трудно сосредоточиться. Найти ключи в холодильнике или посреди фразы забыть, что вы хотели сказать, — нормально. Ваш мозг переходит в «режим материнства» и меняет приоритеты.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В этот период может появиться бессонница, поэтому старайтесь отдыхать в течение дня, делая короткие перерывы. Сегодня вечером послушайте вместе с малышом спокойную музыку — он разделяет ваше умиротворение.') WHERE id = '0a286cb7-93f1-451a-b6be-b5b9dd7ce160';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'С каждым днём в мозге вашего малыша продолжают образовываться миллиарды нейронов. На этом этапе их общее количество уже достигает нескольких триллионов. Нервная система составляет около 7% от примерно 100 триллионов клеток в организме вашего малыша. Это свидетельствует о жизненно важной роли передачи информации. По своим функциям нервные клетки делятся на 3 группы: чувствительные, двигательные и вставочные нейроны. Чувствительные нейроны передают импульсы, полученные от рецепторов, в органы центральной нервной системы, такие как головной и спинной мозг. Двигательные нейроны передают команды от центральной нервной системы мышцам или железам. Вставочные нейроны находятся в центральной нервной системе и обеспечивают связь между двигательными и чувствительными нейронами.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой мозг покрывается извилинами! 🧠 Раньше он был гладким, а теперь становится складчатым, как ядро грецкого ореха. Почему? Потому что клетки моего мозга размножаются так быстро, что ему приходится образовывать складки, чтобы поместиться в черепе. Эти извилины показывают, что развиваются мой интеллект, память и способности. Я готовлюсь стать гением!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большая тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Тренировочные схватки могут стать более частыми и заметными. Живот может становиться твёрдым как камень несколько раз в течение дня. Обычно это безболезненно, но может вызывать дискомфорт. Если схватки регулярные (например, каждые 10 минут) и болезненные, это может быть признаком преждевременных родов — немедленно позвоните врачу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В эти дни вы можете постепенно добавлять в список для сумки в роддом необходимые средства гигиены. На ужин отдавайте предпочтение лёгкой пище, чтобы сон был более комфортным.') WHERE id = '195a150b-6bd1-4a69-9196-35f5d6e3f9f4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Слой верникса, который начал формироваться на коже вашего малыша несколько недель назад, становится толще. Верникс — это напоминающий крем слой, который начинает образовываться на коже малыша в последние 3 месяца беременности. Почти все малыши рождаются покрытыми слоем верникса. У недоношенных малышей этот слой обычно более плотный, а у малышей, родившихся после 40 недель, его, как правило, значительно меньше. Этот жирный слой белого цвета имеет густую кремообразную консистенцию. Верникс представляет собой разновидность жирового секрета, который выделяется жировыми клетками кожи малыша под воздействием вырабатываемых вашим организмом гормонов. Верникс содержит около 50 особых белков и очень эффективно защищает малыша от различных инфекций как в утробе, так и после рождения. Благодаря верниксу кожа малыша остаётся защищённой и в период адаптации к окружающему миру после рождения. В течение 1-2 дней после родов кожа малыша полностью впитывает верникс. Это также помогает уменьшить вероятность появления высыпаний в период новорождённости.'), baby_message_ru = COALESCE(baby_message_ru, 'Вы считаете мои толчки? 🦶 Врачи говорят, что вам нужно следить за моими движениями. Обычно я активничаю после еды или когда вы отдыхаете. Если я долго не подаю признаков, выпейте стакан сладкой воды и лягте на левый бок. Я сразу отреагирую. Иногда я просто крепко сплю.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан капусты'), body_changes_ru = COALESCE(body_changes_ru, 'Если вы испытываете боль в паху, не беспокойтесь. По мере роста малыша центр равновесия вашего тела смещается, поэтому могут появляться различные болезненные ощущения. Одно из них — боль в паховой области. Боль в паху является распространённой жалобой во время беременности. Она может ощущаться как лёгкое нытьё или проявляться периодическими острыми приступами.;;;
В первом триместре беременности боль в паху связана с ростом матки, а в последнем — с подготовкой организма к родам. При недостатке магния в организме такие боли могут возникать чаще и становиться более интенсивными. Авокадо, фундук, бобовые, цельнозерновые продукты, жирная рыба и бананы богаты магнием.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить отёчность и тяжесть в ногах, носите удобную обувь и приподнимайте ноги, когда сидите. Продолжайте следить за движениями малыша в течение дня; обычно считается нормой почувствовать 10 движений за 2 часа. Сегодня вечером уделите немного времени себе, примите тёплый душ и помечтайте вместе с малышом о прекрасных днях, которые ждут вас впереди.') WHERE id = 'eadf5bb2-e6e7-4d41-83d0-6c1c3223ad40';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Если ваш малыш — девочка, её яичники продолжают развиваться, и в них формируются миллионы яйцеклеток. Яичники — это две симметричные железы, расположенные по обеим сторонам матки и поддерживаемые широкими связками. Яичник является женским репродуктивным органом, в котором хранятся женские половые клетки — яйцеклетки. В каждом яичнике вашего малыша находится множество фолликулов, которые будут участвовать в созревании яйцеклеток. Эти яйцеклетки пока находятся в незрелом состоянии и не созревают до периода полового созревания. После наступления половой зрелости под воздействием гормонов, выделяемых гипофизом, каждый месяц созревает одна яйцеклетка и продвигается к матке. К этим гормонам относятся: ФСГ, обеспечивающий созревание яйцеклетки; ЛГ, запускающий овуляцию; эстроген, выделяемый фолликулами и обеспечивающий формирование вторичных половых признаков; а также прогестерон, выделяемый жёлтым телом и подготавливающий внутреннюю оболочку матки к беременности. Если созревшая яйцеклетка не оплодотворяется сперматозоидом, она выводится из организма и наступает менструация.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с большой кочан капусты! Anacan, невероятно, мы уже прошли 3/4 пути (75%)! Осталось всего 10 недель (примерно). Я уже большой малыш, просто моим лёгким и мозгу нужно ещё немного созреть. Финиш уже близко!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан капусты'), body_changes_ru = COALESCE(body_changes_ru, 'Своевременное прохождение медицинских обследований крайне важно для раннего выявления таких проблем, как уменьшение объёма амниотической жидкости. Во время беременности снижение её количества определяют с помощью измерений при ультразвуковом исследовании (УЗИ). О маловодии говорят, если общий объём жидкости составляет менее 500 ml. Замедление кровотока в плаценте может способствовать уменьшению объёма амниотической жидкости. При артериальной гипертензии, вызванной сужением сосудов, или состояниях, связанных с уменьшением объёма крови, снижается приток крови, питающей малыша. Это, в свою очередь, приводит к уменьшению количества амниотической жидкости.;;;
Кроме того, общий дефицит жидкости в вашем организме, а в некоторых случаях и сахарный диабет могут привести к уменьшению количества околоплодных вод. Объём амниотической жидкости также может снизиться из-за побочного действия некоторых лекарств, принимаемых без ведома врача. Вероятность этой проблемы повышается и при переношенной беременности сроком 42 недели и более.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте окончание 30-й недели спокойным отдыхом. Чтобы уменьшить боль в пояснице, во время сидения обязательно используйте подушки, поддерживающие спину. Если вы ещё не сделали этого, можете начать собирать основные вещи для сумки малыша (подгузники, одежду). С завтрашнего дня начинается 31-я неделя — последний большой поворот на пути к родам!') WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Скорость роста вашего малыша уже достигла «рекордного» уровня — каждую неделю он прибавляет примерно 200 грамм! Такой стремительный рост обусловлен как увеличением слоя подкожного жира, так и ростом внутренних органов. В эти недели лёгкие всё ещё продолжают развиваться. Несмотря на то что малыш тренируется дышать в утробе, его лёгким потребуется ещё несколько недель, чтобы они могли полностью самостоятельно функционировать во внешней среде. За это время воздушные мешочки в лёгких станут ещё крепче. Режим сна вашего малыша уже стал более чётким и упорядоченным. В определённые часы он спит, а в другие просыпается и продолжает свои «тренировки». Его циклы сна уже напоминают режим сна новорождённого малыша.'), baby_message_ru = COALESCE(baby_message_ru, '31 НЕДЕЛЯ! 🥥 Здравствуйте, Anacan! Я размером с кокос (coconut). Мой вес достиг 1.5 кг, а рост — 41 см. Я уже достаточно «тяжёлый». Теперь моя главная цель — подготовить лёгкие и накопить ещё больше жира. Я готовлюсь появиться на свет!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Вас могут беспокоить боль в рёбрах и одышка. Матка давит на диафрагму и лёгкие, смещая их вверх. Возможность глубоко вдохнуть может казаться роскошью. Ножки малыша могут упираться вам в рёбра.;;;
Также могут вернуться усталость и слабость. Тяжесть живота, бессонные ночи и возросшая потребность организма в энергии могут совершенно лишать вас сил уже к середине дня. Не пытайтесь быть героиней — вам необходим отдых. Кроме того, у вас могут возникнуть проблемы с равновесием и риск споткнуться, поэтому будьте осторожны.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сейчас подходящее время, чтобы начать собирать сумку в роддом. Составьте список и постепенно складывайте необходимые вещи. Спешить не нужно, но готовность подарит вам спокойствие.') WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе ваш малыш производит около половины литра мочи в сутки. Он заглатывает амниотическую жидкость, а образовавшуюся мочу снова выделяет в неё, создавая круговорот, благодаря которому объём жидкости постоянно поддерживается на необходимом уровне. Количество и состав амниотической жидкости непрерывно меняются на протяжении беременности. В первые недели беременности она образуется путём фильтрации вашей крови и содержит вещества, обеспечивающие малыша питательными веществами и кислородом. В последующие недели состав амниотической жидкости меняется: помимо воды, неорганических солей, белков, жиров, углеводов и ферментов, в неё входит моча, которую малыш начинает производить с 12-й недели. Эта жидкость играет важную роль в формировании сосательного рефлекса и развитии лёгких малыша. Кроме того, благодаря возможности свободно потягиваться, поворачиваться и совершать другие движения развиваются его скелет и мышцы. Амниотическая жидкость также защищает малыша от внешних ударов. В среднем она обновляется каждые 3 часа, и её состав меняется. Моча, вырабатываемая малышом, также участвует в изменении состава амниотической жидкости.'), baby_message_ru = COALESCE(baby_message_ru, 'Какого цвета мои глаза? 👁️ Сейчас мои глаза, как и у всех малышей, тёмно-синие или серые. После рождения, когда на них начнёт попадать свет, проявится их настоящий цвет — карий, зелёный или ореховый. Это может занять 6-9 месяцев. Но в любом случае я буду смотреть на вас с любовью.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Растущая матка вызывает растяжение окружающих мышц и связок, из-за чего может возникать боль во влагалище. Под влиянием растущего малыша матка увеличивается и смещает центр тяжести вашего тела, что приводит к боли в спине и нижней части живота. В третьем триместре, когда живот значительно увеличивается, растяжение связок при резких движениях может вызывать тянущую или острую, словно от укола ножом, боль в паховой области. Причина этого — растяжение круглой связки матки.;;;
Боль в области матки во время беременности часто путают с болью во влагалище. В последние недели беременности шейка матки может начать размягчаться и частично раскрываться. Это может произойти за несколько недель до родов. Во время такого раскрытия боль во влагалище может быть сильной и острой, словно от укола ножом. Это не означает, что начались родовые схватки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При боли по ходу седалищного нерва не ложитесь на больную сторону. Примите тёплую ванну или приложите тёплый компресс к болезненному месту. После консультации с врачом можно пройти курс физиотерапии или массажа для беременных.') WHERE id = 'ef1f18bb-3c48-4a2a-96b2-7141d5fc2528';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На волосистой части головы вашего малыша может появиться припухлость, называемая родовой опухолью. Это связано с процессом конфигурации головки. Молдинг — это временное изменение формы и в определённой степени объёма головы малыша во время родов. Чтобы головка малыша могла пройти через родовой канал, она должна принять форму, соответствующую его форме и размерам. Проходя по родовому каналу, малыш сгибает голову вперёд, поворачивает её внутрь, разгибает и поворачивает наружу. В ходе этого процесса кости черепа малыша благодаря эластичной хрящевой ткани между ними сближаются и частично заходят друг на друга. Из-за быстрого изменения формы мягких тканей во время прохождения по родовому каналу на голове могут появиться временные неровности. Среди причин деформации черепа у новорождённых могут быть положение малыша в утробе, затяжные и тяжёлые роды, пребывание малыша в кувезе или укорочение мышц шеи.'), baby_message_ru = COALESCE(baby_message_ru, 'Я лежу головой вниз? 🙃 Скорее всего, я уже пытаюсь занять положение головой вниз — головное предлежание. Это самое подходящее положение для родов. Но если я ещё не повернулся, не волнуйтесь: у меня ещё есть время. Мне нравится сила притяжения — поскольку моя голова тяжёлая, мне удобно опускаться вниз.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Беременность — один из периодов, когда женщина наиболее быстро набирает вес. Из-за повышения уровня гормонов и необходимости поддерживать развитие малыша вы можете часто испытывать голод. Если не утолять его полезными перекусами, вы можете начать есть большими порциями и употреблять слишком много калорий. Женщины с нормальным или низким индексом массы тела до беременности обычно набирают в этот период в среднем 10-12 килограммов. Женщины, имевшие лишний вес до беременности, склонны набирать ещё больше. Основная причина заключается в том, что во время беременности они продолжают придерживаться нездоровых пищевых привычек, нередко усугубляя их.;;;
Вместо нездоровой пищи с «пустыми» калориями и низкой питательной ценностью ежедневно съедайте 3 порции фруктов, выбирайте основные блюда с высоким содержанием белка, обязательно включайте молоко и молочные продукты в перекусы и регулярно выполняйте лёгкие физические упражнения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не ешьте за 2-3 часа до сна. Молоко или горсть сырого миндаля могут помочь нейтрализовать желудочную кислоту. Избегайте кислых и острых блюд.') WHERE id = '805cdfb6-2608-4845-b4aa-f6272786a6f0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В структуре радужки — цветной части глаза вашего малыша — продолжается пигментация. Радужка регулирует размер зрачка и количество света, попадающего в глаз. Несмотря на разнообразие цветов глаз, за цвет радужки отвечает только один вид пигмента. Если в переднем слое радужки много пигмента, глаза малыша будут карими, если пигмента мало — зелёными, а если он отсутствует — голубыми. Цвет глаз вашего малыша определяется с самого момента оплодотворения. Начиная с 4-й недели беременности начинает формироваться эта пигментация. Хотя образование пигмента начинается на очень раннем этапе, узнать цвет глаз малыша можно будет только после рождения. Несмотря на то что в глазах малыша уже образовался пигмент меланин, клеткам необходимо время для созревания. Иными словами, чёткая пигментация пока ещё не сформировалась. Обычно постоянный цвет глаз малыша начинает проявляться примерно через 5 месяцев после рождения.'), baby_message_ru = COALESCE(baby_message_ru, 'Я сбрасываю свои «волоски»! 🐻 Помнишь, я рассказывал, что моё тело покрыто волосками под названием «лануго»? Теперь жировая прослойка согревает меня, поэтому эти волоски мне нужны всё меньше. Они начинают понемногу выпадать. Я становлюсь более гладким и мягким. Возможно, к рождению немного останется на спинке, но большая часть исчезнет.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан капусты'), body_changes_ru = COALESCE(body_changes_ru, 'В эти недели, когда вы приближаетесь к концу беременности, важно знать признаки начала родов. Слизистая пробка может отойти как за 1 месяц до родов, так и за несколько часов до их начала. Ещё одним признаком приближающихся родов является излитие околоплодных вод. Эта жидкость может быть водянистой и очень светло-жёлтой. Околоплодные воды могут отойти внезапно, и в таком случае лучше всего сразу отправиться в больницу. После излития вод малыш может остаться без защиты от микроорганизмов.;;;
После излития околоплодных вод роды должны произойти не позднее чем через 48 часов. Если пройдёт больше времени, риск инфицирования малыша значительно возрастёт.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Короткий дневной сон (15-20 минут) поможет восстановить силы. Но не спите слишком долго, иначе ночной сон может нарушиться. Спускаясь по лестнице, держитесь за перила.') WHERE id = '1dccc97f-570f-4f2a-ba96-d46cdb785a71';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Позади уже 30 недель вашей беременности. Благодаря быстрому процессу окостенения скелет малыша стал значительно более развитым. Однако кости черепа пока ещё не прошли этот процесс. Это позволяет малышу легче пройти через родовые пути.;;;
Родничок — это участок соединительной ткани в месте соединения костей черепа до их окончательного окостенения. В области черепа имеется 6 родничков, и ближе к родам 5 из них закрываются. После рождения малыша остаётся только родничок, расположенный в передней части головы. Область родничка на голове малыша состоит из соединительной ткани. Эта структура придаёт черепу гибкость, позволяя костям немного заходить друг на друга, а голове — пройти через родовые пути, благодаря чему роды становятся возможными. После рождения рост мозга также обеспечивается за счёт роста черепа. Благодаря его гибкой структуре примерно 75% роста мозга малыша происходит в первые 2 года жизни.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой мозг растёт! 🧠 Anacan, сейчас мой мозг развивается с невероятной скоростью. В нём образуются миллиарды новых связей. Теперь я двигаюсь не только благодаря рефлексам — я думаю, чувствую и запоминаю. Твой голос — моё самое любимое воспоминание.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан капусты'), body_changes_ru = COALESCE(body_changes_ru, 'С началом третьего триместра у вас может появиться страх перед родами. Умеренная тревога и волнение в этот период совершенно нормальны. Однако чрезмерное беспокойство может навредить и вам, и малышу. Если вы ещё не рожали, ситуация может казаться особенно сложной, а неизвестность — вызывать дополнительную тревогу. Присутствие близких и поддержка супруга помогут вам легче пройти этот период и справиться со своими страхами.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Во время тренировочных схваток смените положение тела, выпейте воды и глубоко подышите. Положение лёжа на левом боку может помочь ослабить схватки. Всегда держите воду рядом: обезвоживание усиливает схватки.') WHERE id = 'c04052f3-92f1-4783-8ceb-a4f9489af352';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя слёзные каналы малыша уже сформировались, некоторые из них при рождении остаются закрытыми. Поэтому в течение некоторого времени после рождения, даже если малыш будет плакать, слёзы могут не течь из его глаз. Слёзные железы вырабатывают слёзы, которые через отверстия на нижнем веке отводятся в полость носа. Такая ситуация может сохраняться примерно до 3 недель после рождения малыша. Слеза — это прозрачная солоноватая жидкость, выделяемая слёзными железами, расположенными над глазами малыша. Она увлажняет глаза и помогает предотвратить трение. Кроме того, слёзная жидкость обладает важными антибактериальными свойствами. Она обеспечивает свободное движение глазного яблока в глазнице и помогает очищать поверхность глаза от пыли и посторонних частиц. Примерно 98% слезы составляет вода. В оставшейся части содержатся мочевина в концентрации, сопоставимой с плазмой крови, а также меньшее количество глюкозы, солей и органических веществ. Слёзные железы вырабатывают 3 вида слёз: базальные, рефлекторные и эмоциональные.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой бассейн становится теснее! 🏊‍♂️ По мере того как я расту, воды вокруг меня становится недостаточно. Её примерно 1 литр, но я занимаю так много места, что двигаться становится труднее. Теперь ты гораздо отчётливее чувствуешь каждое движение моих локтей и коленей. Иногда я причиняю тебе боль, прости.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан капусты'), body_changes_ru = COALESCE(body_changes_ru, 'Употребление фиников во время беременности может принести много пользы. Финики богаты белком, калием, магнием, марганцем, железом, медью и витаминами B1, B2, B3, A1, C. Благодаря высокому содержанию клетчатки они надолго дают чувство сытости и помогают регулировать работу пищеварительной системы. Финики содержат различные антиоксиданты и являются полезным природным источником углеводов. Они также насыщают, помогают регулировать уровень сахара в крови и тем самым способствуют контролю веса во время беременности. Содержащаяся в них фолиевая кислота поддерживает здоровое развитие малыша на протяжении беременности. Финики содержат вещество, связанное с действием окситоцина. Окситоцин способствует раскрытию шейки матки без дополнительных вмешательств. Поэтому считается, что финики относятся к продуктам, способным облегчить естественные роды.;;;
Хотя однозначных научных данных по этому вопросу пока нет, во время беременности следует избегать чрезмерного употребления фиников из-за предполагаемой вероятности преждевременного раскрытия шейки матки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При одышке выпрямитесь и поднимите руки над головой. Это поможет расширить грудную клетку. Ешьте небольшими порциями, чтобы желудок не оказывал дополнительного давления на диафрагму.') WHERE id = '676af173-b90a-4c64-a591-ff651fa5a3ea';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Сразу после рождения кожа вашего малыша может иметь оттенок от серо-голубого до фиолетового. Кроме того, его тело будет влажным из-за амниотической жидкости и покрытым слоем верникса — первородной смазки. Как только малыш начнёт дышать, его кожа сначала на лице и теле, а вскоре и на руках и ногах порозовеет и приобретёт нормальный цвет. Внешний вид кожи новорождённых может различаться в зависимости от срока беременности, на котором они родились. Кожа недоношенных малышей обычно очень тонкая и прозрачная. Их тело покрыто тонкими волосками, называемыми лануго, а на коже присутствует похожий на сыр слой верникса, который защищает её в матке от воздействия амниотической жидкости. Чем больше срок беременности, тем меньше на коже малыша верникса и волосков лануго. Поскольку кожа малышей очень тонкая, она может выглядеть более розовой, чем обычно. Такая розоватость обусловлена просвечивающими капиллярами. Кроме того, почти половина малышей рождается с небольшими белыми или жёлтыми бугорками на лице, напоминающими прыщики. Это закупоренные сальные железы, которые вскоре исчезают самостоятельно.'), baby_message_ru = COALESCE(baby_message_ru, 'Я сосу пальчики! 👍 Это моё самое любимое занятие. На УЗИ ты часто можешь увидеть, как я сосу большой палец. Это успокаивает меня и укрепляет мышцы челюсти. Я тренируюсь, чтобы после рождения сосать твоё молоко.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности в области влагалища может появиться неприятный зуд. Его причинами могут быть аллергические реакции, раздражающие химические вещества, гестационный диабет, кожные заболевания, например экзема, инфекции, передающиеся половым путём, или грибковая инфекция.;;;
Из-за гормональных изменений во время беременности риск вагинальных инфекций значительно возрастает. Если зуд вызван вагинальной инфекцией, в этой области могут появиться покраснение и отёк. Наряду с зудом могут наблюдаться белые густые выделения. Использование не подходящих при беременности кремов и мазей, смягчающего мыла и моющих средств, вагинальных спреев и ароматизированной туалетной бумаги может усилить зуд. Если вас беспокоит зуд в области влагалища, лечебные и успокаивающие кремы и мази, рекомендованные врачом, могут облегчить симптомы. Кроме того, стирайте одежду мыльным порошком вместо стирального средства, носите хлопковое нижнее бельё и часто меняйте его в течение дня, отдавайте предпочтение свободной одежде, не сдавливающей тело, а также всегда поддерживайте чистоту и по возможности сухость интимной зоны.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить онемение рук, чаще встряхивайте и поднимайте их. Ношение ортеза на запястье по ночам может снизить давление на нерв.') WHERE id = 'd4779c73-b7cd-4428-bca1-d013881798d5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К 32-й неделе ногти на руках вашего малыша уже дорастают до кончиков пальцев. Ногти на ногах достигают кончиков пальцев к 36-й неделе. Ногти малыша, начавшие формироваться на 10-й неделе, состоят из кератина и будут расти на протяжении всей жизни. Кератин в структуре ногтей содержит аминокислоты с высоким содержанием серы. На этом сроке малыш довольно часто икает. По мере приближения родов икота становится всё чаще. Малыши рождаются с сосательным рефлексом. Этот рефлекс формируется в утробе матери, когда малыш глотает амниотическую жидкость и икает. На этой неделе во время осмотра вы даже можете увидеть на УЗИ, как малыш икает и сосёт палец.'), baby_message_ru = COALESCE(baby_message_ru, 'Все мои 5 чувств работают! 🖐️👃👂👀👅 Зрение, слух, вкус, обоняние и осязание. Все мои чувства пробудились. Я слышу твой голос, ощущаю вкус еды, которую ты ешь, вижу свет и прикасаюсь к своему лицу. Я уже чувствующее живое существо. Ты — мой мир, Anacan.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Эмоциональный инстинкт «гнездования» может усилиться. Вам хочется убрать дом, постирать и погладить одежду малыша. Воспользуйтесь этим приливом энергии, но не переутомляйтесь.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить отёки, продолжайте пить много воды и сведите употребление соли к минимуму. При болях в пояснице обязательно используйте подушку для беременных и старайтесь сидеть прямо. Если вы ещё этого не сделали, сейчас самое подходящее время, чтобы завершить оформление комнаты малыша или сделать крупные покупки, например приобрести коляску, поскольку в последующие недели двигаться может стать сложнее.') WHERE id = 'a8ac9e30-a252-4631-aca6-20ffff4ecf20';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Кости вашего малыша состоят из так называемой «первичной костной ткани», то есть они ещё не полностью созрели. В утробе матери соединительная ткань костей малыша ещё не сформировалась окончательно, а сами кости недостаточно затвердели. Кости являются частью скелетной системы, которая защищает тело, обеспечивает вертикальное положение и опору, а также позволяет совершать движения. В них также находится костный мозг, отвечающий за образование клеток крови. Костная ткань служит хранилищем кальция в организме и помогает обеспечивать его суточную потребность.;;;
В кишечнике малыша продолжает накапливаться меконий. Он состоит из слюны малыша, желудочного и панкреатического секрета, клеточных отходов, слизи и волосков лануго. Пока меконий находится в кишечнике, он стерилен. Он выводится из организма в течение 48 часов после рождения.'), baby_message_ru = COALESCE(baby_message_ru, 'Я писаю! 🚽 Звучит забавно, но за день я выделяю примерно пол-литра мочи, которая смешивается с амниотической жидкостью. Затем я снова проглатываю эту жидкость. Такой круговорот показывает, что мои почки и пищеварительная система здоровы. Я сам регулирую количество своей жидкости.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Кокос'), body_changes_ru = COALESCE(body_changes_ru, 'Отёки рук и ног могут сохраняться и по утрам. Если у вас внезапно отекло лицо, измерьте артериальное давление. Кроме того, из-за «Carpal Tunnel Syndrome» (синдрома запястного канала) могут возникать онемение и боль в руках.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Очень важно носить удобную обувь. Полностью откажитесь от обуви на каблуках. При болях в пояснице может помочь бандаж для беременных.') WHERE id = 'b1c4365d-e81a-4bcf-93eb-e36cdbc64c30';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе, когда вы вступаете в 8-й месяц беременности, лёгкие малыша продолжают быстро развиваться. В период с 28-й по 36-ю неделю лёгкие находятся на «саккулярной» стадии. На этом этапе, когда формируются мешочки лёгких, поверхностный слой, образующий бронхи, истончается, а количество капилляров в лёгких быстро увеличивается. К моменту полного созревания лёгких вашего малыша сформируется около 300 миллионов воздушных мешочков. Вскоре они начнут полностью покрываться веществом под названием сурфактант. Сурфактант помогает осуществлять газообмен в этих мешочках и снижает поверхностное натяжение, позволяя лёгким без затруднений выполнять свою функцию даже при самом глубоком вдохе. Инъекции для ускорения созревания лёгких, которые назначают будущим мамам при угрозе преждевременных родов, стимулируют выработку сурфактанта в лёгких. Благодаря этому у недоношенных малышей дыхательные нарушения сохраняются в течение более короткого времени.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои лёгкие созревают! 🌬️ Альвеолы в моих лёгких с каждым днём развиваются всё больше. Количество вещества под названием «сурфактант» увеличивается. Если я рожусь сейчас, мне всё ещё потребуется помощь, но мои шансы очень высоки. С каждым днём я становлюсь сильнее. Просто дай мне ещё немного времени.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Салат-латук'), body_changes_ru = COALESCE(body_changes_ru, 'Сейчас, когда вы вступаете в 8-й месяц беременности, прибавка веса на 2-4 килограмма в месяц, или в среднем на 500 граммов в неделю, считается нормальной. В эти недели из-за быстрого развития малыша ваш живот заметно увеличился, а движения стали значительно более ограниченными. Растущий живот может вызывать изжогу и одышку. При таких проблемах очень полезно есть часто и небольшими порциями, а также лежать на левом боку. В эти недели вам может быть довольно трудно ходить или вставать со стула. Причина этого — расслабление суставов и мышц, происходящее во время беременности. Хотя двигаться может быть непросто, отсутствие физической активности способно ещё больше ухудшить состояние. Достаточно совершать короткие прогулки и выполнять упражнения, не переутомляя себя.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить изжогу, ешьте чаще, но небольшими порциями. Во время сна старайтесь лежать на левом боку: это полезно и для вашего пищеварения, и для кровообращения малыша. При болях в пояснице обязательно используйте подушки, поддерживающие спину. Сегодня уделите немного времени себе и начните составлять окончательный список вещей в сумку для роддома.') WHERE id = '073c7d59-96b0-4ee4-a0d5-1e595fd135fb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На 32-й неделе, когда начинается 8-й месяц беременности, количество жировой и мышечной ткани продолжает быстро увеличиваться. Благодаря этому кожа становится более мягкой и гладкой. Из-за накопления подкожного жира её прозрачность уже практически полностью исчезла. С этой недели лануго, покрывающее тело вашего малыша, также начинает выпадать. Лануго — это тонкие шелковистые волоски, которые покрывают тело малыша после 20-й недели. Эти мягкие бесцветные волоски особенно густо растут на лбу, спине и лице. В период, когда кожа ещё тонкая, лануго помогает сохранять тепло тела малыша и защищать его от инфекций. Эти волоски часто встречаются у недоношенных малышей и начинают выпадать вскоре после рождения.'), baby_message_ru = COALESCE(baby_message_ru, 'Я тренируюсь дышать 🌬️ Anacan, моя грудная клетка ритмично поднимается и опускается. Я втягиваю амниотическую жидкость в лёгкие и выталкиваю её обратно. Это укрепляет мои мышцы, чтобы после рождения я смог сделать свой первый и самый важный вдох. Иногда ты можешь чувствовать мои ритмичные движения — икоту. Это моя тренировка!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Салат-латук'), body_changes_ru = COALESCE(body_changes_ru, 'В этот период следует избегать однообразного питания. Сбалансированный и полноценный рацион обеспечит ваш организм всеми необходимыми витаминами и минералами. В первом триместре дополнительные калории для потребностей плода не требуются. Начиная со второго триместра, для развития малыша достаточно дополнительно получать 300 калорий в день. Важно понимать, что избыток калорий не принесёт пользы малышу, а отложится в вашем организме в виде жира. Уже стоит подготовить одежду и другие вещи, которые понадобятся вам и малышу в роддоме.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Обязательно включайте в ежедневный рацион продукты, богатые кальцием, поскольку кости вашего малыша сейчас проходят наиболее активный этап укрепления. При болях в пояснице регулярно выполняйте лёгкие упражнения на растяжку, а во время сна старайтесь лежать на левом боку.') WHERE id = '6dc5213e-1c8a-4a6b-8be6-3e050cac8345';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В 3-м триместре мозг вашего малыша продолжает быстро развиваться, однако голова растёт медленнее, чем остальные части тела. Формирование мозга малыша начинается на 3-й неделе внутриутробного развития. Нервная система появляется одной из первых и завершает своё развитие позже всех остальных систем — уже после рождения. Начиная с этой недели формирование нейронов завершается. В течение предыдущих 9 недель нейроны разделялись на различные типы, а их количество многократно увеличивалось. На 32-й неделе они начинают перемещаться к нижним участкам наружного слоя мозга — коры. Именно в ходе этого процесса завершается формирование основных структур мозга и нервной системы. К моменту родов мозг уже практически приобретает окончательную форму и почти не меняется.'), baby_message_ru = COALESCE(baby_message_ru, 'Все мои 5 чувств уже работают! 🖐️ Я полностью готов: вижу, слышу, различаю вкус и запахи, чувствую прикосновения. Услышав твой голос, я поворачиваю голову. Когда появляется свет, я моргаю. По вкусу амниотической жидкости я понимаю, что ты ела. Я готов познавать мир!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Салат-латук'), body_changes_ru = COALESCE(body_changes_ru, 'Эмоциональное состояние, которое малыш в утробе переживает через свою маму, в медицине называют «эмбриональной психологией». На протяжении беременности эмоциональный мир малыша формируется под влиянием тех же событий и переживаний, что и эмоциональный мир мамы. Помимо генетически обусловленного характера, существует и психологический характер ребёнка, который начинает развиваться с первых мгновений его формирования в утробе. Психологический характер — это вторичный характер, который формируется на основе генетического под влиянием счастья, волнения, гнева и печали мамы. Начав формироваться в утробе, он продолжает развиваться до 6 лет и влияет на всю жизнь человека. Никогда не забывайте, что ваш малыш связан с вами не только физиологически, но и психологически.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Используйте вкладыши для груди, чтобы защитить одежду. Не мойте соски с мылом: оно сушит кожу и провоцирует появление трещин. Достаточно промывать их тёплой водой.') WHERE id = 'fc626924-530b-4871-85a2-84474a5bcec0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Амниотическая жидкость — это стерильная, бесцветная и защитная жидкость, в которой находится малыш. Хотя частично она вырабатывается "амниотическими клетками" в матке, основная её часть поступает из организма матери. Эта жидкость позволяет малышу свободно двигаться в матке и одновременно защищает его от ударов, инфекций и перепадов температуры. Амниотическая жидкость поддерживает постоянную температуру 37 градусов на протяжении беременности, поэтому малыш не страдает ни от зимнего холода, ни от летней жары. Во 2-м триместре объём амниотической жидкости увеличивается параллельно с весом малыша. К 32-й неделе он достигает 1 литра — это максимальный объём амниотической жидкости. Чтобы у малыша оставалось больше места для набора веса, с этой недели и до родов объём амниотической жидкости уменьшается примерно на 150-250 мл и стабилизируется в среднем на уровне 750-800 мл.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня очень длинные ногти! 💅 Они уже выступают за кончики пальцев. Иногда я случайно царапаю себе лицо. Подготовьте для меня к рождению рукавички или ножницы для ногтей. Я пока не умею ухаживать за собой. Вы ведь мне поможете, правда?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Салат-латук'), body_changes_ru = COALESCE(body_changes_ru, 'Одышка может утомлять вас. Матка почти достигла своей наивысшей точки — рёберной дуги. Она давит на диафрагму и мешает лёгким полностью расправляться. Подниматься по лестнице или быстро ходить становится сложнее.;;;
Выделение "молозива" из груди может усилиться. Ваш организм готовит "золотую жидкость" для первого кормления малыша после родов. Грудь может стать тяжелее и чувствительнее. Кожа живота сейчас максимально растянута.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить давление на мочевой пузырь, сведите к минимуму употребление напитков с кофеином, поскольку они обладают мочегонным действием. Чтобы облегчить боль в пояснице, во время сна подкладывайте небольшие подушки между ногами и под живот. Продолжайте принимать кальций и железо, поскольку сейчас малыш активно накапливает эти элементы. Сегодня постарайтесь не переутомляться.') WHERE id = 'b016d6e4-baac-45d0-93bb-1a801a1ac462';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Малыш начал слышать с 16-й недели, а к концу этой недели он уже способен запоминать услышанное и реагировать на него. Начав узнавать голоса родителей, малыш оживляется, когда один из них разговаривает с ним: его сердцебиение учащается, и он старается ответить движениями. Это показывает, насколько быстро развивается мозг малыша. Хотя к концу этого периода лёгкие уже способны осуществлять газообмен, они всё ещё недостаточно зрелые. После полного развития лёгкие смогут обеспечивать защиту от микроорганизмов. Кроме того, они участвуют в регуляции водно-электролитного баланса. Они регулируют баланс водорода и йода в крови и помогают производить некоторые звуки, необходимые для речи.'), baby_message_ru = COALESCE(baby_message_ru, '32 НЕДЕЛИ! 🎃 Я размером с салат-латук! Я уже настоящий "тяжеловес". Теперь мне тесно в матке. Я не могу полностью выпрямить ноги, поэтому нахожусь в "позе эмбриона". Для меня это самое удобное положение.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Салат-латук'), body_changes_ru = COALESCE(body_changes_ru, 'Высокий уровень гормона эстрогена в крови во время беременности усиливает выработку выделений в организме. В результате слизи образуется больше, чем до беременности, и это может вызвать отёк кровеносных сосудов в носу. Возникает заложенность носа, доставляющая беременным дискомфорт. Массаж улучшает кровообращение в носовых ходах и делает слизь менее густой. Благодаря этому дышать становится легче. Не забывайте пить достаточно воды, принимайте тёплый душ, прикладывайте тёплый компресс к области носа и держите голову выше — эти меры также помогают справиться с заложенностью носа.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не пропускайте приёмы у врача. На этих неделях очень важно контролировать артериальное давление и уровень белка в моче из-за риска "преэклампсии". Если у вас появилась головная боль или затуманилось зрение, немедленно сообщите об этом врачу.') WHERE id = '33dd2de9-c534-420c-8e3d-e027683ad6e9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Слой первородной смазки на коже малыша достиг оптимальной толщины. Пока малыш находится в матке, первородная смазка образует на его коже защитный наружный слой. Она состоит из 80% воды, 10% жиров и 10% белковых соединений.;;;
Во время родов она защищает кожу от высушивающего воздействия воздуха и вредных микроорганизмов, удерживает влагу и предотвращает пересыхание кожи, поддерживает её pH-баланс на определённом уровне, а также защищает малыша от возможных инфекций и повреждений при рождении.'), baby_message_ru = COALESCE(baby_message_ru, 'Я вижу сны! 💤 Мои мозговые волны показывают, что у меня чередуются фазы глубокого и лёгкого сна. Во сне я улыбаюсь, хмурюсь и даже двигаю глазами. Мой мозг уже начинает работать почти как мозг взрослого человека. Я мечтательный малыш.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Салат-латук'), body_changes_ru = COALESCE(body_changes_ru, 'Бессонница по ночам и судороги в ногах могут утомлять вас. Из-за большого живота становится сложно переворачиваться в постели. Поскольку у вас могут возникнуть проблемы с равновесием, двигайтесь медленно. Недостаток сна может сделать вас раздражительной, поэтому постарайтесь отдыхать днём.;;;
Давление на мочевой пузырь может усилиться, но изжога и одышка могут немного уменьшиться. По мере того как головка малыша опускается, верхним органам становится легче, а нижние органы — мочевой пузырь и кости таза — испытывают большее давление. У вас может появиться "пингвинья походка".'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить отёчность ног, продолжайте пить много воды и сведите употребление соли к минимуму. Сидя старайтесь держать спину прямо, чтобы лёгким было легче расправляться. Эта неделя — подходящее время, чтобы уточнить план родов: выбрать роддом и проконсультироваться с врачом. По вечерам легко массируйте живот — малыш уже очень хорошо чувствует ваши прикосновения.') WHERE id = '7757d4d7-3e07-45ad-b80b-78b87e96663b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш продолжает расти с невероятной скоростью! В третьем триместре беременности вы набираете в среднем около 500 граммов в неделю. Почти половина этой прибавки приходится на жировую ткань, которую накапливает малыш. Основная причина столь интенсивного образования жировых клеток заключается в том, что после рождения они помогут малышу поддерживать температуру тела и при необходимости будут служить источником энергии. На этом этапе в организме малыша присутствуют как бурые, так и белые жировые клетки. Бурые жировые клетки в медицине известны как фетальная жировая ткань. У малышей их больше, чем у взрослых, поскольку они обеспечивают эффективное сохранение тепла. Бурые жировые клетки выполняют эту функцию благодаря белку термогенину, расположенному во внешней мембране многочисленных митохондрий. Термогенин обеспечивает эффективную выработку тепла за счёт использования кислорода, поступающего в клетки через кровеносные сосуды.'), baby_message_ru = COALESCE(baby_message_ru, 'Я поворачиваюсь головой вниз! ⬇️ Сила притяжения и инстинкты побуждают меня занять положение головой вниз. Голова — самая тяжёлая часть моего тела, поэтому ей удобно опуститься вниз. Это лучшее положение для родов. Если я ещё не повернулся, не волнуйтесь: некоторые мои друзья ждут до самого последнего момента.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'В третьем триместре беременности у вас может возникать выраженная одышка. Повышенный во время беременности уровень гормона прогестерона стимулирует дыхательный центр в головном мозге, заставляя вас дышать чаще и глубже. Вашей дыхательной системе требуется больше воздуха, чтобы кровь доставляла плаценте достаточное количество кислорода и выводила больше углекислого газа, чем обычно. По этим причинам при каждом вдохе и выдохе через лёгкие проходит на 30-40% больше воздуха. В результате этих изменений могут возникать затруднённое дыхание и ощущение нехватки воздуха. Чтобы облегчить это состояние, старайтесь лежать на левом боку, избегать утомительной работы, сидеть прямо и правильно дышать.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Продолжайте выполнять упражнения Кегеля. Укрепление мышц тазового дна поможет справиться с давлением, возникающим по мере опускания головы малыша, и предотвратить недержание мочи.') WHERE id = '7324ee36-63a7-4db4-bc5e-2444adb29718';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К этой неделе ваш малыш уже мог занять положение для родов. Обычно после 32-й недели малыши начинают принимать необходимое для рождения положение. Хотя в среднем это происходит в этот период, малыш может повернуться на 4 недели раньше или даже непосредственно перед родами. В положении для родов голова малыша находится внизу, ягодицы располагаются под вашей диафрагмой, ноги согнуты к животу, а руки скрещены на груди. Такое нормальное положение для родов называется головным, или затылочным, предлежанием. >:P Для физиологического течения родов голова должна определённым образом располагаться внутри таза. В родовые пути первой входит выступающая часть затылка малыша. Благодаря этому голова входит в тазовое кольцо своим наименьшим диаметром.'), baby_message_ru = COALESCE(baby_message_ru, 'Я получаю ваш иммунитет! 🛡️ Anacan, через плаценту от вас ко мне поступают "антитела" — солдаты, которые сражаются с микробами. Это моя первая вакцина. После рождения мой собственный иммунитет будет ещё слабым, но подаренная вами защита будет оберегать меня от болезней в первые месяцы. Вы мой ангел-хранитель!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'Расстройство пищеварения и запор всё ещё могут вас беспокоить. Из-за воздействия гормона прогестерона и давления матки на кишечник пищеварительная система работает медленнее. Важно пить много воды и употреблять продукты, богатые клетчаткой.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить изжогу, ешьте небольшими порциями, но часто. Сон на левом боку поможет вам легче дышать и улучшит кровообращение малыша. Если вы ещё не начали, подумайте, что нужно положить в сумку для роддома. Не забывайте отдыхать и не перенапрягайтесь!') WHERE id = '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе рост вашего малыша может находиться в довольно широком диапазоне — 40-48 см. Увеличение роста происходит главным образом за счёт удлинения костей. Этот процесс начинается в конце эмбрионального периода в утробе матери и продолжается после рождения вплоть до завершения подросткового возраста. В разные периоды темпы роста могут ускоряться или замедляться. Периоды роста у мальчиков и девочек различаются. До 2 лет мальчики обычно растут быстрее девочек. Однако начиная с 2 лет и до подросткового возраста девочки проходят этапы роста раньше мальчиков. Наиболее заметной эта разница становится в возрасте 11-13 лет, когда девочки обычно выше мальчиков. Примерно к 15-16 годам разница исчезает, а к завершению подросткового возраста мальчики становятся выше девочек. Важнейшим фактором, влияющим на рост, является генетика. Уже на этом этапе будущий рост вашего малыша во взрослом возрасте приблизительно определён.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои кости укрепляются, но... 🦴 Кости моего тела становятся твёрже, однако кости черепа ещё не срослись и остаются мягкими. Почему? Потому что во время рождения моей голове придётся немного сжаться и изменить форму, чтобы пройти через узкие родовые пути. Это удивительный замысел природы. После рождения форма моей головы восстановится.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'Если во время ультразвукового исследования плацента, которая на протяжении всей беременности доставляет малышу питательные вещества и кислород, выглядит яркой и белой, это указывает на начало её кальцификации.;;;
Старение плаценты может происходить на любом сроке беременности, однако чаще наблюдается в последнем триместре. Такие вредные привычки, как употребление алкоголя и курение, ускоряют старение плаценты. В последние месяцы беременности старение плаценты обычно не представляет опасности, но требует регулярного наблюдения. Кроме того, если у вас повышенное артериальное давление, рекомендуется находиться под медицинским наблюдением из-за риска влияния кальцификации на малыша.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Продукты, богатые пробиотиками (натуральный йогурт, кефир), могут помочь нормализовать работу пищеварительной системы. При запоре может быть полезно утром выпивать одну ложку оливкового масла или есть чернослив.') WHERE id = 'ffcf32a2-fefd-4897-8f4a-507b427193a8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Пуповина, которая переносит питательные вещества и кислород между плацентой и организмом малыша, состоит из 2 артерий и 1 вены. Пуповина, называемая в медицине умбиликальным канатиком, физиологически и генетически является частью вашего малыша. Она обеспечивает перенос насыщенной кислородом крови и крови, содержащей продукты обмена, не допуская их смешивания. Длина пуповины составляет около 50 см, а диаметр — около 2 см. Артерии и вена в ней выполняют функции, противоположные их обычным. Как правило, насыщенная кислородом кровь переносится по артериям, а бедная кислородом кровь, содержащая продукты обмена, — по венам. Однако в пуповине артерии переносят кровь с продуктами обмена, а вена — кровь, богатую кислородом и питательными веществами. Поскольку пуповина не содержит нервных окончаний, её перерезание после рождения не причиняет малышу боли. Однако в некоторых случаях пуповина может состоять всего из двух сосудов — одной артерии и одной вены. В таких ситуациях оценивают развитие малыша и может потребоваться более тщательное наблюдение.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои кости твёрдые как камень! 🦴 Мой скелет полностью окреп. Мои ручки и ножки уже не мягкие, как резина, а крепкие. Когда я толкаюсь, вы, вероятно, ощущаете это болезненнее. Продолжайте получать достаточно кальция, ведь я всё ещё использую ваши запасы.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'Релаксин — это гормон белковой природы, уровень которого в вашем организме начинает повышаться с наступлением беременности.;;;
По своему химическому строению релаксин очень похож на инсулин. Он вырабатывается плацентой и яичниками и выполняет очень важные функции во время беременности.;;;
Релаксин способствует размягчению и расслаблению связок, удерживающих кости таза. Кроме того, начиная с третьего триместра, по мере приближения родов он помогает расслабляться связкам, окружающим матку.;;;
По сравнению с периодом до беременности его уровень в организме увеличивается примерно в 10 раз. Уже в первые дни после прикрепления малыша к матке уровень этого гормона в крови значительно повышается. Стимулируя образование новых кровеносных сосудов, он помогает создать наиболее благоприятные условия для оплодотворённой яйцеклетки.;;;
Вместе с тем релаксин вызывает расслабление различных связок в области бёдер, голеностопных суставов, коленей и плеч. В результате в этих областях нередко могут возникать повышенная чувствительность или боль.;;;
В последние недели беременности релаксин размягчает связки таза, образованного соединением тазовых костей и крестца, что облегчает прохождение малыша во время родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в руках, чаще встряхивайте кистями. Следите, чтобы во время ночного сна запястья не сгибались, или используйте специальные ортезы для запястий.') WHERE id = '17265dbc-d27e-4949-9a83-25783c4be9dd';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Гладкие мышцы, обеспечивающие продвижение содержимого по тонкому кишечнику малыша, продолжают развиваться. Этот процесс длится примерно до 37-й недели. В тонком кишечнике белки, жиры и углеводы, содержащиеся в химусе — частично переваренной пище, поступающей из желудка, — расщепляются на структурные компоненты. Пищеварение происходит благодаря желчи, которая вырабатывается в печени и накапливается в желчном пузыре, а также панкреатическому соку, вырабатываемому поджелудочной железой и поступающему непосредственно в тонкий кишечник.;;;
Кроме того, именно в тонком кишечнике происходит всасывание питательных веществ, расщеплённых на структурные компоненты. За этот процесс отвечают ворсинки, расположенные во внутреннем слое тонкого кишечника. На данном этапе на каждый миллиметр тонкого кишечника приходится около 40 ворсинок. Питательные вещества, переваренные в начальных отделах тонкого кишечника, затем всасываются ворсинками в его средних отделах и поступают в кровь и лимфу. Продвижение пищи, необходимое для её переваривания и всасывания, обеспечивается гладкими мышцами, расположенными в среднем слое кишечной стенки. Эти продольные и кольцевые мышцы создают перистальтические движения тонкого кишечника. Благодаря перистальтике пищевые массы продвигаются дальше.'), baby_message_ru = COALESCE(baby_message_ru, 'Объём моих околоплодных вод достиг максимума! 💧 Сейчас в моём бассейне больше всего воды (примерно 1 литр). После этого её количество останется стабильным или немного уменьшится ближе к родам, потому что я вырасту и займу всё пространство. Пока мне удобно, но стенки уже становятся всё ближе!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'С наступлением третьего триместра беременности изжога могла стать значительно сильнее. Она может возникать в любое время дня, но чаще всего появляется вечером после еды. Рефлюкс, известный как изжога, возникает, когда кислое содержимое желудка попадает в пищевод и раздражает его, вызывая чувство жжения за грудиной. Изжога во время беременности в основном связана с гормональными и физическими изменениями.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При одышке ешьте очень маленькими порциями. Наполненный желудок сильнее давит на диафрагму. Сидите прямо — так у лёгких будет немного больше пространства.') WHERE id = '41437aba-e2e0-4e6a-ba9f-969bd7411f70';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В толстом кишечнике малыша уже накопилось множество полезных бактерий, которые будут помогать пищеварению. Их количество почти сопоставимо с числом клеток организма.;;;
Толстый кишечник — это конечный отдел пищеварительной системы. Он отделяет воду и витамины от остатков переваренной и усвоенной пищи и формирует кал. Одна из важнейших функций толстого кишечника — всасывание витаминов. Этот процесс осуществляется благодаря живущим в нём бактериям. В толстом кишечнике насчитывается более 700 видов бактерий, а их общее количество превышает миллионы.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с ананас! Я уже большой малыш. Мои щёчки округлились, а тело стало пухленьким. До нашей встречи осталось совсем немного, Anacan. С каждым днём я набираю всё больше веса.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'Инфекции мочевыводящих путей относятся к наиболее распространённым проблемам со здоровьем в последние недели беременности. Одна из лучших мер профилактики — выпивать не менее 2,5 литра воды в день. Особенно важно избегать пакетированных сладких напитков. Сахар может создавать благоприятную среду для потенциально вредных бактерий в мочевыводящих путях и способствовать их быстрому размножению. Кроме того, старайтесь не терпеть и чаще посещайте туалет, следите за полным опорожнением мочевого пузыря и тщательно соблюдайте гигиену интимной области после туалета.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы восполнить потребность в кальции, увеличьте употребление молока, йогурта или сыра. Для уменьшения изжоги не ложитесь сразу после еды и завершайте ужин как минимум за 3 часа до сна. Чтобы предотвратить отёки ног и варикозное расширение вен, не стойте подолгу и не скрещивайте ноги, когда сидите. Сегодня ещё раз проверьте сумку в роддом — возможно, вы что-то забыли?') WHERE id = '97daa5bb-e709-4882-8a96-d104cbbdafc3';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Пуповина, которая служит связующим звеном и обеспечивает все потребности вашего малыша, на этом сроке беременности может стать причиной некоторых осложнений. К ним относятся обвитие пуповиной и наличие только двух сосудов в пуповине. Обвитие этой структуры, соединяющей плаценту с пупком малыша, вокруг его шеи может представлять опасность.;;;
Пуповина может не только обвиться вокруг шеи малыша, но и образовать истинный узел. Некоторые узлы формируются во время родов, а другие — в период беременности из-за движений малыша. Если узел свободный, он обычно не представляет опасности. Однако при тугом узле может нарушиться кровоток от плаценты к малышу, что способно привести к нехватке кислорода. Наиболее распространённый признак обвития или узла пуповины — уменьшение количества шевелений малыша в последние недели. Если узел затягивается во время родов, на КТГ могут наблюдаться отклонения сердечного ритма. Свободное обвитие пуповиной чаще встречается при большом количестве амниотической жидкости, поскольку у малыша больше пространства для движений. Примерно в 1 из 2000 родов образуется настолько тугой узел пуповины, что он представляет риск для малыша.'), baby_message_ru = COALESCE(baby_message_ru, 'Моей воды становится меньше, а я продолжаю расти! 💧 Раньше мой бассейн был очень просторным, но теперь я занимаю столько места, что амниотической жидкости кажется относительно меньше. Сейчас ты ощущаешь мои движения отчётливее и сильнее. Когда я выставляю локоть в твою сторону, форма твоего живота может измениться.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'В эти недели, когда вы приближаетесь к завершению беременности, стоит задуматься о том, как вы хотели бы рожать. В последние годы роды в воде стали одним из наиболее активно изучаемых способов родоразрешения. Они проходят в воде, в специально оборудованном бассейне или ванне, а расслабляющее действие воды помогает легче переносить схватки. Нахождение в тёплой воде во время родов способствует расслаблению тела и выработке окситоцина. Окситоцин делает схватки более регулярными и может сократить продолжительность родов. Кроме того, тёплая вода расслабляет мышцы и ткани, уменьшая боль и напряжение. Благодаря расслаблению мышц, особенно в области живота и паха, схватки могут переноситься гораздо легче. Это поможет вам пройти роды спокойнее и с более позитивным настроем.;;;
Кроме того, малыш, который на протяжении всей беременности развивался в амниотической жидкости, при рождении в тёплую воду переживает более плавный переход и испытывает минимальный родовой стресс.;;;
Если вы хотите рожать в воде, уточните, есть ли в выбранном вами роддоме необходимые условия для таких родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Продолжайте наносить на живот увлажняющие масла. Старайтесь не расчёсывать кожу. Если цвет или запах выделений изменится (они станут зелёными или приобретут неприятный запах), обратитесь к врачу. Для удобства можно использовать ежедневные прокладки.') WHERE id = '1071fbaa-eb8a-400f-b713-0a3f36f51bd7';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Благодаря тому, что веки малыша уже разделились, во время бодрствования он начинает довольно часто открывать глаза. Радужная оболочка уже помогает зрачкам сужаться при ярком свете и расширяться в темноте.;;;
Зрачок — это отверстие в центре цветной части глаза, которая называется радужной оболочкой. Через него свет попадает на сетчатку. Поскольку проходящие через зрачок лучи поглощаются внутренними тканями глаза и почти не отражаются обратно, зрачок кажется чёрным. Цветная часть глаза, окружающая зрачок, имеет сократимую структуру и в основном состоит из гладких мышц. Свет проникает в глаз через зрачок, а радужная оболочка, управляющая его размером, регулирует количество поступающего света. Расширение и сужение зрачка происходит благодаря двум гладким мышцам радужной оболочки. При ярком свете одна из них сокращается, сужая зрачок и защищая глаз от негативного воздействия интенсивного света. В темноте другая мышца сокращается и расширяет зрачок. Благодаря этому в глаз поступает больше света, что помогает видеть в темноте.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя кожа больше не прозрачная! 👶 Она стала плотнее и приобрела розовый оттенок, поэтому мои внутренние органы уже не видны. Жировая прослойка делает меня более "пухленьким". Теперь я похож на настоящего новорождённого малыша. Если ты увидишь меня на 3D-УЗИ, тебе захочется потрогать мои щёчки!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'Если это ваша вторая беременность, а первые роды прошли путём кесарева сечения, вы можете рассмотреть ЕРПКС. ЕРПКС — это сокращённое название естественных родов после кесарева сечения. Речь идёт о возможности родить естественным путём после предыдущего кесарева сечения. Раньше женщинам, перенёсшим кесарево сечение, не рекомендовали завершать следующую беременность естественными родами.;;;
Однако результаты последних исследований показали, что вероятность успешных естественных родов после кесарева сечения превышает 75%.;;;
Если после кесарева сечения прошло не менее 1 года, у вас не было разрыва матки или других операций на матке, а во время текущей беременности не возникло противопоказаний к естественным родам, вы можете обсудить с врачом ЕРПКС. Кроме того, естественные роды имеют ряд преимуществ по сравнению с кесаревым сечением. После них сокращается период послеродового восстановления, снижается риск инфекций и сводится к минимуму кровопотеря.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Уделите время себе. Это последние недели перед родами, когда у вас есть возможность побыть наедине с собой. Читайте книги, смотрите фильмы, встречайтесь с друзьями. Цените эти спокойные дни.') WHERE id = '79fb5c0f-3cea-4126-92e7-e885b95bc603';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Гены, определяющие рост и вес вашего малыша, передаются через хромосомы половых клеток. В частности, факторы, определяющие рост, на 80% связаны с генетическим кодом. Количество таких генетических вариантов может составлять от 600 до 700. Иными словами, если мама и папа генетически невысокие и худощавые, то без влияния других факторов малыш вряд ли будет очень высоким или склонным к набору веса. Пищевые привычки также напрямую влияют на набор веса, рост и укрепление костей. Развитие костей обеспечивает увеличение роста. На соотношение роста и веса, помимо наследственных факторов, влияют различные заболевания, препятствующие развитию генетические нарушения, дефицит питательных веществ и неправильные пищевые привычки, режим сна и физическая активность. Климат также может влиять на рост и набор веса. В частности, жители регионов с тропическим климатом чаще имеют более низкий рост и плотное телосложение, тогда как жители Северной Европы, включая скандинавские страны, чаще бывают более высокими и худощавыми.'), baby_message_ru = COALESCE(baby_message_ru, 'Я получаю твой иммунитет! 🛡️ Anacan, знаешь, чем я сейчас занимаюсь? Я получаю из твоей крови своих "солдат иммунитета" (антитела). Ты передаёшь мне защиту от болезней, к которым у тебя выработался иммунитет на протяжении жизни. После рождения ты станешь моим первым щитом от микробов.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Ананас'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности из-за развития костей малыша ваша потребность в витамине D возрастает примерно в 5 раз. Особенно во втором триместре, когда кости малыша активно развиваются, из вашего организма к нему поступает большое количество кальция. Чтобы удовлетворить возросшую потребность в витамине D, организм усиливает его всасывание в кишечнике. Одновременно может происходить мобилизация кальция из костей в кровь. Из-за этого во время беременности кости могут стать более уязвимыми.;;;
За всю беременность женщины могут потерять около 5% костной массы. При снижении уровня витамина D может повыситься риск гестационного диабета, преэклампсии и инфекций. Поэтому при подтверждённом дефиците очень важно принимать витамин D по рекомендации врача. Наряду с добавками может быть полезно проводить 15-20 минут в день на солнце.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Продолжайте пить достаточно воды. Это важно для регулирования температуры тела и предотвращения обезвоживания. Обезвоживание может спровоцировать преждевременные схватки.') WHERE id = 'adc2549c-64e5-4fcb-ab22-00fd00f59fac';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе скелет малыша в основном состоит из хрящевой ткани. После рождения, по мере взросления малыша, хрящевая ткань, составляющая большую часть скелета, постепенно заменяется костной. Накопление в костной ткани солей кальция, придающих костям твёрдость, продолжается до конца подросткового периода. После завершения окостенения хрящевая ткань сохраняется на концах рёбер, суставных поверхностях, в трахее, гортани, ушных раковинах и на кончике носа. Она также придаёт костям эластичность и обеспечивает подвижность скелета.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя голова всё ещё мягкая! 🧠 Хотя кости моего тела уже твёрдые, кости черепа остаются настолько подвижными, что могут заходить друг на друга. Почему? Потому что во время рождения моя голова должна будет немного уменьшиться, чтобы пройти через узкие родовые пути. Природа подарила мне "эластичный шлем".'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Возможно, сейчас бессонница беспокоит вас сильнее, чем когда-либо прежде. Тошнота, изжога и жжение в желудке, постоянные позывы в туалет и невозможность удобно устроиться из-за растущего живота — каждый из этих факторов может ухудшать качество сна. Справиться с бессонницей вам помогут короткий душ и 1 стакан тёплого молока перед сном, отказ от тяжёлой и жирной пищи, которую трудно переваривать, особенно в вечернее время, а также от напитков с кофеином, таких как чай и кофе.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В течение дня чаще поднимайте ноги. Носите удобную обувь или тапочки на один размер больше. Избегайте солёных продуктов.') WHERE id = '75724f71-0d67-40e0-ac05-b52a8a77f3b7';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Мочевыделительная система малыша — одна из наиболее активно работающих систем в период внутриутробного развития. На этом этапе над почкой малыша расположен надпочечник, отделённый от неё жировой тканью. В области углубления на внутренней стороне к почке также подходят многочисленные кровеносные и лимфатические сосуды, нервы и мочевыводящие пути. Мочевой пузырь малыша представляет собой мешковидный орган, стенки которого полностью состоят из гладкой мышечной ткани. В местах впадения мочеточников в мочевой пузырь имеются клапаны, препятствующие обратному току мочи. Когда мочевой пузырь наполняется, нервные окончания в его растягивающихся стенках посылают сигнал в мозг, вызывая сокращение пузыря. Благодаря этому малыш ощущает потребность в мочеиспускании. Моча выводится через уретру. Если ваш малыш — мальчик, его уретра связана с мужской репродуктивной системой.'), baby_message_ru = COALESCE(baby_message_ru, 'Я слежу за светом! 🔦 Мои глаза открыты, и я осматриваюсь вокруг. Зрачки реагируют на свет — сужаются при ярком освещении и расширяются в темноте. Моя зрительная система уже работает. После рождения я смогу видеть ваше лицо с расстояния примерно 20-30 см (именно на таком расстоянии оно будет находиться во время кормления грудью!).'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности дискомфорт со стороны желудка и кишечника может ощущаться гораздо сильнее, чем обычно. Поэтому скопление газов и вызванные им боли становятся довольно распространённой проблемой. Причина повышенного газообразования при беременности связана с гормональными изменениями, особенно с действием прогестерона. Этот гормон расслабляет гладкую мускулатуру пищеварительной системы.;;;
Ромашковый чай может быть полезен при повышенном газообразовании. Следует избегать острых и пряных продуктов, усиливающих неприятные симптомы. Кроме того, отказ от употребления жидкости непосредственно во время еды помогает уменьшить вздутие и предотвратить боли, вызванные скоплением газов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить одышку, во время сидения обязательно держите спину прямо. Для уменьшения отёков ног пейте больше воды и в течение дня отдыхайте, приподняв ноги. Бессонница в этот период нормальна, поэтому короткий сон продолжительностью 15-20 минут в течение дня поможет вам восстановить силы. Сегодня вечером уделите немного времени себе и расслабьте тело под тёплым душем.') WHERE id = '0d05bbb2-bf77-46f6-81b3-38696a1de3f5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Формирование слизистого слоя из эпителиальных клеток на внешней поверхности кишечника малыша уже завершилось. Благодаря этому кишечник защищён от повреждений, которые могли бы возникнуть из-за трения о другие органы. В толстом кишечнике присутствуют скопления лимфоидной ткани. Вырабатываемые ими антитела препятствуют чрезмерному размножению полезных бактерий, обитающих в кишечнике, и обезвреживают вредные микроорганизмы, попадающие в организм с пищей. Это помогает предотвращать возможные инфекции. Кишечные бактерии синтезируют витамины, которые организм малыша не способен вырабатывать самостоятельно. Наиболее важные из них — витамин K и витамины группы B. Кроме того, всасывание воды в толстом кишечнике предотвращает её выведение с калом и обеспечивает возвращение необходимой организму жидкости в кровь. После того как углеводы, жиры, белки, витамины, минералы и вода, содержащиеся в пище, всасываются в тонком и толстом кишечнике, оставшиеся отходы хранятся в толстом кишечнике до их выведения через анус. Таким образом, толстый кишечник также выполняет роль хранилища отходов.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне здесь очень тесно! 🏠 Anacan, я хочу повернуться, но стенки так близко. Теперь мои движения больше похожи на "скольжение" и "толчки". Когда я выпячиваю локоть с одной стороны вашего живота, вы можете увидеть небольшой бугорок. Погладьте меня, и я уберу его.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'По мере приближения конца беременности тренировочные схватки могут становиться значительно интенсивнее. В последние недели такие сокращения матки порой бывают довольно болезненными. Эти тренировочные схватки, называемые схватками Брекстона-Хикса, часто путают с настоящими родовыми схватками. Их интенсивность может усиливаться при переутомлении, длительном пребывании на ногах или ударе в область живота. Кроме того, у женщин, которые уже рожали несколько раз, такие схватки обычно начинаются раньше и продолжаются дольше. При первой беременности они, как правило, начинаются позже, а промежутки между ними бывают более неравномерными.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить отёки ног, продолжайте пить больше воды и приподнимайте ноги, когда сидите. При повышенной чувствительности дёсен используйте мягкую зубную щётку. Если вы ещё этого не сделали, можно начать стирать и гладить первую одежду для малыша. Это успокаивающее занятие поможет вам подготовиться и одновременно укрепит вашу связь с малышом.') WHERE id = 'd5a88302-fe21-4399-b36c-3480a294c860';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К концу 33-й недели срок вашей беременности составляет 7 месяцев и 28 дней. Начиная с этой недели ваш малыш будет набирать не менее 30 граммов в день. Такой быстрый набор веса обусловлен активным образованием жировых клеток. Благодаря значительному увеличению подкожной жировой ткани ваш малыш уже выглядит как полностью сформировавшийся новорождённый. В течение следующих 2 недель количество жировой ткани почти достигнет уровня, который будет у малыша при рождении. Благодаря этому его кожа станет гораздо более гладкой. Жировые клетки, накопленные под кожей малыша, помогают сохранять тепло и служат запасом энергии. В эти последние недели беременности иммунная система малыша также укрепляется. Это происходит благодаря тому, что антитела, вырабатываемые вашим организмом, передаются малышу через плаценту и пуповину. Благодаря развивающейся иммунной системе после рождения ваш малыш будет достаточно крепким и готовым к жизни во внешнем мире.'), baby_message_ru = COALESCE(baby_message_ru, '🍈 Я размером с дыню! Эта неделя — очень важный этап. Если я рожусь сейчас, то, скорее всего, смогу дышать самостоятельно, потому что мои лёгкие уже достаточно развиты. Теперь я отношусь к категории поздней недоношенности. Риск значительно снизился!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Вашему малышу, который быстро развивается на протяжении беременности, требуется большое количество кальция, особенно для укрепления скелета и костей. Если во время беременности вы получаете недостаточно кальция, малыш будет восполнять свою потребность за счёт вашей костной системы, что может привести к истощению запасов кальция в организме. При недостаточном поступлении кальция с ежедневным питанием могут часто возникать боли и спазмы, особенно по вечерам. Кроме того, из-за значительной нагрузки на скелетную систему могут создаваться предпосылки для развития остеопороза и других проблем с костями. Поэтому для развития малыша и сохранения собственного здоровья вам следует внимательно относиться к питанию и следить за тем, чтобы ежедневно получать достаточно кальция. К продуктам, помогающим восполнить потребность в кальции, относятся белый сыр, йогурт, молоко, необжаренные орехи, бобовые, натуральный тахини и пекмез. Одна миска йогурта содержит 250 мг кальция, один ломтик белого сыра — 100 мг, горсть необжаренных орехов — 50 мг, 50 граммов пекмеза — 200 мг, а 50 граммов тахини — 220 мг.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня наградите себя за то, что успешно прошли этот 34-недельный путь, и обязательно отдохните. Чтобы уменьшить боль в пояснице, во время сидения используйте подушки, поддерживающие спину. Если вы ещё этого не сделали, поставьте сумку для роддома у двери, чтобы быть готовой в любой момент. С завтрашнего дня начинается 35-я неделя — последний большой поворот на пути к родам!') WHERE id = '5eeb8067-0b28-436d-9bac-19e1ef1b2e15';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К этой неделе все функции организма вашего малыша уже работают. Его органы почти достигли размеров, которые будут иметь при рождении. Один из этих органов — печень — составляет около %5 массы тела малыша и весит в среднем 100 граммов. Печень — самый крупный внутренний орган малыша. У взрослого человека она весит около 2 килограммов. Печень расположена справа от желудка, рядом с другими органами и системами, и выполняет жизненно важные для малыша функции. При возникновении потребности в энергии она может преобразовывать накопленный гликоген в сахар. В ней хранятся витамины A, D, E, K, B12 и железо. Печень вырабатывает белки и в зависимости от потребностей организма может преобразовывать их в гормоны и антитела. Благодаря вырабатываемой ею желчи поступающие в организм жиры расщепляются до жирных кислот и глицерина, после чего клетки могут их использовать. Печень также выполняет функцию фильтра для вредных веществ, накапливающихся в организме. Она обезвреживает все вредные для организма вещества, прежде всего алкоголь и токсины, и способствует их выведению с мочой.'), baby_message_ru = COALESCE(baby_message_ru, 'Слой верникса становится толще! 🧀 Белое сыровидное вещество, покрывающее мою кожу (верникс), сейчас достигло максимальной толщины. Оно защищает меня. Ближе к родам этот слой будет постепенно уменьшаться и смешиваться с околоплодными водами. Когда я проглатываю эту жидкость, то получаю белок. У меня ничего не пропадает зря!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Чтобы обеспечивать малыша кислородом и питательными веществами, ваш организм быстро увеличивает объём крови. Это приводит к расширению сосудов и снижению артериального давления. В целом пониженное давление обычно не причиняет серьёзного дискомфорта. Однако чрезмерная усталость, инфекции, длительная неподвижность, недостаточное употребление жидкости, неполноценное питание, анемия, кровотечения и аллергические реакции могут ещё сильнее снизить давление и вызвать головокружение, потемнение или туман перед глазами, учащённое дыхание, тошноту и предобморочное состояние. Если у вас пониженное давление, не вставайте резко из положения сидя или лёжа, не стойте подолгу, не допускайте длительных перерывов между приёмами пищи, избегайте слишком горячих и продолжительных ванн, пейте достаточно жидкости и придерживайтесь полноценного рациона, чтобы получать необходимые витамины.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если нарушение зрения незначительное, не беспокойтесь. Но если перед глазами мелькают «мушки», это может быть признаком повышенного давления — немедленно сообщите врачу.') WHERE id = 'ee172976-4ef5-4259-a92a-16b538ea9e64';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя формирование многих костей и суставов вашего малыша уже завершилось, кости черепа всё ещё остаются мягкими. Их подвижность очень важна для прохождения малыша через родовые пути. На этом этапе кости черепа удерживаются вместе соединительной тканью, не срастаясь полностью. Благодаря этой ткани кости черепа сохраняют подвижность, поэтому головка малыша может легче пройти через довольно узкие родовые пути.;;;
В местах, где кости черепа ещё не соединились, находятся мягкие участки, называемые родничками. Эти участки вместе с расположенной под ними соединительной тканью придают головке малыша гибкость, необходимую для продвижения по родовым путям. После рождения малыша роднички постепенно закрываются по мере роста и развития головного мозга. Проходя через родовые пути, малыш должен совершать определённые движения, чтобы размеры его головки соответствовали диаметру родового канала. Кроме того, продвигаясь по родовым путям, он меняет положение, чтобы преодолевать сопротивление. Во время этих движений соединительная ткань сжимается, кости черепа сближаются и могут даже частично заходить друг на друга.'), baby_message_ru = COALESCE(baby_message_ru, 'Я смотрю вниз! ⬇️ Скорее всего, моя головка уже опустилась между костями таза. Это может причинять вам некоторый дискомфорт — будто между ног находится мяч, — но для меня это означает, что я приближаюсь к выходу. Я уже на стартовой линии!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности рыба обязательно должна входить в рацион, поскольку она богата жирными кислотами Омега-3 и Омега-6. Употребление рыбы очень важно для общего развития организма малыша, особенно его нервной системы и органов зрения. Однако при употреблении рыбы с высоким содержанием ртути это токсичное вещество легко всасывается организмом, попадает в кровь и через плаценту проникает к малышу. Очень полезны лосось, хамса, сардины, форель и скумбрия. При этом рыба-меч, тунец и акула содержат большое количество ртути. Хотя тунец содержит ртуть, он является важным продуктом для развития малыша, поэтому его можно употреблять изредка, но не часто.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Двигайтесь медленно. Вставая со стула или кресла, опирайтесь на руки. Чтобы расслабить мышцы таза, полезно сидеть на гимнастическом мяче и выполнять круговые движения.') WHERE id = '75621ce6-a937-4f79-9f2e-175be59eec6b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Лёгкие вашего малыша готовятся ко дню рождения, непрерывно совершая дыхательные движения. В отличие от обычного дыхания, дыхательные движения малыша в утробе происходят с участием не воздуха, а воды (амниотической жидкости). Его организм получает необходимый кислород не через дыхательные пути, а через плаценту. Эти дыхательные движения служат тренировкой вдохов и выдохов. Благодаря такой тренировке в лёгких вырабатывается сурфактант — вещество, жизненно необходимое для дыхания. Передача кислорода от плаценты к малышу происходит по довольно простому принципу. Две молекулы, участвующие в дыхании, — кислород и углекислый газ — переносятся через плаценту благодаря разнице давления. Когда в плаценте встречаются кровь малыша, в которой кислород уже был использован организмом, и ваша кровь с высоким содержанием кислорода, возникает разница давления, благодаря которой кислород переходит из вашей крови через плаценту. Несмотря на более низкое давление кислорода, кровь малыша способна доставлять тканям достаточное его количество. Это связано с тем, что уровень гемоглобина в крови малыша примерно на %50 выше. Кроме того, способность гемоглобина в системе кровообращения переносить кислород значительно выше, чем при получении кислорода через дыхательные пути.'), baby_message_ru = COALESCE(baby_message_ru, 'Я накапливаю запасы железа! 🔩 Anacan, сейчас я получаю железо из твоей крови. Я создаю запас железа в своей печени. Он понадобится мне для кроветворения в первые 6 месяцев после рождения. Ты можешь чувствовать слабость, потому что я «краду» твою энергию. Прости, но мне это необходимо!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'С наступлением беременности в микрофлоре вашего кишечника происходят определённые изменения. В результате изменения кишечной микрофлоры увеличивается доля жира в организме и снижается чувствительность к инсулину — гормону, регулирующему уровень сахара в крови. Изменения обмена веществ обеспечивают малыша дополнительной энергией для роста, а также помогают вашему организму накопить жировые запасы, необходимые во время грудного вскармливания. Однако из-за повышения уровня гормонов беременности гладкая мускулатура пищеварительной системы расслабляется, поэтому пища медленнее продвигается по кишечнику. В результате могут возникнуть несварение, скопление газов и запор. Чтобы предотвратить запор, необходимо пить много жидкости и больше двигаться. Составьте рацион, включающий богатые клетчаткой овощи, фрукты, бобовые и злаки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в области таза, не скрещивайте ноги, когда сидите, и очень медленно поворачивайтесь в постели с одного бока на другой. Чтобы избежать изжоги, не ешьте тяжёлую пищу перед сном. На этой неделе в последний раз проверьте свой «список вещей в роддом»: убедитесь, что подготовлены удобный халат для вас, первый комплект одежды для малыша и подгузники. Сегодня уделите немного времени себе и послушайте спокойную музыку.') WHERE id = 'b978e435-783d-4177-aada-9e6cd05f0950';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В организме вашего малыша продолжается очень быстрое образование жировой ткани. При этом большая часть покрывавших его тело волосков лануго уже выпала. Лануго — это тонкие волоски, которые начинают расти по всему телу малыша с первого триместра беременности. К 20-й неделе их становится значительно больше и они густеют. Эти волоски помогают поддерживать стабильную температуру тела малыша, пока у него ещё нет жировой прослойки. Когда в последнем триместре начинается образование жировой ткани, они постепенно выпадают. В последние недели беременности жировая прослойка формируется очень быстро. Поэтому лануго выпадает всё интенсивнее, а отделившиеся от поверхности кожи волоски попадают в амниотическую жидкость. Во время дыхательных движений малыша волоски из амниотической жидкости проникают в его организм. Проглоченные малышом волоски лануго соединяются в кишечнике со слизью, остатками клеток кожи и другими продуктами жизнедеятельности, образуя меконий.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои почки работают в полную силу! 💧 Мои почки уже полностью сформированы, а печень способна перерабатывать некоторые продукты жизнедеятельности. Если я появлюсь на свет сегодня, система очищения моего организма будет работать. С каждым днём я становлюсь всё более «самостоятельным». Ты можешь мной гордиться.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Время от времени вы можете чувствовать сильную слабость, истощение и усталость. Во время беременности из-за гормональных изменений, значительного увеличения размеров малыша и набранного веса вполне нормально чувствовать себя более уставшей и слабой, чем до беременности. Обычно такая усталость уменьшается после отдыха и качественного сна. Однако если усталость не проходит даже после отдыха, ощущается сразу после пробуждения и сохраняется длительное время, можно говорить о синдроме хронической усталости. Это состояние сопровождается длительной усталостью, которая не уменьшается после отдыха, а также несколькими другими симптомами: проблемами с памятью и концентрацией, головными болями различной интенсивности, трудностями с засыпанием и повторяющейся болью в горле. Неполноценное питание — один из основных факторов, вызывающих хроническую усталость. Если вы не получаете с пищей витамины и минералы, необходимые вам и малышу, обязательно принимайте добавки, рекомендованные вашим врачом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы справиться с бессонницей, старайтесь не переутомляться в течение дня и принимайте тёплый душ перед сном. При боли в спине обязательно используйте подушку для беременных и лежите на левом боку. Чтобы уменьшить отёки ног, пейте много воды и не менее 3-4 раз в день отдыхайте по 15 минут, подняв ноги выше уровня сердца. Сегодня не переутомляйтесь — берегите силы для важного дня.') WHERE id = '35db243b-b555-441f-ace2-1f8b3ddb076b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе объём крови малыша составляет 80 миллилитров на каждый килограмм массы тела, а всего в его организме в среднем содержится 250 грамм крови. Клетки крови вырабатываются в костном мозге. Костный мозг — это губчатая ткань, находящаяся внутри некоторых костей. В нём содержатся специализированные стволовые клетки. Под воздействием различных факторов и в соответствии с потребностями организма малыша эти клетки образуют эритроциты, лейкоциты и кровяные пластинки, называемые тромбоцитами. Уровень гемоглобина в крови, циркулирующей по кровеносной системе малыша, значительно отличается от обычных показателей. Начиная с этой недели и до родов уровень гемоглобина в его крови составляет около  г/дл. В течение короткого времени после рождения может наблюдаться повышение уровня гемоглобина до  г/дл, однако к третьему месяцу этот показатель снижается примерно до  г/дл. После рождения малыша в костном мозге временно приостанавливается выработка эритроцитов. Это связано с тем, что после рождения его организм сталкивается с более высоким давлением кислорода. Когда костный мозг адаптируется к кислородному давлению, процесс нормализуется, однако у новорождённых часто возникает малокровие, называемое физиологической анемией.'), baby_message_ru = COALESCE(baby_message_ru, 'Я «перекатываюсь»! 🔄 Раньше я пинался, а теперь мне так тесно, что я могу только перекатываться или толкаться локтями. Ты можешь увидеть, как на животе выпирает моя пятка или колено. Погладь меня — возможно, я уберу их.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'С наступлением беременности уровень прогестерона в крови значительно повышается, из-за чего изменяется способность роговицы — прозрачной оболочки в передней части глаза — удерживать воду. В результате зрение может стать затуманенным, а у тех, кто носит контактные линзы, может развиться повышенная чувствительность к ним. В этот период следует отказаться от контактных линз. Кроме того, снижение уровня андрогенов во время беременности может привести к сухости глаз. Искусственные слёзы, применяемые по рекомендации врача, помогают облегчить этот симптом. Обычно после родов эта жалоба постепенно уменьшается и полностью исчезает.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить отёки, продолжайте пить много воды и регулярно отдыхайте, держа ноги в приподнятом положении. При боли в спине вам помогут расслабиться лёгкая гимнастика для беременных или упражнения йоги.') WHERE id = '8220cf1e-c217-46c8-aaef-257724e08389';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Иммунная система вашего малыша формируется благодаря антителам, которые передаются ему от вас через плаценту. Антитела — это гликопротеины, органические молекулы, состоящие из сахаров и аминокислот. Так называют защитные вещества, которые организм вырабатывает в ответ на проникновение чужеродных агентов. Организм малыша начнёт вырабатывать собственные антитела через некоторое время после рождения. А пока его иммунная система не сформировалась, он защищается от вредных микроорганизмов, называемых антигенами, с помощью антител, полученных от вас. Антитела уничтожают находящиеся в крови вредные микроорганизмы, вирусы и другие чужеродные частицы до того, как они проникнут внутрь клеток. Когда в кровь попадает бактерия, клетки иммунной системы, такие как лимфоциты и макрофаги, распознают особую молекулярную структуру её клеточной стенки и запускают выработку антител. В организме для каждого антигена формируется специфический лимфоцит. В свою очередь, лимфоциты синтезируют соответствующие антитела. Несовместимость групп крови возникает в результате взаимодействия антигенов и антител.'), baby_message_ru = COALESCE(baby_message_ru, 'Я уже очень большой малыш. Я заполнил почти всё свободное пространство в матке. Теперь я занят только тем, что набираю вес, — примерно по 200-250 граммов в неделю. Мои щёчки, ручки и ножки становятся пухленькими.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'С приближением конца беременности отёки и припухлости могут стать значительно заметнее. Отёки главным образом возникают из-за нарушения кровообращения. Особенно в последнем триместре сильно увеличившаяся матка давит на кровеносные сосуды таза и ног. Это давление замедляет кровообращение, в результате чего появляются отёки. Вызванная скоплением жидкости отёчность может составлять около 25% прибавки веса во время беременности. Полностью избавиться от отёков в этот период невозможно, но некоторые меры помогут немного их уменьшить. Регулярно выполняйте физические упражнения, не сидите и не стойте подолгу, в течение дня приподнимайте ноги, чтобы улучшить кровообращение, а во время сна лежите на левом боку.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Продолжайте выполнять упражнения Кегеля. Это один из самых эффективных способов профилактики недержания мочи после родов. Выполняйте по 10 повторений 3 раза в день.') WHERE id = 'f7c92a09-eddb-4b29-936d-0133e3378e1e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Иммунная система вашего малыша не может полностью развиться до рождения прежде всего потому, что он находится внутри вашего организма. Пока малыш остаётся в матке, активность его иммунной системы должна быть ограничена. Благодаря этому защитные клетки малыша и клетки вашего организма сохраняют взаимную толерантность. Иммунная система, которая начинает активно развиваться после рождения, помимо антител вырабатывает защитные белки гликопротеиновой структуры, называемые интерферонами. Интерферон — это белок, который клетки организма вырабатывают в качестве защитной реакции на вирусы. Интерфероны препятствуют размножению вирусов внутри клеток, быстро вырабатываются и обеспечивают мощную противовирусную защиту. Их производство запускается, когда клетки распознают вирус или другой чужеродный агент. Это происходит следующим образом: при атаке вируса в ДНК клетки активируется ген, отвечающий за выработку интерферона. Выделившийся интерферон предупреждает окружающие клетки, и те начинают производить белки, которые изменяют процессы белкового синтеза таким образом, чтобы вирус больше не мог размножаться внутри клеток. Так организм препятствует распространению вирусов.'), baby_message_ru = COALESCE(baby_message_ru, 'Кажется, моя головка уже внизу! ⬇️ Я принял положение для родов. Моя головка опустилась между костями вашего таза. Мне немного неудобно, но это самый короткий путь к выходу. Если я ещё не перевернулся, врач может порекомендовать вам специальные упражнения.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Возможно, вам станет немного легче дышать. Поскольку малыш опустился ниже, давление на лёгкие и желудок уменьшилось. Теперь вы можете дышать свободнее и съедать немного больше. Но при этом усиливается давление в области паха и на мочевой пузырь.;;;
Кроме того, вам может стать немного легче дышать. Поскольку малыш опустился ниже, давление на лёгкие и желудок уменьшилось. Теперь вы можете дышать свободнее и съедать немного больше. Но при этом усиливается давление в области паха и на мочевой пузырь.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня наградите себя за то, что успешно прошли этот 35-недельный путь, и отдохните. Чтобы уменьшить боль в пояснице, обязательно используйте подушки, поддерживающие спину. Если малыш опустился ниже и при ходьбе вы чувствуете боль в области таза, двигайтесь медленнее и осторожнее. Завтра начинается 36-я неделя — последний большой поворот на пути к родам!') WHERE id = '3e398e58-41a7-4c07-9c59-78972adc37be';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В кишечнике вашего малыша продолжает накапливаться меконий. Меконием называют первый стул малыша — очень вязкую массу тёмно-зелёного или чёрного цвета. Эта масса на %90 состоит из воды, а также содержит отпавшие с кожи малыша волоски лануго, клетки кишечного эпителия, слизь и желчь. Высокое содержание билирубина в меконии может способствовать развитию желтухи у новорождённого. Если малыш не выделяет меконий в течение первых 48 часов после рождения, показатели билирубина могут быть выше нормы. Билирубин — это жёлтое вещество, которое образуется при естественном распаде эритроцитов. Оно перерабатывается в печени и выводится из организма через пищеварительную систему. До рождения меконий обычно не выводится из кишечника малыша, поэтому билирубин накапливается в его составе в толстой кишке. Если после рождения меконий долго не покидает организм, билирубин может повторно всасываться из кишечника в кровь. Значительное повышение его уровня в крови приводит к желтухе.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне снятся очень яркие сны! Anacan, я провожу много времени в фазе быстрого сна. Мой мозг так активен! А когда я бодрствую, то осматриваюсь вокруг, хотя здесь и темно. Я прекрасно различаю свет и тень. Пусть вы меня пока не видите, но я вас чувствую.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан салата'), body_changes_ru = COALESCE(body_changes_ru, 'Бессонница может сделать вас раздражительной. Вам трудно удобно устроиться, всё тело болит. Мысли «Как пройдут роды?» не выходят из головы. Так природа готовит вас к ночным пробуждениям, когда нужно будет ухаживать за малышом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Начиная с этой недели рекомендуется посещать врача каждую неделю. В последний раз проверьте сумку в роддом и добавьте недостающие мелочи. Чтобы уменьшить боль в области таза, не скрещивайте ноги, когда сидите, и не оставайтесь слишком долго в одном положении. Продолжайте отдыхать лёжа на левом боку и в течение дня следите за движениями малыша.') WHERE id = 'df4bd1af-d6a3-4228-b3e2-3e6d8392ce93';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'У вашего малыша продолжается выработка тестостерона. Причём этот процесс происходит как у мальчиков, так и у девочек. Тестостерон — это стероидный гормон из группы андрогенов, то есть гормон, содержащий в своей структуре жиры. У мальчиков тестостерон в основном вырабатывается в яичках и надпочечниках — железах, расположенных над почками. У девочек за выработку тестостерона отвечают яичники. У малышей обоих полов секреция этого гормона регулируется гипоталамусом — отделом головного мозга.;;;
Хотя тестостерон вырабатывается и у девочек, его количество значительно меньше, чем у мальчиков. Уровень тестостерона начинает заметно повышаться в подростковом возрасте, достигает максимума примерно к 20 годам, а после 30 лет постепенно снижается. Во время внутриутробного развития тестостерон играет важную роль в формировании половых органов малыша. Для развития пениса и яичек у мальчиков необходимо достаточное количество этого гормона. У мужчин тестостерон отвечает за понижение тембра голоса, рост волос, развитие и функционирование половых органов. У девочек он участвует в активации рецепторов эстрогена, стимулирует окостенение хрящевой ткани и задействован в механизме действия гормона ЛГ, который особенно важен для запуска овуляции ещё во время внутриутробного развития.'), baby_message_ru = COALESCE(baby_message_ru, 'Я готов на 99%! ✅ Если я появлюсь на свет сегодня, то с очень большой вероятностью выживу без каких-либо серьёзных проблем — возможно, мне лишь ненадолго понадобится специальный уход. Мои лёгкие почти готовы. Но каждый дополнительный день в мамином животике помогает мне набрать вес и стать сильнее. Не будем торопиться!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан салата'), body_changes_ru = COALESCE(body_changes_ru, 'Начиная с этой недели врач может рекомендовать вам проходить КТГ каждую неделю. На результат КТГ могут влиять такие факторы, как сон малыша во время исследования и срок беременности. Поэтому при отсутствии риска преждевременных родов КТГ обычно не проводят до 28-й недели беременности. Чтобы получить наиболее информативный результат, рекомендуется начинать исследование через 2 часа после еды. Во время процедуры на животе закрепляют два датчика. Один отслеживает сокращения матки, а другой — сердцебиение и движения малыша.;;;
КТГ — один из методов оценки состояния малыша в матке, особенно на поздних сроках беременности. С помощью КТГ наблюдают за состоянием малыша при диабете, хронических заболеваниях почек, повышенном артериальном давлении, возникшем во время беременности, снижении двигательной активности малыша, задержке его развития, уменьшении количества околоплодных вод, а также если срок беременности превысил 40 недель.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в пояснице и тазу, во время сидения обязательно используйте подушки, поддерживающие спину. Если ноги сильно отекают, вечером на 15-20 минут поднимайте их вверх, опирая на стену. Продолжайте пить достаточно воды: это важно как для работы ваших почек, так и для обновления околоплодных вод. Сегодня не перенапрягайтесь и сведите физическую активность к минимуму.') WHERE id = 'ded751f7-f2a6-42dd-a319-bc879f101abf';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Извилины головного мозга вашего малыша уже почти приобрели тот вид, который будет у них при рождении. Размер головного мозга без извилин в среднем составляет  см. Чтобы мозг сохранял пропорции по отношению к телу, на нём должны формироваться извилины. Проще говоря, мозговые извилины — это особенность строения, позволяющая увеличить площадь поверхности головного мозга.'), baby_message_ru = COALESCE(baby_message_ru, 'Я реагирую на ваш голос! 🎤 Когда вы говорите, я начинаю двигаться. Когда вы смеётесь, я подпрыгиваю. А папин голос звучит для меня как сказка. Продолжайте разговаривать со мной — я слушаю.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан салата'), body_changes_ru = COALESCE(body_changes_ru, 'Боль в области соединения лобковых костей (симфизит) может затруднять ходьбу. Даже поворот с одного бока на другой в постели может превратиться в настоящее мучение. Это связано с подготовкой таза к родам.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Убедитесь, что ваша сумка в роддом уже полностью собрана, а документы находятся под рукой. Сегодня немного отдохните и поговорите с малышом — он уже очень хорошо узнаёт ваш голос, наполненный любовью.') WHERE id = '0307b519-8b14-459a-84c3-9d370f50a4be';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Нервная система вашего малыша почти завершила своё развитие. На этом этапе она включает две части: вегетативную и периферическую нервную систему. Вегетативная нервная система отвечает за непроизвольные процессы и управление работой внутренних органов. Она независимо от воли регулирует частоту сердечных сокращений, переваривание пищи, дыхательные движения, обеспечивающие обмен кислорода и углекислого газа, слюноотделение, потоотделение и мочеиспускание.'), baby_message_ru = COALESCE(baby_message_ru, 'На моих ручках уже появился слой жирка! 💪 Мои ручки и ножки больше не похожи на палочки — теперь на них настоящие милые складочки. На локтях и коленях появляются очаровательные ямочки. Моя кожа гладкая. Я создан для объятий.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан салата'), body_changes_ru = COALESCE(body_changes_ru, 'Пришло время сдать анализ на стрептококк группы B (GBS). Этот тест проводят между 35-й и 37-й неделями, чтобы определить наличие бактерий стрептококка группы B. Врач возьмёт мазок из влагалища и проверит, присутствуют ли эти бактерии. Для вас они обычно неопасны, но во время родов могут передаться малышу. Если результат окажется положительным, во время родов вам введут антибиотик. Если вы планируете естественные роды, обязательно пройдите это обследование.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Переворачиваясь в постели, держите колени вместе, как русалка. Это поможет уменьшить боль и напряжение в области тазовых костей.') WHERE id = 'f9ddf067-2beb-491f-a9d9-5cef8bbb118b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Быстрый набор веса вашего малыша связан с образованием жировых клеток в его организме. Этот жир очень важен для поддержания температуры тела малыша после рождения. Почки уже полностью развиты и вырабатывают более 1 литра мочи в сутки. На этой неделе количество околоплодных вод начинает уменьшаться. Это нормально, поскольку малыш сильно вырос, и пока их количество не снижается до опасного уровня, причин для беспокойства нет.;;;
В дальнейшем ваш малыш продолжит набирать вес, но его рост несколько замедлится. При рождении рост малышей обычно составляет 48-52 см.'), baby_message_ru = COALESCE(baby_message_ru, '35 НЕДЕЛЬ ПОЗАДИ! 👋 Здравствуй, 9-й месяц! (По календарю). Мы уже совсем близко к финишу. Мне здесь очень тесно, но я продолжаю двигаться. Если моих движений станет меньше, обязательно скажите врачу. Я затихаю не потому, что скучаю, а когда сплю.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан салата'), body_changes_ru = COALESCE(body_changes_ru, 'Риск преждевременных родов снижается. Если роды начнутся сейчас, 99% малышей выживут и не столкнутся с серьёзными долгосрочными проблемами. Однако такие роды всё ещё считаются преждевременными. Схватки Брэкстона — Хикса могут стать более регулярными — научитесь отличать их от настоящих схваток.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не пропускайте еженедельные осмотры у врача. В последние недели ситуация может быстро меняться. Запишите все возникающие у вас вопросы и задайте их врачу.') WHERE id = '7800e1ad-f092-45f7-8448-b5a2384087fa';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'С завершением 36-й недели для вашего малыша начинается новый этап. Это последняя неделя, когда в случае родов малыш будет считаться недоношенным.;;;
Преждевременные роды могут произойти из-за высокого артериального давления, преэклампсии, различных инфекций, истмико-цервикальной недостаточности, нарушений свёртывания крови, курения и употребления алкоголя, недостаточного наблюдения за беременностью и низкого социально-экономического уровня. Малыши, родившиеся до завершения 37 недель беременности, считаются недоношенными. Если роды произойдут на этой неделе, ваш малыш, вероятнее всего, сможет жить без осложнений после непродолжительной дыхательной поддержки. На сроке от 36+0 до 36+6 недель, то есть в течение 37-й недели беременности, малыш уже завершил большую часть своего развития и готов родиться в любой момент.;;;
Тем не менее при родах до 38-й недели, когда лёгкие завершают выработку сурфактанта, а кишечник становится полностью функциональным, могут возникнуть некоторые проблемы. Некоторые специалисты связывают колики у малышей с тем, что роды происходят до полного созревания кишечника.'), baby_message_ru = COALESCE(baby_message_ru, 'Я становлюсь пухленьким! 🧸 Anacan, мои щёчки, ручки и ножки покрываются жирком. Теперь я уже не такой сморщенный. Мой вес увеличивается каждый день. Этот жировой слой поможет мне сохранять тепло и энергию после рождения. Когда вы возьмёте меня на руки, я буду мягким и пухленьким.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан салата'), body_changes_ru = COALESCE(body_changes_ru, 'Не забывайте, что во время беременности важно есть фрукты — они полезны и вам, и вашему малышу. Один из таких фруктов — банан, богатый кальцием, калием, витамином C, фолиевой кислотой и витамином B6. Банан помогает восполнять потребность в железе, которая особенно важна во время беременности. Кроме того, он богат фолиевой кислотой. Фолиевая кислота крайне важна для развития позвоночника и нервной системы малыша. Банан также содержит кальций, необходимый для формирования костной ткани малыша. Поэтому его рекомендуется включать в рацион для здорового развития костей. Банан является хорошим источником витамина B6. Витамин B6 участвует в работе нейромедиаторов нервной системы, а также в образовании красных кровяных клеток. Богатый витамином C банан обладает антиоксидантными свойствами. Благодаря этому он помогает замедлить старение клеток и укрепляет иммунную систему. Банан содержит полезную для кишечника клетчатку. Однако с учётом замедления пищеварения его чрезмерное употребление может вызвать запор. Поэтому будет достаточно добавить в свой рацион 2 небольших банана в день.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить одышку, во время сидения обязательно держите спину прямо. Чтобы снизить тяжесть и отёчность в ногах, регулярно отдыхайте, приподняв их. В эти дни понемногу проверяйте содержимое сумки в роддом и убедитесь, что всё готово. Старайтесь есть на ужин лёгкую пищу небольшими порциями, чтобы изжога не мешала вам спать.') WHERE id = 'e948b641-0b79-4f83-9869-a66d090c81f1';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ствол мозга вашего малыша уже занял своё место и начал управлять такими процессами, как сон, бодрствование и даже сновидения. Эта небольшая область, расположенная в нижней части головного мозга, чрезвычайно важна, поскольку через неё проходят все нервные связи между мозгом и телом. Ствол мозга регулирует такие жизненно важные функции, как дыхание, глотание и сердцебиение. Кроме того, в этот период формируется циркадный ритм малыша — его биологические часы. Этот ритм автоматически регулирует работу организма в течение 24 часов. Например, благодаря биологическим часам ночью вырабатывается вызывающий сон гормон мелатонин, а утром повышается артериальное давление.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой кочан салата'), body_changes_ru = COALESCE(body_changes_ru, 'Проблемы с кожей возникают из-за гормональных изменений во время беременности. Вскоре после родов состояние кожи начнёт улучшаться, в том числе постепенно исчезнут изменения пигментации. Изменение цвета кожи чаще всего наблюдается на щеках, над верхней губой, на носу, подбородке и лбу. Оно проявляется в виде светло- или тёмно-коричневых пятен. Эти пятна, называемые «маской беременности», обычно исчезают после родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня постарайтесь уделить больше времени отдыху. Чтобы уменьшить боль в области таза, обязательно используйте подушки, поддерживающие спину. Если вы ещё этого не сделали, убедитесь, что все документы для роддома собраны. Завтра начинается 37-я неделя — «период готовности», когда роды могут начаться в любой момент!') WHERE id = 'e930fbe3-29bc-4413-bfef-dc68f6603a0e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Печень вашего малыша уже начала очищать организм от некоторых продуктов обмена и участвовать в пищеварении. Этот жизненно важный орган выполняет в организме малыша роль своеобразной «лаборатории»:;;;
• Очищение: печень преобразует токсичный аммиак в менее вредные вещества, а также расщепляет старые клетки крови и выводит их из организма.;;;
• Энергия и пищеварение: перерабатывает полученные из пищи вещества и распределяет их между другими органами. Вырабатывает желчь, необходимую для переваривания жиров и белков.;;;
• Защитная система: вырабатывает антитела, укрепляющие иммунитет, и регулирует температуру тела.;;;
• Важные белки: отвечает за выработку альбумина — белка, который помогает удерживать жидкость в кровеносных сосудах.;;;
Одним словом, печень малыша не только очищает его организм, но и готовит его к защите от болезней.'), baby_message_ru = COALESCE(baby_message_ru, 'Я ем свои волосики! 😮 (Знаю, это звучит немного странно). Тонкие волоски «Лануго», покрывающие моё тело, и слой «Верникса» постепенно отделяются. Я проглатываю их вместе с амниотической жидкостью. Они накапливаются в моём кишечнике и образуют мой первый стул (Меконий). Вы увидите его, когда будете менять мой первый подгузник!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мангольд'), body_changes_ru = COALESCE(body_changes_ru, 'Недостаток веществ, которые не всегда удаётся получить в достаточном количестве с пищей, во время беременности стараются восполнить с помощью добавок, рекомендованных врачом. К ним относятся фолиевая кислота, железо, кальций, магний, цинк, витамин D и омега-жирные кислоты. Начиная со второго триместра беременности почти всем будущим мамам назначают железо. Оно крайне важно для кроветворения у вас и малыша и помогает предотвратить риск анемии. Кроме того, дефицит железа повышает риск рождения малыша с массой тела ниже средней. Наряду с этим могут быть назначены и комплексные витаминные препараты. Несмотря на их пользу, не принимайте такие добавки без рекомендации врача.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Малыш уже полностью доношен, поэтому внимательно следите за признаками начала родов. Чтобы уменьшить боль в области таза, регулярно выполняйте лёгкие упражнения на растяжку и не поднимайте тяжёлые предметы. Поставьте сумку для роддома у двери и ещё раз согласуйте всё с врачом. Сегодня не перенапрягайтесь и берегите силы для важного дня.') WHERE id = 'cc423b6f-434a-47b7-97ce-c5b407e5861b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Все функции организма вашего малыша уже полностью сформированы, включая работу органов чувств. Особенно хорошо развилась область мозга, управляющая восприятием ощущений, поэтому малыш стал настолько чувствительным, что уже способен реагировать на ваш голос. Мозг малыша состоит из двух полушарий — левого и правого. Они соединены сложной сетью нервных волокон, благодаря которой постоянно взаимодействуют друг с другом. Основная задача мозга — регулировать работу внутренних органов, поддерживать здоровье организма и обеспечивать жизнедеятельность. Одновременно он обрабатывает и интерпретирует все сигналы, поступающие из окружающей среды через органы чувств, а важную информацию сохраняет в памяти. Благодаря слуху малыш уже начал очень активно использовать правое полушарие мозга. Именно развитые мозг и нервная система позволяют ему отличать ваш голос от других окружающих звуков.'), baby_message_ru = COALESCE(baby_message_ru, 'Я опускаюсь ниже! 📉 Чувствуете? Моя головка уже полностью вошла в полость вашего таза. Мне здесь немного тесно, зато это самое близкое место к выходу. Вам, вероятно, стало легче дышать, но теперь приходится чаще бегать в туалет.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мангольд'), body_changes_ru = COALESCE(body_changes_ru, 'Сбалансированное и регулярное питание во время беременности чрезвычайно важно для здорового развития малыша. Одними из самых полезных продуктов, поддерживающих его развитие, являются необжаренные орехи и сухофрукты. Они богаты ненасыщенными жирными кислотами, селеном, различными витаминами и минералами. Грецкие орехи активно способствуют развитию мозга малыша. Они обладают антиоксидантными свойствами, а также служат хорошим источником клетчатки и белка. Фисташки помогают обеспечить организм жирными кислотами, необходимыми во время беременности. Фундук благодаря содержащемуся в нём кальцию значительно поддерживает развитие костей малыша. Кроме того, он является хорошим источником энергии. Миндаль богат витаминами и минералами, а высокое содержание цинка способствует хорошему качеству грудного молока после родов. Кешью благодаря содержащейся в нём меди помогает восполнить суточную потребность организма в этом минерале. Сушёный инжир богат цинком, железом, калием и кальцием. Употребляя его, вы можете получать минералы, необходимые малышу в период развития. Орехи очень полезны, но как масличные культуры обладают высокой питательной ценностью. Поэтому рекомендуется съедать не более одной горсти в день.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку роды могут начаться в любой момент, берегите силы. Чтобы уменьшить отёчность ног, сократите потребление соли и пейте достаточно воды. Если схватки Брэкстона — Хикса нерегулярны, это лишь тренировка вашего организма, поэтому не беспокойтесь. Сегодня уделите немного времени себе: загляните в подготовленную для малыша комнату или переберите его одежду — это поможет вам успокоиться.') WHERE id = 'cd1a59da-8207-4de3-b297-f013b1d7c429';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя скелет вашего малыша сейчас в основном состоит из хрящевой ткани, процесс окостенения продолжается быстрыми темпами. В этот период малыш усваивает почти весь кальций, который поступает в ваш организм. Если в вашем рационе недостаточно кальция, он восполняет свою потребность за счёт запасов кальция в ваших костях.;;;
У хрящевой ткани есть интересная особенность: в ней отсутствуют кровеносные сосуды и нервы. Хрящевые клетки малыша получают необходимый кислород и питательные вещества из окружающих тканей путём диффузии и таким же образом выводят продукты обмена. Ткань, образующая скелет малыша, называется волокнистым хрящом. Она очень устойчива к давлению и движению, поскольку содержит большое количество коллагеновых волокон. Коллагеновые волокна имеют белковую основу и обеспечивают эластичность и прочность тканей.'), baby_message_ru = COALESCE(baby_message_ru, 'Вы меня ждёте? ⏳ Я знаю, что вам уже не терпится. Вы спрашиваете: «Когда же ты появишься?» Но я пока не совсем готов. Мой мозг всё ещё развивается, а лёгкие завершают последние приготовления. Каждый дополнительный день в мамином животике делает меня сильнее. Потерпите ещё немного, Anacan.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мангольд'), body_changes_ru = COALESCE(body_changes_ru, 'Хотя точная причина, запускающая роды, неизвестна, установлено, что во время родов значительно повышается уровень простагландинов, вырабатываемых маткой на поздних сроках беременности. Эти гормоноподобные вещества, образованные из жирных кислот, повышают чувствительность болевых рецепторов к механическим и химическим раздражителям. Вне беременности они способствуют появлению боли во время менструации, а при родах вызывают сокращения мышц матки.;;;
Кроме того, в последние дни беременности кишечник может опорожняться чаще. Это способно вызывать боль в области живота. Диарея перед родами считается одним из способов подготовки организма: она помогает очистить кишечник, чтобы мышцы матки могли работать свободнее.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы справиться с бессонницей в этот период, старайтесь дремать днём по 15-20 минут. Регулярно держите ноги в приподнятом положении, чтобы уменьшить отёки. Если вы ещё этого не сделали, установите в машине и проверьте автокресло, в котором повезёте малыша домой из роддома. Сегодня не перенапрягайтесь и двигайтесь спокойно и осторожно.') WHERE id = 'ff965161-e8f2-4262-b993-4dbf99f22a66';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Рефлексы вашего малыша с каждым днём становятся всё сильнее. Хотя он ещё не умеет говорить, с помощью этих непроизвольных движений он познаёт окружающий мир, защищает себя и общается с вами. Благодаря ориентировочному рефлексу малыш чувствителен к свету: заметив его, он поворачивает голову в ту сторону и пытается исследовать окружающее пространство. Поисковый и сосательный рефлексы, одни из самых важных, обеспечивают питание малыша: если прикоснуться к уголку его рта, он сразу повернёт голову в эту сторону и начнёт искать грудь. Примерно через 3-4 месяца эти движения становятся осознанными. Рефлекс моргания — это защитный механизм малыша: при ярком и интенсивном свете он моргает, оберегая себя от дискомфорта. Все эти рефлексы являются важными показателями здорового развития малыша и правильной работы его нервной системы.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои движения меняются! 🛑 Поскольку места у меня совсем мало, я уже не могу резко толкаться. Вместо этого вы чувствуете, как я «скольжу» и «поворачиваюсь». Хотя характер движений меняется, их частота не должна уменьшаться. Я должен быть активным каждый день.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мангольд'), body_changes_ru = COALESCE(body_changes_ru, 'Существуют определённые признаки, указывающие на то, что ваше тело готовится к приближающимся родам. Изменения в организме перед родами могут появиться как за несколько часов, так и за месяц до их начала. Один из таких признаков, особенно характерный для последнего месяца, в быту называют «опущением живота». Если это ваша первая беременность, обычно в течение последнего месяца перед началом родов малыш начинает опускаться к тазу. Когда малыш занимает положение в родовых путях, может возникнуть ощущение давления во влагалище и прямой кишке. Это связано с тем, что малыш давит на кости таза.;;;
С приближением родов почти половина женщин замечает, что набор веса прекращается или масса тела даже уменьшается на 1-2 килограмма. Точная причина этого неизвестна, но такое изменение может быть связано с более активной работой кишечника и замедлением набора веса малышом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В этот период бессонница считается нормальным явлением, поэтому короткие перерывы на сон в течение дня помогут вам восстановить силы. Сегодня вечером уделите немного времени себе и поговорите с малышом — он уже очень хорошо узнаёт ваш наполненный любовью голос.') WHERE id = '152b266a-9f3e-44b6-ad2a-c45afaa30675';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поздравляем! Позади 8 месяцев беременности, и вы вступаете в последний месяц — теперь ваш малыш готов появиться на свет в любой момент. В этот период его печень и почки работают в полную силу, а кровообращение и иммунная система функционируют должным образом. Он постоянно тренируется, чтобы самостоятельно дышать и адаптироваться к жизни после рождения. Всё тело малыша покрыто белым жироподобным слоем, который называется «первородной смазкой». Этот особый слой служит естественным щитом, защищающим новорождённого малыша, чья иммунная система ещё не сформировалась полностью, от микроорганизмов. Кроме того, первородная смазка помогает адаптироваться к разнице температур между материнской утробой и внешней средой и предотвращает температурный стресс. Одним словом, благодаря этому естественному защитному крему малыш готовится к появлению на свет, оставаясь защищённым от неблагоприятных воздействий внешней среды.'), baby_message_ru = COALESCE(baby_message_ru, 'Неужели я учусь плакать? 😢 Некоторые учёные считают, что в материнской утробе я беззвучно выполняю движения, похожие на плач: у меня дрожит подбородок и меняется дыхание. Это важно, чтобы после рождения я мог подавать вам сигналы. Плач станет моим единственным способом общения.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мангольд'), body_changes_ru = COALESCE(body_changes_ru, 'Ваша кожа может стать очень чувствительной. Кожа на животе растянута настолько сильно, что начинает блестеть. Если вас беспокоит зуд, приложите холодный компресс. Достаточное употребление жидкости помогает увлажнять кожу изнутри.;;;
Отёки на руках и ногах могут сохраняться даже по утрам. Не носите кольца. Кроме того, онемение рук по ночам может нарушать ваш сон. Очень важно контролировать артериальное давление.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в области таза, во время сна обязательно кладите подушку между коленями и лежите на левом боку. Продолжайте пить достаточно воды для уменьшения отёков, поскольку вода помогает выводить лишнюю жидкость из организма. В эти дни ещё раз ознакомьтесь с информацией о первых признаках родов. Постарайтесь сохранять спокойствие и душевное равновесие — важный день уже совсем близко!') WHERE id = '225c7f32-cf83-462a-bfe6-21c45812a3e6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш продолжает быстро набирать вес, ежедневно накапливая примерно 15-20 граммов жира. Хотя жировые клетки имеют небольшой вес, они занимают много места и являются богатейшим источником энергии для малыша. Накопленный в организме жир не только даёт энергию, но и играет важную роль в формировании защитных мембран других клеток, поступлении витаминов A, D, E и K в кровь и выработке гормонов, необходимых для роста. Однако важнейшая задача жировой ткани — создание под кожей защитного слоя, который оберегает малыша от холода и перепадов температуры. Кроме того, жир, окружающий внутренние органы, обеспечивает запас энергии, которая может понадобиться малышу в любой момент.'), baby_message_ru = COALESCE(baby_message_ru, 'Я накапливаю антитела! 🛡️ Уровень иммунных клеток, поступающих ко мне из вашей крови, сейчас максимален. Когда я появлюсь на свет, я не буду полностью беззащитен перед окружающими микроорганизмами. Иммунитет, который вы приобрели после перенесённых инфекций, передаётся мне, словно защитный щит.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зимняя дыня'), body_changes_ru = COALESCE(body_changes_ru, 'На поздних сроках беременности шейка матки истончается и начинает раскрываться, из-за чего организм выводит слизистую пробку, которая закрывала вход в шейку матки. Отхождение слизистой пробки в быту называют «предвестником родов»: оно указывает на то, что до начала настоящих родовых схваток осталось немного времени. Пробка может быть ярко-красной, розовой, коричневой или желтоватой. На её цвет влияют различные факторы.;;;
Слизистая пробка может отойти как за несколько часов, так и за неделю до родов. Её отхождение не означает, что вам нужно немедленно ехать в больницу. Однако важно сообщить об этом врачу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Ухаживайте за кожей. Массаж с натуральными маслами (миндальным, какао) помогает уменьшить чувство натяжения. Не носите синтетическую одежду — лучше всего выбирать хлопок.') WHERE id = '58a80f20-6823-4c80-8b83-b7ba46702490';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе вес вашего малыша в среднем составляет 2400–2800 граммов, а рост — 46–52 см; дёсны становятся плотнее, а кожа — всё более гладкой и мягкой. На этом этапе хватательный рефлекс малыша уже хорошо развит, что является одним из главных признаков правильной работы его нервной системы. Хватательный рефлекс особенно выражен в кистях и стопах и представляет собой непроизвольную реакцию на раздражители. Этот рефлекс формируется ещё до рождения и остаётся активным в течение первых двух месяцев жизни, после чего постепенно ослабевает, уступая место осознанному захватыванию. Интересно, что хватательный рефлекс стоп сохраняется дольше, чем рефлекс кистей, а его переход в произвольное движение может продолжаться до 6-го месяца.'), baby_message_ru = COALESCE(baby_message_ru, '37 НЕДЕЛЬ! 🎉 Поздравляю, Anacan! Сегодня важный день. Я уже не считаюсь недоношенным малышом! Официально я нахожусь на раннем доношенном сроке. Это значит, что, если я рожусь сейчас, меня будут считать доношенным малышом. Я вешу почти 3 кг. Теперь я могу появиться в любой момент! Ваша сумка готова?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зимняя дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Важный рубеж: ранний доношенный срок! Теперь роды могут начаться в любой момент, а ваш малыш будет считаться доношенным. Врач может проверить состояние шейки матки — её раскрытие и размягчение. Готовясь к родам, шейка матки смещается вперёд и становится мягче.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Гордитесь собой — вы успешно прошли этот удивительный путь длиной в 37 недель! Сегодня постарайтесь как можно больше отдыхать, чтобы сохранить силы. Поставьте сумку для роддома у двери и убедитесь, что все документы собраны. Если у вас появятся регулярные боли в животе, интенсивность которых нарастает, или отойдут воды, немедленно свяжитесь с врачом. Наберитесь терпения — до чуда осталось совсем немного!') WHERE id = 'cca07f51-052d-4eba-bb6f-e780658e5cc2';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе вес вашего малыша в среднем составляет 2500–2900 граммов, а рост — 48–52 см. Поскольку в лёгких завершилась выработка особого вещества — сурфактанта, обеспечивающего дыхание, после рождения малыш уже сможет дышать самостоятельно, без посторонней помощи.;;;
Поскольку малыш растёт и места в матке становится всё меньше, его движения могут быть немного реже, чем в предыдущие недели, однако ощущаются они сильнее. Начиная с 37-й недели это считается нормальным, но, если вы долго не ощущаете движений малыша, лучше проконсультироваться с врачом. По мере роста малыша количество околоплодных вод также немного уменьшается. Обычно это нормально, но, если их объём снизится до уровня, представляющего риск для малыша, врач может госпитализировать вас для наблюдения.'), baby_message_ru = COALESCE(baby_message_ru, 'Я тренируюсь! 🏋️‍♂️ Роды потребуют усилий не только от вас, но и от меня. Чтобы пройти через узкий родовой канал, мне придётся сжимать тело, поворачивать голову и отталкиваться. Сейчас я тренирую эти движения. Мы будем работать как одна команда, Anacan. Вы откроете мне путь, а я появлюсь на свет.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зимняя дыня'), body_changes_ru = COALESCE(body_changes_ru, 'Пилатес, которым вы занимались во время беременности, поможет подготовиться к родам и сделает этот процесс более комфортным. По мере роста матки центр тяжести вашего тела постоянно смещается. Пилатес помогает скорректировать нарушения осанки, вызванные этими изменениями, и поддерживать правильное положение тела. Благодаря этому также уменьшаются боли в спине и пояснице.;;;
При этом упражнения пилатеса должны быть адаптированы для беременных и обязательно выполняться под руководством специалиста в этой области. Помните, что неправильные упражнения, выполняемые без профессионального контроля, могут навредить и вам, и малышу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку роды могут начаться в любой момент, старайтесь больше отдыхать и беречь силы. Выходя из дома, убедитесь, что телефон полностью заряжен, а сумка для роддома находится в машине. Если отойдёт слизистая пробка или околоплодные воды, немедленно сообщите об этом врачу.') WHERE id = '9bb1bfbd-4fc9-4fdd-8462-715ca0719a8a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе ваш малыш, возможно, уже занял наиболее подходящее для вагинальных родов положение — опустился головкой вниз в родовой канал. Особенно если это ваша первая беременность, вы можете заметить это по ощущению тяжести в области таза и затруднениям при ходьбе. Опущение малыша приносит и некоторое облегчение: давление на грудную клетку и желудок уменьшается, поэтому вам становится легче дышать, а изжога беспокоит реже.;;;
Интересно, что при первой беременности малыши обычно занимают это положение примерно за месяц до родов, а при последующих беременностях это может произойти всего за несколько часов до их начала. Кроме того, на этой неделе нежные волоски лануго, покрывавшие тело малыша, уже полностью выпали. Это означает, что благодаря собственным жировым клеткам малыш достаточно развит, чтобы самостоятельно поддерживать температуру тела, и полностью готов появиться на свет.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с тыкву. Я уже большой малыш. Здесь так тесно, что вместо ударов ножками я могу только потягиваться. Вы даже можете увидеть очертания моей пяточки на животе. Прикоснитесь ко мне!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Тыква'), body_changes_ru = COALESCE(body_changes_ru, 'Сна почти не осталось. Просыпаться каждый час ночью, ходить в туалет, не находить удобного положения... Так ваше тело готовит вас к ночным пробуждениям малыша. Старайтесь спать днём. Берегите силы — они понадобятся вам во время родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Медитация или аудиозаписи для "Гипнородов" (Hypnobirthing) перед сном помогут вам успокоиться и заснуть. Страх вызывает напряжение, а спокойствие облегчает роды.') WHERE id = '01bba5ce-c513-4ffc-af67-bbc602f0ece1';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Скелет вашего малыша ещё не полностью окостенел и остаётся достаточно мягким и эластичным. Благодаря этой эластичности во время прохождения через родовые пути тело малыша может легко сгибаться, что способствует рождению без осложнений. В то же время покрывающий кожу малыша плотный слой первородной смазки — "vernix caseosa" — уже полностью сформировался. Он защищает кожу от воздействия амниотической жидкости и предотвращает её сморщивание.;;;
Тело вашего малыша почти полностью покрыто практически незаметными волосками и кожным салом — "себумом", которое вырабатывается железами у основания этих волосков. Содержащийся в себуме белок кератин образует на коже водонепроницаемый слой, благодаря которому она остаётся мягкой и не сморщивается, несмотря на длительное пребывание в жидкости. Однако на кончиках пальцев, ладонях и подошвах нет волосков и плотного кератинового слоя, поэтому эти участки пропускают воду. Именно поэтому после рождения на них можно заметить сморщивание кожи.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня нет слёз! 💧 Когда я появлюсь на свет, то буду громко плакать ("Уа-а!"), но слёзы из глаз течь не будут. Мои слёзные каналы ещё не полностью открылись. Настоящие слёзы появятся через несколько недель после рождения. А мои голосовые связки? Они уже полностью работают, и ты услышишь мой голос!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Тыква'), body_changes_ru = COALESCE(body_changes_ru, 'В последние недели беременности из-за вновь появившихся тошноты, рвоты и снижения аппетита вы также можете столкнуться с изжогой. Поскольку желудок находится под давлением матки, облегчить это состояние помогут частые приёмы пищи небольшими порциями и отказ от употребления жидкости во время еды. Кроме того, не следует ложиться или спать сразу после еды и надолго оставаться без движения. Чтобы улучшить пищеварение, можно совершать короткие прогулки в медленном темпе. Избыточная прибавка веса, особенно на поздних сроках беременности, также может усиливать изжогу. Поэтому старайтесь не употреблять слишком много калорий за один приём пищи.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не пугайтесь, когда отойдёт слизистая пробка. Это нормальный процесс. Однако если кровотечение обильное, как при менструации, и кровь ярко-красная, немедленно отправляйтесь в больницу.') WHERE id = '9cfe44a2-80b6-4626-b317-1135744027c8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Вам может казаться, что до завершения 40 недель ещё есть время, однако не забывайте, что примерно 80% беременностей заканчиваются уже к 39-й неделе. При здоровой беременности малыш полностью готов к рождению, поэтому роды могут начаться в любой момент между 37-й и 42-й неделями. Ваш малыш уже полностью созрел, и до вашей встречи осталось совсем немного.;;;
Если в первые недели вес малыша увеличивался всего на 1-2 грамма, то на поздних сроках благодаря образованию жировых клеток темп прибавки в среднем достигает половины килограмма в неделю. Столь быстрый набор веса незадолго до родов важен для того, чтобы малыш мог адаптироваться к внешнему миру и самостоятельно поддерживать температуру тела. При этом следует учитывать, что темп прибавки веса у каждого малыша может различаться в зависимости от пола, генетики и факторов окружающей среды.'), baby_message_ru = COALESCE(baby_message_ru, 'Я смотрю вниз! ⬇️ Моя голова уже надёжно зафиксировалась между костями таза. Я занял позицию для "старта". Мне немного неудобно, но это лучший угол для вхождения в родовые пути. Я готов встретиться с тобой.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Тыква'), body_changes_ru = COALESCE(body_changes_ru, 'В последние месяцы беременности уровень прогестерона и эстрогена, повышавшийся на протяжении всей беременности, значительно возрастает. Это может вызвать заложенность носа.;;;
Из-за заложенности носа могут возникнуть сухость во рту, кашель, головная боль и бессонница. Кроме того, когда дыхание через нос затруднено, слизистая оболочка носа хуже задерживает вредные микроорганизмы, поэтому организм может стать более уязвимым перед заболеваниями.;;;
Когда начнутся родовые схватки, правильное дыхание будет очень важно для облегчения боли. Головная боль, кашель и бессонница могут затруднить этот процесс, мешая вам правильно дышать. Поэтому будут полезны регулярные дыхательные упражнения, короткие прогулки на свежем воздухе и отдых лёжа на левом боку.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сократите употребление жидкости перед сном, чтобы реже просыпаться для похода в туалет. Позаботьтесь о том, чтобы в спальне было темно и прохладно.') WHERE id = 'f767f4b5-3cd7-4998-b9f7-8ee66f29236d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К этой неделе лимфатическая система вашего малыша уже достаточно хорошо развита. Она состоит из лимфатических сосудов и лимфатических узлов. К органам лимфатической системы относятся лимфатические узлы, миндалины, лимфоидные узелки слизистых оболочек и селезёнка. Основная задача лимфатической системы — обеспечивать циркуляцию лимфы по всему организму. Лимфа — чрезвычайно важная жидкость, содержащая большое количество белых кровяных клеток (лейкоцитов), которые помогают бороться с инфекциями во всём организме.'), baby_message_ru = COALESCE(baby_message_ru, 'Я как маленький арбуз! Здесь так тесно, что мне приходится прокладывать себе путь локтями. Иногда я причиняю тебе боль, я знаю, но мне здесь тоже очень тесно!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маленький арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'На этом этапе беременности ваш аппетит мог заметно усилиться. Поэтому на поздних сроках важно следить за быстрой прибавкой веса и удерживать её в определённых пределах. В последние недели беременности нормальной считается еженедельная прибавка веса в пределах 250-500 граммов. Если вы продолжаете питаться сбалансированно и регулярно, прибавка веса также будет соответствовать норме. Кроме того, на увеличение вашего веса могут влиять развитие малыша и его размеры, превышающие средние показатели. Не весь вес, набранный во время беременности, отражает ваш фактический вес. Примерно 3000-3500 граммов приходится на малыша, 800 граммов — на плаценту, 700 граммов — на околоплодные воды, 800 граммов — на увеличившуюся матку, а около 5000 граммов составляют накопленные в организме жир и отёчная жидкость.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку в этот период роды могут начаться в любой момент, расходуйте силы бережно. Если вы почувствуете боль, которая распространяется от поясницы к животу и постепенно усиливается, начните засекать время. Чтобы уменьшить отёчность ног, продолжайте пить достаточно воды и отдыхайте, приподняв ноги. Сегодня не перенапрягайтесь — занимайтесь только тем, что приносит вам спокойствие.') WHERE id = '5ba8c0c5-91c9-4151-91cf-d3f16e08e88d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В кровеносной системе вашего малыша количество кровяных пластинок, называемых тромбоцитами, и белых кровяных клеток достигло оптимального уровня. Тромбоциты активно участвуют в обеспечении свертываемости крови. В среднем они живут 10 дней, а после выполнения своей функции разрушаются в селезенке или печени и выводятся из организма. Поскольку тромбоциты обеспечивают свертывание крови, при кровопотере их количество увеличивается, чтобы сформировать эффективный сгусток. Белые кровяные клетки в кровеносной системе вашего малыша вырабатывают антитела и активно участвуют в защите организма. Эти клетки не способны делиться и самостоятельно обновляться, поэтому вырабатываются в костном мозге и лимфатических узлах малыша.;;;
При инфекциях их количество значительно возрастает, а по мере развития иммунной системы малыша достигает самого высокого уровня за всю жизнь. В зависимости от реакции иммунной системы на вредные микроорганизмы они могут жить от нескольких часов до нескольких дней. После выполнения своей функции они разрушаются в селезенке и печени малыша.'), baby_message_ru = COALESCE(baby_message_ru, 'Я икаю! 🤭 Теперь моя икота стала сильнее. Вы чувствуете, как вздрагивает весь ваш живот. Это значит, что моя диафрагма всё ещё тренируется. Я готовлюсь дышать.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маленький арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'На протяжении всей беременности качественный сон чрезвычайно важен и для вас, и для вашего малыша. Достаточный сон не только помогает вам чувствовать себя бодрее, но и облегчает процесс родов.;;;
Одним из факторов, вызывающих бессонницу, является снижение уровня сахара в крови ночью. Это состояние может привести к сильной головной боли и повышенной потливости. Тёплое молоко перед сном может помочь вам справиться с этой проблемой. Ещё одной причиной бессонницы является изжога, чаще возникающая в ночное время. Главная её причина — привычка ложиться сразу после еды. Особенно после ужина вам следует оставаться в вертикальном положении не менее 2 часов, не ложиться и не спать.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Измеряйте артериальное давление утром и вечером. Если оно выше 140/90, сообщите своему врачу. Чтобы уменьшить отёчность, полностью исключите солёные продукты.') WHERE id = 'c2434362-3321-422e-8c43-c14fba4ebb39';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе окружность головы вашего малыша составляет от 32 см до 37 см. Если окружность головы малыша находится в этом диапазоне, это указывает на здоровое развитие его головного мозга. Увеличение окружности головы имеет большое значение для развития мозга малыша. Показатели ниже нормы или выше средних значений могут свидетельствовать о нарушении развития мозга. Поэтому во время ежемесячных осмотров необходимо измерять и отслеживать окружность головы. В первые шесть месяцев её обязательно измеряют каждый месяц во время плановых осмотров. Вес и рост малыша позволяют оценить общее состояние его здоровья, а окружность головы очень важна для оценки функций головного мозга. Это связано с тем, что при нарушениях функций мозга показатели окружности головы могут отклоняться от нормы.;;;
Мозг вашего малыша развивается очень быстро: в течение первого года после рождения он увеличивается на 88%, а благодаря получаемым знаниям количество новых связей между клетками мозга непрерывно растёт.'), baby_message_ru = COALESCE(baby_message_ru, 'Врачи говорят, что нормальный срок для родов — от 38 до 42 недель. Значит, я могу появиться в любой момент. Вы уже придумали, как меня назовёте, Anacan? Я уже иду!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маленький арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Если нет проблем, требующих кесарева сечения, на этой неделе во время осмотра врач проведёт обследование вашего таза. Оно позволяет определить, подходят ли размеры и строение костей таза для естественных родов.;;;
Такое обследование проводят до начала родов, между 36-й и 38-й неделями, чтобы уточнить возможность естественных родов. Если роды будут проходить путём кесарева сечения, в обследовании таза нет необходимости. При перекрытии родовых путей плацентой, преэклампсии и многоплодной беременности, например двойней или тройней, оценка соответствия размеров таза обычно не требуется.;;;
Эта процедура проводится прежде всего для определения способа родоразрешения, положения малыша и того, опустился ли он в родовой канал, а также для выявления инфекции во влагалище и оценки степени раскрытия и размягчения шейки матки.;;;
Если врач установит, что таз узкий, он назначит дату кесарева сечения с учётом степени сужения и веса малыша. При узком тазе родовой канал может оказаться слишком тесным, из-за чего малыш не сможет пройти через него и во время родов могут возникнуть осложнения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Когда начнутся схватки, помните правило "5-1-1": если схватки возникают каждые 5 минут, длятся по 1 минуте и продолжаются в таком режиме уже 1 час, отправляйтесь в больницу.') WHERE id = '4a0b4b38-f357-4956-99dd-b078f66f4393';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Самый важный щит, защищающий здоровье вашего малыша, — его иммунная система. Она создаёт совершенную трёхуровневую линию защиты от вредных микроорганизмов:;;;
Первая линия защиты (Пограничный контроль): Это физические барьеры, которые препятствуют проникновению микробов в организм. К ним относятся кожа, слизистые оболочки носа и рта, а также особые ферменты, содержащиеся в слезах и слюне.;;;
Вторая линия защиты (Быстрая реакция): Если микробу всё же удаётся проникнуть в организм, тот немедленно вырабатывает противомикробные белки, повышает температуру или запускает воспаление, стараясь уничтожить врага.;;;
Третья линия защиты (Спецназ): Против микробов, преодолевших первые две линии, организм вырабатывает особое "оружие" — лимфоциты и антитела. На этом этапе иммунная система распознаёт врага и борется именно с этим видом возбудителя.;;;
Первые две линии защиты одинаково реагируют на все чужеродные вещества, тогда как третья использует особую стратегию против каждого вида заболевания. Благодаря этой системе организм вашего малыша готов противостоять самым разным угрозам.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне здесь тесно! 🏠 Здесь совсем мало места. Я хочу двигаться, но места нет. Вам может показаться, что я стал двигаться реже, но будьте внимательны: характер движений может измениться (вместо толчков — скольжение), однако их количество не должно уменьшаться. Каждый день у меня должны быть периоды активности.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маленький арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Вы проживаете последние дни третьего триместра беременности. Из-за усталости, накопившейся за непростые 9 месяцев, вы можете чувствовать сильную слабость.;;;
Во время беременности уровень гормонов в вашем организме значительно меняется. Чтобы обеспечить малышу оптимальные условия, ваш организм вырабатывает на 50% больше крови, сердцебиение учащается, уровень сахара в крови снижается, а обмен веществ требует больше энергии. По этим причинам, особенно на последних сроках, вы можете ощущать выраженную слабость. Кроме того, приближение родов и связанный с этим страх могут повлиять на ваше психологическое состояние. Недостаточное употребление жидкости способно ещё больше усилить слабость. Поэтому вам следует выпивать не менее 2 литров воды в день и не допускать длительного обезвоживания.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Продолжайте считать движения малыша в течение дня. Если вы не чувствуете движений, съешьте что-нибудь сладкое и лягте на левый бок. Если малыш не реагирует, немедленно обратитесь к врачу.') WHERE id = 'f9044cd4-84b9-4a00-86de-1671dcaabd83';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В начале беременности ваша матка весила около 60 граммов и была размером с теннисный мяч, а на этом этапе её вес достигает 1500 граммов, а размер — футбольного мяча. Матка — самый сильный орган женского организма. Она состоит из множества мышечных волокон, расположенных в разных направлениях. В ней выделяют три слоя, от наружного к внутреннему: серозный, мышечный и внутренний, в котором развивается ваш малыш. Толстый мышечный слой матки расслабляется и растягивается, увеличивая её внутренний объём и позволяя малышу расти. Чтобы поддерживать рост матки, работа вашего организма полностью перестраивается, и эти изменения затрагивают все органы. На этом этапе вес мощных мышц матки и всей матки в целом достигает 1500 граммов, а её объём увеличивается настолько, что она может выдерживать нагрузку более 5 килограммов. На этой неделе ваша матка весит 1500 граммов, малыш — в среднем 3500 граммов, плацента — 1000 граммов, а амниотическая жидкость — 1200 граммов. Таким образом, ваш организм несёт нагрузку в среднем более 7 килограммов.'), baby_message_ru = COALESCE(baby_message_ru, 'Моё сердце связано с тобой! ❤️ Моё кровообращение пока ещё регулируется через твою плаценту. После рождения, как только перережут пуповину, моя сердечно-сосудистая система начнёт работать самостоятельно. Некоторые отверстия в моём сердце закроются, и кровь начнёт поступать в лёгкие. Это удивительный переход.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маленький арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности растущая матка, в которой находится ваш малыш, смещает центр тяжести тела и может вызывать боль во влагалище, пояснице и нижней части живота.;;;
Кроме того, за несколько дней до родов шейка матки начинает раскрываться, что также может вызывать боль во влагалище. Боль, связанная с раскрытием, временами может быть довольно сильной и ощущаться как схватки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Практикуйте дыхательные техники, которые будете использовать во время родов. Глубокое дыхание — один из лучших способов справиться с болью во время схваток.') WHERE id = '5df96ea7-65a1-4678-8453-5c3a6e6b2deb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Темпы роста малыша немного снизились, поскольку места в матке стало совсем мало. На этом этапе малыш набирает в среднем около 15 граммов в день. Во время родов малыш проходит через шейку матки. Поэтому укрепление мышц этой области поможет облегчить роды и снизить риск возможных осложнений. Мышцы тазового дна — это группа мышц, которые окружают и поддерживают матку, влагалище, мочевой пузырь и прямую кишку — конечный отдел кишечника.;;;
Во время беременности очень важно, чтобы мышцы тазового дна были крепкими. Именно внутри этой мышечной структуры находится малыш, пока он растёт и развивается. Через неё он также проходит во время рождения.;;;
Во время родов мышцы тазового дна сильно напрягаются и совершают выталкивающие движения, помогая малышу продвигаться вниз. Каждое сокращение матки создаёт давление в среднем около 25 килограммов. Это показывает, какое усилие необходимо приложить, чтобы помочь малышу появиться на свет.'), baby_message_ru = COALESCE(baby_message_ru, 'Я всё слышу! 👂 Сейчас мой слух развит настолько хорошо, что я слышу твоё сердцебиение, звуки твоего желудка и разговоры снаружи. После рождения звуки больницы покажутся мне непривычными, поэтому, если ты возьмёшь меня на руки и заговоришь со мной, я успокоюсь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маленький арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Гормоны изменяют микрофлору влагалища, создавая условия для неконтролируемого размножения бактерий. Из-за растущего живота соблюдать личную гигиену в полной мере может быть сложнее, что также способствует возникновению этой проблемы. Бактерии, проникающие в организм через влагалище и вызывающие инфекцию, особенно быстро размножаются в местах, где отток мочи затруднён и возникает её застой. Эти инфекции довольно легко поддаются лечению, но к ним следует относиться серьёзно: без своевременного лечения они могут привести к некоторым осложнениям во время родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Попросите партнёра помассировать вам поясницу. Массаж поясницы теннисным мячом может принести значительное облегчение во время схваток.') WHERE id = '7cd91bfd-2c65-4ec8-b473-970178378a3f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя неспецифическая часть иммунной системы уже сформировалась, специфическая часть иммунитета ещё не развита, поскольку малыш пока не может самостоятельно вырабатывать антитела.;;;
Неспецифическая часть иммунной системы реагирует на любые вредные вещества, попадающие в организм, не различая их. Её формируют защитные барьеры, препятствующие проникновению возбудителей инфекций через рот, нос, глаза и кожу, а также выделяемые этими органами секреты.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Осмотр органов малого таза, проводимый врачом, может стимулировать шейку матки и спровоцировать начало родов. Поэтому такой осмотр целесообразно проводить после 36-й недели.;;;
Осмотр органов малого таза может проводиться двумя способами — вручную или с помощью инструмента, называемого гинекологическим зеркалом. Во время осмотра врач оценивает состояние костей таза. Цель обследования — определить соответствие размеров головки малыша и родового канала, через который ему предстоит пройти.;;;
При ручном осмотре вас попросят расположиться в гинекологическом кресле, после чего врач двумя пальцами проверит степень раскрытия шейки матки и оценит состояние костей таза.;;;
При осмотре с помощью гинекологического зеркала инструмент вводят во влагалище, чтобы осторожно расширить его стенки. После установки зеркала врач осматривает шейку матки, оценивает размеры таза и определяет подходящий способ родоразрешения.;;;
Если результаты осмотра покажут, что ширина таза достаточна, препятствий для естественных родов не будет. Если же выявится сужение таза, врач вместе с вами определит способ родоразрешения с учётом степени сужения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Старайтесь не оставаться дома одной. Если начнутся роды, важно, чтобы рядом был человек, который сможет помочь вам и отвезти в больницу. Сохраняйте спокойствие — до долгожданной встречи осталось совсем немного!') WHERE id = 'e4196ad3-1e48-4295-82c8-6c810ea2f084';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя все ткани, органы и системы вашего малыша уже завершили функциональное развитие, его лёгкие продолжат созревать до самого дня рождения. Начиная с 24-й недели беременности лёгкие развиты настолько, что могут функционировать при респираторной поддержке. Однако до 38-й недели беременности, когда выработка сурфактанта ещё не полностью налажена, могут возникать некоторые трудности с дыханием. В целом о полном созревании дыхательной системы можно говорить лишь к 2 годам, поскольку лёгкие продолжают развиваться до этого возраста.;;;
Первый вдох вашего малыша сразу после рождения будет самым трудным вдохом в его жизни. Прекращение поступления кислорода через плаценту и контакт кожи с кислородом активируют дыхательную систему через нервную систему. Прежде чем первый вдыхаемый воздух попадёт в альвеолы, из дыхательных путей малыша должна выйти находящаяся в лёгких жидкость. Поэтому при первом вдохе воздушные мешочки в лёгких малыша заполняются воздухом не полностью. Со вторым вдохом лёгкие начинают выполнять дыхательную функцию. С последующими вдохами лёгкие малыша расправляются, а сурфактант распределяется по поверхности альвеол. Он подготавливает поверхность альвеол к дыханию и не даёт воздушным мешочкам слипаться. Таким образом, лёгкие вашего малыша начинают полноценно функционировать.'), baby_message_ru = COALESCE(baby_message_ru, 'Спасибо тебе за терпение! 🙏 Я знаю, ты очень устала. У тебя всё болит, и ты не можешь спать. Но эти последние дни очень важны для меня. Мой мозг и нервная система завершают последние настройки. Ты подарила мне самый безопасный дом в мире. А теперь пришло время выходить.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, '🍉 Я размером с большой арбуз! Врачи говорят, что 39-я неделя — идеальное время для родов. Мой мозг, лёгкие, печень — всё полностью готово. У меня больше нет оправданий, я лишь жду, когда откроется дверь!'), daily_tip_ru = COALESCE(daily_tip_ru, 'Будьте терпеливы. Отвечать на вопросы «Когда вы родите?» может быть утомительно. Переведите телефон в беззвучный режим и сосредоточьтесь только на себе и своём малыше.') WHERE id = '37c59540-1af3-42e8-95c8-2c53b72f2a9f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе ваш малыш уже полностью занимает всё пространство матки. Поэтому уменьшение количества его движений считается вполне нормальным. Находясь в тесном пространстве, малыш старается освободить для себя как можно больше места: подтягивает скрещённые ножки к туловищу и складывает ручки на груди. Поскольку в матке почти не осталось места для движений, на этом этапе даже малейшее шевеление малыша может причинять вам боль. Готовясь к родам, малыш расположил голову в родовом канале. Если это не первая ваша беременность, он может ещё не занять необходимое для родов положение. Когда малыш принимает положение для рождения и опускается в родовой канал, давление матки на желудок и диафрагму уменьшается. Благодаря этому изжога и затруднённое дыхание значительно ослабевают. Однако давление на мочевой пузырь становится сильнее, чем когда-либо, поэтому вам может часто хотеться в туалет.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои щёчки округляются! 🐹 Теперь моё личико стало более пухлым и круглым. Мои сосательные мышцы настолько сильные, что на щёчках сформировались жировые подушечки. Они помогут мне сосать твою грудь. Когда ты меня увидишь, тебе непременно захочется потрогать эти щёчки!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'На заключительном этапе беременности из-за гормональных изменений у вас могут возникать резкие перепады настроения. А страх перед родами и другие переживания могут стать причиной подавленного состояния.;;;
В таких ситуациях вырабатываемые организмом гормоны кортизол и адреналин через кровь и плаценту попадают непосредственно к малышу. Воздействие большого количества этих гормонов в будущем может быть связано с такими трудностями, как нарушение концентрации внимания, недостаточное развитие речевых навыков, сложности с адаптацией к новому и депрессивные расстройства.;;;
Кроме того, стресс во время беременности способен вызывать не только психологические, но и физиологические последствия. Усиление бессонницы, напряжение и отсутствие молока после родов напрямую связаны с гормональными изменениями.;;;
Если вы чувствуете, что испытываете чрезмерный стресс, возможно, вам стоит обратиться за помощью к специалисту.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Бессонница в эти дни — нормальное явление, поэтому старайтесь отдыхать в течение дня при любой возможности. Обращайте внимание на такие признаки, как отхождение «пробки» (слизистой пробки) или подтекание околоплодных вод. Чтобы сохранить энергию, отдавайте предпочтение лёгкой, быстро усваиваемой пище. В последний раз убедитесь, что сумка в роддом полностью собрана и находится в доступном месте. Сохраняйте спокойствие, всё идёт по плану!') WHERE id = '89f0050d-f633-47d8-92b8-7c424334510d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш завершает последние приготовления к долгожданной встрече. На этом этапе он занимает положение головой вниз и начинает оказывать полноценное давление на таз и родовой канал. Это давление — не просто физическая нагрузка, а важный естественный стимул для начала родов.;;;
Давление головки малыша на шейку матки способствует её размягчению и постепенному раскрытию. Этот процесс также стимулирует выработку окситоцина в вашем организме, подготавливая матку к сокращениям. Малыш уже достаточно вырос, а пространства в матке стало мало, поэтому его «акробатические» движения ограничены. Но помните: хотя характер движений меняется — например, вместо сильных толчков вы чаще ощущаете скольжение или потягивание, — они обязательно должны чувствоваться регулярно. Двигательная активность малыша — самый простой показатель его благополучия и достаточного поступления кислорода. Если вы заметите внезапное уменьшение количества движений или длительное их отсутствие, важно незамедлительно проконсультироваться с врачом.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня могут отойти воды! 💧 Когда я двигаюсь или давлю головкой, амниотический пузырь может разорваться. Иногда воды отходят «потоком», а иногда лишь понемногу подтекают. Если у тебя отойдут воды, значит, до нашей встречи останутся считаные часы! Не бойся, это не больно.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Родовые схватки ощущаются в пояснице и паховой области, а вначале напоминают боли при менструации. По сравнению с ложными схватками Брэкстона — Хикса они более регулярны. Их интенсивность не уменьшается во время отдыха: схватки прогрессируют, постепенно становятся чаще, сильнее и продолжительнее.;;;
То, что в быту называют «опущением живота», указывает на то, что малыш опустился в таз. Особенно при первой беременности за несколько недель до родов женщина может почувствовать облегчение. Когда головка малыша располагается в родовом канале, вам становится легче дышать и вы ощущаете, что давление на рёбра уменьшилось.;;;
Если плодный пузырь, в котором находится малыш, вскрылся и отошли воды, необходимо связаться с врачом, не дожидаясь начала схваток. В такой ситуации малыш становится более уязвимым перед инфекциями, поэтому вам следует находиться под медицинским наблюдением.;;;
Отхождение вод — точный признак того, что роды уже начались. Не заметить это практически невозможно. Это обильное, неконтролируемое выделение жидкости, которое непрерывно или через короткие промежутки времени стекает по ногам. Обычно в течение нескольких часов начинаются и схватки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня вечером создайте для себя спокойную обстановку и вспомните, какой долгий 39-недельный путь вы успешно прошли. Запомните 3 основных признака родов: регулярные схватки с нарастающей интенсивностью, отхождение вод или слизистой пробки. При появлении любого из них свяжитесь с врачом. Берегите силы и верьте, что всё пройдёт самым лучшим образом.-') WHERE id = '46262d69-53e1-4e37-8004-ee9b3e95fbbb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Восприятие малышом внешних раздражителей с помощью органов чувств, их индивидуальная интерпретация, рефлекторные движения, режим сна — словом, все эти сложные процессы происходят благодаря эффективной работе систем организма. Слаженную, согласованную и бесперебойную работу систем в организме малыша обеспечивает высокоразвитая система контроля и регуляции.;;;
Для регуляции взаимодействия между тканями и органами малыша одной только нервной системы недостаточно. Этот процесс осуществляется благодаря совместной работе нервной системы и желёз внутренней секреции. Получая сигналы от головного мозга малыша, железы внутренней секреции вырабатывают особые вещества — гормоны, которые выполняют регулирующую функцию.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои гормоны вступают в действие! 🧪 Мой организм и ваша плацента выделяют особые гормоны, чтобы ускорить процесс родов. Вы можете стать очень эмоциональной и, возможно, плаксивой. Так проявляется наша химическая связь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности вы можете столкнуться не только с дискомфортом, вызванным некоторыми факторами окружающей среды, но и с различными неприятными проявлениями, связанными с гормональными изменениями в организме. Преэклампсия, то есть осложнение беременности, возникающее на поздних сроках, характеризуется повышением артериального давления и появлением белка в моче. По мере развития беременности количество крови и питательных веществ, необходимых плаценте, значительно увеличивается. Поэтому питающие плаценту сосуды расширяются. Однако при преэклампсии в структуре этих сосудов возникают сужения, из-за чего плацента не получает необходимого количества крови и питательных веществ. Хотя вероятность развития этого осложнения довольно низкая, оно представляет угрозу для жизни как вашей, так и малыша и требует неотложной медицинской помощи.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Берегите силы. Не ешьте тяжёлую пищу. Поскольку роды могут начаться в любой момент, не перегружайте желудок — может возникнуть рвотный рефлекс.') WHERE id = '938fd655-5567-4125-a9f7-ead570f3ba8c';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поскольку все железы внутренней секреции малыша уже сформировались, его организм может синтезировать все гормоны в тех же пропорциях, что и организм взрослого человека. Среди них важнейшим гормоном, обеспечивающим рост малыша и особенно активно выделяющимся во время сна, является гормон роста.;;;
Гормон роста — это белок, состоящий примерно из 200 различных аминокислот и синтезируемый передней долей расположенного в головном мозге гипофиза. Этот гормон участвует во многих сложных физиологических процессах, включая рост малыша и скорость обмена веществ. В отличие от других гормонов, его мишенью является не отдельный орган, а все клетки организма. Во время роста он ускоряет синтез белка в клетках, регулирует обмен углеводов и жиров.;;;
Синтез и выделение гормона роста начинаются вечером и завершаются с восходом солнца. Наиболее активно он выделяется в период с 23:00 до 05:00. Особенно высокого уровня в организме он достигает примерно в 03:00. Повышаясь в крови в ночное время, этот гормон ускоряет митотическое деление клеток и обеспечивает рост тканей и органов, особенно скелетных мышц, костей и хрящей.'), baby_message_ru = COALESCE(baby_message_ru, 'Я изменил свой цвет! 🎨 Теперь я уже не красный. Благодаря слою подкожного жира моя кожа стала розовой или светлой. Слой верникса почти исчез. Моя кожа может быть немного сухой. Я уже полностью сформировавшийся человек.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'У некоторых беременных кровотечения из носа возникают время от времени, а у других подобные эпизоды могут повторяться почти ежедневно. Оба варианта считаются нормальными во время беременности и обычно не причиняют вреда ни вам, ни малышу. Чтобы удовлетворять растущие потребности малыша и поддерживать ваше здоровье, во время беременности организм вырабатывает больше крови. Поэтому объём крови, циркулирующей в кровеносной системе, значительно увеличивается. По мере увеличения объёма крови возрастает давление на тонкие поверхностные сосуды слизистой оболочки носа. Из-за повышенного давления стенка такого сосуда может повредиться, вызывая кровотечение. Если у вас началось кровотечение из носа, зажмите мягкую часть носа и удерживайте её примерно 10 минут.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сделайте массаж или ванночку для ног. Поддержка партнёра очень важна. Ещё раз обсудите с ним план родов.') WHERE id = '4e4de332-7546-4ae2-8266-e548c84af11c';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'То, что малыш реагирует на ваш голос, когда вы говорите, свидетельствует о наличии у него хорошо развитых органов чувств и нервной системы, которая позволяет интерпретировать раздражители и отвечать на них. Вещество, вызывающее у малыша возбуждение, когда вы говорите, — это гормон адреналин. Адреналин, также называемый эпинефрином, — чрезвычайно важный гормон и нейромедиатор, действующий в головном мозге и организме малыша. В организме адреналин выделяется надпочечниками, а в головном мозге — некоторыми специализированными нервными клетками, расположенными в области ствола мозга.;;;
Повышение уровня сахара в крови помогает клеткам организма малыша получать больше питательных веществ. Сердцебиение учащается, чтобы лучше обеспечить повышенную потребность организма в кислороде.;;;
В результате всех этих изменений адреналин создаёт условия, необходимые для сокращения мышц малыша и расходования ими энергии. Благодаря этому он реагирует на ваш голос движениями.'), baby_message_ru = COALESCE(baby_message_ru, 'Завтра большой день? 📅 Завтра моя официальная "Due Date". Но я могу появиться и сегодня. Я слышу ваш голос, вы говорите: "Ну же, выходи". Я тоже хочу прийти к вам, Anacan. Путь долог, но в его конце — свет.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Одна из наиболее распространённых проблем, особенно на поздних сроках беременности, — бессонница. При дефиците магния в организме бессонница может усилиться. Чтобы уровень гормонов нервной системы, то есть нейромедиаторов, обеспечивающих качественный сон, оставался в крови на необходимом уровне, организму требуется достаточное количество магния. К овощам, наиболее богатым магнием, относятся шпинат, стручковая фасоль, брокколи и капуста.;;;
Кроме того, много магния содержится в тыквенных и подсолнечных семечках, арахисе, миндале, кешью, бананах, авокадо, зерновых продуктах, молоке и йогурте.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Пусть сегодня станет для вас днём "последнего затишья". Ни в коем случае не тратьте силы на уборку или утомительные дела. Роды могут начаться в любой момент, поэтому не ешьте тяжёлую пищу — отдавайте предпочтение лёгким и питательным перекусам, дающим энергию. Если у вас отойдут воды (даже при отсутствии схваток) или схватки станут регулярными и будут повторяться каждые 5-7 минут, пора отправляться в больницу. Верьте в себя — вы готовы!') WHERE id = '7abac408-c74e-44ce-86ac-a1a2470ea25a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже полностью готов к рождению и превратился в настоящего «маленького героя». Большая часть его костей (кроме костей черепа) полностью затвердела и окрепла.;;;
То, что кости черепа всё ещё остаются мягкими и подвижными, — настоящее чудо природы: благодаря этой эластичности малышу легче и безопаснее пройти через родовые пути. Ногти вашего малыша уже отросли за кончики пальцев, а некоторые малыши появляются на свет с довольно длинными и густыми волосами.;;;
И самое главное: внутренние «часы» малыша — его гормональная система — уже полностью готовы подать «сигнал к родам». Мозг и надпочечники малыша выделяют особые гормоны, сообщая вашему организму, что пришло время начала родов. Этот гормональный диалог приводит мышцы матки в действие и приближает вашу долгожданную встречу с малышом.'), baby_message_ru = COALESCE(baby_message_ru, 'Я официально готов. На этой неделе мне пора родиться. Может быть, сегодня, а может, завтра... Но обещаю, что не заставлю тебя долго ждать. Я тоже хочу тебя увидеть!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Правильное питание во время беременности поддерживает интеллектуальное развитие вашего малыша и помогает ему реализовать заложенный потенциал. На протяжении всей беременности важно регулярно и в необходимых количествах употреблять разнообразные продукты: овощи и фрукты как источники витаминов, продукты животного происхождения как источники белка, полезные жиры, молоко и молочные продукты, а также злаки.;;;
Для здоровья вашего малыша и вашего собственного важно употреблять продукты, богатые белком. Включайте в рацион овощи и фрукты, содержащие углеводы, а для восполнения потребности в железе — яйца, мясо и тёмно-зелёные листовые овощи. Кроме того, продукты, содержащие витамины A, C и D, и достаточное количество воды помогут вам поддерживать здоровое и сбалансированное питание во время беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы справиться с волнением в эти дни, выполняйте дыхательные упражнения. Чтобы ускорить начало родов, совершайте лёгкие прогулки по дому, если ваш врач не рекомендовал иное. Помните, что только 5% малышей рождаются точно в предполагаемую дату, поэтому не беспокойтесь, если роды задержатся на несколько дней. Убедитесь, что ваш телефон и сумка в любой момент готовы.') WHERE id = 'c09d4d91-1d82-48b0-8145-2433217890b4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'До момента рождения кишечник вашего малыша остаётся полностью стерильным. На этом этапе он готовится принять более 500 различных видов бактерий, которые сформируют его уникальную кишечную флору. Эта система, расположенная в тонком и толстом кишечнике малыша, называется микрофлорой, и именно здесь находится примерно %70 клеток иммунной системы.;;;
Развитие микрофлоры в кишечнике, который до момента рождения остаётся стерильным, зависит от способа родоразрешения, генетических особенностей малыша, контакта с окружающей средой и характера питания. После рождения малыша некоторые бактерии, участвующие в пищеварении, начинают появляться в кишечнике на 4-й день после естественных родов и на 7-й день после кесарева сечения.;;;
Среди микроорганизмов кишечной флоры есть как полезные, так и вредные бактерии. Это необходимо для поддержания баланса микрофлоры. Оба вида бактерий создают в пищеварительной системе равновесие, не позволяя друг другу чрезмерно размножаться или слишком сильно сокращаться в количестве. Избыток бактерий во флоре может привести к диарее и значительной потере жидкости, а их недостаток создаёт условия для возникновения запора.'), baby_message_ru = COALESCE(baby_message_ru, 'Я уже иду — со схватками! ⚡ Если живот регулярно напрягается и расслабляется, а ощущения постепенно усиливаются, значит, я уже стучусь в дверь. Схватки продвигают меня вниз, к выходу. Во время каждой схватки мне поступает немного меньше кислорода, но я выносливый. Дыши глубоко, чтобы помочь мне.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Стресс из-за задержки родов может утомлять вас. Все спрашивают: «Вы ещё не родили?» Это создаёт психологическое давление. Физически давление на кости таза уже достигло максимума. Бессонница и беспокойство сохраняются. Ваш организм полностью готов к родам. Связки таза максимально расслаблены.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если схватки Брекстона — Хикса становятся регулярными, обязательно прилягте, отдохните и пейте больше воды. Если схватки не проходят даже в положении лёжа и повторяются каждые 10 минут, это уже может быть началом родов. Сегодня постарайтесь не переутомляться, послушайте спокойную музыку и насладитесь вместе с малышом последними мгновениями вашего внутреннего единства.') WHERE id = '7bc0ef79-b157-4b4f-94b8-a06d51f2d8d7';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Скорость развития мозга вашего малыша соответствует темпам роста его головы. Окружность головы, которая при рождении в среднем составляет 33-35 см, быстро увеличивается в первые шесть месяцев. Затем рост продолжается, но его темп замедляется. Развитие мозга малыша после рождения, то есть рост его головы, оценивается по стандартным возрастным кривым роста:;;;
Микроцефалия: если окружность головы малыша ниже %3 диапазона значений, соответствующих его возрасту, это состояние называется микроцефалией. В таком случае выясняют причины, препятствующие развитию мозга, например генетические факторы или тяжёлые инфекции, перенесённые во время беременности.;;;
Макроцефалия: если окружность головы превышает %90 нормальных значений, диагностируется макроцефалия. В таком случае исследуют причины аномального увеличения мозга и поддерживающих его структур, а также повышения давления на них.;;;
Мозг вашего малыша развивается очень быстро: в течение первого года после рождения его объём увеличивается примерно на %88.'), baby_message_ru = COALESCE(baby_message_ru, 'Я всё ещё здесь? 🏠 Если я пока не родился, не расстраивайся. Иногда в расчётах может быть ошибка или мне просто нужно ещё несколько дней. Каждый день, проведённый в утробе, идёт мне на пользу (если плацента работает хорошо). Я знаю, когда придёт моё время.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Если ваша беременность пришлась на летние месяцы, особенно полезно есть сезонные летние фрукты. Они богаты витаминами и минералами, обладают антиоксидантными свойствами и высокой питательной ценностью.;;;
Богатые клетчаткой фрукты, например клубника, помогают дольше сохранять чувство сытости и легче контролировать вес на протяжении беременности.;;;
Содержащаяся в клубнике фолиевая кислота способствует развитию нервной системы малыша, а магний поддерживает развитие его костей и здоровый процесс формирования костной ткани.;;;
Авокадо — один из фруктов с самым высоким содержанием ненасыщенных жирных кислот. Помимо полезных жиров, он содержит большое количество фолата и калия. Калий помогает облегчить судороги в ногах на поздних сроках беременности.;;;
Эти фрукты содержат полезные углеводы, витамин C и клетчатку. Особенно много в них витамина C, необходимого для усвоения железа в организме. Витамин C также важен для здоровья кожи и работы иммунной системы.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы ощущаете сильную тяжесть, примите тёплый душ, обеспечив опору для спины: это поможет расслабить мышцы и уменьшить схватки Брекстона — Хикса. Важно по-прежнему чувствовать движения малыша; если вы заметите их внезапное уменьшение, немедленно сообщите об этом врачу. В последние дни вам может быть трудно спать, поэтому ложитесь на левый бок и кладите подушку между ног.') WHERE id = 'fd795c4a-8409-4cb2-89fc-4a9fbcef21a6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К завершению 40-й недели беременности ваш малыш достиг окончательных показателей веса и роста при рождении. Примерно %20 общей массы тела малыша составляют белые и бурые жировые клетки, которые придают его коже розовый оттенок и мягкость. Все системы органов малыша полностью сформированы, а благодаря завершению выработки сурфактанта в лёгких он полностью готов к жизни во внешнем мире.;;;
Если вы завершили 40-ю неделю, но роды ещё не начались и беременность продолжается, следует внимательнее следить за признаками родов:;;;
Влагалищные выделения: Из-за давления значительно увеличившейся матки выделения могут стать более жидкими. Они также могут иметь коричневый или жёлтый оттенок.;;;
Предупреждение об инфекции: Неприятный запах таких подтекающих выделений считается признаком инфекции.;;;
Исследование амниотической жидкости: Если вы не можете понять, являются ли выделения обычными или это окружающая малыша амниотическая жидкость, в медицинском учреждении это можно уточнить с помощью простого теста на уровень pH (нитразинового теста).'), baby_message_ru = COALESCE(baby_message_ru, 'Поздравляю, Anacan! Мы завершили 40-недельный марафон. Сегодня мой официальный день рождения! 🎂 Если сегодня я уже оказался у вас на руках — привет, мир! А если ещё нет, не волнуйтесь: я не опаздываю, а просто следую «тренду» и заставляю себя ждать. Самое позднее через 1-2 недели мы обязательно встретимся. Я вас люблю!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Сегодня вы завершили 40 недель беременности. Если срок уже подошёл, но роды ещё не начались, не стоит беспокоиться. Вы ждали много месяцев и, возможно, хотите как можно скорее встретиться со своим малышом. У вас могут возникать вопросы о том, почему роды задерживаются. Отсутствие родов к концу 40-й недели может быть связано с неверно рассчитанной датой последней менструации или поздним оплодотворением. Но даже если срок рассчитан правильно, роды могут задерживаться без какой-либо причины. Не паникуйте и помните, что у вас есть ещё 2 недели. В этот период просто нужно внимательнее следить за возможными осложнениями, чаще посещать врача и проходить необходимые обследования. Поскольку после завершения срока беременности малыш продолжает набирать вес с прежней скоростью, естественные роды могут стать сложнее. По данным Всемирной организации здравоохранения (ВОЗ), вес малыша 4500 грамм сам по себе не является препятствием для естественных родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Хотя по календарю сегодня последний день, постарайтесь сохранять спокойствие. Если схватки ещё не начались, немного прогуляйтесь или примите тёплый душ. В последний раз проверьте у двери сумку в роддом и документы. Если схватки повторяются каждые 5 минут или отошли воды, немедленно отправляйтесь в больницу. Помните: вы проделали невероятную работу и теперь вот-вот получите свою самую большую награду!') WHERE id = '08e8895d-cc10-4825-8aac-fb6a2a6d3d95';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Нервная система и мозг малыша активно развиваются ещё в утробе и непрерывно растут с необычайной скоростью. Особенно в последнем триместре беременности (последние три месяца), когда частично начинается процесс обучения, каждая испытываемая вами эмоция через гормоны напрямую влияет на малыша:;;;
Влияние кортизола: Когда вы испытываете чрезмерное беспокойство, стресс или страх, уровень кортизола в вашем организме повышается. Этот гормон воздействует на всю нервную систему малыша.;;;
Химическая реакция: Кортизол, выделяющийся из-за сильных переживаний, попадает в организм малыша и вызывает выработку некоторых химических веществ, влияющих на работу его мозга.;;;
Сейчас, в последние дни беременности, для здоровья нервной системы малыша очень важно по возможности держать свои эмоции под контролем.'), baby_message_ru = COALESCE(baby_message_ru, 'Я всё ещё здесь! 👋 Здравствуйте, Anacan! Дата в календаре уже прошла, но я всё ещё нахожусь в вашем тёплом животике. Не волнуйтесь: по статистике только 5% малышей рождаются точно в рассчитанный день. Просто мне настолько уютно, что я не спешу выходить. У нас своё особенное время.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Если после 40 недель роды ещё не начались, в некоторых ситуациях следует быть особенно внимательной. Важнее всего следить за частотой движений малыша. Замедление его движений иногда может вызывать у вас беспокойство. Причина может заключаться в том, что из-за своего веса малышу уже не хватает пространства для движений внутри матки. Тем не менее, если вы заметили значительное уменьшение активности малыша, следует проконсультироваться с врачом. Поскольку роды уже совсем близко, ложные схватки, называемые схватками Брекстона — Хикса, могут стать болезненными. Наблюдайте за ложными схватками и отмечайте, как часто они возникают, — это поможет не перепутать их с настоящими родовыми схватками.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте этот день! Купите себе торт и сделайте селфи «Я всё ещё не родила». Эти дни больше никогда не повторятся. Самое большое приключение вашей жизни вот-вот начнётся!') WHERE id = '2d2b31a8-8f73-4858-b9b0-2f01ec75aada';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе малыш получает необходимые его организму кислород, углеводы, жиры, белки, витамины и минералы непосредственно из вашего организма через плаценту. При этом вся пищеварительная система малыша уже достаточно развита, чтобы с момента рождения начать работать, расщеплять молоко на составляющие и использовать их для роста и развития. Каждый день в утробе малыш заглатывает ртом литры амниотической жидкости, тренируя свою пищеварительную систему. Такая «тренировка» очень важна для нормального пищеварения после рождения.'), baby_message_ru = COALESCE(baby_message_ru, 'Не слушайте родственников! 🙉 Я знаю, все звонят и спрашивают: «Вы ещё не родили?» Это утомляет вас, правда? Скажите им, что я «VIP-гость» и жду идеального момента, чтобы выйти на сцену. А вы просто отдыхайте и не обращайте внимания на эти вопросы.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности вам порой может быть трудно контролировать вес и сдерживать усилившийся аппетит. Однако недостаточное питание из-за страха набрать вес также крайне вредно для здоровья. Важно помнить, что пища, которую вы употребляете, жизненно необходима для развития малыша. Чтобы обеспечить малыша необходимыми витаминами и минералами и одновременно контролировать свой вес, в этот период следует употреблять меньше продуктов, богатых углеводами, и отдавать предпочтение белковой пище.;;;
Для здорового развития малыша достаточно завершить беременность, набрав 10-12 килограммов. Это средние показатели: в зависимости от вашего индекса массы тела прибавка может составлять от 6 до 16 килограммов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В эти дни вопросы окружающих «Вы ещё не родили?» могут вас утомлять. Мягко улыбнитесь и напомните им, что малыш сам выберет наиболее подходящее время. Берегите своё внутреннее спокойствие.') WHERE id = '912237d6-e1bb-4ef4-b942-ca1a90b3bc59';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Кишечная микрофлора, которая помогает усваивать питательные вещества в кишечнике малыша и синтезирует некоторые необходимые его организму бактерии, формируется только после рождения — благодаря грудному молоку и контакту с окружающей средой. На этом этапе малыш заглатывает лишь амниотическую жидкость в матке, а после рождения с первым кормлением начинается первый этап становления его пищеварительной системы. Полное развитие пищеварительной системы малыша, который находился в абсолютно стерильной внутриутробной среде, происходит только после рождения. Размер желудка малыша с момента рождения быстро меняется:;;;
В первые 24 часа: размером с вишню (примерно 5-7 мл).;;;
На 3-й день: размером с грецкий орех (примерно 22-27 мл).;;;
К концу 30-го дня: достигает размера среднего яйца (примерно 60-150 мл).;;;
Пищеварительная система малыша начинает становиться похожей на пищеварительную систему взрослого человека с 6-го месяца, в период введения прикорма, а с 2 лет достигает почти такой же зрелости, как у взрослого.'), baby_message_ru = COALESCE(baby_message_ru, 'Я ещё немного поправился! ⚖️ Anacan, я всё ещё набираю вес. Благодаря этим дополнительным дням мои щёчки становятся ещё милее, а на ручках появляется ещё больше складочек. Когда я появлюсь на свет, обнимать меня будет ещё приятнее. Набирайтесь сил, вы мне очень понадобитесь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности важно, чтобы с пищей в ваш организм регулярно поступали все необходимые витамины и минералы. Один из них — витамин K, который крайне важен как для работы вашего организма, так и для здоровья малыша. Он способствует накоплению кальция в костях скелета и тем самым поддерживает их здоровье. Также он препятствует отложению кальция в кровеносных сосудах и почках. Иными словами, витамин K помогает поддерживать баланс кальция в организме. Ещё одна его функция — активировать белки, играющие важную роль в поддержании здоровья сердца. Избыток витамина K накапливается в печени. Витамин K является жирорастворимым. Во время беременности вам необходимо не менее 90 мкг витамина K в день. Поэтому рекомендуется употреблять зелёные листовые овощи, яйца, мясо и молочные продукты.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Роды могут начаться в любой момент, поэтому сегодня будьте особенно бережны к себе. Чтобы отвлечься от стресса, посмотрите любимый фильм или просто глубоко подышите, любуясь природой за окном.') WHERE id = 'ab9a202d-7f8e-48d6-9bd2-ce62eab926ef';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Печень малыша, регулирующая углеводный обмен и с помощью инсулина преобразующая глюкозу в крови в гликоген для создания запасов, полностью готова к рождению. Благодаря этой подготовке печени уровень сахара в крови малыша не снижается во время родов и до первого кормления, а клетки продолжают получать питание. В первый день молочные протоки вырабатывают столько молока, сколько соответствует объёму желудка новорождённого малыша, размер которого сопоставим с вишней. Благодаря запасам гликогена в печени небольшое количество молока в первые дни не представляет опасности для малыша. По мере приближения родов малыш заглатывает больше амниотической жидкости, чем выделяет с мочой. Эта избыточная жидкость сохраняется в его организме, накапливается между тканями и после рождения используется клетками.;;;
Поскольку после рождения накопленная в организме малыша избыточная жидкость используется, а затем выводится с мочой, в первые дни масса тела может уменьшиться на 10% по сравнению с массой при рождении. Такая потеря веса считается нормальной. В среднем в течение 7-10 дней малыш накапливает жир взамен выведенной из организма жидкости и снова достигает массы тела при рождении.'), baby_message_ru = COALESCE(baby_message_ru, 'Время для маникюра? 💅 Знаете, мои ногти уже заметно отросли. Иногда я даже царапаю себя, когда прикасаюсь к лицу. Возможно, сразу после моего рождения одним из первых дел будет подстричь мне ногти. Мои волосы тоже продолжают расти (если они у меня есть). Я появлюсь на свет при полном параде!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Не забывайте, что роды могут начаться в любой момент, и будьте к этому готовы. Когда приходит время родов, появляются лёгкие схватки. На начальном этапе они могут быть редкими, но затем боли, возникающие через регулярные промежутки времени, становятся всё более частыми, продолжительными и интенсивными. Каждая беременность протекает по-разному, поэтому и роды у всех проходят по-своему. В целом эти ощущения принято сравнивать с сильными болями во время менструации. Если схватки начинают повторяться каждые 10-15 минут, это может означать приближение родов. Однако точнее всего оценить ситуацию сможет ваш врач, поэтому не следует долго ждать — отправляйтесь в больницу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Прислушивайтесь к своему телу. Если вы почувствуете внутреннее беспокойство, сразу прилягте и поговорите с малышом. Ваше спокойствие — самая важная поддержка для него на пути к появлению на свет.') WHERE id = '2c4fb6e2-626f-4582-b7ad-da6ef85b1258';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Одно из наиболее распространённых состояний, с которыми можно столкнуться после рождения малыша, — желтуха новорождённых. Она наблюдается примерно у %60% доношенных и у %80% недоношенных малышей. В народе это состояние часто связывают с недостаточным питанием, но это ошибочное представление. На самом деле это полностью физиологический процесс и реакция организма на адаптацию к внешней среде.;;;
На протяжении беременности малыш получает необходимый кислород из вашей крови через плаценту. Однако уровень кислорода в матке значительно ниже, чем во внешнем мире. Чтобы распределять это небольшое количество кислорода между всеми клетками и поддерживать баланс, организм малыша заставляет костный мозг работать интенсивнее. В результате такой активной работы костного мозга образуется большое количество эритроцитов. Они легко доставляют кислород к каждой клетке организма малыша, предотвращая кислородное голодание.;;;
Сразу после рождения малыш оказывается в среде, богатой кислородом. Теперь его организму больше не нужно такое большое количество эритроцитов, и печень начинает разрушать лишние клетки. Образующийся при этом билирубин вызывает физиологическую желтуху, при которой кожа и белки глаз малыша приобретают желтоватый оттенок.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне стало совсем тесно! 🏠 Anacan, здесь уже меньше места, чем в "квартире-студии". Двигаться очень трудно, поэтому моих движений может стать меньше. Но вы должны чувствовать меня каждый день. Если вам покажется, что я притих, съешьте что-нибудь сладкое — и я сразу отвечу!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Поскольку малыш уже достаточно вырос, на этом этапе некоторые физиологические неприятные ощущения могут заметно усилиться. В частности, из-за давления на желудок может возникнуть сильная изжога. Изжога во время беременности связана с гормональными изменениями и давлением увеличивающейся матки на желудок.;;;
Одним из продуктов, способных облегчить изжогу во время беременности, является тёплое молоко. Стакан тёплого молока перед сном успокаивает желудок и уменьшает вызванное кислотой жжение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня отложите все дела. Расслабьтесь так, словно вы отправились в отпуск. Помните: вы творите чудо, а ваше тело готовится выполнить самую сложную и одновременно самую прекрасную работу в мире.') WHERE id = 'd01cbe86-cb64-4e22-98cc-8f8bd1c8a6d5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В кишечнике вашего малыша бактерии, называемые микробиотой, начинают быстро размножаться в составе кишечной флоры, которая формируется с 3-го дня после рождения. Микробиота кишечника малыша участвует в сложных процессах, способствующих размножению клеток, выстилающих внутреннюю стенку кишечника. Масса этих сообществ бактерий, называемых микробиотой, увеличивается по мере роста малыша и к моменту достижения зрелого возраста составляет примерно 2 килограмма. Эти бактерии выполняют функцию защитного барьера, препятствуя проникновению в организм малыша болезнетворных микроорганизмов. Они помогают переваривать некоторые продукты, которые организм малыша не способен переварить самостоятельно, и регулируют работу иммунной системы. Сообщество микроорганизмов, входящее в состав кишечной флоры малыша, участвует, в частности, в выработке жирорастворимых витаминов и некоторых необходимых организму веществ. В последние годы кишечную флору стали называть отдельным органом благодаря миллионам содержащихся в ней бактерий и нейромедиаторам, количество которых в 9 раз превышает их количество в нервной системе.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя плацента всё ещё работает! 🔋 Врачи, вероятно, проверяют мои околоплодные воды и плаценту. Всё в порядке. Я по-прежнему дышу благодаря тебе и получаю от тебя питание. Мы — одна команда и будем вместе до самого конца. Не бойся, я жду сигнала.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Вы находитесь на довольно позднем сроке беременности. Поэтому сейчас особенно важно внимательно следить за питанием. Поскольку матка с уже достаточно выросшим малышом оказывает давление на внутренние органы, у вас могут возникать некоторые проблемы с пищеварением.;;;
Особенно на ужин следует избегать жареной, острой и очень жирной пищи и выбирать лёгкие блюда, которые не будут раздражать желудок. Овощные блюда на ужин очень полезны, однако необходимо убедиться, что овощи хорошо приготовлены. Недостаточно приготовленные овощи могут усилить изжогу. Следует сократить употребление или полностью отказаться от газированных и содержащих кофеин напитков, а также фруктов с высокой кислотностью, таких как грейпфрут и апельсин, которые могут повышать кислотность желудка. Кроме того, старайтесь не злоупотреблять такими напитками, как кофе и чай. Ешьте не спеша и избегайте употребления жидкости во время еды, чтобы свести вздутие живота к минимуму.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы снизить напряжение, примите тёплый душ. Позвольте воде расслабить ваше тело. Постарайтесь представлять роды не со страхом, а с радостью от первого мгновения встречи с малышом.') WHERE id = '1682ff26-3ced-4844-9a8e-8e67a40347cb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поскольку при переношенной беременности риск некоторых осложнений возрастает, очень важно обращать внимание на определённые симптомы, которые могут появиться у вас. Начиная с 40-й недели беременности чаще могут возникать такие проблемы, как преждевременная отслойка плаценты и попадание мекония (первородного кала), скопившегося в кишечнике малыша, в околоплодные воды с последующим его вдыханием и проникновением в лёгкие.;;;
Состояние, называемое «отслойкой плаценты», означает отделение плаценты, которая питает малыша до родов, от стенки матки ещё до начала родов. Поскольку такая отслойка может представлять серьёзную опасность как для вас, так и для малыша, при любом кровотечении необходимо немедленно обратиться к врачу. Хотя преждевременная отслойка плаценты встречается довольно редко, она наблюдается в одном случае из каждых 200 беременностей. Наиболее распространённые признаки этого состояния — боль и тёмные, несворачивающиеся кровянистые выделения из влагалища. При выраженной отслойке могут появиться признаки гипотонии и шока, а сердцебиение малыша может ухудшиться. Поэтому при появлении кровотечения обязательно обратитесь к врачу.'), baby_message_ru = COALESCE(baby_message_ru, 'Мне снятся сны... 💤 Большую часть времени я сплю. Интересно, как выглядит твоё лицо? Твой голос мне уже очень хорошо знаком. Я слышу и голос папы. В своих снах я уже вижу вас. Совсем скоро этот сон станет реальностью.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Правильное дыхание и регулярные дыхательные упражнения не только помогают уменьшить неприятные симптомы, возникающие во время беременности, но и способствуют более комфортному течению родов.;;;
Особенно на этом этапе беременности вашему организму требуется больше кислорода, чем обычно. Эффективное и глубокое дыхание как во время беременности, так и в процессе родов действует как естественное обезболивающее и помогает телу расслабиться. Благодаря дыхательным упражнениям органы получают больше кислорода, поэтому такие жалобы, как изжога, расстройство пищеварения, запор, вздутие живота и газы, могут несколько уменьшиться. Кроме того, глубокое, контролируемое и медленное дыхание положительно влияет на тошноту и головокружение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если сегодня мы всё ещё ждём, значит, ваш малыш завершает последние приготовления в утробе. Наберитесь терпения и доверьтесь своему телу. Вы очень сильная женщина и прекрасно со всем справитесь.') WHERE id = '5ae12c1c-33a8-4883-a677-24cfe3025ffd';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К 38-й неделе беременности происходит примерно %80 родов. Поэтому сейчас, когда вы вступили в 42-ю неделю, отсутствие родов может вызывать у вас сильное напряжение. Хорошая новость заключается в том, что если на этом этапе, называемом переношенной беременностью, роды не начнутся самостоятельно до 42-й недели, по рекомендации врача вам могут провести стимуляцию родовой деятельности или кесарево сечение, после чего вы сможете взять малыша на руки. Хотя движения малыша время от времени могут быть очень болезненными, вы можете заметить, что по сравнению с предыдущими неделями он двигается реже. Сейчас малышу теснее, чем когда-либо, и у него почти не осталось свободного пространства для движений. В течение дня необходимо считать его движения и обращаться к врачу, если вы заметите, что их стало значительно меньше, чем должно быть. Существенное уменьшение количества околоплодных вод на этих неделях считается нормальным. Однако если их объём снизится настолько, что это начнёт вызывать стресс у малыша, врач может принять решение начать роды до завершения 42-й недели.'), baby_message_ru = COALESCE(baby_message_ru, 'Добро пожаловать на 41-ю неделю! 🎈 Да, официально мы уже считаемся «задержавшимися» (overdue). Но я бы назвал это «с добавленной ценностью». Верникс (сыровидная смазка) почти полностью исчез. После рождения моя кожа может быть немного сухой, но ты ведь смажешь её, правда?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Если к этому сроку роды ещё не начались, никаких признаков их приближения нет, а вес малыша приближается к предельному значению, вы можете обсудить с врачом возможность кесарева сечения.;;;
Кесарево сечение — это хирургическая операция, которая проводится, когда естественные роды невозможны: примерно на 4 пальца ниже живота выполняется разрез, через который извлекают малыша. Кесарево сечение является хирургической операцией и по сравнению с естественными родами имеет некоторые недостатки, в том числе необходимость анестезии и более длительное восстановление. Однако, несмотря на это, существуют ситуации, когда кесарево сечение предпочтительнее из-за возможных осложнений при естественных родах и рисков для малыша. Кесарево сечение может потребоваться, если малыш неправильно располагается в родовых путях, срок беременности уже подошёл к концу, но схватки не начинаются, или возникло такое осложнение, как преэклампсия.;;;
Независимо от того, пройдут ваши роды естественным путём или с помощью кесарева сечения, никогда не забывайте, что в конце этого 9-месячного приключения вас ждёт встреча с малышом. 😊'), daily_tip_ru = COALESCE(daily_tip_ru, 'Гормоны стресса могут замедлить начало родов. Поэтому сегодня слушайте только хорошие новости и держитесь подальше от людей и тем, которые несут вам негативную энергию. Сейчас ваше эмоциональное благополучие важнее всего.') WHERE id = '7f952d08-70cf-40a7-af2e-4095f1619337';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш как никогда готов к встрече с внешним миром. Все его органы и системы уже хорошо развиты и способны полноценно функционировать. Плацента, находящаяся в матке, продолжает защищать малыша от инфекций и вырабатывать антитела, которые помогут ему бороться с заболеваниями после рождения. После родов малышу потребуется ещё некоторое время, чтобы начать вырабатывать собственные антитела.;;;
На этом этапе незрелость иммунной системы малыша и его неспособность вырабатывать собственные антитела имеют жизненно важное значение, поскольку благодаря этому антигены вашего организма и антигены малыша не вступают в нежелательную иммунную реакцию.;;;
С момента рождения иммунная система малыша начинает быстро развиваться благодаря грудному вскармливанию и продолжает формироваться на протяжении всего детства.;;;
Вместе с грудным молоком в организм малыша поступают секреторные антитела IgA, антиидиотипические антитела, бактерицидные компоненты, лактоферрин, полезные бактерии, а также B- и T-лимфоциты, которые закладывают основу его иммунной системы.;;;
Все эти компоненты иммунной системы всасываются ворсинками кишечника, а затем поступают в кровь и лимфу, благодаря чему иммунная система малыша начинает быстро формироваться.'), baby_message_ru = COALESCE(baby_message_ru, 'Я такой умный! 🧠 В эти последние дни мой мозг быстро развивается. Все мои органы чувств уже работают. Я чувствую свет, звуки и прикосновения. И ваше волнение тоже чувствую. Сохраняйте спокойствие, Anacan. Всё идёт по плану (по моему плану 😉).'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Чтобы состоялись роды, шейка матки должна полностью раскрыться и позволить малышу пройти через родовые пути. Если к этому сроку раскрытие ещё не началось и при КТГ не выявляются сокращения матки, возможны два варианта: кесарево сечение или стимуляция родовой деятельности. За сокращения мышц матки и начало родов отвечает гормон окситоцин. Именно он вызывает сокращения матки, которые продвигают малыша вниз. По мере того как головка малыша давит на шейку матки, раскрытие увеличивается. После полного раскрытия малыш проходит через родовые пути и появляется на свет. Если организм не вырабатывает достаточно окситоцина, его вводят внутривенно для стимуляции схваток. По мере повышения уровня окситоцина в крови мышцы матки начинают сокращаться. Период до полного раскрытия шейки матки сопровождается регулярными схватками. Существует несколько причин для стимуляции родовой деятельности. Среди них — слишком медленное течение родов, отсутствие самостоятельного начала родов при переношенной беременности, инфекции матки и повышение артериального давления.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня постарайтесь лечь спать немного раньше. Вам важно накопить силы для родов. Устройте подушки так, чтобы телу было максимально удобно. Пусть вам приснится улыбка малыша!') WHERE id = '4884c66b-3927-4354-8b35-abb2fd62f234';